const ChronoUnit = {
  DAYS: { between: (a, b) => (b instanceof LocalDateTime ? Math.trunc((b.epochMin() - a.epochMin()) / 1440) : b.toEpochDay() - a.toEpochDay()) },
  WEEKS: { between: (a, b) => Math.trunc((b.toEpochDay() - a.toEpochDay()) / 7) },
  MONTHS: { between: (a, b) => { let n = (b.getYear() - a.getYear()) * 12 + (b.getMonthValue() - a.getMonthValue()); if (b.getDayOfMonth && a.getDayOfMonth && n > 0 && b.getDayOfMonth() < a.getDayOfMonth()) n--; return n; } },
  YEARS: { between: (a, b) => Math.trunc(ChronoUnit.MONTHS.between(a, b) / 12) },
  MINUTES: { between: (a, b) => Math.trunc(toMin(b) - toMin(a)) },
  HOURS: { between: (a, b) => Math.trunc((toMin(b) - toMin(a)) / 60) }
};
function toMin(x) { return x instanceof LocalDateTime ? x.epochMin() : x instanceof LocalTime ? x.toSecondOfDay() / 60 : x.toEpochDay() * 1440; }

class Duration {
  constructor(mins) { this.mins = mins; }
  static between(a, b) { return new Duration(toMin(b) - toMin(a)); }
  static ofMinutes(n) { return new Duration(n); }
  static ofHours(n) { return new Duration(60 * n); }
  toMinutes() { return Math.trunc(this.mins); }
  toHours() { return Math.trunc(this.mins / 60); }
  toDays() { return Math.trunc(this.mins / 1440); }
  getSeconds() { return Math.trunc(this.mins * 60); }
  isNegative() { return this.mins < 0; }
}

const TemporalAdjusters = {
  previousOrSame: dw => d => d.minusDays(((d.getDayOfWeek().v - dw.v) % 7 + 7) % 7),
  nextOrSame: dw => d => d.plusDays(((dw.v - d.getDayOfWeek().v) % 7 + 7) % 7),
  previous: dw => d => d.minusDays(((d.getDayOfWeek().v - dw.v - 1) % 7 + 7) % 7 + 1),
  next: dw => d => d.plusDays(((dw.v - d.getDayOfWeek().v - 1) % 7 + 7) % 7 + 1),
  firstDayOfMonth: () => d => d.withDayOfMonth(1),
  lastDayOfMonth: () => d => d.withDayOfMonth(d.lengthOfMonth()),
  firstDayOfNextMonth: () => d => d.withDayOfMonth(1).plusMonths(1),
  firstInMonth: dw => d => TemporalAdjusters.nextOrSame(dw)(d.withDayOfMonth(1))
};

/** DateTimeFormatter.ofPattern with the letters the app uses: d dd M MM MMM MMMM yy yyyy E EEE EEEE H HH h hh m mm s ss SSS a and 'quoted' text. */
class DateTimeFormatter {
  constructor(p) { this.p = p; }
  static ofPattern(p) { return new DateTimeFormatter(p); }
  withLocale() { return this; }
  format(x) {
    const d = x instanceof LocalDateTime ? x.date : x instanceof LocalDate ? x : null;
    const t = x instanceof LocalDateTime ? x.time : x instanceof LocalTime ? x : null;
    let out = '';
    const p = this.p;
    for (let i = 0; i < p.length;) {
      const c = p[i];
      if (c === '\'') {
        const j = p.indexOf('\'', i + 1);
        out += j < 0 ? p.slice(i + 1) : p.slice(i + 1, j);
        i = j < 0 ? p.length : j + 1;
        continue;
      }
      let n = 1;
      while (p[i + n] === c) n++;
      i += n;
      switch (c) {
        case 'd': out += n >= 2 ? pad2(d.d) : d.d; break;
        case 'M': out += n >= 4 ? MONTH_NAMES[d.m - 1] : n === 3 ? MONTH_NAMES[d.m - 1].slice(0, 3) : n === 2 ? pad2(d.m) : d.m; break;
        case 'y': case 'u': out += n === 2 ? String(d.y).slice(-2) : d.y; break;
        case 'E': out += d.getDayOfWeek().getDisplayName(n >= 4 ? TextStyle.FULL : TextStyle.SHORT); break;
        case 'H': out += n >= 2 ? pad2(t.h) : t.h; break;
        case 'h': { const h = t.h % 12 === 0 ? 12 : t.h % 12; out += n >= 2 ? pad2(h) : h; break; }
        case 'm': out += n >= 2 ? pad2(t.mi) : t.mi; break;
        case 's': out += n >= 2 ? pad2(t.s) : t.s; break;
        case 'S': out += '000'.slice(0, n); break;
        case 'a': out += t.h < 12 ? 'AM' : 'PM'; break;
        default: out += c.repeat(n);
      }
    }
    return out;
  }
}
DateTimeFormatter.ISO_LOCAL_DATE = { format: d => d.toString() };

/** The clock; tests can pin it. */
const Clock = {
  offsetMs: 0,
  fixedTime: null,
  now() { return new Date(Date.now() + Clock.offsetMs); },
  millis() { return Date.now() + Clock.offsetMs; }
};
const System = { currentTimeMillis: () => Clock.millis(), nanoTime: () => Math.round(performance.now() * 1e6) };

// ---------- String.format (the subset the app uses) ----------
/** Java String.format: %s %d %,d %02d %.1f %5.1f %x %% and %n. */
function jfmt(fmt) {
  const args = Array.prototype.slice.call(arguments, 1);
  if (typeof fmt !== 'string' && args.length && typeof args[0] === 'string') { fmt = args.shift(); }   // String.format(Locale, fmt, ...)
  let k = 0;
  return fmt.replace(/%([-0,+ ]*)(\d+)?(?:\.(\d+))?([sdfxXc%n])/g, (all, flags, width, prec, conv) => {
    if (conv === '%') return '%';
    if (conv === 'n') return '\n';
    let v = args[k++];
    let s;
    if (conv === 'd') {
      v = Math.trunc(Number(v));
      s = flags.includes(',') ? Math.abs(v).toLocaleString('en-IN') : String(Math.abs(v));
      if (v < 0) s = '-' + s; else if (flags.includes('+')) s = '+' + s;
    } else if (conv === 'f') {
      v = Number(v);
      s = v.toFixed(prec == null ? 6 : +prec);
      if (flags.includes(',')) { const [a, b] = s.split('.'); s = Number(a).toLocaleString('en-IN') + (b ? '.' + b : ''); }
      if (flags.includes('+') && v >= 0) s = '+' + s;
    } else if (conv === 'x' || conv === 'X') {
      s = (Number(v) >>> 0).toString(16);
      if (conv === 'X') s = s.toUpperCase();
    } else if (conv === 'c') s = typeof v === 'number' ? String.fromCharCode(v) : String(v);
    else { s = v == null ? 'null' : String(v); if (prec != null) s = s.slice(0, +prec); }
    if (width && s.length < +width) {
      if (flags.includes('-')) s = s + ' '.repeat(+width - s.length);
      else if (flags.includes('0') && conv !== 's') { const neg = s[0] === '-'; s = (neg ? '-' : '') + '0'.repeat(+width - s.length) + (neg ? s.slice(1) : s); }
      else s = ' '.repeat(+width - s.length) + s;
    }
    return s;
  });
}

// ---------- org.json ----------
class JSONException extends Error {}
