    if (act === Intent.ACTION_OPEN_DOCUMENT || act === Intent.ACTION_GET_CONTENT) return External.pick(from, i, req, false);
    if (act === MediaStore.ACTION_IMAGE_CAPTURE) return External.pick(from, i, req, true);
