/** res/raw files, read synchronously like openRawResource on the phone (they ship with the website). */
Resources.openRawResource = function (res) {
  const x = new XMLHttpRequest();
  x.open('GET', res, false);
  x.overrideMimeType('text/plain; charset=x-user-defined');
  x.send(null);
  const t = x.responseText || '';
  const u = new Uint8Array(t.length);
  for (let i = 0; i < t.length; i++) u[i] = t.charCodeAt(i) & 255;
  return new ByteArrayInputStream(u);
};
