'use strict';
/**
 * Switches only the admin (app maker) can change. They are shared settings rows named "admin_…": every phone follows them,
 * and the server refuses a change to them from anyone but the admin.
 */
class AdminControl {
  /** The AI check (differential diagnosis and treatment) in the case sheet: "on" (default) or "off". */
  static AI_CHECK = "admin_ai_check";

  static aiCheckOn(db) {
    return "off" !== db.setting(AdminControl.AI_CHECK, "on");
  }

  static setAiCheck(db, on) {
    db.setSetting(AdminControl.AI_CHECK, on ? "on" : "off");
  }

  /** The intercom (calls and pages) for the whole department: "on" (default) or "off". */
  static INTERCOM = "admin_intercom";

  static intercomOn(db) {
    return "off" !== db.setting(AdminControl.INTERCOM, "on");
  }

  static setIntercom(db, on) {
    db.setSetting(AdminControl.INTERCOM, on ? "on" : "off");
  }
}
