'use strict';
/**
 * Raised 3D "slab" look for the two most important home cards (admission day and today's DAP):
 * a thick coloured block with a visible lower edge, a glossy face, a light rim, extruded lettering,
 * a pulsing live dot and a duty-time bar.
 */
class Slab {
  /** A small dot that gently pulses: "live now". */
  static pulse(c, color) {
    const dot = new View(c);
    const g = new GradientDrawable();
    g.setShape(GradientDrawable.OVAL);
    g.setColor(color);
    g.setStroke(Ui.dp(c, 2), 0x99FFFFFF);
    dot.setBackground(g);
    const a = ObjectAnimator.ofFloat(dot, "alpha", 1, 0.25);
    a.setDuration(900);
    a.setRepeatMode(ValueAnimator.REVERSE);
    a.setRepeatCount(ValueAnimator.INFINITE);
    // web: stop the endless animation once the dot has left the page (a redraw replaced it)
    a.addUpdateListener({
      onAnimationUpdate: (an) => {
        if (dot.el.isConnected) dot._shown = true;
        else if (dot._shown) a.cancel();
      }
    });
    a.start();
    return dot;
  }

  static orb(c, color, glyphRes, sizeDp) {
    const iv = new ImageView(c);
    iv.setImageDrawable(new Slab.Orb(c, color, glyphRes));
    iv.setScaleType(ImageView.ScaleType.FIT_XY);
    iv.setLayoutParams(Ui.lp(Ui.dp(c, sizeDp), Ui.dp(c, sizeDp)));
    return iv;
  }

  /** Pressing sinks the tile into its 3D edge; letting go springs it back. */
  static pressable(v, depthDp) {
    const d = Ui.dp(v.getContext(), depthDp);
    v.setOnTouchListener({
      onTouch: (view, e) => {
        const a = e.getActionMasked();
        if (a === MotionEvent.ACTION_DOWN) {
          view.animate().translationY(d * 0.6).scaleX(0.985).scaleY(0.985).setDuration(90).start();
        } else if (a === MotionEvent.ACTION_UP || a === MotionEvent.ACTION_CANCEL) {
          view.animate().translationY(0).scaleX(1).scaleY(1).setDuration(180)
            .setInterpolator(new OvershootInterpolator(2)).start();
        }
        return false;
      }
    });
  }
}

/** The block: an extruded base (the 3D edge), a glossy gradient face, a sheen and a light rim. */
Slab.Face = class extends Drawable {
  /** Face(c, colors, radiusDp, depthDp) or Face(c, colors, radiusDp, depthDp, side). */
  constructor(c, colors, radiusDp, depthDp, side) {
    super();
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.r = new RectF();
    this.side = side == null ? null : side;
    this.colors = colors;
    this.radius = Ui.dp(c, radiusDp);
    this.depth = Ui.dp(c, depthDp);
  }

  draw(cv) {
    const p = this.p, r = this.r, colors = this.colors, radius = this.radius, depth = this.depth;
    const w = this.getBounds().width(), h = this.getBounds().height();
    const left = this.getBounds().left, top = this.getBounds().top;
    const deep = this.side != null ? this.side : Ui.mix(colors[colors.length - 1], Color.BLACK, 0.45);
    // the side of the block, a few dp below the face
    p.setShader(null);
    p.setStyle(Paint.Style.FILL);
    p.setColor(deep);
    r.set(left, top + depth, left + w, top + h);
    cv.drawRoundRect(r, radius, radius, p);
    // the face
    r.set(left, top, left + w, top + h - depth);
    p.setShader(new LinearGradient(r.left, r.top, r.right, r.bottom, colors, null, Shader.TileMode.CLAMP));
    cv.drawRoundRect(r, radius, radius, p);
    // glossy light from the top left
    p.setShader(new RadialGradient(r.left + w * 0.18, r.top, Math.max(w, h) * 0.75, 0x30FFFFFF, 0x00FFFFFF, Shader.TileMode.CLAMP));
    cv.drawRoundRect(r, radius, radius, p);
    // a highlight band along the top edge
    p.setShader(new LinearGradient(0, r.top, 0, r.top + (h - depth) * 0.45, 0x33FFFFFF, 0x00FFFFFF, Shader.TileMode.CLAMP));
    cv.drawRoundRect(r, radius, radius, p);
    // rim
    p.setShader(null);
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeWidth(Math.max(1, depth / 5));
    p.setColor(0x66FFFFFF);
    r.inset(p.getStrokeWidth() / 2, p.getStrokeWidth() / 2);
    cv.drawRoundRect(r, radius, radius, p);
  }

  setAlpha(a) {}
  setColorFilter(cf) {}
  getOpacity() { return PixelFormat.TRANSLUCENT; }
};

/** Big lettering with a stepped 3D extrusion and a soft drop shadow (unit code, initials). */
Slab.Extruded = class extends View {
  constructor(c, text, sizeSp, face, side) {
    super(c);
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.text = text;
    this.size = sizeSp * c.getResources().getDisplayMetrics().scaledDensity;
    this.face = face;
    this.side = side;
    this.p.setTypeface(Typeface.create(Typeface.DEFAULT, Typeface.BOLD));
    this.p.setTextSize(this.size);
    this.p.setTextAlign(Paint.Align.CENTER);
    this.setLayerType(View.LAYER_TYPE_SOFTWARE, null);
  }

  onMeasure(ws, hs) {
    const w = this.p.measureText(this.text) + this.size * 0.25;
    const h = this.size * 1.15;
    this.setMeasuredDimension(View.resolveSize(toInt(w), ws), View.resolveSize(toInt(h), hs));
  }

  onDraw(cv) {
    const p = this.p, size = this.size, text = this.text;
    const cx = this.getWidth() / 2 - size * 0.04;
    const base = this.getHeight() / 2 - (p.descent() + p.ascent()) / 2 - size * 0.05;
    const steps = Math.max(3, Math.round(size / 14));
    p.setShader(null);
    p.setMaskFilter(new BlurMaskFilter(size * 0.08, BlurMaskFilter.Blur.NORMAL));
    p.setColor(0x66000000);
    cv.drawText(text, cx + steps + 2, base + steps + 4, p);
    p.setMaskFilter(null);
    for (let i = steps; i >= 1; i--) {
      p.setColor(Ui.mix(this.side, Color.BLACK, 0.1 * (steps - i) / steps));
      cv.drawText(text, cx + i * 0.7, base + i, p);
    }
    p.setShader(new LinearGradient(0, base - size * 0.8, 0, base, Ui.mix(this.face, Color.WHITE, 0.4), this.face, Shader.TileMode.CLAMP));
    p.setColor(0xFF000000);
    cv.drawText(text, cx, base, p);
  }
};

/** A frosted track with a bright fill: how far through the 24-hour duty we are. */
Slab.Progress = class extends View {
  constructor(c, frac, fill) {
    super(c);
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.r = new RectF();
    this.fill = fill;
    this.frac = Math.max(0, Math.min(1, frac));
  }

  onDraw(cv) {
    const p = this.p, r = this.r;
    const w = this.getWidth(), h = this.getHeight(), rad = h / 2;
    p.setShader(null);
    p.setColor(0x38000000);
    r.set(0, 0, w, h);
    cv.drawRoundRect(r, rad, rad, p);
    if (this.frac > 0) {
      r.set(0, 0, Math.max(h, w * this.frac), h);
      p.setShader(null);
      p.setColor(this.fill);
      cv.drawRoundRect(r, rad, rad, p);
      p.setColor(Color.WHITE);
      cv.drawCircle(r.right - rad, rad, rad * 1.35, p);
    }
  }
};

/**
 * A real 3D icon: a glossy sphere lit from the top left, with reflected light along its lower rim,
 * a specular highlight, a soft shadow on the surface below and an embossed white symbol.
 */
Slab.Orb = class extends Drawable {
  constructor(c, color, glyphRes) {
    super();
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.clip = new Path();
    this.base = color;
    this.light = Ui.mix(color, Color.WHITE, 0.55);
    this.deep = Ui.mix(color, Color.BLACK, 0.45);
    this.density = c.getResources().getDisplayMetrics().density;
    const g = c.getResources().getDrawable(glyphRes, null);
    this.glyph = g.getConstantState().newDrawable().mutate();
    this.glyph.setColorFilter(new PorterDuffColorFilter(Color.WHITE, PorterDuff.Mode.SRC_IN));
    this.glyphEdge = g.getConstantState().newDrawable().mutate();
    this.glyphEdge.setColorFilter(new PorterDuffColorFilter(Ui.mix(color, Color.BLACK, 0.35), PorterDuff.Mode.SRC_IN));
  }

  draw(cv) {
    const p = this.p, base = this.base, light = this.light, deep = this.deep, density = this.density;
    const b = this.getBounds();
    const w = b.width(), h = b.height();
    const R = Math.min(w, h) * 0.41;
    const cx = b.left + w / 2, cy = b.top + h * 0.45;
    p.setStyle(Paint.Style.FILL);

    // shadow on the surface below: stacked soft ellipses
    p.setShader(null);
    const gy = cy + R + h * 0.035;
    for (let i = 6; i >= 1; i--) {
      p.setColor(Ui.alpha(deep, 0x0A + (6 - i) * 0x06));
      const rx = R * (0.55 + i * 0.08), ry = R * (0.07 + i * 0.022);
      cv.drawOval(new RectF(cx - rx, gy - ry, cx + rx, gy + ry), p);
    }

    // the sphere, shaded from a deep lower right to a light top left: a stack of circles that
    // shrink toward the light, so it renders the same on every phone
    const n = 28;
    for (let i = 0; i <= n; i++) {
      const t = i / n;
      const rr = R * (1 - 0.88 * t);
      const ox = -0.36 * R * t, oy = -0.42 * R * t;
      const col = t < 0.45 ? Ui.mix(deep, base, Math.pow(t / 0.45, 0.6)) : Ui.mix(base, light, (t - 0.45) / 0.55);
      p.setColor(col);
      cv.drawCircle(cx + ox, cy + oy, rr, p);
    }

    cv.save();
    this.clip.reset();
    this.clip.addCircle(cx, cy, R, Path.Direction.CW);
    cv.clipPath(this.clip);
    // light bounced back up from the surface onto the lower rim
    const bounce = Ui.mix(base, Color.WHITE, 0.55);
    for (let i = 0; i < 6; i++) {
      p.setColor(Ui.alpha(bounce, 0x16));
      const rr = R * (0.75 - i * 0.08);
      cv.drawCircle(cx + R * 0.12, cy + R * 1.08, rr, p);
    }
    cv.restore();

    // embossed symbol: a few darker layers stepped down, then the white face
    const gs = Math.round(R * 1.0);
    const gl = Math.round(cx - gs / 2), gt = Math.round(cy - gs / 2 + R * 0.04);
    const steps = Math.max(2, Math.round(R / (9 * density)) + 1);
    for (let i = steps; i >= 1; i--) {
      const off = Math.round(i * density * 0.9);
      this.glyphEdge.setBounds(gl + idiv(off, 2), gt + off, gl + gs + idiv(off, 2), gt + gs + off);
      this.glyphEdge.draw(cv);
    }
    this.glyph.setBounds(gl, gt, gl + gs, gt + gs);
    this.glyph.draw(cv);

    // specular highlight: a curved window reflection across the top, brightest at its top edge
    cv.save();
    cv.rotate(-18, cx - R * 0.09, cy - R * 0.52);
    for (let i = 0; i < 8; i++) {
      const t = i / 8;
      const hi = new RectF(cx - R * (0.6 - 0.25 * t), cy - R * (0.9 - 0.03 * t),
        cx + R * (0.42 - 0.25 * t), cy - R * (0.16 + 0.42 * t));
      p.setColor(Ui.alpha(Color.WHITE, 0x1A + i * 0x0C));
      cv.drawOval(hi, p);
    }
    cv.restore();
    // sparkle
    p.setShader(null);
    p.setColor(0xF2FFFFFF);
    cv.drawCircle(cx - R * 0.42, cy - R * 0.52, R * 0.08, p);
    // thin rim
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeWidth(Math.max(1, density * 0.8));
    p.setColor(Ui.alpha(Color.WHITE, 0x55));
    cv.drawCircle(cx, cy, R - p.getStrokeWidth() / 2, p);
    p.setStyle(Paint.Style.FILL);
  }

  setAlpha(a) {}
  setColorFilter(cf) {}
  getOpacity() { return PixelFormat.TRANSLUCENT; }
};

/** A small progress ring with "done/target" in the middle; target 0 shows a dash (not due this week). */
Slab.Counter = class extends View {
  constructor(c, done, target, color) {
    super(c);
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.r = new RectF();
    this.done = done;
    this.target = target;
    this.color = color;
  }

  onDraw(cv) {
    const p = this.p, r = this.r, done = this.done, target = this.target, color = this.color;
    const w = this.getWidth(), h = this.getHeight(), s = Math.min(w, h), stroke = s * 0.12;
    r.set((w - s) / 2 + stroke, (h - s) / 2 + stroke, (w + s) / 2 - stroke, (h + s) / 2 - stroke);
    p.setShader(null);
    p.setStyle(Paint.Style.FILL);
    p.setColor(0xCCFFFFFF);
    cv.drawCircle(w / 2, h / 2, s / 2 - stroke / 2, p);
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeWidth(stroke);
    p.setStrokeCap(Paint.Cap.ROUND);
    p.setColor(Ui.alpha(color, 0x2E));
    cv.drawArc(r, 0, 360, false, p);
    const frac = target <= 0 ? 0 : Math.min(1, done / target);
    if (frac > 0) {
      p.setColor(frac >= 1 ? Ui.GREEN : color);
      cv.drawArc(r, -90, Math.max(8, 360 * frac), false, p);
    }
    p.setStyle(Paint.Style.FILL);
    p.setColor(Ui.mix(color, Color.BLACK, 0.5));
    p.setTextAlign(Paint.Align.CENTER);
    p.setFakeBoldText(true);
    const t = target <= 0 ? "–" : done + "/" + target;
    p.setTextSize(s * (t.length > 4 ? 0.22 : 0.27));
    cv.drawText(t, w / 2, h / 2 - (p.descent() + p.ascent()) / 2, p);
  }
};
;
