/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Options shown as colour bands with the words on them: a soft tinted band when not chosen,
 * a solid raised band with white letters when chosen. Used for tick lists and single choices across the app.
 */
class Bands {
  /** Distinct, rich colours handed out to options in turn. */
  static PALETTE = [0xFF2563EB, 0xFF7C3AED, 0xFF0D9488, 0xFFDB2777, 0xFFEA580C, 0xFF059669,
    0xFFCA8A04, 0xFF0891B2, 0xFF4F46E5, 0xFFC026D3, 0xFF65A30D, 0xFFE11D48];

  static color(i) {
    return Bands.PALETTE[((i % Bands.PALETTE.length) + Bands.PALETTE.length) % Bands.PALETTE.length];
  }

  /** The darker shade used for letters on a soft band. */
  static ink(color) {
    return Ui.mix(color, Color.BLACK, 0.35);
  }

  static soft(c, color) {
    const g = new GradientDrawable();
    g.setCornerRadius(Ui.dp(c, 18));
    g.setColor(Ui.mix(color, Color.WHITE, 0.88));
    g.setStroke(Math.max(1, Ui.dp(c, 1)), Ui.mix(color, Color.WHITE, 0.6));
    return g;
  }

  static solid(c, color) {
    const g = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,
      [Ui.mix(color, Color.WHITE, 0.12), Ui.mix(color, Color.BLACK, 0.12)]);
    g.setCornerRadius(Ui.dp(c, 18));
    g.setStroke(Math.max(1, Ui.dp(c, 1)), Ui.mix(color, Color.BLACK, 0.2));
    return g;
  }

  static padBand(c, t) {
    t.setPadding(Ui.dp(c, 14), Ui.dp(c, 8), Ui.dp(c, 14), Ui.dp(c, 8));
    t.setMinHeight(Ui.dp(c, 38));
    t.setGravity(Gravity.CENTER_VERTICAL);
    t.setTextSize(14);
    t.setTypeface(Typeface.DEFAULT_BOLD);
    t.setIncludeFontPadding(false);
  }

  /** Paints a single-choice band as chosen or not. */
  static paint(c, t, color, on) {
    t.setBackground(on ? Bands.solid(c, color) : Bands.soft(c, color));
    t.setTextColor(on ? Color.WHITE : Bands.ink(color));
    t.setElevation(on ? Ui.dp(c, 3) : 0);
  }
}

/** A tick option drawn as a band. Still a CheckBox, so isChecked / setChecked work as before. */
Bands.Band = class extends CheckBox {
  constructor(c, text, color) {
    super(c);
    this.setText(text.trim());
    this.setButtonDrawable(null);
    Bands.padBand(c, this);
    const bg = new StateListDrawable();
    bg.addState([ANDROID_R.attr.state_checked], Bands.solid(c, color));
    bg.addState([], Bands.soft(c, color));
    this.setBackground(bg);
    this.setTextColor(new ColorStateList([[ANDROID_R.attr.state_checked], []], [Color.WHITE, Bands.ink(color)]));
  }

  setChecked(on) {
    super.setChecked(on);
    this.setElevation(on ? Ui.dp(this.getContext(), 3) : 0);
  }
};

/**
 * Lays its children left to right and wraps to the next line, like words in a sentence.
 * (The Java onMeasure/onLayout wrapping is done by the runtime's FlowLayout with the same 8 dp gap.)
 */
Bands.Flow = class extends FlowLayout {
  constructor(c) {
    const gap = Ui.dp(c, 8);
    super(c, gap, gap);
    this.gap = gap;
    this.setClipToPadding(false);
    this.setClipChildren(false);
  }
};
;
