/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * The department's shared Supabase project: sign-in, membership and raw HTTP calls.
 * Settings live in SharedPreferences so they never travel in backups or sync.
 */
class Cloud {
  static ROLES = ["admin", "hod", "registrar", "professor", "faculty", "pg", "crmi", "staff", "pending", "blocked"];
  static ROLE_LABELS = ["Admin (app maker)", "HOD", "Medical Registrar", "Professor / Associate Professor", "Assistant Professor", "Postgraduate", "CRMI", "Staff",
    "Waiting for approval", "Removed (no access)"];

  static prefs(c) {
    return c.getApplicationContext().getSharedPreferences("cloud", Context.MODE_PRIVATE);
  }

  /** Project URL and public key: from Account settings, else the ones built into the app. */
  static url(c) {
    let u = Cloud.prefs(c).getString("url", "");
    if (u.isEmpty()) u = c.getString(R.string.cloud_url);
    while (u.endsWith("/")) u = u.substring(0, u.length - 1);
    return u.trim();
  }

  static key(c) {
    const k = Cloud.prefs(c).getString("key", "");
    return (k.isEmpty() ? c.getString(R.string.cloud_key) : k).trim();
  }

  static configured(c) {
    return Cloud.url(c).startsWith("https://") && !Cloud.key(c).isEmpty() || Cloud.url(c).startsWith("http://127.0.0.1") || Cloud.url(c).startsWith("http://10.0.2.2");
  }

  static signedIn(c) {
    return !Cloud.prefs(c).getString("refresh", "").isEmpty();
  }

  static role(c) {
    return Cloud.prefs(c).getString("role", "");
  }

  static approved(c) {
    const r = Cloud.role(c);
    return Cloud.signedIn(c) && (r.equals("admin") || r.equals("hod") || r.equals("registrar") || r.equals("professor") || r.equals("faculty") || r.equals("pg") || r.equals("crmi") || r.equals("staff"));
  }

  /** True once this phone shares records with the department. */
  static active(c) {
    return Cloud.approved(c) && Db.get(c).meta("id_base", 0) > 0;
  }

  /** Every screen stays behind the email + password sign-in until this phone shares records. Tests turn it off. */
  static requireLogin = true;

  static loginRequired(c) {
    return Cloud.requireLogin && Cloud.configured(c) && !Cloud.active(c);
  }

  /** Opens the sign-in page as the app's first page, clearing every other screen. */
  static openLogin(a) {
    a.startActivity(new Intent(a, AccountActivity).putExtra("gate", true)
      .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TASK));
    a.overridePendingTransition(0, 0);
  }

  /** The admin, the HOD and the Medical Registrar: every admin power. */
  static isAdmin(c) {
    return Cloud.isManager(Cloud.role(c));
  }

  static isManager(r) {
    return "admin".equals(r) || "hod".equals(r) || "registrar".equals(r);
  }

  /** The admin: Dr. S. Rajkumar, who makes the app. Every power, including appointing and removing the HOD, and publishing app updates. */
  static isOwner(c) {
    return "admin".equals(Cloud.role(c));
  }

  /** "Admin (app maker) · Assistant Professor" once the admin is linked to an Assistant Professor entry, else the role's label. */
  static myRoleLabel(c, db) {
    const l = Cloud.roleLabel(Cloud.role(c));
    return Cloud.isOwner(c) && Cloud.myApEntry(c, db) != null ? l + "  ·  Assistant Professor" : l;
  }

  /** The admin's own Faculty entry when it is an Assistant Professor's, else null. */
  static myApEntry(c, db) {
    const id = Cloud.myStaff(c);
    const s = id > 0 ? db.row("SELECT * FROM staff WHERE id=?", String(id)) : null;
    return s != null && "Assistant Professor".equals(s.get("role")) ? s : null;
  }

  /** The Faculty entry that is probably the admin's: the linked one, else an Assistant Professor with the admin's name. */
  static apMatch(c, db) {
    const id = Cloud.myStaff(c);
    const s = id > 0 ? db.row("SELECT * FROM staff WHERE id=?", String(id)) : null;
    if (s != null && Db.isFaculty(s.get("role"))) return s;
    let me = Cloud.prefs(c).getString("name", "");
    if (me.trim().isEmpty()) me = "S. Rajkumar";
    for (const r of db.rows("SELECT * FROM staff WHERE role='Assistant Professor' ORDER BY id"))
      if (Chat.sameName(r.get("name"), me)) return r;
    return null;
  }

  /** Saves the admin's own Assistant Professor entry (approved, in his unit) and returns its id. */
  static saveApEntry(c, db, old, name, unit) {
    const cv = new ContentValues();
    cv.put("name", name);
    cv.put("role", "Assistant Professor");
    cv.put("unit", unit);
    cv.put("approval", "");
    if (old == null) {
      cv.put("approved_by", Approvals.me(c));
      return db.insert("staff", cv);
    }
    const id = Long.parseLong(old.get("id"));
    db.update("staff", cv, id);
    return id;
  }

  static myStaff(c) {
    return Cloud.prefs(c).getLong("staff_id", -1);
  }

  /** The Faculty section is only for the admin, the HOD, the Medical Registrar, Professors and the Associate Professor. */
  static canSeeFaculty(c) {
    return !Cloud.active(c) || Cloud.isAdmin(c) || "professor".equals(Cloud.role(c));
  }

  /** Faculty leave is only for the faculty themselves (Assistant / Associate Professors, Professors, HOD). */
  static canSeeFacultyLeave(c) {
    const r = Cloud.role(c);
    return !Cloud.active(c) || Cloud.isManager(r) || r.equals("professor") || r.equals("faculty");
  }

  static canSeeDocs(c, staffId) {
    return Cloud.canSeeFaculty(c);
  }

  static roleLabel(r) {
    return Db.label(Cloud.ROLES, Cloud.ROLE_LABELS, r);
  }

  // ---------- HTTP ----------

  static http(c, method, path, body, contentType, token, ...headers) {
    if (headers.length === 1 && Array.isArray(headers[0])) headers = headers[0];
    const h = new URL_(Cloud.url(c) + path).openConnection();
    h.setConnectTimeout(15000);
    h.setReadTimeout(60000);
    h.setRequestMethod(method);
    h.setRequestProperty("apikey", Cloud.key(c));
    // New-style publishable keys (sb_publishable_…) go only in "apikey"; old anon keys are JWTs and may be sent as the bearer too.
    if (token != null) h.setRequestProperty("Authorization", "Bearer " + token);
    else if (Cloud.key(c).startsWith("eyJ")) h.setRequestProperty("Authorization", "Bearer " + Cloud.key(c));
    for (let i = 0; i + 1 < headers.length; i += 2) h.setRequestProperty(headers[i], headers[i + 1]);
    if (body != null) {
      h.setDoOutput(true);
      h.setRequestProperty("Content-Type", contentType == null ? "application/json" : contentType);
      h.setFixedLengthStreamingMode(body.length);
      const os = h.getOutputStream();
      os.write(body);
      os.close();
    }
    const r = new Cloud.Resp();
    r.code = h.getResponseCode();
    const inp = r.code >= 400 ? h.getErrorStream() : h.getInputStream();
    const bo = new ByteArrayOutputStream();
    if (inp != null) {
      const buf = new Uint8Array(16384);
      let n;
      while ((n = inp.read(buf)) > 0) bo.write(buf, 0, n);
      inp.close();
    }
    r.body = bo.toByteArray();
    h.disconnect();
    if (r.code >= 400) throw new Cloud.HttpError(r.code, Cloud.message(r));
    return r;
  }

  /** Web: the same request as http() without blocking the page (used by Sync). */
  static async httpA(c, method, path, body, contentType, token, ...headers) {
    if (headers.length === 1 && Array.isArray(headers[0])) headers = headers[0];
    const hd = {};
    hd["apikey"] = Cloud.key(c);
    if (token != null) hd["Authorization"] = "Bearer " + token;
    else if (Cloud.key(c).startsWith("eyJ")) hd["Authorization"] = "Bearer " + Cloud.key(c);
    for (let i = 0; i + 1 < headers.length; i += 2) hd[headers[i]] = headers[i + 1];
    if (body != null) hd["Content-Type"] = contentType == null ? "application/json" : contentType;
    const x = await httpAsync(method, Cloud.url(c) + path, hd, body);
    const r = new Cloud.Resp();
    r.code = x.code;
    r.body = x.body || new Uint8Array(0);
    if (r.code >= 400) throw new Cloud.HttpError(r.code, Cloud.message(r));
    return r;
  }

  static message(r) {
    try {
      const o = new JSONObject(r.text());
      for (const k of ["msg", "message", "error_description", "error"])
        if (o.has(k) && !o.optString(k).isEmpty()) return o.optString(k);
    } catch (ignored) {}
    return "Server error " + r.code;
  }

  static json(c, method, path, body, ...headers) {
    if (headers.length === 1 && Array.isArray(headers[0])) headers = headers[0];
    const b = body == null ? null : jbytes(body.toString());
    return Cloud.http(c, method, path, b, "application/json", Cloud.token(c), headers);
  }

  static async jsonA(c, method, path, body, ...headers) {
    if (headers.length === 1 && Array.isArray(headers[0])) headers = headers[0];
    const b = body == null ? null : jbytes(body.toString());
    return Cloud.httpA(c, method, path, b, "application/json", await Cloud.tokenA(c), headers);
  }

  // ---------- auth ----------

  static saveSession(c, s) {
    Cloud.prefs(c).edit()
      .putString("access", s.optString("access_token"))
      .putString("refresh", s.optString("refresh_token"))
      .putLong("expires", System.currentTimeMillis() + 1000 * s.optLong("expires_in", 3600))
      .putString("user_id", s.optJSONObject("user") == null ? "" : s.optJSONObject("user").optString("id"))
      .apply();
  }

  /** Signs in, or creates the account first. Returns null when signed in, else a message for the person. */
  static signIn(c, email, password, name, create) {
    const body = new JSONObject().put("email", email).put("password", password);
    if (create) {
      body.put("data", new JSONObject().put("name", name));
      const r = new JSONObject(Cloud.http(c, "POST", "/auth/v1/signup", jbytes(body.toString()), null, null).text());
      if (!r.has("access_token")) return "Account created. Open the confirmation email, then sign in here.";
      Cloud.saveSession(c, r);
    } else {
      const r = new JSONObject(Cloud.http(c, "POST", "/auth/v1/token?grant_type=password", jbytes(body.toString()), null, null).text());
      Cloud.saveSession(c, r);
    }
    Cloud.prefs(c).edit().putString("email", email).putString("name", name).apply();
    Cloud.join(c, name);
    return null;
  }

  static resetPassword(c, email) {
    Cloud.http(c, "POST", "/auth/v1/recover", jbytes(new JSONObject().put("email", email).toString()), null, null);
  }

  /** A valid access token, refreshing it when it is about to expire. */
  static token(c) {
    const p = Cloud.prefs(c);
    if (p.getString("refresh", "").isEmpty()) throw new Cloud.HttpError(401, "Not signed in");
    if (System.currentTimeMillis() < p.getLong("expires", 0) - 60000) return p.getString("access", "");
    try {
      const body = new JSONObject().put("refresh_token", p.getString("refresh", ""));
      const r = Cloud.http(c, "POST", "/auth/v1/token?grant_type=refresh_token", jbytes(body.toString()), null, null);
      Cloud.saveSession(c, new JSONObject(r.text()));
    } catch (e) {
      if (e instanceof Cloud.HttpError) {
        if (e.code === 400 || e.code === 401) p.edit().remove("refresh").remove("access").apply();
        throw e;
      }
      if (e instanceof JSONException) throw new IOException(e.getMessage());
      throw e;
    }
    return p.getString("access", "");
  }

  /** Web: token() without blocking the page; one refresh at a time (Java's synchronized). */
  static async tokenA(c) {
    const p = Cloud.prefs(c);
    if (p.getString("refresh", "").isEmpty()) throw new Cloud.HttpError(401, "Not signed in");
    if (System.currentTimeMillis() < p.getLong("expires", 0) - 60000) return p.getString("access", "");
    if (Cloud.refreshing) return Cloud.refreshing;
    Cloud.refreshing = (async () => {
      try {
        const body = new JSONObject().put("refresh_token", p.getString("refresh", ""));
        const r = await Cloud.httpA(c, "POST", "/auth/v1/token?grant_type=refresh_token", jbytes(body.toString()), null, null);
        Cloud.saveSession(c, new JSONObject(r.text()));
      } catch (e) {
        if (e instanceof Cloud.HttpError) {
          if (e.code === 400 || e.code === 401) p.edit().remove("refresh").remove("access").apply();
          throw e;
        }
        if (e instanceof JSONException) throw new IOException(e.getMessage());
        throw e;
      }
      return p.getString("access", "");
    })();
    try { return await Cloud.refreshing; } finally { Cloud.refreshing = null; }
  }

  static refreshing = null;

  static signOut(c) {
    Cloud.prefs(c).edit().remove("access").remove("refresh").remove("expires").remove("role").remove("staff_id").remove("user_id").apply();
    Lock.clear(c);
  }

  /** Registers the person with the department (first one becomes admin) and refreshes their role. */
  static join(c, name) {
    const r = Cloud.json(c, "POST", "/rest/v1/rpc/join_department", new JSONObject().put("p_name", name == null ? "" : name)).text();
    const role = r.split("\"").join("").trim();
    const e = Cloud.prefs(c).edit().putString("role", role);
    try {
      const me = new JSONArray(Cloud.json(c, "GET", "/rest/v1/members?select=staff_id,name&user_id=eq." + Cloud.prefs(c).getString("user_id", ""), null).text());
      if (me.length() > 0) {
        const m = me.getJSONObject(0);
        e.putLong("staff_id", m.isNull("staff_id") ? -1 : m.getLong("staff_id"));
        if (!m.optString("name").isEmpty() && !m.isNull("name")) e.putString("name", m.optString("name"));
      }
    } catch (ignored) {}
    e.apply();
    return role;
  }

  /** Web: join() without blocking the page (Sync's role check). */
  static async joinA(c, name) {
    const r = (await Cloud.jsonA(c, "POST", "/rest/v1/rpc/join_department", new JSONObject().put("p_name", name == null ? "" : name))).text();
    const role = r.split("\"").join("").trim();
    const e = Cloud.prefs(c).edit().putString("role", role);
    try {
      const me = new JSONArray((await Cloud.jsonA(c, "GET", "/rest/v1/members?select=staff_id,name&user_id=eq." + Cloud.prefs(c).getString("user_id", ""), null)).text());
      if (me.length() > 0) {
        const m = me.getJSONObject(0);
        e.putLong("staff_id", m.isNull("staff_id") ? -1 : m.getLong("staff_id"));
        if (!m.optString("name").isEmpty() && !m.isNull("name")) e.putString("name", m.optString("name"));
      }
    } catch (ignored) {}
    e.apply();
    return role;
  }

  static members(c) {
    return new JSONArray(Cloud.json(c, "GET", "/rest/v1/members?select=*&order=created_at", null).text());
  }

  static setMember(c, userId, role, staffId) {
    const b = new JSONObject().put("p_user", userId).put("p_role", role).put("p_staff", staffId > 0 ? staffId : JSONObject.NULL);
    Cloud.json(c, "POST", "/rest/v1/rpc/set_member", b);
  }

  // ---------- who may remove whom (the server's can_remove() makes the final check) ----------

  /** ADMIN, HOD, REGISTRAR, PROF, AP, PG, CRMI, MBBS or WORKER: from the Students/Faculty entry, else the app role. */
  static kind(db, role, staffId) {
    const s = staffId > 0 ? db.row("SELECT role FROM staff WHERE id=?", String(staffId)) : null;
    const sr = s == null ? null : Ui.nz(s.get("role"));
    if ("admin".equals(role)) return "ADMIN";
    if ("hod".equals(role) || "HOD".equals(sr)) return "HOD";
    if ("registrar".equals(role)) return "REGISTRAR";
    if (sr != null) {
      if (sr.startsWith("MBBS")) return "MBBS";
      if (sr.equals("Professor") || sr.equals("Associate Professor")) return "PROF";
      if (sr.equals("Assistant Professor")) return "AP";
      if (sr.equals("Postgraduate")) return "PG";
      if (sr.equals("CRMI")) return "CRMI";
      return "WORKER";
    }
    if ("professor".equals(role)) return "PROF";
    if ("faculty".equals(role)) return "AP";
    if ("pg".equals(role)) return "PG";
    if ("crmi".equals(role)) return "CRMI";
    return "WORKER";
  }

  static unitOf(db, staffId) {
    const s = staffId > 0 ? db.row("SELECT unit FROM staff WHERE id=?", String(staffId)) : null;
    const u = s == null ? "" : Ui.nz(s.get("unit")).trim();
    return u.isEmpty() ? null : u;
  }

  static staffOf(m) {
    return m.isNull("staff_id") ? -1 : m.optLong("staff_id", -1);
  }

  /**
   * MBBS students: the same unit's Assistant Professors or Professors (not PGs). PGs and CRMIs: the same unit's Assistant Professors
   * or Professors. Assistant Professors: the same unit's Professors. Any faculty and workers: the HOD, the Medical Registrar or
   * the admin. The Medical Registrar: the HOD or the admin. The HOD and the admin: the admin only.
   */
  static canRemove(c, db, m) {
    if (m == null || m.optString("user_id").equals(Cloud.prefs(c).getString("user_id", "")) || !Cloud.approved(c)) return false;
    const me = Cloud.role(c), target = Cloud.kind(db, m.optString("role"), Cloud.staffOf(m));
    if (target.equals("ADMIN") || target.equals("HOD")) return "admin".equals(me);
    if (target.equals("REGISTRAR")) return "admin".equals(me) || "hod".equals(me);
    if (Cloud.isManager(me)) return true;
    const tu = Cloud.unitOf(db, Cloud.staffOf(m));
    if (tu == null || !tu.equals(Cloud.unitOf(db, Cloud.myStaff(c)))) return false;
    const mine = Cloud.kind(db, me, Cloud.myStaff(c));
    if (target.equals("MBBS")) return mine.equals("AP") || mine.equals("PROF");
    if (target.equals("PG") || target.equals("CRMI")) return mine.equals("AP") || mine.equals("PROF");
    if (target.equals("AP")) return mine.equals("PROF");
    return false;
  }

  /** True when this person could remove someone (an Assistant Professor, Professor, or the HOD / Registrar / admin). */
  static mayRemoveAnyone(c, db) {
    if (Cloud.isAdmin(c)) return true;
    const k = Cloud.kind(db, Cloud.role(c), Cloud.myStaff(c));
    return (k.equals("AP") || k.equals("PROF")) && Cloud.unitOf(db, Cloud.myStaff(c)) != null;
  }

  static removeMember(c, userId) {
    Cloud.json(c, "POST", "/rest/v1/rpc/remove_member", new JSONObject().put("p_user", userId));
  }

  static claimDevice(c) {
    return Long.parseLong(Cloud.json(c, "POST", "/rest/v1/rpc/claim_device", new JSONObject()).text().trim());
  }
}
Cloud.HttpError = class extends IOException {
  constructor(code, msg) { super(msg); this.code = code; }
};
Cloud.Resp = class {
  constructor() { this.code = 0; this.body = null; }
  text() { return jstr(this.body); }
};
;
