/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Faculty photos and documents on disk, the faculty PIN, and handing files to other apps. */
class Store {
  // ---------- importing files ----------

  static safeName(s) {
    const n = s.replaceAllRx("[^A-Za-z0-9]+", "_").replaceAllRx("^_+|_+$", "");
    return n.isEmpty() ? "file" : n;
  }

  static displayName(c, uri) {
    let cur = null;
    try {
      cur = c.getContentResolver().query(uri, [OpenableColumns.DISPLAY_NAME], null, null, null);
      if (cur != null && cur.moveToFirst() && !cur.isNull(0)) return cur.getString(0);
    } catch (ignored) {
    } finally {
      if (cur != null) cur.close();
    }
    const last = uri.getLastPathSegment();
    return last == null ? "" : last;
  }

  static extOf(name) {
    const dot = name.lastIndexOf('.');
    return dot < 0 ? "" : name.substring(dot + 1).toLowerCase();
  }

  /**
   * Copies a picked file into filesDir/{dir}/{base}_{time}.{ext} and returns the relative path.
   * Photos and scans are re-saved as JPEG no larger than 2400 px to keep the phone and backups small;
   * PDFs and other files are copied unchanged.
   */
  static importUri(c, uri, dir, base) {
    const mime = Ui.nz(c.getContentResolver().getType(uri));
    const name = Store.displayName(c, uri);
    let ext = Store.extOf(name);
    if (ext.isEmpty()) ext = mime.equals("application/pdf") ? "pdf" : mime.startsWith("image/") ? "jpg" : "bin";
    const stem = dir + "/" + Store.safeName(base) + "_" + System.currentTimeMillis();
    if (mime.startsWith("image/") || ext.equals("jpg") || ext.equals("jpeg") || ext.equals("png") || ext.equals("webp") || ext.equals("heic")) {
      const bm = Store.decode(c, uri, 2400);
      if (bm != null) {
        const rel = stem + ".jpg";
        Store.writeJpeg(bm, Db.get(c).file(rel), 88);
        return rel;
      }
    }
    const rel = stem + "." + ext;
    const out = Db.get(c).file(rel);
    out.getParentFile().mkdirs();
    const inp = c.getContentResolver().openInputStream(uri);
    if (inp == null) throw new IOException("Cannot read file");
    try {
      Store.copy(inp, new FileOutputStream(out));
    } finally {
      inp.close();
    }
    return rel;
  }

  static copy(inp, out) {
    try {
      const buf = new Uint8Array(16384);
      let n;
      while ((n = inp.read(buf)) > 0) out.write(buf, 0, n);
    } finally {
      out.close();
    }
  }

  static decode(c, uri, maxPx) {
    try {
      const o = new BitmapFactory.Options();
      o.inJustDecodeBounds = true;
      let inp = c.getContentResolver().openInputStream(uri);
      BitmapFactory.decodeStream(inp, null, o);
      inp.close();
      if (o.outWidth <= 0) return null;
      o.inSampleSize = Store.sample(o, maxPx);
      o.inJustDecodeBounds = false;
      inp = c.getContentResolver().openInputStream(uri);
      const bm = BitmapFactory.decodeStream(inp, null, o);
      inp.close();
      return bm == null ? null : Store.fit(bm, maxPx);
    } catch (e) {
      return null;
    }
  }

  static sample(o, maxPx) {
    let s = 1;
    while (idiv(Math.max(o.outWidth, o.outHeight), s * 2) >= maxPx) s *= 2;
    return s;
  }

  static fit(bm, maxPx) {
    const w = bm.getWidth(), h = bm.getHeight(), m = Math.max(w, h);
    if (m <= maxPx) return bm;
    const k = maxPx / m;
    return Bitmap.createScaledBitmap(bm, Math.round(w * k), Math.round(h * k), true);
  }

  static writeJpeg(bm, f, quality) {
    f.getParentFile().mkdirs();
    const out = new FileOutputStream(f);
    try {
      bm.compress(Bitmap.CompressFormat.JPEG, quality, out);
    } finally {
      out.close();
    }
    // the picture is in memory now: later synchronous decodes of this file see it
    if (bm.canvas) { Bitmaps.decoded.set(VFS.norm(f.rel()), bm); VFS.setMeta(f.rel(), { w: bm.w, h: bm.h }); }
  }

  /** Re-saves a camera capture in place, scaled to at most maxPx. Returns false if it is not an image. */
  static shrink(f, maxPx) {
    try {
      const o = new BitmapFactory.Options();
      o.inJustDecodeBounds = true;
      BitmapFactory.decodeFile(f.getAbsolutePath(), o);
      if (o.outWidth <= 0) return false;
      o.inSampleSize = Store.sample(o, maxPx);
      o.inJustDecodeBounds = false;
      const bm = BitmapFactory.decodeFile(f.getAbsolutePath(), o);
      if (bm == null) return false;
      Store.writeJpeg(Store.fit(bm, maxPx), f, 88);
      return true;
    } catch (e) {
      return false;
    }
  }

  /** Saves a square, centre-cropped profile photo from a picked or captured image. */
  static savePhoto(c, src, srcFile, staffId) {
    let bm;
    if (src != null) bm = Store.decode(c, src, 1400);
    else {
      const o = new BitmapFactory.Options();
      o.inJustDecodeBounds = true;
      BitmapFactory.decodeFile(srcFile.getAbsolutePath(), o);
      o.inSampleSize = Store.sample(o, 1400);
      o.inJustDecodeBounds = false;
      bm = BitmapFactory.decodeFile(srcFile.getAbsolutePath(), o);
    }
    if (bm == null) throw new IOException("Not an image");
    const s = Math.min(bm.getWidth(), bm.getHeight());
    const k = Math.min(1, 640 / s);
    // Java: createBitmap(bm, x, y, s, s, scale matrix k, true)
    let sq = Bitmap.createBitmap(bm, idiv(bm.getWidth() - s, 2), idiv(bm.getHeight() - s, 2), s, s);
    if (k < 1) sq = Bitmap.createScaledBitmap(sq, Math.round(s * k), Math.round(s * k), true);
    const rel = "faculty/" + staffId + "/photo_" + System.currentTimeMillis() + ".jpg";
    Store.writeJpeg(sq, Db.get(c).file(rel), 90);
    return rel;
  }

  static sizeLabel(bytes) {
    if (bytes < 1024) return bytes + " B";
    if (bytes < 1024 * 1024) return Math.round(bytes / 1024.0) + " KB";
    return jfmt("%.1f MB", bytes / (1024.0 * 1024.0));
  }

  static kindLabel(rel) {
    const e = Store.extOf(rel);
    if (e.equals("pdf")) return "PDF";
    if (e.equals("jpg") || e.equals("jpeg") || e.equals("png") || e.equals("webp")) return "Image";
    return e.toUpperCase();
  }

  static isImage(rel) {
    return DocProvider.mimeOf(rel).startsWith("image/");
  }

  // ---------- handing files to other apps ----------

  static share(a, rel, subject) {
    const u = DocProvider.uri(rel);
    const i = new Intent(Intent.ACTION_SEND);
    i.setType(DocProvider.mimeOf(rel));
    i.putExtra(Intent.EXTRA_STREAM, u);
    i.putExtra(Intent.EXTRA_SUBJECT, subject);
    i.setClipData(ClipData.newRawUri(subject, u));
    i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
    const go = () => a.startActivity(Intent.createChooser(i, "Share " + subject));
    // Web: the file's bytes must be in memory before the browser's share sheet opens
    if (VFS.readSync(rel) == null && VFS.exists(rel)) VFS.read(rel).then(go, go); else go();
  }

  static openWith(a, rel) {
    const u = DocProvider.uri(rel);
    const i = new Intent(Intent.ACTION_VIEW);
    i.setDataAndType(u, DocProvider.mimeOf(rel));
    i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
    try {
      a.startActivity(i);
    } catch (e) {
      if (!(e instanceof ActivityNotFoundException)) throw e;
      Ui.toast(a, "No app on this phone can open this file");
    }
  }

  /** Starts the camera, writing the picture to filesDir/{rel}. Returns false if there is no camera app. */
  static capture(a, rel, req) {
    const u = DocProvider.uri(rel);
    const i = new Intent(MediaStore.ACTION_IMAGE_CAPTURE);
    i.putExtra(MediaStore.EXTRA_OUTPUT, u);
    i.setClipData(ClipData.newRawUri("capture", u));
    i.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION | Intent.FLAG_GRANT_READ_URI_PERMISSION);
    try {
      Db.get(a).file(rel).getParentFile().mkdirs();
      a.startActivityForResult(i, req);
      return true;
    } catch (e) {
      if (!(e instanceof ActivityNotFoundException)) throw e;
      Ui.toast(a, "No camera app found");
      return false;
    }
  }

  static pick(a, mimes, req) {
    const i = new Intent(Intent.ACTION_OPEN_DOCUMENT);
    i.addCategory(Intent.CATEGORY_OPENABLE);
    i.setType(mimes.length == 1 ? mimes[0] : "*/*");
    if (mimes.length > 1) i.putExtra(Intent.EXTRA_MIME_TYPES, mimes);
    try {
      a.startActivityForResult(i, req);
    } catch (e) {
      if (!(e instanceof ActivityNotFoundException)) throw e;
      Ui.toast(a, "No file picker found");
    }
  }

  // ---------- faculty PIN ----------

  static unlockedAt = 0;
  static UNLOCK_MS = 5 * 60 * 1000;

  static hash(pin) {
    const md = MessageDigest.getInstance("SHA-256");
    const d = md.digest(jbytes("tvmchmed-faculty:" + pin));
    const sb = new StringBuilder();
    for (const b of d) sb.append(jfmt("%02x", b & 0xFF));
    return sb.toString();
  }

  static hasPin(db) {
    return !db.setting("faculty_pin", "").isEmpty();
  }

  /** True while the faculty section needs the PIN. Each unlocked screen keeps it open a few minutes longer. */
  static locked(db) {
    if (!Store.hasPin(db)) return false;
    const now = System.currentTimeMillis();
    if (Store.unlockedAt > 0 && now - Store.unlockedAt < Store.UNLOCK_MS) {
      Store.unlockedAt = now;
      return false;
    }
    return true;
  }

  static unlock(db, pin) {
    if (!Store.hash(pin).equals(db.setting("faculty_pin", ""))) return false;
    Store.unlockedAt = System.currentTimeMillis();
    return true;
  }

  static lock() {
    Store.unlockedAt = 0;
  }

  static setPin(db, pin) {
    db.setSetting("faculty_pin", pin == null ? "" : Store.hash(pin));
    Store.unlockedAt = pin == null ? 0 : System.currentTimeMillis();
  }

  // ---------- faces ----------

  static initials(name) {
    const n = name.replaceAllRx("(?i)^(prof\\.?|dr\\.?|\\s)+", "").replaceAllRx("(?i)\\b(dr|prof)\\.?\\s*", "").trim();
    const sb = new StringBuilder();
    for (const w of n.jsplit("[\\s.]+")) {
      if (!w.isEmpty() && Character.isLetter(w.charAt(0))) sb.append(Character.toUpperCase(w.charAt(0)));
      if (sb.length() == 2) break;
    }
    return sb.length() == 0 ? "?" : sb.toString();
  }

  /** Round profile photo, or coloured initials when there is no photo. */
  static avatar(c, s, sizeDp, color) {
    const px = Ui.dp(c, sizeDp);
    const photo = s.get("photo");
    const bm = photo == null || photo.isEmpty() ? null : Ui.loadScaled(Db.get(c).file(photo), px * 2);
    let v;
    if (bm != null) {
      const iv = new ImageView(c);
      iv.setImageBitmap(Store.circle(bm, px));
      v = iv;
    } else {
      const t = Ui.tv(c, Store.initials(Ui.nz(s.get("name"))), sizeDp * 0.36, Color.WHITE, true);
      t.setGravity(Gravity.CENTER);
      v = t;
    }
    v.setBackground(Ui.gradient(c, [color, Ui.mix(color, 0xFF000000, 0.3)], sizeDp / 2));
    v.setOutlineProvider({
      getOutline: (view, o) => { o.setOval(0, 0, view.getWidth(), view.getHeight()); }
    });
    v.setClipToOutline(true);
    v.setLayoutParams(Ui.lp(px, px));
    return v;
  }

  /** Centre-crops a bitmap into a round one, so photos look right on every launcher and Android version. */
  static circle(src, px) {
    return Bitmaps.circle(src, px);
  }

  static roleColor(role) {
    if ("Professor".equals(role)) return Ui.PRIMARY;
    if ("Associate Professor".equals(role)) return Ui.PURPLE;
    return Ui.TEAL;
  }

  static exists(c, rel) {
    return rel != null && !rel.isEmpty() && Db.get(c).file(rel).exists();
  }

  static size(c, rel) {
    return rel == null || rel.isEmpty() ? 0 : Db.get(c).file(rel).length();
  }
}
;
/* ---- app/Lock.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * App lock for a lost or borrowed phone: once signed in, the app opens only with this phone's PIN (or fingerprint).
 * It locks when the app starts and after a few minutes away. The PIN never leaves the phone; only a salted PBKDF2 hash
 * is kept in prefs "lock". Five wrong PINs sign the phone out (email + password needed again).
 * Web: browsers give pages no fingerprint check, so only the PIN is offered.
 */
class Lock {
  static MAX_TRIES = 5;
  static MIN_LEN = 4; static MAX_LEN = 8;
  static AFTER_MINUTES = [1, 3, 5, 15];

  /** Tests turn the lock on without a real sign-in. */
  static always = false;
  /** True from a correct PIN until the app is away longer than the lock time (or the process restarts). */
  static unlocked = false;
  /** True while no screen of the app is showing; hiddenAt = elapsedRealtime when the last one went away. */
  static away = false;
  static hiddenAt = 0;

  static prefs(c) {
    return c.getSharedPreferences("lock", Context.MODE_PRIVATE);
  }

  /** The lock applies once this phone is signed in and sharing records. */
  static applies(c) {
    return Lock.always || (Cloud.requireLogin && Cloud.active(c));
  }

  static hasPin(c) {
    return !Lock.prefs(c).getString("hash", "").isEmpty();
  }

  static afterMinutes(c) {
    return Lock.prefs(c).getInt("after", 3);
  }

  static setAfterMinutes(c, m) {
    Lock.prefs(c).edit().putInt("after", m).apply();
  }

  /** Whether the lock screen must come up before this screen shows. */
  static needed(c) {
    if (!Lock.applies(c)) return false;
    if (!Lock.hasPin(c) || !Lock.unlocked) return true;
    return Lock.away && SystemClock.elapsedRealtime() - Lock.hiddenAt >= Lock.afterMinutes(c) * 60000;
  }

  /** A screen went to the background. */
  static hidden() {
    if (Lock.unlocked) { Lock.away = true; Lock.hiddenAt = SystemClock.elapsedRealtime(); }
  }

  /** A screen is showing while unlocked: the time away starts again. */
  static shown() {
    Lock.away = false;
  }

  static open(c) {
    c.startActivity(new Intent(c, LockActivity).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP | 0x10000 /* FLAG_ACTIVITY_NO_ANIMATION */));
  }

  static validPin(pin) {
    return pin != null && pin.length >= Lock.MIN_LEN && pin.length <= Lock.MAX_LEN && pin.matches("[0-9]+");
  }

  static setPin(c, pin) {
    const salt = new Uint8Array(16);
    new SecureRandom().nextBytes(salt);
    const s = Base64.encodeToString(salt, Base64.NO_WRAP);
    Lock.prefs(c).edit().putString("salt", s).putString("hash", Lock.hash(pin, salt)).putInt("fails", 0).apply();
  }

  /** Checks a PIN; a wrong one counts towards the sign-out. */
  static check(c, pin) {
    const p = Lock.prefs(c);
    const salt = Base64.decode(p.getString("salt", ""), Base64.NO_WRAP);
    const ok = Lock.hasPin(c) && MessageDigest.isEqual(jbytes(Lock.hash(pin, salt)), jbytes(p.getString("hash", "")));
    p.edit().putInt("fails", ok ? 0 : p.getInt("fails", 0) + 1).apply();
    return ok;
  }

  static triesLeft(c) {
    return Math.max(0, Lock.MAX_TRIES - Lock.prefs(c).getInt("fails", 0));
  }

  /** Forgets the PIN and fingerprint choice (sign out, forgot PIN, too many tries). The lock time is kept. */
  static clear(c) {
    Lock.prefs(c).edit().remove("salt").remove("hash").remove("fails").remove("bio").apply();
    Lock.unlocked = false;
    Lock.away = false;
  }

  static unlock() {
    Lock.unlocked = true;
    Lock.away = false;
  }

  /** PBKDF2WithHmacSHA256, 20000 rounds, 256 bits (the PIN's digits as UTF-8, as Java's chars for ASCII digits). */
  static hash(pin, salt) {
    const h = pbkdf2Sha256(jbytes(pin), salt, 20000, 32);
    return Base64.encodeToString(h, Base64.NO_WRAP);
  }

  // ---------- fingerprint ----------

  /** Tests pretend the phone has an enrolled fingerprint. */
  static bioForTests = null;

  /** Whether this phone has a fingerprint (or face) set up that the app can ask for. Never in a browser. */
  static bioAvailable(c) {
    if (Lock.bioForTests != null) return Lock.bioForTests;
    if (Build.VERSION.SDK_INT < 28) return false;
    return BiometricManager.canAuthenticate() == BiometricManager.BIOMETRIC_SUCCESS;
  }

  static bio(c) {
    return Lock.prefs(c).getBoolean("bio", false) && Lock.bioAvailable(c);
  }

  static setBio(c, on) {
    Lock.prefs(c).edit().putBoolean("bio", on).apply();
  }
}
;
/* ---- app/E2e.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * End-to-end encryption and the 7:30 AM wipe for the Duty team chat.
 *
 * Each phone makes its own key pair; only the public half is shared (table chat_keys). A message is locked on the
 * sender's phone with a fresh key, and that key is locked again for every phone of the day's team, so the server
 * only ever holds scrambled text and files. Messages, read receipts and files vanish when the DAP's duty ends.
 *
 * Web: the crypto runs on WebCrypto (ECDH P-256 keys as X.509 "spki" / PKCS#8, AES-GCM with a 12-byte IV and the
 * 128-bit tag after the cipher text), byte for byte as on the phones, so phones and the website read each other's
 * messages. Every function that does crypto returns a Promise (seal, open, sealFile, openFile, ensureKey, purgeServer).
 */
class E2e {
  static DUTY_DIR = "chat/duty/";
  static LOCKED = "🔒 This message can't be opened on this phone (it was sent before this phone's secure key reached the sender).";
  static PREFS = "e2e";

  static prefs(c) {
    return c.getApplicationContext().getSharedPreferences(E2e.PREFS, Context.MODE_PRIVATE);
  }

  static b64(b) {
    return Base64.encodeToString(b, Base64.NO_WRAP);
  }

  static unb64(s) {
    return Base64.decode(s, Base64.NO_WRAP);
  }

  static random(n) {
    const b = new Uint8Array(n);
    crypto.getRandomValues(b);
    return b;
  }

  // ---------- keys ----------

  static async newPair() {
    return crypto.subtle.generateKey({ name: "ECDH", namedCurve: "P-256" }, true, ["deriveBits"]);
  }

  /** The X.509 (spki) encoding, as Java's getEncoded() of an EC public key. */
  static async encPub(kp) {
    return new Uint8Array(await crypto.subtle.exportKey("spki", kp.publicKey));
  }

  /** The PKCS#8 encoding, as Java's getEncoded() of an EC private key. */
  static async encPriv(kp) {
    return new Uint8Array(await crypto.subtle.exportKey("pkcs8", kp.privateKey));
  }

  static async pub(s) {
    return crypto.subtle.importKey("spki", E2e.unb64(s), { name: "ECDH", namedCurve: "P-256" }, true, []);
  }

  static async priv(s) {
    return crypto.subtle.importKey("pkcs8", E2e.unb64(s), { name: "ECDH", namedCurve: "P-256" }, false, ["deriveBits"]);
  }

  /** Makes this phone's key pair once and shares the public half (again if the person was linked to another staff entry). */
  static async ensureKey(c, db) {
    const me = Chat.me(c);
    // wait for the first download, so a key this phone already shared is found rather than made again
    if (me <= 0 || db.meta("last_seq", 0) == 0) return false;
    const p = E2e.prefs(c);
    try {
      if (p.getString("pub", "").isEmpty()) {
        const kp = await E2e.newPair();
        p.edit().putString("pub", E2e.b64(await E2e.encPub(kp))).putString("priv", E2e.b64(await E2e.encPriv(kp))).remove("row").apply();
      }
    } catch (e) {
      return false;
    }
    const pub = p.getString("pub", "");
    let row = p.getLong("row", -1);
    let r = row > 0 ? db.row("SELECT * FROM chat_keys WHERE id=?", String(row)) : null;
    if (r == null) {
      const same = db.row("SELECT id FROM chat_keys WHERE pub=? LIMIT 1", pub);
      if (same != null) {
        row = Long.parseLong(same.get("id"));
        r = db.row("SELECT * FROM chat_keys WHERE id=?", String(row));
        p.edit().putLong("row", row).apply();
      }
    }
    const cv = new ContentValues();
    cv.put("staff_id", me);
    cv.put("pub", pub);
    cv.put("time", Chat.now());
    if (r == null) p.edit().putLong("row", db.insert("chat_keys", cv)).apply();
    else if (!String(me).equals(r.get("staff_id"))) db.update("chat_keys", cv, row);
    else return false;
    return true;
  }

  /** How many of these people have at least one phone that can open locked messages. */
  static ready(db, ids) {
    let n = 0;
    for (const id of ids) if (db.num("SELECT COUNT(*) FROM chat_keys WHERE staff_id=?", String(id)) > 0) n++;
    return n;
  }

  /** ECDH shared secret (the x coordinate, as Java's KeyAgreement), then SHA-256("TVMCH duty chat v1" + secret). */
  static async wrapKey(mine, theirs) {
    const secret = new Uint8Array(await crypto.subtle.deriveBits({ name: "ECDH", public: theirs }, mine, 256));
    const d = MessageDigest.getInstance("SHA-256");
    d.update(jbytes("TVMCH duty chat v1"));
    return d.digest(secret);
  }

  /** AES/GCM/NoPadding with a 128-bit tag appended to the cipher text (Java's layout). Throws GeneralSecurityException. */
  static async gcm(lock, key, iv, data) {
    try {
      const k = await crypto.subtle.importKey("raw", key, { name: "AES-GCM" }, false, [lock ? "encrypt" : "decrypt"]);
      const alg = { name: "AES-GCM", iv: iv, tagLength: 128 };
      return new Uint8Array(lock ? await crypto.subtle.encrypt(alg, k, data) : await crypto.subtle.decrypt(alg, k, data));
    } catch (e) {
      throw new GeneralSecurityException(e && e.message ? e.message : String(e));
    }
  }

  // ---------- messages ----------

  static isDutyRow(t, data) {
    return t.equals("chat_messages") && String(Chat.DUTY).equals(data.optString("chat_id"));
  }

  /** PG Connect messages (7.79): locked the same way, for the postgraduates' and the admin's phones only. */
  static isWardRow(t) {
    return t.equals(PgConnect.TABLE);
  }

  /** Rows that travel locked: the Duty team chat and PG Connect. */
  static isSealed(t, data) {
    return E2e.isDutyRow(t, data) || E2e.isWardRow(t);
  }

  /** Before upload: replaces the text and file name with a locked envelope only the day's team can open. */
  static async seal(c, db, data) {
    if ("1".equals(data.optString("deleted"))) return;
    const rel = data.isNull("file") ? "" : data.optString("file", "");
    const inner = new JSONObject()
      .put("text", data.isNull("text") ? "" : data.optString("text", ""))
      .put("file_name", data.isNull("file_name") ? "" : data.optString("file_name", ""));
    if (data.has("patient")) inner.put("patient", data.isNull("patient") ? "" : data.optString("patient", ""));
    if (!rel.isEmpty()) inner.put("fk", E2e.fileKey(c, rel, true));
    const k = E2e.random(32), iv = E2e.random(12);
    const eph = await E2e.newPair();
    const keys = new JSONObject();
    // PG Connect: only the postgraduates and the admin, worked out at each upload so new PGs get resent messages
    const members = data.has("from_ward") ? PgConnect.audience(db) : data.isNull("members") ? "" : data.optString("members", "");
    for (const r of db.rows("SELECT id, staff_id, pub FROM chat_keys")) {
      if (!"*".equals(members) && !members.contains("," + r.get("staff_id") + ",")) continue;
      try {
        const iv2 = E2e.random(12);
        const w = await E2e.gcm(true, await E2e.wrapKey(eph.privateKey, await E2e.pub(r.get("pub"))), iv2, k);
        keys.put(r.get("id"), E2e.b64(iv2) + "." + E2e.b64(w));
      } catch (ignored) {
        // a damaged key: that phone can't read this message
      }
    }
    const env = new JSONObject().put("v", 1).put("e", E2e.b64(await E2e.encPub(eph))).put("iv", E2e.b64(iv))
      .put("ct", E2e.b64(await E2e.gcm(true, k, iv, jbytes(inner.toString())))).put("k", keys);
    data.put("text", "");
    data.put("file_name", "");
    if (data.has("patient")) data.put("patient", "");
    data.put("enc", env.toString());
  }

  /** After download: opens a locked envelope with this phone's key, or leaves a note that it can't. */
  static async open(c, data) {
    const enc = data.isNull("enc") ? "" : data.optString("enc", "");
    if (enc.isEmpty()) return;
    try {
      const env = new JSONObject(enc);
      const p = E2e.prefs(c);
      const w = env.getJSONObject("k").optString(String(p.getLong("row", -1)), "");
      if (w.isEmpty() || p.getString("priv", "").isEmpty()) throw new Error("no key");
      const parts = w.jsplit("\\.");
      const k = await E2e.gcm(false, await E2e.wrapKey(await E2e.priv(p.getString("priv", "")), await E2e.pub(env.getString("e"))), E2e.unb64(parts[0]), E2e.unb64(parts[1]));
      const inner = new JSONObject(jstr(await E2e.gcm(false, k, E2e.unb64(env.getString("iv")), E2e.unb64(env.getString("ct")))));
      data.put("text", inner.optString("text", ""));
      data.put("file_name", inner.optString("file_name", ""));
      if (inner.has("patient")) data.put("patient", inner.optString("patient", ""));
      const rel = data.isNull("file") ? "" : data.optString("file", "");
      if (!rel.isEmpty() && inner.has("fk")) p.edit().putString("fk_" + rel, inner.getString("fk")).apply();
    } catch (e) {
      try {
        data.put("text", E2e.LOCKED);
        if (data.has("patient")) data.put("patient", "");
        data.put("file", "");
        data.put("file_name", "");
      } catch (ignored) {}
    }
    data.remove("enc");
  }

  /**
   * A team member's phone shared its key after some messages were sent: send this phone's messages of the current
   * duty again, locked for every key now known, so latecomers can read them. Returns true if any were queued.
   */
  static reseal(c, db) {
    const me = Chat.me(c);
    if (me <= 0) return false;
    const p = E2e.prefs(c);
    const seen = p.getString("keys_seen", ",");
    const all = new StringBuilder(",");
    let fresh = false;
    for (const r of db.rows("SELECT id FROM chat_keys ORDER BY id")) {
      all.append(r.get("id")).append(',');
      if (!seen.contains("," + r.get("id") + ",")) fresh = true;
    }
    p.edit().putString("keys_seen", all.toString()).apply();
    if (!fresh) return false;
    const mine = db.rows("SELECT id FROM chat_messages WHERE chat_id=? AND sender_id=? AND time>=? AND deleted=''",
      String(Chat.DUTY), String(me), E2e.dutyStart());
    for (const m of mine)
      db.getWritableDatabase().execSQL("INSERT OR REPLACE INTO outbox(tbl, pk) VALUES ('chat_messages', ?)", [m.get("id")]);
    // PG Connect: this phone's messages of the last week, so a new phone can read the recent conversation
    const ward = db.rows("SELECT id FROM " + PgConnect.TABLE + " WHERE sender_id=? AND time>=? AND IFNULL(deleted,'')=''",
      String(me), Chat.stamp(LocalDateTime.now().minusDays(7)));
    for (const m of ward)
      db.getWritableDatabase().execSQL("INSERT OR REPLACE INTO outbox(tbl, pk) VALUES ('" + PgConnect.TABLE + "', ?)", [m.get("id")]);
    return !mine.isEmpty() || !ward.isEmpty();
  }

  // ---------- files ----------

  static fileKey(c, rel, create) {
    const p = E2e.prefs(c);
    let k = p.getString("fk_" + rel, "");
    if (k.isEmpty() && create) {
      k = E2e.b64(E2e.random(32));
      p.edit().putString("fk_" + rel, k).apply();
    }
    return k;
  }

  /** Locks a Duty team file before upload. */
  static async sealFile(c, rel, plain) {
    if (!rel.startsWith(E2e.DUTY_DIR)) return plain;
    const iv = E2e.random(12);
    const ct = await E2e.gcm(true, E2e.unb64(E2e.fileKey(c, rel, true)), iv, plain);
    const out = new Uint8Array(12 + ct.length);
    out.set(iv, 0);
    out.set(ct, 12);
    return out;
  }

  /** Opens a downloaded Duty team file (files from before encryption have no key and are kept as they are). */
  static async openFile(c, rel, body) {
    if (!rel.startsWith(E2e.DUTY_DIR)) return body;
    const k = E2e.fileKey(c, rel, false);
    if (k.isEmpty() || body.length < 28) return body;
    const iv = body.slice(0, 12);
    const ct = body.slice(12);
    return E2e.gcm(false, E2e.unb64(k), iv, ct);
  }

  // ---------- the 7:30 AM wipe ----------

  /** When the current DAP duty began (7:30 AM today, or yesterday before 7:30 AM), as a chat time. */
  static dutyStart() {
    return Chat.stamp(E2e.dutyStartTime());
  }

  /** By the phone's real clock, like the message times (not the test clock of Dates). */
  static dutyStartTime() {
    const now = LocalDateTime.now();
    return LocalDateTime.of(now.toLocalTime().isBefore(Dates.CHANGEOVER) ? now.toLocalDate().minusDays(1) : now.toLocalDate(), Dates.CHANGEOVER);
  }

  /** Removes the earlier duty's messages, read receipts and files from this phone. Returns how many messages went. */
  static purgeLocal(c) {
    const db = Db.get(c);
    const start = E2e.dutyStart(), id = String(Chat.DUTY);
    const old = db.rows("SELECT id, file FROM chat_messages WHERE chat_id=? AND time<?", id, start);
    const reads = db.rows("SELECT id FROM chat_reads WHERE chat_id=? AND time<?", id, start);
    if (old.isEmpty() && reads.isEmpty()) return 0;
    const w = db.getWritableDatabase();
    w.beginTransaction();
    try {
      w.execSQL("INSERT INTO sync_mute VALUES (1)");
      for (const m of old) {
        w.delete("chat_messages", "id=?", [m.get("id")]);
        w.delete("outbox", "tbl='chat_messages' AND pk=?", [m.get("id")]);
      }
      for (const r of reads) {
        w.delete("chat_reads", "id=?", [r.get("id")]);
        w.delete("outbox", "tbl='chat_reads' AND pk=?", [r.get("id")]);
      }
      w.execSQL("DELETE FROM sync_mute");
      w.setTransactionSuccessful();
    } finally {
      w.endTransaction();
    }
    const e = E2e.prefs(c).edit();
    for (const m of old) {
      const rel = Ui.nz(m.get("file"));
      if (rel.isEmpty()) continue;
      db.file(rel).delete();
      w.delete("files_up", "rel=?", [rel]);
      e.remove("fk_" + rel);
    }
    e.apply();
    const nm = c.getSystemService(Context.NOTIFICATION_SERVICE);
    if (nm != null) nm.cancel(7100);
    return old.size();
  }

  /** Once per duty: asks the server to drop the earlier duty's messages and deletes their stored files. */
  static async purgeServer(c) {
    const start = E2e.dutyStart();
    const p = E2e.prefs(c);
    if (start.equals(p.getString("server_purged", ""))) return;
    let ok = true;
    try {
      await Cloud.jsonA(c, "POST", "/rest/v1/rpc/purge_duty", new JSONObject());
    } catch (e) {
      ok = false; // the server set-up has not been re-run yet; the server still hides old messages from phones
    }
    try {
      const cut = E2e.dutyStartTime().atZone(ZoneId.systemDefault()).toInstant();
      const items = new JSONArray((await Cloud.jsonA(c, "POST", "/storage/v1/object/list/files",
        new JSONObject().put("prefix", "chat/duty/").put("limit", 1000).put("offset", 0))).text());
      const gone = [];
      for (let i = 0; i < items.length(); i++) {
        const o = items.getJSONObject(i);
        const name = o.optString("name", ""), at = o.optString("created_at", "");
        if (name.isEmpty() || at.isEmpty() || o.isNull("id")) continue;
        let made;
        try {
          made = OffsetDateTime.parse(at).toInstant();
        } catch (x) {
          made = Instant.parse(at);
        }
        if (made.isBefore(cut)) gone.add("chat/duty/" + name);
      }
      for (const rel of gone)
        if (Sync.safeRel(rel)) await Cloud.httpA(c, "DELETE", "/storage/v1/object/files/" + Uri.encode(rel, "/"), null, null, await Cloud.tokenA(c));
    } catch (e) {
      ok = false;
    }
    if (ok) p.edit().putString("server_purged", start).apply();
  }
}
;
/* ---- app/DocProvider.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Hands stored faculty files and notice images to viewer, share and camera apps.
 * Web: there is no ContentProvider; a file Uri is Uri.ofRel(rel), which the runtime's share / view / camera code reads
 * from the browser's file store. The provider methods (resolve, onCreate, openFile, getType, query, insert, delete,
 * update) are not needed in the browser and are left out.
 */
class DocProvider {
  static AUTHORITY = "com.tvmchmed.app.files";

  static uri(rel) {
    return Uri.ofRel(rel);
  }

  static mimeOf(name) {
    const n = name.toLowerCase();
    if (n.endsWith(".pdf")) return "application/pdf";
    if (n.endsWith(".jpg") || n.endsWith(".jpeg")) return "image/jpeg";
    if (n.endsWith(".png")) return "image/png";
    if (n.endsWith(".webp")) return "image/webp";
    if (n.endsWith(".doc")) return "application/msword";
    if (n.endsWith(".ppt")) return "application/vnd.ms-powerpoint";
    if (n.endsWith(".pptx")) return "application/vnd.openxmlformats-officedocument.presentationml.presentation";
    if (n.endsWith(".apk")) return Updates.APK_MIME;
    if (n.endsWith(".xlsx")) return "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
    if (n.endsWith(".docx")) return "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
    // other types: the runtime's table (the phone said application/octet-stream)
    return mimeOf(name);
  }

  /** As on the phone: the type of a shared file Uri. */
  getType(uri) {
    return DocProvider.mimeOf(Ui.nz(uri.getLastPathSegment()));
  }
}
;
/* ---- app/Approvals.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Approval of new faculty and student entries. A person added by someone who cannot approve that kind of entry
 * waits as "pending" and is left out of attendance, rosters and name pickers until approved.
 * Faculty (Professor, Associate and Assistant Professor) are approved by the admin, the HOD or the Medical Registrar;
 * PGs, CRMIs and MBBS students by any faculty member (Assistant Professor, Professor or HOD).
 */
class Approvals {
  static PENDING = "pending"; static REJECTED = "rejected";

  /** SQL: entries that count (approved). Older rows have an empty status and count as approved. */
  static APPROVED_SQL = "COALESCE(approval,'')=''";

  static isStudent(role) {
    const r = Ui.nz(role);
    return r.equals("Postgraduate") || r.equals("CRMI") || r.startsWith("MBBS");
  }

  /** Who approves this kind of entry, for display. */
  static approverLabel(role) {
    if (Db.isFaculty(role)) return "the HOD";
    if (Approvals.isStudent(role)) return "a faculty member";
    return "the HOD";
  }

  /** Whether the person using this phone may approve an entry with this role. Without shared login, the phone's user can. */
  static canApprove(c, role) {
    if (!Cloud.active(c) || Cloud.isAdmin(c)) return true;
    const me = Cloud.role(c);
    return Approvals.isStudent(role) && (me.equals("professor") || me.equals("faculty"));
  }

  /** CRMIs and MBBS students: everyone on the students list except the PGs. */
  static facultyOnly(role) {
    const r = Ui.nz(role);
    return r.equals("CRMI") || r.startsWith("MBBS");
  }

  /**
   * Whether this person may add, change or remove an entry with this role on the students list. CRMIs and MBBS students
   * are added and removed only by the Assistant Professors, Associate Professors, Professors, the HOD, the Medical
   * Registrar and the admin, never by PGs (user's rule). Other entries follow the usual approval.
   */
  static mayChange(c, role) {
    return !Approvals.facultyOnly(role) || Approvals.canApprove(c, role);
  }

  static FACULTY_ONLY_NOTE = "CRMIs and MBBS students are added and removed only by the Assistant Professors, Associate Professors, Professors, the HOD and the admin.";

  static canApproveAny(c) {
    return Approvals.canApprove(c, "Postgraduate") || Approvals.canApprove(c, "Professor");
  }

  static me(c) {
    let n = Cloud.prefs(c).getString("name", "");
    if (n.isEmpty()) n = Cloud.prefs(c).getString("email", "");
    return n;
  }

  /**
   * Sets the approval fields on a staff row being saved. New entries from someone who cannot approve them wait;
   * an edit that moves a person into a role the editor cannot approve also waits.
   */
  static stamp(c, cv, old) {
    const role = cv.containsKey("role") ? cv.getAsString("role") : old == null ? "" : old.get("role");
    const can = Approvals.canApprove(c, role);
    const now = Dates.todayIso() + " " + Dates.now();
    if (old == null) {
      cv.put("added_by", Approvals.me(c));
      cv.put("added_on", now);
      if (can) {
        cv.put("approval", "");
        cv.put("approved_by", Approvals.me(c));
      } else {
        cv.put("approval", Approvals.PENDING);
        cv.put("approved_by", "");
      }
      return;
    }
    const status = Ui.nz(old.get("approval"));
    const roleChanged = cv.containsKey("role") && !Ui.nz(cv.getAsString("role")).equals(Ui.nz(old.get("role")));
    if (status.equals(Approvals.REJECTED) && !can) {
      cv.put("approval", Approvals.PENDING);                 // corrected and sent again
      cv.put("approval_note", "");
    } else if (roleChanged && !can) {
      cv.put("approval", Approvals.PENDING);
      cv.put("added_by", Approvals.me(c));
      cv.put("added_on", now);
    }
  }

  static approve(db, c, id) {
    const cv = new ContentValues();
    cv.put("approval", "");
    cv.put("approved_by", Approvals.me(c));
    cv.put("approved_on", Dates.todayIso() + " " + Dates.now());
    cv.put("approval_note", "");
    db.update("staff", cv, id);
  }

  static reject(db, c, id, reason) {
    const cv = new ContentValues();
    cv.put("approval", Approvals.REJECTED);
    cv.put("approved_by", Approvals.me(c));
    cv.put("approved_on", Dates.todayIso() + " " + Dates.now());
    cv.put("approval_note", reason);
    db.update("staff", cv, id);
  }

  /** Entries waiting for the person using this phone. */
  static waitingForMe(c, db) {
    let n = 0;
    for (const r of db.rows("SELECT role FROM staff WHERE approval=?", Approvals.PENDING)) if (Approvals.canApprove(c, r.get("role"))) n++;
    return n;
  }

  /** A small pill for lists: awaiting approval or not approved; null when approved. */
  static pill(c, s) {
    const a = Ui.nz(s.get("approval"));
    if (a.equals(Approvals.PENDING)) return Ui.softPill(c, "Awaiting approval", Ui.AMBER);
    if (a.equals(Approvals.REJECTED)) return Ui.softPill(c, "Not approved", Ui.RED);
    return null;
  }
}
