/* ---- app/Sync.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Two-way sync between this phone's database and the department's shared one.
 * Local triggers note every change in "outbox"; a sync uploads those rows (and their files),
 * then downloads everything changed on the server since the last sync. Works offline in between.
 *
 * Web: the network and crypto steps are asynchronous (the page never freezes). kick() and setListener() stay plain
 * calls; now(c, callback) calls back when done like on the phone; run(), push(), pull(), fetchFile() … return Promises.
 * Runs never overlap (the phone's single-thread executor): each waits for the one before.
 */
class Sync {
  // interface Listener { void synced(boolean changed); }
  // interface Callback { void done(String error); }

  static BATCH = 200;
  /** Re-read a few server changes before the last one seen, in case two phones saved at the same moment. */
  static OVERLAP = 50;
  static MAIN = new Handler();
  static listener = null;
  static queued = false;
  static missingFiles = new JSet();
  /** The single-thread executor: the tail of the queue of runs. */
  static EXEC = Promise.resolve();
  /** Java's "synchronized" on run(). */
  static runLock = Promise.resolve();

  static setListener(l) {
    Sync.listener = l;
  }

  /** Syncs soon (after a short pause, so a burst of saves goes up together). */
  static kick(c) {
    if (!Cloud.active(c)) return;
    if (Sync.queued) return;
    Sync.queued = true;
    Sync.MAIN.postDelayed({
      run: () => { Sync.now(c.getApplicationContext(), null); }
    }, 1500);
  }

  /** Syncs in the background; done (if any) runs on the main thread with an error message or null. */
  static now(c, done) {
    Sync.EXEC = Sync.EXEC.then(async () => {
      Sync.queued = false;
      let err = null;
      let changed = false;
      try {
        changed = await Sync.run(c);
        if (changed) Reminders.schedule(c);
        if (changed) Chat.notifyNew(c);
        if (Beacon.verifyPending(c) > 0) changed = true;
      } catch (e) {
        err = e == null ? "Error" : e.getMessage() == null ? String(e) : e.getMessage();
        if (e instanceof TypeError && /fetch|network/i.test(String(e.message))) err = "No internet connection";
      }
      Cloud.prefs(c).edit().putString("last_error", err == null ? "" : err).apply();
      const e2 = err;
      const ch = changed;
      Sync.MAIN.post({
        run: () => {
          if (Sync.listener != null) Sync.listener.synced(ch);
          if (done != null) done.done(e2);
        }
      });
    }).catch(e => console.error(e));
  }

  /** One full sync. Returns (a Promise of) true if anything on this phone changed. */
  static run(c) {
    const p = Sync.runLock.then(() => Sync.runOnce(c));
    Sync.runLock = p.catch(() => {});
    return p;
  }

  static async runOnce(c) {
    if (!Cloud.active(c)) return false;
    const db = Db.get(c);
    if (System.currentTimeMillis() - Cloud.prefs(c).getLong("role_checked", 0) > Sync.ROLE_CHECK_MS) {
      await Cloud.joinA(c, "");
      Cloud.prefs(c).edit().putLong("role_checked", System.currentTimeMillis()).apply();
      if (!Cloud.approved(c)) {
        Sync.lockOut(c);
        return true;
      }
    }
    let changed = E2e.purgeLocal(c) > 0;
    await Sync.pushDeletedFiles(c, db);
    await Sync.push(c, db);
    changed = (await Sync.pull(c, db)) || changed;
    changed = E2e.purgeLocal(c) > 0 || changed;
    const keyed = await E2e.ensureKey(c, db);
    if (E2e.reseal(c, db) | keyed) await Sync.push(c, db);
    await E2e.purgeServer(c);
    changed = (await Sync.fetchFiles(c, db)) || changed;
    Cloud.prefs(c).edit().putLong("last_sync", System.currentTimeMillis()).apply();
    return changed;
  }

  // ---------- upload ----------

  static async push(c, db) {
    const uploadedThisRun = new JSet();
    while (true) {
      const box = db.rows("SELECT * FROM outbox ORDER BY id LIMIT " + Sync.BATCH);
      if (box.isEmpty()) return;
      const arr = new JSONArray();
      for (const o of box) {
        const t = o.get("tbl"), pk = o.get("pk");
        if (!Sync.known(t)) continue;
        const rec = Sync.record(db, t, pk);
        if (!rec.getBoolean("deleted") && E2e.isSealed(t, rec.getJSONObject("data"))) await E2e.seal(c, db, rec.getJSONObject("data"));
        if (!rec.getBoolean("deleted")) await Sync.uploadFiles(c, db, rec.getJSONObject("data"), t, uploadedThisRun);
        arr.put(rec);
      }
      try {
        if (arr.length() > 0) await Sync.upsert(c, arr);
      } catch (e) {
        if (!(e instanceof Cloud.HttpError) || (e.code !== 401 && e.code !== 403 && e.code !== 400 && e.code !== 409)) throw e;
        // One row the server refuses (e.g. someone else's documents) must not block the rest.
        for (let i = 0; i < arr.length(); i++) {
          try {
            await Sync.upsert(c, new JSONArray().put(arr.get(i)));
          } catch (one) {
            if (!(one instanceof Cloud.HttpError) || (one.code !== 401 && one.code !== 403 && one.code !== 400 && one.code !== 409)) throw one;
          }
        }
      }
      const w = db.getWritableDatabase();
      for (const o of box) w.delete("outbox", "id=?", [o.get("id")]);
    }
  }

  static async upsert(c, arr) {
    await Cloud.jsonA(c, "POST", "/rest/v1/records?on_conflict=tbl,pk", arr, "Prefer", "resolution=merge-duplicates,return=minimal");
  }

  static known(t) {
    for (const x of Db.TABLES) if (x.equals(t)) return true;
    return false;
  }

  /** The server record for one local row; a missing row becomes a deletion. */
  static record(db, t, pk) {
    const rec = new JSONObject().put("tbl", t).put("pk", pk);
    const cur = db.getReadableDatabase().rawQuery("SELECT * FROM " + t + " WHERE " + Db.keyCol(t) + "=?", [pk]);
    try {
      if (!cur.moveToFirst()) {
        rec.put("deleted", true).put("data", JSONObject.NULL).put("owner_staff", JSONObject.NULL);
        return rec;
      }
      const data = new JSONObject();
      for (let i = 0; i < cur.getColumnCount(); i++) data.put(cur.getColumnName(i), cur.isNull(i) ? JSONObject.NULL : cur.getString(i));
      rec.put("deleted", false).put("data", data);
      rec.put("owner_staff", t.equals("docs") && !data.isNull("staff_id") ? Long.parseLong(data.getString("staff_id")) : JSONObject.NULL);
      return rec;
    } finally {
      cur.close();
    }
  }

  static fileOf(t, data) {
    if (t.equals("settings")) return "hod_photo".equals(data.optString("k")) && !data.isNull("v") ? data.optString("v", "") : "";
    const col = t.equals("docs") ? "file" : t.equals("staff") ? "photo" : t.equals("notices") ? "image" : t.equals("pg_leaves") ? "letter" : t.equals("acad_files") ? "file" : t.equals("chat_messages") ? "file" : t.equals("spots") || t.equals("achievements") ? "image" : t.equals("imaging_files") ? "file" : null;
    return col == null || data.isNull(col) ? "" : data.optString(col, "");
  }

  static async uploadFiles(c, db, data, t, done) {
    const rel = Sync.fileOf(t, data);
    if (rel.isEmpty() || done.contains(rel) || !Sync.safeRel(rel)) return;
    const f = db.file(rel);
    if (!f.exists() || db.num("SELECT COUNT(*) FROM files_up WHERE rel=?", rel) > 0) return;
    try {
      await Cloud.httpA(c, "POST", "/storage/v1/object/files/" + Uri.encode(rel, "/"), await E2e.sealFile(c, rel, await Sync.readFile(f)),
        DocProvider.mimeOf(rel), await Cloud.tokenA(c), "x-upsert", "true");
    } catch (e) {
      if (!(e instanceof Cloud.HttpError) || (e.code !== 403 && e.code !== 400 && e.code !== 401 && e.code !== 413)) throw e;
      return; // not allowed to share this file; the record still goes up
    }
    done.add(rel);
    const cv = new ContentValues();
    cv.put("rel", rel);
    db.getWritableDatabase().insertWithOnConflict("files_up", null, cv, SQLiteDatabase.CONFLICT_REPLACE);
  }

  /** The file's bytes, loaded from the browser's file store. */
  static async readFile(f) {
    const b = await VFS.read(f.rel());
    if (b == null) throw new FileNotFoundException(f.getPath() + " (No such file)");
    return b;
  }

  static async pushDeletedFiles(c, db) {
    for (const r of db.rows("SELECT rel FROM files_del")) {
      const rel = r.get("rel");
      try {
        if (Sync.safeRel(rel)) await Cloud.httpA(c, "DELETE", "/storage/v1/object/files/" + Uri.encode(rel, "/"), null, null, await Cloud.tokenA(c));
      } catch (e) {
        if (!(e instanceof Cloud.HttpError) || e.code >= 500) throw e;
      }
      db.getWritableDatabase().delete("files_del", "rel=?", [rel]);
    }
  }

  // ---------- download ----------

  static async pull(c, db) {
    let changed = false;
    while (true) {
      const since = db.meta("last_seq", 0);
      const q = "/rest/v1/records?select=tbl,pk,data,deleted,seq&seq=gt." + Math.max(0, since - Sync.OVERLAP) + "&order=seq.asc&limit=1000";
      const arr = new JSONArray((await Cloud.jsonA(c, "GET", q, null)).text());
      // Web: locked rows are opened first (WebCrypto is asynchronous), so the transaction below runs in one go.
      for (let i = 0; i < arr.length(); i++) await Sync.prepare(c, arr.getJSONObject(i));
      let max = since;
      let fresh = 0;
      const w = db.getWritableDatabase();
      w.beginTransaction();
      try {
        w.execSQL("INSERT INTO sync_mute VALUES (1)");
        for (let i = 0; i < arr.length(); i++) {
          const r = arr.getJSONObject(i);
          const seq = r.getLong("seq");
          if (seq > since) fresh++;
          max = Math.max(max, seq);
          if (Sync.apply(c, db, w, r)) changed = true;
        }
        w.execSQL("DELETE FROM sync_mute");
        db.setMeta("last_seq", String(max));
        w.setTransactionSuccessful();
      } finally {
        w.endTransaction();
      }
      if (fresh == 0 || arr.length() < 1000) return changed;
    }
  }

  /** Web: the E2e.open step of apply(), done before it (the same rows, the same order of checks). */
  static async prepare(c, r) {
    const t = r.optString("tbl", "");
    if (!Sync.known(t) || r.optBoolean("deleted") || r.isNull("data")) return;
    const data = r.optJSONObject("data");
    if (data == null) return;
    if (E2e.isDutyRow(t, data)) {
      if (Ui.nz(data.optString("time")).compareTo(E2e.dutyStart()) < 0) return;
      await E2e.open(c, data);
    } else if (E2e.isWardRow(t)) {
      await E2e.open(c, data);
    }
  }

  /** Writes one server record into the local table. Rows changed here and not yet uploaded are left alone. */
  static apply(c, db, w, r) {
    if (arguments.length === 3) { r = w; w = db; db = c; c = null; }
    const t = r.getString("tbl"), pk = r.getString("pk");
    if (!Sync.known(t)) return false;
    if (t.equals("settings") && pk.equals("faculty_pin")) return false;
    if (db.num("SELECT COUNT(*) FROM outbox WHERE tbl=? AND pk=?", t, pk) > 0) return false;
    const key = Db.keyCol(t);
    if (r.optBoolean("deleted") || r.isNull("data")) {
      return w.delete(t, key + "=?", [pk]) > 0;
    }
    const data = r.getJSONObject("data");
    if (c != null && E2e.isDutyRow(t, data)) {
      if (Ui.nz(data.optString("time")).compareTo(E2e.dutyStart()) < 0) return w.delete(t, key + "=?", [pk]) > 0;
      // E2e.open(c, data) already ran in prepare()
    }
    const cols = Sync.columns(w, t);
    const cv = new ContentValues();
    for (const k of data.keySet()) {
      if (!cols.contains(k)) continue;
      if (data.isNull(k)) cv.putNull(k);
      else cv.put(k, data.getString(k));
    }
    cv.put(key, pk);
    if (Sync.same(db, t, key, pk, cv)) return false;
    // Natural-key tables (one CMCHIS row per week and ward, etc.) replace a clashing row made on another phone.
    w.insertWithOnConflict(t, null, cv, SQLiteDatabase.CONFLICT_REPLACE);
    return true;
  }

  static same(db, t, key, pk, cv) {
    const cur = db.row("SELECT * FROM " + t + " WHERE " + key + "=?", pk);
    if (cur == null) return false;
    for (const k of cv.keySet()) {
      const v = cv.get(k);
      if (!Ui.nz(cur.get(k)).equals(v == null ? "" : v.toString())) return false;
    }
    return true;
  }

  static COLS = new JMap();

  static columns(w, t) {
    let s = Sync.COLS.get(t);
    if (s != null) return s;
    s = new JSet();
    const c = w.rawQuery("PRAGMA table_info(" + t + ")", null);
    try {
      while (c.moveToNext()) s.add(c.getString(1));
    } finally {
      c.close();
    }
    Sync.COLS.put(t, s);
    return s;
  }

  /** Only our own folders, no climbing out of them: file names come from other phones. */
  static safeRel(rel) {
    return rel.matches("(faculty|notices|leaves|academics|chat|spots|achievements|imaging)/[A-Za-z0-9_./-]+") && !rel.contains("..");
  }

  /** Downloads one shared file now (presentations are fetched only when someone opens them). Returns a Promise. */
  static async fetchFile(c, db, rel) {
    if (!Sync.safeRel(rel)) throw new IOException("Bad file name");
    const resp = await Cloud.httpA(c, "GET", "/storage/v1/object/authenticated/files/" + Uri.encode(rel, "/"), null, null, await Cloud.tokenA(c));
    let body;
    try {
      body = await E2e.openFile(c, rel, resp.body);
    } catch (e) {
      if (!(e instanceof GeneralSecurityException)) throw e;
      throw new IOException("This file can't be opened on this phone");
    }
    const f = db.file(rel);
    f.getParentFile().mkdirs();
    const tmp = new File(f.getPath() + ".part");
    const o = new FileOutputStream(tmp);
    try {
      o.write(body);
    } finally {
      o.close();
    }
    if (!tmp.renameTo(f)) throw new IOException("Could not save " + rel);
    const cv = new ContentValues();
    cv.put("rel", rel);
    db.getWritableDatabase().insertWithOnConflict("files_up", null, cv, SQLiteDatabase.CONFLICT_REPLACE);
  }

  /** Downloads photos and documents that other phones added. */
  static async fetchFiles(c, db) {
    const want = [];
    for (const r of db.rows("SELECT file AS f FROM docs UNION SELECT photo FROM staff UNION SELECT image FROM notices UNION SELECT letter FROM pg_leaves UNION SELECT v FROM settings WHERE k='hod_photo' UNION SELECT file FROM chat_messages WHERE file LIKE 'chat/%.jpg' AND deleted='' UNION SELECT image FROM spots UNION SELECT image FROM achievements UNION SELECT file FROM imaging_files")) {
      const rel = r.get("f");
      if (!rel.isEmpty() && Sync.safeRel(rel) && !db.file(rel).exists() && !Sync.missingFiles.contains(rel)) want.add(rel);
    }
    let got = false;
    for (const rel of want) {
      try {
        const resp = await Cloud.httpA(c, "GET", "/storage/v1/object/authenticated/files/" + Uri.encode(rel, "/"), null, null, await Cloud.tokenA(c));
        const body = await E2e.openFile(c, rel, resp.body);
        const f = db.file(rel);
        f.getParentFile().mkdirs();
        const tmp = new File(f.getPath() + ".part");
        const o = new FileOutputStream(tmp);
        o.write(body);
        o.close();
        if (!tmp.renameTo(f)) throw new IOException("Could not save " + rel);
        const cv = new ContentValues();
        cv.put("rel", rel);
        db.getWritableDatabase().insertWithOnConflict("files_up", null, cv, SQLiteDatabase.CONFLICT_REPLACE);
        got = true;
      } catch (e) {
        if (e instanceof Cloud.HttpError) {
          if (e.code >= 500) throw e;
          Sync.missingFiles.add(rel); // not shared with this user, or not uploaded yet
        } else if (e instanceof GeneralSecurityException) {
          Sync.missingFiles.add(rel); // a Duty team file this phone has no key for
        } else throw e;
      }
    }
    return got;
  }

  // ---------- joining ----------

  /** True when the department's shared database has no records yet. */
  static async serverEmpty(c) {
    return new JSONArray((await Cloud.jsonA(c, "GET", "/rest/v1/records?select=pk&limit=1", null)).text()).length() == 0;
  }

  /** True when this phone holds records someone typed in (not just the built-in units and settings). */
  static localData(db) {
    for (const t of Db.TABLES)
      if (!t.equals("units") && !t.equals("settings") && db.num("SELECT COUNT(*) FROM " + t) > 0) return true;
    return false;
  }

  /**
   * Starts sharing on this phone. upload = true sends this phone's records as the department's
   * starting data; false replaces this phone's records with the shared ones. Returns a Promise.
   */
  static async start(c, upload) {
    const db = Db.get(c);
    const device = Long.parseLong((await Cloud.jsonA(c, "POST", "/rest/v1/rpc/claim_device", new JSONObject())).text().trim());
    const w = db.getWritableDatabase();
    w.beginTransaction();
    try {
      w.execSQL("DELETE FROM outbox");
      w.execSQL("DELETE FROM files_up");
      w.execSQL("DELETE FROM files_del");
      if (upload) {
        for (const t of Db.TABLES)
          w.execSQL("INSERT OR REPLACE INTO outbox(tbl, pk) SELECT '" + t + "', " + Db.keyCol(t) + " FROM " + t
            + (t.equals("settings") ? " WHERE k NOT IN ('faculty_pin')" : ""));
      } else {
        w.execSQL("INSERT INTO sync_mute VALUES (1)");
        for (const t of Db.TABLES) {
          if (t.equals("settings")) w.execSQL("DELETE FROM settings WHERE k NOT IN ('faculty_pin')");
          else w.execSQL("DELETE FROM " + t);
        }
        w.execSQL("DELETE FROM sync_mute");
      }
      db.setMeta("last_seq", "0");
      db.setMeta("id_next", "0");
      // Java: device << 32 (a long)
      db.setMeta("id_base", String(device * 4294967296));
      w.setTransactionSuccessful();
    } finally {
      w.endTransaction();
    }
    Sync.missingFiles.clear();
  }

  /** How often a phone asks the server whether this person still has access. */
  static ROLE_CHECK_MS = 2 * 60 * 1000;

  /**
   * The admin removed this person (or their account is gone): delete the department's records,
   * case sheets and files from this phone Only the sign-in page is left, saying why.
   */
  static lockOut(c) {
    const db = Db.get(c);
    const w = db.getWritableDatabase();
    w.beginTransaction();
    try {
      w.execSQL("INSERT INTO sync_mute VALUES (1)");
      for (const t of Db.TABLES) if (!t.equals("units")) w.execSQL("DELETE FROM " + t);
      for (const t of Db.LOCAL_TABLES) w.execSQL("DELETE FROM " + t);
      w.execSQL("DELETE FROM outbox");
      w.execSQL("DELETE FROM files_up");
      w.execSQL("DELETE FROM files_del");
      w.execSQL("DELETE FROM sync_mute");
      w.setTransactionSuccessful();
    } finally {
      w.endTransaction();
    }
    Sync.deleteTree(c.getFilesDir(), false);
    Sync.deleteTree(c.getCacheDir(), false);
    Sync.missingFiles.clear();
    db.setMeta("id_base", "0");
    db.setMeta("last_seq", "0");
  }

  static deleteTree(f, self) {
    if (f == null) return;
    const kids = f.listFiles();
    if (kids != null) for (const k of kids) Sync.deleteTree(k, true);
    if (self) f.delete();
  }

  /** Stops sharing on this phone (records stay here; a later sign-in starts afresh). */
  static leave(c) {
    const db = Db.get(c);
    db.setMeta("id_base", "0");
    db.setMeta("last_seq", "0");
    Cloud.signOut(c);
  }
}
;
/* ---- app/Reminders.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Reminders on this phone shortly before the user's own classes, academic sessions and duties:
 * classes they take, conferences / journal clubs they present or moderate, DAP duty, the daily duty roster
 * and the ward duty list. The person is matched by name (or phone number) in those records.
 * Everything runs on the phone; nothing new is stored online.
 * (In the browser, alarms and notifications are runtime no-ops; the data logic is unchanged.)
 */
class Reminders {
  static CHANNEL = "reminders";
  static LEADS = [10, 15, 30, 60, 120];
  static LEAD_LABELS = ["10 minutes before", "15 minutes before", "30 minutes before", "1 hour before", "2 hours before"];
  static REFRESH_MS = 3 * 60 * 60 * 1000;   // look again (and fetch new rosters) at least every 3 hours
  static CLOCK = Pattern.compile("(\\d{1,2})(?:[.:](\\d{2}))?\\s*(am|pm)", Pattern.CASE_INSENSITIVE);
  static TITLES = new JSet(["dr", "prof", "professor", "mr", "mrs", "ms", "md", "mbbs", "dnb", "pg", "crri", "crmi", "asst", "assoc", "ap", "hod", "chief", "dap"]);

  static prefs(c) {
    return c.getSharedPreferences("reminders", Context.MODE_PRIVATE);
  }

  static on(c) {
    return Reminders.prefs(c).getBoolean("on", true);
  }

  static lead(c) {
    return Reminders.prefs(c).getInt("lead", 30);
  }

  /** Whose reminders this phone shows: the name chosen in Settings, else the signed-in member's name. */
  static myName(c, db) {
    const n = Reminders.prefs(c).getString("name", "");
    if (!n.isEmpty()) return n;
    const sid = Cloud.myStaff(c);
    if (sid > 0) {
      const s = db.row("SELECT name FROM staff WHERE id=?", String(sid));
      if (s != null && !Ui.nz(s.get("name")).isEmpty()) return s.get("name");
    }
    return Approvals.me(c).contains("@") ? "" : Approvals.me(c);
  }

  static myPhone(db, name) {
    if (name.isEmpty()) return "";
    const s = db.row("SELECT phone FROM staff WHERE name=? AND phone<>'' LIMIT 1", name);
    const d = s == null ? "" : Ui.nz(s.get("phone")).replaceAllRx("\\D", "");
    return d.length >= 10 ? d.substring(d.length - 10) : "";
  }

  // ---------- matching ----------

  static tokens(s) {
    const out = new JSet();
    for (const t of Ui.nz(s).toLowerCase().jsplit("[^a-z]+"))
      if (t.length > 1 && !Reminders.TITLES.contains(t)) out.add(t);
    return out;
  }

  /** Whether one line of a roster or a name field names this person: same phone number, or every part of their name. */
  static names(line, me, phone) {
    if (!phone.isEmpty() && Ui.nz(line).replaceAllRx("\\D", "").contains(phone)) return true;
    return !me.isEmpty() && Reminders.tokens(line).containsAll(me);
  }

  static anyLine(field, me, phone) {
    for (const l of Ui.nz(field).jsplit("[\\n,;/]")) if (Reminders.names(l, me, phone)) return true;
    return false;
  }

  static clock(s, def) {
    if (Ui.nz(s).matches("\\d{1,2}:\\d{2}")) {
      try {
        return LocalTime.parse(s.length === 4 ? "0" + s : s);
      } catch (e) {
      }
    }
    const m = Reminders.CLOCK.matcher(Ui.nz(s));
    if (!m.find()) return def;
    let h = Integer.parseInt(m.group(1)) % 12;
    if (m.group(3).equalsIgnoreCase("pm")) h += 12;
    const min = m.group(2) == null ? 0 : Integer.parseInt(m.group(2));
    return LocalTime.of(Math.min(h, 23), Math.min(min, 59));
  }

  // ---------- what is coming up ----------

  /** This person's classes, sessions and duties starting between from and to, earliest first. */
  static upcoming(c, db, from, to) {
    const name = Reminders.myName(c, db);
    const me = Reminders.tokens(name);
    const phone = Reminders.myPhone(db, name);
    const out = new JMap();
    if (me.isEmpty() && phone.isEmpty()) return [];
    const d0 = from.toLocalDate().toString(), d1 = to.toLocalDate().toString();
    const nine = LocalTime.of(9, 0), eight = LocalTime.of(8, 0);
    const Item = Reminders.Item;

    for (const r of db.rows("SELECT * FROM classes WHERE date BETWEEN ? AND ?", d0, d1)) {
      if (!Reminders.anyLine(r.get("taken_by"), me, phone)) continue;
      const kind = Db.label(Db.CLASS_KINDS, Db.CLASS_LABELS, r.get("kind"));
      Reminders.add(out, from, to, new Item("class" + r.get("id") + "@" + r.get("date") + r.get("time"), kind + ": " + r.get("topic"),
        "You are taking this class" + Reminders.where(r.get("unit")), Reminders.at(r.get("date"), Reminders.clock(r.get("time"), nine)), "AcademicActivity"));
    }
    for (const r of db.rows("SELECT * FROM academics WHERE date BETWEEN ? AND ?", d0, d1)) {
      const pres = Reminders.anyLine(r.get("presenter"), me, phone), mod = Reminders.anyLine(r.get("moderator"), me, phone);
      if (!pres && !mod) continue;
      const kind = Db.label(Db.ACAD_KINDS, Db.ACAD_LABELS, r.get("kind"));
      Reminders.add(out, from, to, new Item("acad" + r.get("id") + "@" + r.get("date") + r.get("time"), kind + ": " + r.get("topic"),
        (pres ? "You are presenting" : "You are the moderator") + Reminders.where(r.get("unit")),
        Reminders.at(r.get("date"), Reminders.clock(r.get("time"), nine)), "AcademicActivity"));
    }
    for (const r of db.rows("SELECT * FROM dap WHERE date BETWEEN ? AND ?", d0, d1)) {
      if (!Reminders.anyLine(r.get("dap_name"), me, phone)) continue;
      Reminders.add(out, from, to, new Item("dap@" + r.get("date"), "DAP duty from 7:30 AM",
        "You are the Duty Assistant Professor" + Reminders.where(r.get("unit")) + " for 24 hours, till 7:30 AM next day", Reminders.at(r.get("date"), Dates.CHANGEOVER), "DapActivity"));
    }
    for (const r of db.rows("SELECT * FROM duty_roster WHERE date BETWEEN ? AND ?", d0, d1)) {
      for (const g of Roster.FIELDS) {
        for (const f of g) {
          if (!Reminders.anyLine(r.get(f[0]), me, phone)) continue;
          const t = f[0].equals("dap") ? Dates.CHANGEOVER : Reminders.clock(f[1], f[1].toLowerCase().contains("night") ? LocalTime.of(20, 0) : eight);
          const what = Roster.GROUPS[Reminders.groupOf(f[0])] + " · " + f[1];
          Reminders.add(out, from, to, new Item((f[0].equals("dap") ? "dap" : "roster:" + f[0]) + "@" + r.get("date"), "Duty: " + what,
            "Duty roster" + Reminders.where(r.get("unit")) + ", starts " + t, Reminders.at(r.get("date"), t), "CallDutyActivity"));
        }
      }
    }
    for (const r of db.rows("SELECT * FROM ward_duty WHERE date BETWEEN ? AND ?", d0, d1)) {
      if (!Reminders.anyLine(r.get("pg"), me, phone) && !Reminders.anyLine(r.get("crri"), me, phone)) continue;
      Reminders.add(out, from, to, new Item("ward:" + r.get("unit") + "@" + r.get("date"), "Ward duty: " + Db.unitName(r.get("unit")),
        "You are on ward duty from 8 AM", Reminders.at(r.get("date"), eight), "CallDutyActivity"));
    }
    for (const r of db.rows("SELECT * FROM cal_events WHERE date BETWEEN ? AND ?", d0, d1)) {
      if (!Reminders.anyLine(r.get("people"), me, phone)) continue;
      const kind = Db.label(CalendarActivity.KINDS, CalendarActivity.KIND_LABELS, r.get("kind"));
      Reminders.add(out, from, to, new Item("cal" + r.get("id") + "@" + r.get("date") + r.get("time"), kind + ": " + r.get("title"),
        "On the academic calendar" + (Ui.nz(r.get("venue")).isEmpty() ? "" : ", at " + r.get("venue")),
        Reminders.at(r.get("date"), Reminders.clock(r.get("time"), nine)), "CalendarActivity"));
    }
    // today's MCQ, at 8 AM, if not answered yet
    const meRow = SessionAttendance.me(c, db);
    for (const q of db.rows("SELECT * FROM mcqs WHERE date BETWEEN ? AND ? ORDER BY id", d0, d1)) {
      if (meRow != null && Mcq.mine(db, q.get("id"), meRow) != null) continue;
      Reminders.add(out, from, to, new Item("mcq@" + q.get("date"), "Today's MCQ: " + Ui.nz(q.get("subject")),
        "A new case is waiting. Answer it to see the explanation", Reminders.at(q.get("date"), LocalTime.of(8, 0).plusMinutes(Reminders.lead(c))), "McqActivity"));
    }
    const list = ArrayList(out.values());
    Collections.sort(list, (a, b) => a.start.compareTo(b.start));
    return list;
  }

  static add(out, from, to, it) {
    if (it.start == null || it.start.isBefore(from) || it.start.isAfter(to)) return;
    if (!out.containsKey(it.key)) out.put(it.key, it);
  }

  static groupOf(key) {
    for (let i = 0; i < Roster.FIELDS.length; i++) for (const f of Roster.FIELDS[i]) if (f[0].equals(key)) return i;
    return 0;
  }

  static where(unit) {
    return Ui.nz(unit).isEmpty() ? "" : " (" + Db.unitName(unit) + ")";
  }

  static at(date, t) {
    const d = Dates.parse(date);
    return d == null ? null : LocalDateTime.of(d, t);
  }

  // ---------- alarms and notifications ----------

  /** The next reminder this phone will show, or null. */
  static next(c, db) {
    if (!Reminders.on(c)) return null;
    const now = LocalDateTime.now();
    const shown = Reminders.prefs(c).getStringSet("shown", new JSet());
    for (const it of Reminders.upcoming(c, db, now, now.plusDays(3))) if (!shown.contains(it.key)) return it;
    return null;
  }

  /** Sets the alarm for the next reminder (or a later look for new rosters). Safe to call often. */
  static schedule(c) {
    const app = c.getApplicationContext();
    Census.schedule(app);
    const am = app.getSystemService(Context.ALARM_SERVICE);
    const pi = PendingIntent.getBroadcast(app, 0, new Intent(app, Reminders.Receiver).setAction("com.tvmchmed.app.REMIND"),
      PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
    Beacon.refresh(app);
    if (am == null) return;
    const ble = Reminders.prefs(app).getBoolean("ble", true);
    const change = ble ? Beacon.nextChange(app, Db.get(app)) : null;
    if (!Reminders.on(app) && change == null) {
      am.cancel(pi);
      return;
    }
    const now = System.currentTimeMillis();
    let when = Reminders.on(app) ? now + Reminders.REFRESH_MS : Long.MAX_VALUE;
    const it = Reminders.next(app, Db.get(app));
    if (it != null) when = Math.min(when, Math.max(now + 1000, Reminders.millis(it.start.minusMinutes(Reminders.lead(app)))));
    if (change != null) when = Math.min(when, Math.max(now + 1000, Reminders.millis(change) + 1000));
    if (Build.VERSION.SDK_INT < 31 || am.canScheduleExactAlarms()) am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, when, pi);
    else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, when, pi);
  }

  static millis(t) {
    const d = t.toLocalDate(), tm = t.toLocalTime();
    return new Date(d.getYear(), d.getMonthValue() - 1, d.getDayOfMonth(), tm.getHour(), tm.getMinute(), tm.getSecond()).getTime();
  }

  /** Shows every reminder that is due now (started less than 15 minutes ago at the latest). Returns how many. */
  static notifyDue(c) {
    if (!Reminders.on(c)) return 0;
    const db = Db.get(c);
    const now = LocalDateTime.now();
    const lead = Reminders.lead(c);
    const shown = new JSet(Reminders.prefs(c).getStringSet("shown", new JSet()));
    let n = 0;
    for (const it of Reminders.upcoming(c, db, now.minusMinutes(15), now.plusMinutes(lead + 1))) {
      if (shown.contains(it.key) || it.start.minusMinutes(lead).isAfter(now.plusMinutes(1))) continue;
      Reminders.show(c, it);
      shown.add(it.key);
      n++;
    }
    // forget reminders of past days
    const cutoff = Dates.today().minusDays(3).toString();
    const keep = new JSet();
    for (const k of shown) {
      const at = k.indexOf('@');
      if (at < 0 || k.substring(at + 1).compareTo(cutoff) >= 0) keep.add(k);
    }
    Reminders.prefs(c).edit().putStringSet("shown", keep).apply();
    return n;
  }

  static channel(c) {
    const nm = c.getSystemService(Context.NOTIFICATION_SERVICE);
    if (nm == null || Build.VERSION.SDK_INT < 26) return;
    const ch = new NotificationChannel(Reminders.CHANNEL, "Class and duty reminders", NotificationManager.IMPORTANCE_HIGH);
    ch.setDescription("Shortly before your classes, academic sessions and duties");
    nm.createNotificationChannel(ch);
  }

  static show(c, it) {
    Reminders.channel(c);
    const nm = c.getSystemService(Context.NOTIFICATION_SERVICE);
    if (nm == null) return;
    let open = new Intent();
    try {
      // the runtime's setClassName is a no-op; resolve the screen class by name so a tap on the notification opens it
      const cls = new Function("return " + it.screen)();
      open = new Intent(c, cls);
    } catch (e) {
      open.setClassName(c, "com.tvmchmed.app." + it.screen);
    }
    open.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TOP);
    const pi = PendingIntent.getActivity(c, it.key.hashCode(), open, PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
    const when = it.start.toLocalDate().equals(Dates.today()) ? "Today " : Dates.shortFmt(it.start.toLocalDate()) + " ";
    const b = Build.VERSION.SDK_INT >= 26 ? new Notification.Builder(c, Reminders.CHANNEL) : new Notification.Builder(c);
    b.setSmallIcon(R.drawable.ic_event)
      .setContentTitle(it.title)
      .setContentText(when + it.start.toLocalTime() + " · " + it.text)
      .setStyle(new Notification.BigTextStyle().bigText(when + "at " + it.start.toLocalTime() + "\n" + it.text))
      .setWhen(Reminders.millis(it.start))
      .setShowWhen(true)
      .setColor(Ui.PRIMARY)
      .setAutoCancel(true)
      .setContentIntent(pi);
    if (Build.VERSION.SDK_INT < 26) b.setPriority(Notification.PRIORITY_HIGH).setDefaults(Notification.DEFAULT_ALL);
    nm.notify(it.key.hashCode(), b.build());
  }

  /** Android 13 and later: notifications need the user's permission. */
  static allowed(c) {
    return Build.VERSION.SDK_INT < 33 || c.checkSelfPermission("android.permission.POST_NOTIFICATIONS") === PackageManager.PERMISSION_GRANTED;
  }

  static askPermission(a, always) {
    if (Reminders.allowed(a) || !Reminders.on(a)) return;
    if (!always && Reminders.prefs(a).getBoolean("asked", false)) return;
    Reminders.prefs(a).edit().putBoolean("asked", true).apply();
    a.requestPermissions(["android.permission.POST_NOTIFICATIONS"], 77);
  }

  /** First start after this update: asks once for notifications and Bluetooth together. */
  static askAllOnce(a) {
    if (Reminders.prefs(a).getBoolean("asked_all", false)) return;
    Reminders.prefs(a).edit().putBoolean("asked_all", true).putBoolean("asked", true).apply();
    const want = [];
    if (Reminders.on(a) && !Reminders.allowed(a)) want.add("android.permission.POST_NOTIFICATIONS");
    if (Reminders.prefs(a).getBoolean("ble", true))
      for (const p of Beacon.perms()) if (a.checkSelfPermission(p) !== PackageManager.PERMISSION_GRANTED) want.add(p);
    if (!want.isEmpty()) a.requestPermissions(want, 77);
  }
}

/** One upcoming reminder. */
Reminders.Item = class {
  constructor(key, title, text, start, screen) {
    this.key = key;
    this.title = title;
    this.text = text;
    this.start = start;
    this.screen = screen;
  }
};

/** Fires at the reminder time, after a restart and after an app update. */
Reminders.Receiver = class extends BroadcastReceiver {
  onReceive(context, intent) {
    const c = context.getApplicationContext();
    const census = Census.ACTION.equals(intent.getAction());
    if (census) E2e.purgeLocal(c);
    Reminders.notifyDue(c);
    Reminders.schedule(c);
    if (!Cloud.active(c)) {
      if (census) Census.autoPost(c);
      return;
    }
    // fetch new rosters and schedules, then look again
    const pr = this.goAsync();
    const done = [false];
    const finish = {
      run: () => {
        if (done[0]) return;
        done[0] = true;
        // the 7:30 AM census goes up once this phone has the other phones' latest entries
        if (census) Census.autoPost(c);
        Reminders.notifyDue(c);
        Reminders.schedule(c);
        pr.finish();
      }
    };
    new Handler(Looper.getMainLooper()).postDelayed(finish, 25000);
    Sync.now(c, {
      done: (err) => { finish.run(); }
    });
  }
};
;
