/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Phone alerts while the app is closed. Android wakes this job about every 15 minutes when there is internet:
 * it syncs, then shows notifications for new chat messages, HOD urgent messages, the morning handover and
 * anything waiting for this person (approvals, leave letters, logbook entries to sign).
 * Web: a page cannot be woken while it is closed, so schedule() runs the same work every 15 minutes while the page is open.
 */
class Background extends JobService {
  static JOB = 7300;
  static CHANNEL = "alerts";
  static PERIOD_MS = 15 * 60 * 1000;
  static N_ALERT = 7200; static N_WAITING = 7201; static N_HANDOVER = 7202; static N_UPDATE = 7203; static N_PGC = 7204;
  /** Web: the repeating timer, started once. */
  static timer = null;

  /** Starts the repeating job once; safe to call often. */
  static schedule(c) {
    const app = c.getApplicationContext();
    if (!Cloud.active(app)) {
      if (Background.timer != null) { clearInterval(Background.timer); Background.timer = null; }
      return;
    }
    if (Background.timer != null) return;
    Background.timer = setInterval(() => { Background.work(app); }, Background.PERIOD_MS);
  }

  onStartJob(params) {
    const c = this.getApplicationContext();
    Background.work(c).then(() => this.jobFinished(params, false));
    return true;
  }

  /** The job's work (sync, then notifications), callable without JobParameters. Returns a Promise. */
  static async work(c) {
    try {
      if (Cloud.active(c)) {
        const changed = await Sync.run(c);
        if (changed) Reminders.schedule(c);
        Chat.notifyNew(c);
        Background.check(c);
        try {
          Updates.autoFetch(c, Db.get(c));
        } catch (ignored) {
          // tried again next time; the home page still offers the update
        }
      }
    } catch (ignored) {
      // no internet or the server is busy: try again next time
    }
  }

  onStopJob(params) {
    return true;
  }

  // ---------- what to tell the person ----------

  static prefs(c) {
    return c.getApplicationContext().getSharedPreferences("bg_alerts", Context.MODE_PRIVATE);
  }

  /** After a sync: new HOD urgent messages, the morning handover, and things waiting for this person. */
  static check(c) {
    if (!Cloud.active(c)) return;
    const db = Db.get(c);
    const p = Background.prefs(c);
    const e = p.edit();

    // HOD urgent messages: each new one once
    const seen = p.getString("alert_seen", "");
    let max = seen;
    let newest = null;
    for (const a of Alerts.active(db)) {
      const t = Ui.nz(a.get("posted_at"));
      if (t.compareTo(max) > 0) max = t;
      if (!seen.isEmpty() && t.compareTo(seen) > 0 && (newest == null || t.compareTo(newest.get("posted_at")) > 0)) newest = a;
    }
    e.putString("alert_seen", max.isEmpty() ? Alerts.now() : max);
    if (newest != null) Background.show(c, Background.N_ALERT, "🚨 HOD urgent message", Ui.nz(newest.get("message")), Ui.RED, MainActivity);

    // PG Connect: never the message itself on the lock screen, it is end-to-end encrypted
    const pgSeen = p.getString("pgc_seen", "");
    if (pgSeen.isEmpty()) e.putString("pgc_seen", Chat.now());
    else if (PgConnect.canUse(c, db)) {
      const n = PgConnect.newSince(c, db, pgSeen);
      e.putString("pgc_seen", Chat.now());
      if (n > 0) Background.show(c, Background.N_PGC, "💬 New message in PG Connect", n == 1 ? "1 new message for your ward" : n + " new messages for your ward", PgConnect.GREEN, PgConnectActivity);
    }

    // the handover from last night's team, once each morning
    const day = Dates.admitDay().minusDays(1).toString();
    const items = db.num("SELECT COUNT(*) FROM handovers WHERE day=?", day);
    if (items > 0 && !day.equals(p.getString("handover_day", ""))) {
      e.putString("handover_day", day);
      Background.show(c, Background.N_HANDOVER, "🔁 Handover from last night's team", items + (items == 1 ? " patient" : " patients")
        + " to see first: sick patients, pending tests and plans", Ui.TEAL, HandoverActivity);
    }

    // waiting for this person
    const lines = [];
    let total = 0;
    const ap = Approvals.canApproveAny(c) ? Approvals.waitingForMe(c, db) : 0;
    if (ap > 0) lines.add(ap + " new " + (ap == 1 ? "entry" : "entries") + " to approve");
    total += ap;
    if (SessionAttendance.canRun(c)) {
      let lv = 0;
      for (const r of db.rows("SELECT ap_status, prof_status, hod_status FROM pg_leaves"))
        if (PgLeaveActivity.overall(r).equals("Awaiting approval")) lv++;
      if (lv > 0) lines.add(lv + " PG leave " + (lv == 1 ? "letter" : "letters") + " awaiting approval");
      const lb = Logbook.waitingToSign(c, db);
      if (lb > 0) lines.add(lb + " logbook " + (lb == 1 ? "procedure" : "procedures") + " to sign");
      total += lv + lb;
    }
    const um = UnitMoves.waitingForMe(c, db).size();
    if (um > 0) lines.add(um + (um == 1 ? " case" : " cases") + " another unit asks your unit to take over");
    total += um;
    const ex = ExamCases.waitingForMe(c, db).size();
    if (ex > 0) lines.add(ex + " exam " + (ex == 1 ? "case" : "cases") + " for another unit's students to allow");
    total += ex;
    if (Cloud.isAdmin(c)) {
      const fl = db.num("SELECT COUNT(*) FROM faculty_leaves WHERE status='Applied'");
      if (fl > 0) lines.add(fl + " faculty leave " + (fl == 1 ? "request" : "requests"));
      total += fl;
    }
    const before = p.getInt("waiting", -1);
    e.putInt("waiting", total);
    if (before >= 0 && total > before) {
      const s = new StringBuilder();
      for (const l of lines) s.append(s.length() == 0 ? "" : "\n").append(l);
      Background.show(c, Background.N_WAITING, "Waiting for you · " + total, s.toString(), Ui.AMBER, MainActivity);
    }
    e.apply();
  }

  static channel(c) {
    const nm = c.getSystemService(Context.NOTIFICATION_SERVICE);
    if (nm == null || Build.VERSION.SDK_INT < 26) return;
    const ch = new NotificationChannel(Background.CHANNEL, "Urgent messages and approvals", NotificationManager.IMPORTANCE_HIGH);
    ch.setDescription("HOD urgent messages, the morning handover and things waiting for you, even when the app is closed");
    nm.createNotificationChannel(ch);
  }

  /** open: a screen class or an Intent. */
  static show(c, id, title, text, color, open) {
    if (typeof open === 'function') open = new Intent(c, open);
    Background.channel(c);
    const nm = c.getSystemService(Context.NOTIFICATION_SERVICE);
    if (nm == null) return;
    open.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TOP);
    const pi = PendingIntent.getActivity(c, id, open, PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
    const b = new Notification.Builder(c, Background.CHANNEL);
    b.setSmallIcon(R.drawable.ic_notice)
      .setContentTitle(title)
      .setContentText(text.contains("\n") ? text.substring(0, text.indexOf('\n')) : text)
      .setStyle(new Notification.BigTextStyle().bigText(text))
      .setShowWhen(true)
      .setColor(color)
      .setAutoCancel(true)
      .setContentIntent(pi);
    if (Build.VERSION.SDK_INT < 26) b.setPriority(Notification.PRIORITY_HIGH).setDefaults(Notification.DEFAULT_ALL);
    try {
      nm.notify(id, b.build());
    } catch (ignored) {
      // notifications not allowed on this phone
    }
  }

  /** Android 13 and later: asks once for permission to show notifications, so alerts can reach a closed app. */
  static askOnce(a) {
    if (Build.VERSION.SDK_INT < 33 || !Cloud.active(a)) return;
    if (a.checkSelfPermission("android.permission.POST_NOTIFICATIONS") == PackageManager.PERMISSION_GRANTED) return;
    if (Background.prefs(a).getBoolean("asked", false)) return;
    Background.prefs(a).edit().putBoolean("asked", true).apply();
    a.requestPermissions(["android.permission.POST_NOTIFICATIONS"], 78);
  }
}
;
