/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Shared screen plumbing: gradient header, database access, redraw on resume and common rows. */
class Base extends Activity {
  constructor() {
    super();
    this.db = null;
    this._scroll = null;
    this.titleText = "";          // Java: private CharSequence title
    this.subtitle = null;
    this.headerColors = Ui.HERO;
    this._actionLabel = null;
    this._actionListener = null;
    this._ticker = new Handler(Looper.getMainLooper());
    this._tick = {
      run: () => {
        Sync.kick(this);
        this._ticker.postDelayed(this._tick, 30000);
      }
    };
    this._cloudBadge = null;
  }

  onCreate(b) {
    super.onCreate(b);
    this.db = Db.get(this);
    if (!(this instanceof AccountActivity) && Cloud.loginRequired(this)) { Cloud.openLogin(this); this.finish(); }
  }

  /** False on the first-page sign-in, which has nowhere to go back to. */
  showBack() { return true; }

  onResume() {
    super.onResume();
    if (!(this instanceof AccountActivity) && Cloud.loginRequired(this)) { Cloud.openLogin(this); this.finish(); return; }
    if (!(this instanceof LockActivity)) {
      if (Lock.needed(this)) { Lock.open(this); return; }
      Lock.shown();
    }
    this.render();
    Sync.setListener({
      synced: (changed) => {
        if (this.isFinishing()) return;
        if (!(this instanceof AccountActivity) && Cloud.loginRequired(this)) { Cloud.openLogin(this); this.finish(); return; }
        if (changed && this.liveRefresh()) this.render();
        else this.refreshCloudBadge();
      }
    });
    Sync.kick(this);
    Reminders.schedule(this);
    Background.schedule(this);
    this._ticker.removeCallbacks(this._tick);
    this._ticker.postDelayed(this._tick, 30000);
  }

  onPause() {
    super.onPause();
    if (!(this instanceof LockActivity)) Lock.hidden();
    Sync.setListener(null);
    this._ticker.removeCallbacks(this._tick);
  }

  /** Whether this screen may redraw itself when records arrive from other phones (not while someone is typing). */
  liveRefresh() {
    return true;
  }

  refreshCloudBadge() {
    const cloudBadge = this._cloudBadge;
    if (cloudBadge == null) return;
    const pending = this.db.pending();
    const err = Cloud.prefs(this).getString("last_error", "");
    cloudBadge.setText(!err.isEmpty() ? "☁ !" : pending > 0 ? "☁ " + pending : "☁ ✓");
    cloudBadge.setBackground(Ui.round(this, !err.isEmpty() ? 0x66F59E0B : 0x26FFFFFF, 14));
  }

  /** abstract void render(); */
  render() {}

  onTitleChanged(t, color) {
    super.onTitleChanged(t, color);
    this.titleText = t;
  }

  headerColor(color) {
    this.headerColors = Ui.shades(color);
  }

  /** A text button shown at the right of the header. */
  headerAction(label, l) {
    this._actionLabel = label;
    this._actionListener = l;
  }

  header() {
    const headerColors = this.headerColors;
    this.getWindow().setStatusBarColor(headerColors[0]);
    const h = Ui.h(this);
    h.setBackground(new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,
      headerColors.length > 1 ? headerColors : [headerColors[0], headerColors[0]]));
    h.setPadding(Ui.dp(this, 6), Ui.dp(this, 10), Ui.dp(this, 12), Ui.dp(this, 12));
    h.setElevation(Ui.dp(this, 4));
    if (!(this instanceof MainActivity) && this.showBack()) {
      const back = new ImageView(this);
      back.setImageResource(R.drawable.ic_back);
      back.setColorFilter(Color.WHITE);
      const p = Ui.dp(this, 10);
      back.setPadding(p, p, p, p);
      back.setBackground(Ui.round(this, 0x00FFFFFF, 22));
      Ui.ripple(back, 0x44FFFFFF);
      back.setOnClickListener({ onClick: (v) => { this.finish(); } });
      h.addView(back, Ui.lp(Ui.dp(this, 44), Ui.dp(this, 44)));
    } else {
      h.setPadding(Ui.dp(this, 18), Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12));
    }
    const t = Ui.v(this);
    t.setPadding(Ui.dp(this, 4), 0, Ui.dp(this, 8), 0);
    const tt = Ui.tv(this, String(this.titleText == null ? "" : this.titleText), 20, Color.WHITE, true);
    tt.setSingleLine(true);
    tt.setEllipsize(TextUtils.TruncateAt.END);
    t.addView(tt);
    if (this.subtitle != null && !this.subtitle.isEmpty()) t.addView(Ui.tv(this, this.subtitle, 13, 0xD9FFFFFF, false));
    h.addView(t, Ui.weight(1));
    this._cloudBadge = null;
    if (Cloud.active(this) && !(this instanceof AccountActivity) && !(this instanceof LockActivity)) {
      const cloudBadge = this._cloudBadge = Ui.tv(this, "☁", 13, Color.WHITE, true);
      cloudBadge.setPadding(Ui.dp(this, 10), Ui.dp(this, 6), Ui.dp(this, 10), Ui.dp(this, 6));
      cloudBadge.setOnClickListener(this.opener(AccountActivity));
      this.refreshCloudBadge();
      h.addView(cloudBadge);
      if (this._actionLabel != null) Ui.margins(cloudBadge, 0, 0, 8, 0);
    }
    if (this._actionLabel != null) {
      const a = Ui.tv(this, this._actionLabel, 14, Color.WHITE, true);
      a.setBackground(Ui.round(this, 0x33FFFFFF, 18));
      a.setPadding(Ui.dp(this, 14), Ui.dp(this, 7), Ui.dp(this, 14), Ui.dp(this, 7));
      Ui.ripple(a, 0x44FFFFFF);
      a.setOnClickListener(this._actionListener);
      h.addView(a);
    }
    return h;
  }

  /** Replaces the screen with header + scrolling page, keeping the scroll position across redraws. */
  setPage(content) {
    const y = this._scroll == null ? 0 : this._scroll.getScrollY();
    content.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 28));
    const scroll = this._scroll = Ui.scroll(this, content);
    const root = Ui.v(this);
    root.setBackground(new Glass.Backdrop());
    root.addView(this.header(), Ui.lp(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
    root.addView(scroll, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1));
    this.setContentView(root);
    scroll.post({ run: () => { scroll.scrollTo(0, y); } });
  }

  open(cls, ...kv) {
    if (kv.length === 1 && Array.isArray(kv[0])) kv = kv[0];
    const i = new Intent(this, cls);
    for (let k = 0; k + 1 < kv.length; k += 2) i.putExtra(kv[k], kv[k + 1]);
    this.startActivity(i);
  }

  opener(cls, ...kv) {
    if (kv.length === 1 && Array.isArray(kv[0])) kv = kv[0];
    return { onClick: (v) => { this.open(cls, kv); } };
  }

  // ---------- rows shared by several screens ----------

  static sexLabel(s) {
    return "F" === s ? "Female" : "Male";
  }

  static where(p) {
    const loc = p.get("location");
    if (Db.isSpecial(loc)) return Db.shortName(loc) + " (parent " + p.get("home_unit") + ")";
    if (Db.KDP === loc) return "Kandiyaperi " + ("F" === p.get("sex") ? "female" : "male") + " ward";
    return loc + " " + ("F" === p.get("sex") ? "female" : "male") + " ward";
  }

  static statusPill(c, p) {
    const st = p.get("status");
    if (Db.DIED === st) return Ui.pill(c, "Died", Ui.SLATE);
    if (Db.DISCHARGED === st) return Ui.softPill(c, "Discharged", Ui.GREEN);
    const loc = p.get("location");
    if (Db.isSpecial(loc) || Db.KDP === loc) return Ui.pill(c, Db.shortName(loc), Ui.unitColor(loc));
    return Ui.softPill(c, "In ward", Ui.PRIMARY);
  }

  patientRow(p) {
    const db = this.db;
    const card = Ui.card(this);
    card.setOrientation(LinearLayout.HORIZONTAL);
    card.setPadding(0, 0, Ui.dp(this, 14), 0);
    const stripe = new View(this);
    stripe.setBackground(Ui.round(this, Ui.unitColor(p.get("location")), 3));
    const sp = new LinearLayout.LayoutParams(Ui.dp(this, 5), ViewGroup.LayoutParams.MATCH_PARENT);
    sp.setMargins(Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12));
    card.addView(stripe, sp);

    const body = Ui.v(this);
    body.setPadding(0, Ui.dp(this, 12), 0, Ui.dp(this, 12));
    const age = Ui.nz(p.get("age")).isEmpty() ? "" : p.get("age") + " y, ";
    body.addView(Ui.tv(this, p.get("name") + "  ·  " + age + Base.sexLabel(p.get("sex")), 16, Ui.TEXT, true));
    const ip = Ui.nz(p.get("ip_no")).isEmpty() ? "" : "IP " + p.get("ip_no") + "  ·  ";
    const bed = Ui.nz(p.get("bed")).isEmpty() ? "" : "  ·  Bed " + p.get("bed");
    body.addView(Ui.muted(this, ip + Base.where(p) + bed));
    let line = "Adm " + Dates.nice(p.get("admit_date"));
    if (!Ui.nz(p.get("outcome_date")).isEmpty()) line += "  →  " + Dates.nice(p.get("outcome_date"));
    if (!Ui.nz(p.get("diagnosis")).isEmpty()) line += "  ·  " + p.get("diagnosis");
    const d = Ui.muted(this, line);
    d.setMaxLines(2);
    body.addView(d);
    card.addView(body, Ui.weight(1));

    const right = Ui.v(this);
    right.setGravity(Gravity.END | Gravity.CENTER_VERTICAL);
    right.addView(Base.statusPill(this, p));
    const tasks = p.get("id") == null ? 0 : Tasks.pending(db, Long.parseLong(p.get("id")));
    if (tasks > 0) {
      const tk = Ui.softPill(this, "⏳ " + tasks + (tasks === 1 ? " task" : " tasks"), Tasks.COLOR);
      right.addView(tk);
      Ui.margins(tk, 0, 4, 0, 0);
    }
    if (p.get("id") != null && Db.IN === p.get("status") && ExamCases.forPatient(db, Long.parseLong(p.get("id"))) != null) {
      const ex = Ui.softPill(this, "🎓 Exam case", ExamCases.COLOR);
      right.addView(ex);
      Ui.margins(ex, 0, 4, 0, 0);
    }
    if ("1" === p.get("cmchis")) {
      const cm = Ui.softPill(this, "CMCHIS", Ui.TEAL);
      right.addView(cm);
      Ui.margins(cm, 0, 4, 0, 0);
    }
    card.addView(right, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.MATCH_PARENT));
    Ui.ripple(card, Ui.alpha(Ui.PRIMARY, 0x22));
    card.setOnClickListener(this.opener(PatientActivity, "id", p.get("id")));
    return card;
  }

  emptyNote(s) {
    const t = Ui.muted(this, s);
    t.setGravity(Gravity.CENTER);
    t.setPadding(Ui.dp(this, 24), Ui.dp(this, 18), Ui.dp(this, 24), Ui.dp(this, 18));
    return t;
  }

  /** A small list card: coloured pill, title, subtitle, right-side text. */
  entryCard(pill, pillColor, title, sub, right, l) {
    const card = Ui.card(this);
    const top = Ui.h(this);
    if (pill != null) top.addView(Ui.softPill(this, pill, pillColor));
    const sp = new View(this);
    top.addView(sp, Ui.weight(1));
    if (right != null) top.addView(Ui.muted(this, right));
    card.addView(top);
    const t = Ui.tv(this, title, 16, Ui.TEXT, true);
    card.addView(t);
    Ui.margins(t, 0, 6, 0, 0);
    if (sub != null && !sub.isEmpty()) {
      const s = Ui.muted(this, sub);
      s.setMaxLines(4);
      card.addView(s);
    }
    if (l != null) {
      Ui.ripple(card, Ui.alpha(pillColor, 0x1A));
      card.setOnClickListener(l);
    }
    return card;
  }

  // ---------- weekly academic checklist (home + academic screens) ----------

  /** States of a weekly item. */
  static INFO = 0;
  static DONE = 1;
  static DUE = 2;
  static MISSED = 3;

  static stateColor(state) {
    return state === Base.DONE ? Ui.GREEN : state === Base.DUE ? Ui.AMBER : state === Base.MISSED ? Ui.RED : 0xFF64748B;
  }

  /**
   * One weekly item as a pastel 3D tile: a glossy sphere icon, a progress ring (done of target),
   * the name and when it runs, a status and a one-line detail. Tiles sink when pressed.
   */
  scheduleLine(card, title, when, detail, state, done, target, openArgs) {
    const DONE = Base.DONE, DUE = Base.DUE, MISSED = Base.MISSED;
    const key = openArgs.length > 3 ? openArgs[3] : openArgs[1];
    let color, icon;
    switch (key) {
      case "MBBS": color = 0xFF1D4ED8; icon = R.drawable.ic_school; break;
      case "PG": color = 0xFF047857; icon = R.drawable.ic_people; break;
      case "CONF": color = 0xFF7E22CE; icon = R.drawable.ic_mic; break;
      case "JC": color = 0xFFEA580C; icon = R.drawable.ic_book; break;
      case "TOPIC": color = 0xFF0891B2; icon = R.drawable.ic_bulb; break;
      case "SYMP": color = 0xFFCA8A04; icon = R.drawable.ic_trophy; break;
      default: color = 0xFFBE123C; icon = R.drawable.ic_shield; break;
    }
    const wide = "cmchis" === key;
    const stateCol = Base.stateColor(state);
    const stateLabel = state === DONE ? "Done" : state === DUE ? "Due" : state === MISSED ? "Missed" : "Not this week";
    const ink = Ui.mix(color, Color.BLACK, 0.6);

    // a small rectangle: sphere icon, name, status with done/target, and a round "+" to log it
    const tile = Ui.v(this);
    const depth = 3;
    tile.setBackground(new Glass.Block(this, color, 14, depth));
    tile.setPadding(Ui.dp(this, 9), Ui.dp(this, 8), Ui.dp(this, 8), Ui.dp(this, 8 + depth));
    tile.setElevation(Ui.dp(this, 2));
    tile.setTag(wide ? "wide" : "tile");
    tile.setTag(R.id.tag_state, state);

    const tt = Ui.tv(this, title, 13, ink, true);
    tt.setSingleLine(true);
    tt.setEllipsize(TextUtils.TruncateAt.END);
    const dt = Ui.tv(this, wide ? when + " · " + detail : detail, 11, state === MISSED ? Ui.RED : 0xFF475569, false);
    dt.setSingleLine(true);
    dt.setEllipsize(TextUtils.TruncateAt.END);

    const status = Ui.h(this);
    status.setGravity(Gravity.CENTER_VERTICAL);
    const dot = state === DUE ? Slab.pulse(this, stateCol) : new View(this);
    if (state !== DUE) dot.setBackground(Ui.round(this, stateCol, 4));
    status.addView(dot, Ui.lp(Ui.dp(this, 7), Ui.dp(this, 7)));
    const sl = Ui.tv(this, stateLabel + (target > 0 ? "  ·  " + done + "/" + target : ""), 11, stateCol, true);
    sl.setPadding(Ui.dp(this, 5), 0, 0, 0);
    sl.setSingleLine(true);
    status.addView(sl);

    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    const gem = new View(this);
    gem.setBackground(new Glass.Crystal(this, icon, color));
    row.addView(gem, Ui.lp(Ui.dp(this, wide ? 52 : 48), Ui.dp(this, wide ? 52 : 48)));
    const mid = Ui.v(this);
    mid.setPadding(Ui.dp(this, 8), 0, Ui.dp(this, 4), 0);
    mid.addView(tt);
    mid.addView(status);
    mid.addView(dt);
    row.addView(mid, Ui.weight(1));
    tile.addView(row);
    if (wide) {
      const bar = new Slab.Progress(this, target <= 0 ? 0 : done / target, done >= target ? Ui.GREEN : color);
      tile.addView(bar, Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, Ui.dp(this, 5)));
      Ui.margins(bar, 0, 6, 0, 0);
    }

    const go = {
      onClick: (v) => {
        if ("cmchis" === openArgs[1]) this.open(CmchisActivity);
        else this.open(FormActivity, openArgs);
      }
    };
    Ui.ripple(tile, Ui.alpha(color, 0x22));
    Slab.pressable(tile, depth);
    tile.setOnClickListener(go);
    card.addView(tile);
  }

  /** A header strip for the week (number, dates, how many items are done) above the tiles laid two to a row. */
  tileGrid(collected, weekStart) {
    const INFO = Base.INFO, DONE = Base.DONE, MISSED = Base.MISSED;
    const tiles = [];
    for (let i = 0; i < collected.getChildCount(); i++) if (collected.getChildAt(i).getTag() != null) tiles.add(collected.getChildAt(i));
    collected.removeAllViews();

    const out = Ui.v(this);
    out.setPadding(Ui.dp(this, 10), 0, Ui.dp(this, 10), Ui.dp(this, 4));

    let done = 0, missed = 0, counted = 0;
    for (const t of tiles) {
      const st = t.getTag(R.id.tag_state);
      if (st !== INFO) counted++;
      if (st === DONE) done++;
      if (st === MISSED) missed++;
    }
    const head = Ui.h(this);
    head.setGravity(Gravity.CENTER_VERTICAL);
    const depth = 4;
    head.setBackground(new Slab.Face(this, [0xFF334155, 0xFF0F172A], 18, depth));
    head.setPadding(Ui.dp(this, 14), Ui.dp(this, 10), Ui.dp(this, 12), Ui.dp(this, 10 + depth));
    head.setElevation(Ui.dp(this, 3));
    const wkNo = Ui.tv(this, "WK\n" + weekStart.get(IsoFields.WEEK_OF_WEEK_BASED_YEAR), 13, 0xFFFBBF24, true);
    wkNo.setGravity(Gravity.CENTER);
    wkNo.setLineSpacing(0, 0.9);
    wkNo.setBackground(Ui.round(this, 0x26FFFFFF, 12));
    head.addView(wkNo, Ui.lp(Ui.dp(this, 46), Ui.dp(this, 46)));
    const txt = Ui.v(this);
    txt.setPadding(Ui.dp(this, 12), 0, Ui.dp(this, 8), 0);
    const range = Ui.tv(this, Dates.shortFmt(weekStart) + " – " + Dates.shortFmt(weekStart.plusDays(6)), 15, Color.WHITE, true);
    txt.addView(range);
    const dots = Ui.h(this);
    dots.setGravity(Gravity.CENTER_VERTICAL);
    for (const t of tiles) {
      const st = t.getTag(R.id.tag_state);
      const d = new View(this);
      d.setBackground(Ui.round(this, st === INFO ? 0x55FFFFFF : Base.stateColor(st), 5));
      const p = Ui.lp(Ui.dp(this, 18), Ui.dp(this, 6));
      p.setMargins(0, Ui.dp(this, 6), Ui.dp(this, 4), 0);
      dots.addView(d, p);
    }
    txt.addView(dots);
    head.addView(txt, Ui.weight(1));
    const pill = Ui.tv(this, done + " of " + counted + " done" + (missed > 0 ? "\n" + missed + " missed" : ""), 12,
      missed > 0 ? 0xFFFCA5A5 : done === counted ? 0xFF86EFAC : 0xFFE2E8F0, true);
    pill.setGravity(Gravity.CENTER);
    pill.setBackground(Ui.round(this, 0x1FFFFFFF, 14));
    pill.setPadding(Ui.dp(this, 10), Ui.dp(this, 5), Ui.dp(this, 10), Ui.dp(this, 5));
    head.addView(pill);
    const hp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    hp.setMargins(Ui.dp(this, 5), Ui.dp(this, 2), Ui.dp(this, 5), Ui.dp(this, 4));
    out.addView(head, hp);

    let row = null;
    for (const t of tiles) {
      const wide = "wide" === t.getTag();
      if (row == null || wide || row.getChildCount() === 2) {
        row = Ui.h(this);
        out.addView(row);
      }
      const p = Ui.weight(1);
      p.setMargins(Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4));
      row.addView(t, p);
      if (wide) row = null;
    }
    if (row != null && row.getChildCount() === 1) {
      const filler = new View(this);
      const p = Ui.weight(1);
      p.setMargins(Ui.dp(this, 5), 0, Ui.dp(this, 5), 0);
      row.addView(filler, p);
    }
    return out;
  }

  scheduleCard() {
    const db = this.db;
    const INFO = Base.INFO, DONE = Base.DONE, DUE = Base.DUE, MISSED = Base.MISSED;
    const today = Dates.today();
    const t = today.toString();
    const ws = Dates.weekStart(today);
    const w0 = ws.toString(), w1 = ws.plusDays(6).toString();
    const m0 = Dates.monthStart(today).toString(), m1 = Dates.monthStart(today).plusMonths(1).minusDays(1).toString();
    const card = Ui.v(this);

    // CMCHIS first, full width: it is the one with a hard weekly deadline
    const cm = db.num("SELECT COUNT(*) FROM cmchis WHERE week_start=?", w0);
    const dow = Dates.dow(today);
    this.scheduleLine(card, "CMCHIS weekly entry", "All " + Db.UNITS.length + " wards · by Sunday",
      cm + " of " + Db.UNITS.length + " wards entered", cm >= Db.UNITS.length ? DONE : (dow === 7 ? MISSED : DUE),
      cm, Db.UNITS.length, ["kind", "cmchis"]);

    const todayClasses = db.num("SELECT COUNT(*) FROM classes WHERE kind='MBBS' AND date=?", t);
    const daysElapsed = Math.min(dow, 6);
    const daysCovered = db.num("SELECT COUNT(DISTINCT date) FROM classes WHERE kind='MBBS' AND date BETWEEN ? AND ? AND date<=?", w0, w1, t);
    this.scheduleLine(card, "MBBS class", "Mon – Sat",
      dow === 7 ? "No class on Sunday" : todayClasses > 0 ? "Logged today (" + todayClasses + ")" : "Not logged today",
      dow === 7 ? INFO : todayClasses > 0 ? DONE : DUE, daysCovered, daysElapsed, ["kind", "class", "sub", "MBBS"]);

    const pg = db.num("SELECT COUNT(*) FROM classes WHERE kind='PG' AND date BETWEEN ? AND ? AND date<=?", w0, w1, t);
    this.scheduleLine(card, "MD PG class", "Twice a week", pg >= 2 ? "Both held this week" : pg + " of 2 held this week",
      pg >= 2 ? DONE : (dow >= 6 ? MISSED : DUE), pg, 2, ["kind", "class", "sub", "PG"]);

    const wed = Dates.weekday(ws, DayOfWeek.WEDNESDAY);
    const conf = db.num("SELECT COUNT(*) FROM academics WHERE kind='CONF' AND date BETWEEN ? AND ? AND date<=?", w0, w1, t);
    this.scheduleLine(card, "Physicon", "Every Wednesday",
      conf > 0 ? "Held this week" : today.isAfter(wed) ? "Wed " + Dates.shortFmt(wed) + " not logged" : "Due " + (today.equals(wed) ? "today" : "Wed " + Dates.shortFmt(wed)),
      conf > 0 ? DONE : today.isAfter(wed) ? MISSED : DUE, Math.min(conf, 1), 1, ["kind", "academic", "sub", "CONF"]);

    const anchor = Dates.parse(db.setting("jc_anchor", ""));
    const sat = Dates.weekday(ws, DayOfWeek.SATURDAY);
    const jc = db.num("SELECT COUNT(*) FROM academics WHERE kind='JC' AND date BETWEEN ? AND ? AND date<=?", w0, w1, t);
    if (Dates.isJournalClubDay(sat, anchor)) {
      this.scheduleLine(card, "Journal club", "Alternate Saturday",
        jc > 0 ? "Held this week" : today.isAfter(sat) ? "Not logged" : "Due " + (today.equals(sat) ? "today" : "Sat " + Dates.shortFmt(sat)),
        jc > 0 ? DONE : today.isAfter(sat) ? MISSED : DUE, Math.min(jc, 1), 1, ["kind", "academic", "sub", "JC"]);
    } else {
      this.scheduleLine(card, "Journal club", "Alternate Saturday",
        (jc > 0 ? "Held this week. " : "") + "Next on Sat " + Dates.shortFmt(Dates.nextJournalClub(sat.plusDays(1), anchor)),
        jc > 0 ? DONE : INFO, Math.min(jc, 1), jc > 0 ? 1 : 0, ["kind", "academic", "sub", "JC"]);
    }

    const topic = db.num("SELECT COUNT(*) FROM academics WHERE kind='TOPIC' AND date BETWEEN ? AND ? AND date<=?", w0, w1, t);
    this.scheduleLine(card, "Topic discussion", "PG · weekly", topic > 0 ? "Held this week (" + topic + ")" : "Not logged this week",
      topic > 0 ? DONE : (dow === 7 ? MISSED : DUE), Math.min(topic, 1), 1, ["kind", "academic", "sub", "TOPIC"]);

    const symp = db.num("SELECT COUNT(*) FROM academics WHERE kind='SYMP' AND date BETWEEN ? AND ? AND date<=?", m0, m1, t);
    const lateMonth = today.getDayOfMonth() > today.lengthOfMonth() - 3;
    this.scheduleLine(card, "Symposium", "Monthly", symp > 0 ? "Held in " + Dates.month(today) : "Not yet held in " + Dates.month(today),
      symp > 0 ? DONE : lateMonth ? MISSED : DUE, Math.min(symp, 1), 1, ["kind", "academic", "sub", "SYMP"]);
    return this.tileGrid(card, ws);
  }
}
;
