'use strict';
/** Teaching and academic activities: weekly checklist and the log of entries. */
class AcademicActivity extends Base {
  constructor() {
    super();
    this.filter = "ALL";
  }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Academic activities");
    this.subtitle = "Classes, conference, journal club, symposium";
    this.headerColor(Ui.PURPLE);
    this.headerAction("+ Log", this.opener(FormActivity, "kind", "academic"));
  }

  render() {
    const db = this.db;
    const page = Ui.v(this);
    for (const s of SessionAttendance.open(db)) page.addView(AcademicActivity.attendanceBanner(this, db, s));
    page.addView(Ui.heading(this, "This week", Ui.PURPLE));
    page.addView(this.scheduleCard());
    const btns = Ui.card(this);
    btns.addView(Ui.buttonRow(this,
        Ui.button(this, "+ Class", Ui.PRIMARY, this.opener(FormActivity, "kind", "class")),
        Ui.button(this, "+ Academic", Ui.PURPLE, this.opener(FormActivity, "kind", "academic"))));
    const cal = Ui.outlineButton(this, "Academic calendar", CalendarActivity.COLOR, this.opener(CalendarActivity));
    btns.addView(cal);
    Ui.margins(cal, 0, 8, 0, 0);
    page.addView(btns);

    const keys = ["ALL", "MBBS", "PG", "CONF", "JC", "SYMP", "TOPIC"];
    const labels = ["All", "MBBS class", "PG class", "Physicon", "Journal club", "Symposium", "Topic discussion"];
    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 10), Ui.dp(this, 12), Ui.dp(this, 4));
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i];
      const c = Ui.chip(this, labels[i], k.equals(this.filter), Ui.PURPLE);
      c.setOnClickListener({ onClick: (v) => { this.filter = k; this.render(); } });
      chips.addView(c);
    }
    page.addView(Ui.hscroll(this, chips));

    const filter = this.filter;
    // Presentations (PPT / PDF) for Physicon and journal club
    if ("ALL".equals(filter) || "CONF".equals(filter) || "JC".equals(filter)) {
      const pc = Ui.card(this);
      pc.addView(Ui.tv(this, "Presentations (PPT / PDF)", 15, Ui.TEXT, true));
      const bs = [];
      for (const k of ["CONF", "JC"]) {
        if (!"ALL".equals(filter) && !k.equals(filter)) continue;
        const n = PresentationsActivity.count(db, k);
        bs.add(Ui.outlineButton(this, PresentationsActivity.label(k) + (n > 0 ? " (" + n + ")" : ""), Ui.PURPLE, this.opener(PresentationsActivity, "kind", k)));
      }
      const row = Ui.buttonRow(this, bs);
      pc.addView(row);
      Ui.margins(row, 0, 8, 0, 0);
      page.addView(pc);
    }

    const items = [];
    const cls = "ALL".equals(filter) || "MBBS".equals(filter) || "PG".equals(filter);
    const aca = !"MBBS".equals(filter) && !"PG".equals(filter);
    if (cls) items.addAll("ALL".equals(filter)
        ? db.rows("SELECT *, 'class' AS src FROM classes ORDER BY date DESC, id DESC LIMIT 150")
        : db.rows("SELECT *, 'class' AS src FROM classes WHERE kind=? ORDER BY date DESC, id DESC LIMIT 150", filter));
    if (aca) items.addAll("ALL".equals(filter)
        ? db.rows("SELECT *, 'academic' AS src FROM academics ORDER BY date DESC, id DESC LIMIT 150")
        : db.rows("SELECT *, 'academic' AS src FROM academics WHERE kind=? ORDER BY date DESC, id DESC LIMIT 150", filter));
    Collections.sort(items, { compare: (a, b) => b.get("date").compareTo(a.get("date")) });
    page.addView(Ui.heading(this, "Recent entries", Ui.PURPLE));
    if (items.isEmpty()) page.addView(this.emptyNote("Nothing logged yet."));
    for (const it of items) {
      const isClass = "class".equals(it.get("src"));
      const kind = isClass ? Db.label(Db.CLASS_KINDS, Db.CLASS_LABELS, it.get("kind")) : Db.label(Db.ACAD_KINDS, Db.ACAD_LABELS, it.get("kind"));
      const who = isClass ? it.get("taken_by") : it.get("presenter");
      let line = (who.isEmpty() ? "" : (isClass ? "By " : "Presenter: ") + who + "  ·  ") + Db.unitName(it.get("unit"));
      if (!it.get("attendance").isEmpty() && !"0".equals(it.get("attendance"))) line += "  ·  " + it.get("attendance") + " attended";
      const files = isClass ? 0 : PresentationsActivity.countFor(db, it.get("id"));
      if (files > 0) line += "  ·  " + files + (files === 1 ? " file" : " files");
      const upcoming = it.get("date").compareTo(Dates.todayIso()) > 0;
      const when = (upcoming ? "Upcoming · " : "") + Dates.nice(it.get("date")) + (Ui.nz(it.get("time")).isEmpty() ? "" : " " + it.get("time"));
      const card = this.entryCard(kind, isClass ? Ui.PRIMARY : Ui.PURPLE, it.get("topic").isEmpty() ? "(no topic)" : it.get("topic"),
          line, when, this.opener(FormActivity, "kind", it.get("src"), "id", it.get("id")));
      if (!isClass && SessionAttendance.forKind(it.get("kind"))) {
        const n = SessionAttendance.count(db, it.get("id"));
        const open = SessionAttendance.isOpen(it);
        const att = Ui.outlineButton(this, open ? "Attendance open · " + n + " present" : n > 0 ? "Attendance · " + n + " present" : "Attendance",
            open ? Ui.GREEN : Ui.PURPLE, this.opener(CheckinActivity, "id", it.get("id")));
        card.addView(att);
        Ui.margins(att, 0, 8, 0, 0);
      }
      page.addView(card);
    }
    this.setPage(page);
  }

  /** "Attendance open" card: tap to check in (or, for the organiser, to show the code). */
  static attendanceBanner(a, db, s) {
    const me = SessionAttendance.me(a, db);
    const done = me != null && SessionAttendance.isPresent(db, s.get("id"), me);
    const kind = Db.label(Db.ACAD_KINDS, Db.ACAD_LABELS, s.get("kind"));
    const card = a.entryCard(done ? "Present" : "Attendance open", done ? Ui.GREEN : Ui.ORANGE, kind + ": " + s.get("topic"),
        done ? "You are marked present." : "Tap to check in with the code shown in the hall. With Bluetooth on, your phone checks in by itself.",
        null, a.opener(CheckinActivity, "id", s.get("id")));
    return card;
  }
}
;
