'use strict';
/** Faculty: add or edit a department achievement, with an optional photo (camera or gallery). */
class AchievementEditActivity extends Base {
  constructor() {
    super();
    this.form = null;
    this.id = -1;
    this.image = "";
    this.pendingCamera = null;
    this.preview = null;
  }
  static REQ_CAMERA = 71;
  static REQ_PICK = 72;

  onCreate(b) {
    super.onCreate(b);
    const s = this.getIntent().getStringExtra("id");
    if (s != null) this.id = Long.parseLong(s);
    const r = this.id >= 0 ? this.db.row("SELECT * FROM achievements WHERE id=?", String(this.id)) : null;
    if (r != null) this.image = Ui.nz(r.get("image"));
    if (b != null) {
      this.image = b.getString("image", this.image);
      this.pendingCamera = b.getString("camera");
    }
    this.setTitle(this.id >= 0 ? "Edit achievement" : "Add an achievement");
    this.headerColors = AchievementsActivity.GRADIENT;
    this.headerAction("Save", { onClick: (v) => { this.save(); } });
  }

  onSaveInstanceState(out) {
    super.onSaveInstanceState(out);
    out.putString("image", this.image);
    if (this.pendingCamera != null) out.putString("camera", this.pendingCamera);
  }

  liveRefresh() {
    return false;
  }

  render() {
    if (this.form != null) {
      this.showPreview();
      return;
    }
    const page = Ui.v(this);
    if (!AchievementsActivity.canAdd(this)) {
      page.addView(this.emptyNote("Only faculty can add achievements."));
      this.setPage(page);
      return;
    }
    const r = this.id >= 0 ? this.db.row("SELECT * FROM achievements WHERE id=?", String(this.id)) : null;
    const col = AchievementsActivity.COLOR;
    this.form = new Form(this);
    this.form.date("date", "Date", AchievementEditActivity.v(r, "date", Dates.todayIso()));
    this.form.choice("category", "Type", AchievementsActivity.CATEGORIES, AchievementsActivity.CATEGORIES, AchievementEditActivity.v(r, "category", "Award"), null);
    this.form.text("title", "Achievement (e.g. Best paper award at APICON 2026)", AchievementEditActivity.v(r, "title", ""), Form.PLAIN);
    this.form.text("people", "Who (faculty, PGs, students)", AchievementEditActivity.v(r, "people", ""), Form.TEXT);
    this.form.multi("details", "Details (event, place, journal, amount)", AchievementEditActivity.v(r, "details", ""));
    const c = Ui.card(this);
    c.addView(this.form.view);
    page.addView(c);

    const pic = Ui.card(this);
    pic.addView(Ui.title(this, "Photo (optional)"));
    pic.addView(Ui.muted(this, "A photo of the award, certificate, paper or event."));
    this.preview = Ui.v(this);
    pic.addView(this.preview);
    pic.addView(Ui.buttonRow(this,
      Ui.button(this, "Camera", col, {
        onClick: (v) => {
          this.pendingCamera = "achievements/photo_" + System.currentTimeMillis() + ".jpg";
          if (!Store.capture(this, this.pendingCamera, AchievementEditActivity.REQ_CAMERA)) this.pendingCamera = null;
        }
      }),
      Ui.outlineButton(this, "Gallery / file", col, {
        onClick: (v) => { Store.pick(this, ["image/*"], AchievementEditActivity.REQ_PICK); }
      })));
    page.addView(pic);

    const btns = Ui.v(this);
    btns.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), 0);
    btns.addView(Ui.button(this, this.id >= 0 ? "Save changes" : "Add achievement", col, { onClick: (v) => { this.save(); } }));
    if (this.id >= 0) {
      const del = Ui.outlineButton(this, "Delete", Ui.RED, {
        onClick: (v) => {
          Ui.confirm(this, "Delete this achievement?", "It will be removed for everyone.", "Delete", {
            run: () => {
              this.db.delete("achievements", this.id);
              this.finish();
            }
          });
        }
      });
      btns.addView(del);
      Ui.margins(del, 0, 10, 0, 0);
    }
    page.addView(btns);
    this.setPage(page);
    this.showPreview();
  }

  showPreview() {
    if (this.preview == null) return;
    this.preview.removeAllViews();
    const f = this.image.isEmpty() ? null : this.db.file(this.image);
    if (f == null || !f.exists()) return;
    const iv = new ImageView(this);
    iv.setImageBitmap(Ui.loadScaled(f, 1200));
    iv.setAdjustViewBounds(true);
    iv.setMaxHeight(Ui.dp(this, 260));
    this.preview.addView(iv);
    Ui.margins(iv, 0, 10, 0, 6);
    const rm = Ui.outlineButton(this, "Remove photo", Ui.SLATE, { onClick: (v) => { this.image = ""; this.showPreview(); } });
    this.preview.addView(rm);
    Ui.margins(rm, 0, 0, 0, 8);
  }

  static v(r, k, def) {
    return r == null || Ui.nz(r.get(k)).isEmpty() ? def : r.get(k);
  }

  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    if (res !== RESULT_OK) return;
    try {
      if (req === AchievementEditActivity.REQ_CAMERA && this.pendingCamera != null) {
        const f = this.db.file(this.pendingCamera);
        if (!f.exists() || f.length() === 0) return;
        Store.shrink(f, 2000);
        this.image = this.pendingCamera;
        this.pendingCamera = null;
      } else if (req === AchievementEditActivity.REQ_PICK && data != null && data.getData() != null) {
        const rel = Store.importUri(this, data.getData(), "achievements", "photo");
        if (!Store.isImage(rel)) {
          this.db.file(rel).delete();
          Ui.toast(this, "Pick a photo (JPG or PNG)");
          return;
        }
        this.image = rel;
      }
      this.showPreview();
    } catch (e) {
      Ui.toast(this, "Could not add the photo: " + e.getMessage());
    }
  }

  /** For tests: use a file already in filesDir. */
  setImage(rel) {
    this.image = rel;
    this.showPreview();
  }

  save() {
    if (this.form == null) return;
    if (!this.form.require("title", "Enter the achievement")) return;
    const cv = new ContentValues();
    for (const k of ["date", "category", "title", "people", "details"]) cv.put(k, this.form.get(k));
    cv.put("image", this.image);
    if (this.id < 0) {
      cv.put("by_name", Spots.myName(this));
      cv.put("time", Dates.todayIso() + " " + Dates.now());
      this.db.insert("achievements", cv);
      Ui.toast(this, "Achievement added");
    } else {
      this.db.update("achievements", cv, this.id);
      Ui.toast(this, "Saved");
    }
    this.finish();
  }
}
;
