/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Department achievements: awards, publications, grants, exam results, events and recognitions, newest first, with a photo. */
class AchievementsActivity extends Base {
  constructor() { super(); this.filter = ""; }
  static COLOR = 0xFFCA8A04;
  static GRADIENT = [0xFF78350F, 0xFFB45309, 0xFFF59E0B];
  static CATEGORIES = ["Award", "Publication", "Research grant", "Conference", "Exam result", "Event", "Recognition", "Other"];
  static ICONS = ["🏆", "📄", "💰", "🎤", "🎓", "🎉", "🌟", "✨"];

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Department achievements");
    this.subtitle = "Our department's proud moments";
    this.headerColors = AchievementsActivity.GRADIENT;
    if (AchievementsActivity.canAdd(this)) this.headerAction("+ Add", this.opener(AchievementEditActivity));
  }

  /** Faculty and the admin, HOD add and edit; everyone sees them. */
  static canAdd(c) {
    return SessionAttendance.canRun(c);
  }

  static icon(category) {
    for (let i = 0; i < AchievementsActivity.CATEGORIES.length; i++) if (AchievementsActivity.CATEGORIES[i] === category) return AchievementsActivity.ICONS[i];
    return "✨";
  }

  render() {
    const page = Ui.v(this);
    const total = this.db.num("SELECT COUNT(*) FROM achievements");
    const y0 = Dates.today().getYear() + "-01-01";
    const year = this.db.num("SELECT COUNT(*) FROM achievements WHERE date>=?", y0);

    const hero = Ui.v(this);
    hero.setBackground(Glass.hero(this, AchievementsActivity.GRADIENT, 22));
    hero.setPadding(Ui.dp(this, 18), Ui.dp(this, 16), Ui.dp(this, 18), Ui.dp(this, 16));
    const lp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 4));
    hero.setLayoutParams(lp);
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    const gem = new View(this);
    gem.setBackground(new Glass.Gem(this, R.drawable.ic_trophy, 0xFFF59E0B));
    top.addView(gem, Ui.lp(Ui.dp(this, 56), Ui.dp(this, 56)));
    const tx = Ui.v(this);
    tx.setPadding(Ui.dp(this, 14), 0, 0, 0);
    tx.addView(Ui.tv(this, "Department of General Medicine", 12, 0xE6FFFFFF, true));
    tx.addView(Ui.tv(this, total === 0 ? "Achievements" : total + (total === 1 ? " achievement" : " achievements"), 22, Color.WHITE, true));
    tx.addView(Ui.tv(this, year + " in " + Dates.today().getYear(), 13, 0xE6FFFFFF, false));
    top.addView(tx, Ui.weight(1));
    hero.addView(top);
    page.addView(hero);

    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 2));
    chips.addView(this.chip("", "All"));
    for (const c of AchievementsActivity.CATEGORIES) if (this.db.num("SELECT COUNT(*) FROM achievements WHERE category=?", c) > 0) chips.addView(this.chip(c, AchievementsActivity.icon(c) + " " + c));
    page.addView(Ui.hscroll(this, chips));

    const l = this.filter.isEmpty()
      ? this.db.rows("SELECT * FROM achievements ORDER BY date DESC, id DESC")
      : this.db.rows("SELECT * FROM achievements WHERE category=? ORDER BY date DESC, id DESC", this.filter);
    if (l.isEmpty()) page.addView(this.emptyNote(AchievementsActivity.canAdd(this) ? "No achievements yet. Tap + Add to record the first one." : "No achievements recorded yet."));
    for (const a of l) page.addView(this.card(a));
    this.setPage(page);
  }

  chip(key, label) {
    const c = Ui.chip(this, label, key === this.filter, AchievementsActivity.COLOR);
    c.setOnClickListener({ onClick: (v) => { this.filter = key; this.render(); } });
    return c;
  }

  card(a) {
    const c = Ui.card(this);
    c.setBackground(new Glass.Block(this, AchievementsActivity.COLOR, 20, 3));
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    top.addView(Ui.softPill(this, AchievementsActivity.icon(a.get("category")) + "  " + Ui.nz(a.get("category")), AchievementsActivity.COLOR));
    const sp = new View(this);
    top.addView(sp, Ui.weight(1));
    top.addView(Ui.muted(this, Dates.nice(a.get("date"))));
    c.addView(top);
    const t = Ui.tv(this, Ui.nz(a.get("title")), 17, 0xFF422006, true);
    c.addView(t);
    Ui.margins(t, 0, 8, 0, 0);
    if (!Ui.nz(a.get("people")).isEmpty()) {
      const p = Ui.tv(this, "★ " + a.get("people"), 14, 0xFF92400E, true);
      c.addView(p);
      Ui.margins(p, 0, 4, 0, 0);
    }
    const img = Ui.nz(a.get("image"));
    const f = img.isEmpty() ? null : this.db.file(img);
    if (f != null && f.exists()) {
      const iv = new ImageView(this);
      iv.setImageBitmap(Ui.loadScaled(f, 1200));
      iv.setAdjustViewBounds(true);
      iv.setMaxHeight(Ui.dp(this, 260));
      iv.setOnClickListener({ onClick: (v) => { Store.openWith(this, img); } });
      c.addView(iv);
      Ui.margins(iv, 0, 10, 0, 0);
    }
    if (!Ui.nz(a.get("details")).isEmpty()) {
      const d = Ui.body(this, a.get("details"));
      c.addView(d);
      Ui.margins(d, 0, 8, 0, 0);
    }
    if (AchievementsActivity.canAdd(this)) {
      Ui.ripple(c, Ui.alpha(AchievementsActivity.COLOR, 0x22));
      c.setOnClickListener(this.opener(AchievementEditActivity, "id", a.get("id")));
    }
    return c;
  }

  /** A gold card for the home page when something was achieved in the last 30 days. */
  static homeCard(a, db) {
    const r = db.row("SELECT * FROM achievements WHERE date>=? ORDER BY date DESC, id DESC LIMIT 1", Dates.today().minusDays(30).toString());
    if (r == null) return null;
    const card = Ui.h(a);
    card.setGravity(Gravity.CENTER_VERTICAL);
    card.setBackground(Glass.hero(a, AchievementsActivity.GRADIENT, 20));
    card.setPadding(Ui.dp(a, 14), Ui.dp(a, 12), Ui.dp(a, 14), Ui.dp(a, 12));
    const lp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(Ui.dp(a, 12), Ui.dp(a, 6), Ui.dp(a, 12), Ui.dp(a, 4));
    card.setLayoutParams(lp);
    const gem = new View(a);
    gem.setBackground(new Glass.Gem(a, R.drawable.ic_trophy, 0xFFF59E0B));
    card.addView(gem, Ui.lp(Ui.dp(a, 48), Ui.dp(a, 48)));
    const tx = Ui.v(a);
    tx.setPadding(Ui.dp(a, 12), 0, 0, 0);
    const tag = Ui.tv(a, "★  DEPARTMENT ACHIEVEMENT", 10, 0xFFFEF3C7, true);
    tag.setLetterSpacing(0.1);
    tx.addView(tag);
    const t = Ui.tv(a, Ui.nz(r.get("title")), 15, Color.WHITE, true);
    t.setMaxLines(2);
    t.setEllipsize(TextUtils.TruncateAt.END);
    tx.addView(t);
    if (!Ui.nz(r.get("people")).isEmpty()) tx.addView(Ui.tv(a, r.get("people"), 12, 0xE6FFFFFF, false));
    card.addView(tx, Ui.weight(1));
    card.setOnClickListener(a.opener(AchievementsActivity));
    Ui.ripple(card, 0x33FFFFFF);
    return card;
  }
}
;
