/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Admission day: the day's admissions, with hemophilia and stroke kept in their own sections. */
class AdmissionDayActivity extends Base {
  constructor() { super(); this.day = null; }

  onCreate(b) {
    super.onCreate(b);
    const d = this.getIntent().getStringExtra("date");
    this.day = d == null ? Dates.admitDay() : LocalDate.parse(d);
  }

  /** The day's admissions in one group ("" = routine, excluding hemophilia and stroke). */
  static admissions(db, iso, group) {
    const where = group.isEmpty() ? "IFNULL(p.category,'') NOT IN ('Hemophilia','Stroke')" : "p.category='" + group + "'";
    // the admission day runs from 7:30 AM to 7:30 AM the next morning
    const d = LocalDate.parse(iso);
    return db.rows("SELECT p.* FROM patients p JOIN events e ON e.patient_id=p.id AND e.type='ADMIT' WHERE "
      + "((e.date=? AND (IFNULL(e.time,'')='' OR e.time>='07:30')) OR (e.date=? AND IFNULL(e.time,'')<>'' AND e.time<'07:30')) AND " + where
      + " ORDER BY e.date DESC, e.time DESC, p.id DESC", iso, d.plusDays(1).toString());
  }

  render() {
    const iso = this.day.toString();
    const au = this.db.admittingUnits(Dates.dow(this.day));
    const unit = au.isEmpty() ? "" : au.get(0);
    this.setTitle("Admission day");
    this.subtitle = (unit.isEmpty() ? "" : unit + " admits") + " · 7:30 AM " + Dates.nice(this.day) + " to 7:30 AM " + Dates.nice(this.day.plusDays(1));
    this.headerColor(unit.isEmpty() ? Ui.PRIMARY : Ui.unitColor(unit));
    this.headerAction("+ Admit", this.opener(FormActivity, "kind", "patient", "unit", unit.isEmpty() ? this.db.todaysUnit() : unit));
    const page = Ui.v(this);

    const nav = Ui.card(this);
    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    row.addView(Ui.outlineButton(this, "‹", Ui.PRIMARY, {
      onClick: (v) => { this.day = this.day.minusDays(1); this.render(); }
    }));
    const mid = Ui.v(this);
    mid.setGravity(Gravity.CENTER);
    mid.addView(Ui.tv(this, unit.isEmpty() ? "" : Db.unitName(unit) + " admission day", 12, Ui.MUTED, false));
    mid.addView(Ui.tv(this, Dates.longFmt(this.day), 15, Ui.TEXT, true));
    row.addView(mid, Ui.weight(1));
    row.addView(Ui.outlineButton(this, "›", Ui.PRIMARY, {
      onClick: (v) => { this.day = this.day.plusDays(1); this.render(); }
    }));
    nav.addView(row);
    const gen = AdmissionDayActivity.admissions(this.db, iso, ""), hemo = AdmissionDayActivity.admissions(this.db, iso, Db.HEMOPHILIA), stroke = AdmissionDayActivity.admissions(this.db, iso, Db.STROKE);
    const stats = Ui.statRow(this,
      Ui.stat(this, String(gen.length), "Admissions", Ui.PRIMARY),
      Ui.stat(this, String(hemo.length), "Hemophilia", Ui.PINK),
      Ui.stat(this, String(stroke.length), "Stroke", Ui.PURPLE));
    nav.addView(stats);
    Ui.margins(stats, 0, 10, 0, 0);
    page.addView(nav);

    this.section(page, "Admissions (excluding hemophilia & stroke)", gen, Ui.PRIMARY);
    this.section(page, "Hemophilia", hemo, Ui.PINK);
    this.section(page, "Stroke", stroke, Ui.PURPLE);
    const note = Ui.muted(this, "Hemophilia and stroke are picked up from the diagnosis, or set as the admission group in the admission form.");
    note.setPadding(Ui.dp(this, 18), Ui.dp(this, 12), Ui.dp(this, 18), 0);
    page.addView(note);
    this.setPage(page);
  }

  section(page, title, rows, color) {
    page.addView(Ui.heading(this, title + "  ·  " + rows.length, color));
    if (rows.isEmpty()) page.addView(this.emptyNote("None"));
    for (const p of rows) page.addView(this.patientRow(p));
  }
}
;
