/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Remembers that a case was sent to ChatGPT, Claude or Gemini, so the case sheet (and the home screen) can lead the doctor
 * back to paste the answer, even when Android closed the app meanwhile. Kept on this phone for 6 hours.
 */
class AiReturn {
  static REVIEW = "review";
  static COURSE = "course";
  static KEEP_MS = 6 * 3600 * 1000;

  static prefs(c) {
    return c.getApplicationContext().getSharedPreferences("ai_return", Context.MODE_PRIVATE);
  }

  static expect(c, pid, kind, app, prompt) {
    AiReturn.prefs(c).edit().putLong("pid", pid).putString("kind", kind).putString("app", app)
      .putInt("prompt", prompt.trim().hashCode()).putLong("time", System.currentTimeMillis()).apply();
  }

  static clear(c) {
    AiReturn.prefs(c).edit().clear().apply();
  }

  /** The patient awaiting an answer, or -1. */
  static patient(c) {
    const p = AiReturn.prefs(c);
    if (System.currentTimeMillis() - p.getLong("time", 0) > AiReturn.KEEP_MS) return -1;
    return p.getLong("pid", -1);
  }

  /** {kind, app} when an answer is awaited for this patient, else null. */
  static waiting(c, pid) {
    if (pid <= 0 || AiReturn.patient(c) != pid) return null;
    return [AiReturn.prefs(c).getString("kind", AiReturn.REVIEW), AiReturn.prefs(c).getString("app", "AI")];
  }

  /** True when the text is the case we sent (not yet the AI's answer). */
  static isPrompt(c, text) {
    return text != null && text.trim().hashCode() == AiReturn.prefs(c).getInt("prompt", 0) && AiReturn.prefs(c).contains("prompt");
  }

  /** Home screen card: back to the case sheet to paste the answer. */
  static homeCard(a, db) {
    const pid = AiReturn.patient(a);
    if (pid <= 0) return null;
    const p = db.row("SELECT name FROM patients WHERE id=?", String(pid));
    if (p == null) return null;
    const c = Ui.card(a);
    c.setBackground(Ui.round(a, Ui.alpha(CaseSheetActivity.AI_COLOR, 0x1C), 16));
    const app = AiReturn.prefs(a).getString("app", "AI");
    c.addView(Ui.tv(a, "\u21A9  Paste " + app + "'s answer", 15, CaseSheetActivity.AI_COLOR, true));
    c.addView(Ui.muted(a, "Case sheet of " + p.get("name") + ". Tap to go back to it."));
    Ui.ripple(c, Ui.alpha(CaseSheetActivity.AI_COLOR, 0x22));
    c.setOnClickListener(a.opener(CaseSheetActivity, "id", String(pid)));
    return c;
  }
}
;
/* ---- app/Alerts.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** The HOD's urgent messages: a flashing banner on the home page of every phone until it expires or is withdrawn. */
class Alerts {
  constructor() {}

  static DURATIONS = ["2 hours", "6 hours", "12 hours", "24 hours", "3 days", "7 days"];
  static HOURS = [2, 6, 12, 24, 72, 168];
  static STAMP = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm");
  static SHOW = DateTimeFormatter.ofPattern("dd-MM-yyyy, h:mm a");

  static now() {
    return LocalDateTime.now().format(Alerts.STAMP);
  }

  static show(stamp) {
    try { return LocalDateTime.parse(stamp, Alerts.STAMP).format(Alerts.SHOW); } catch (e) { return Ui.nz(stamp); }
  }

  /** The HOD (admin) posts them in the shared database; on a phone that isn't shared, whoever uses it. */
  static canPost(c) {
    return !Cloud.active(c) || Cloud.isAdmin(c);
  }

  static active(db) {
    return db.rows("SELECT * FROM alerts WHERE active='1' AND until>? ORDER BY posted_at DESC", Alerts.now());
  }

  static seen(c) {
    return c.getApplicationContext().getSharedPreferences("alerts_seen", Context.MODE_PRIVATE);
  }

  /** The banner for one message, pulsing so it catches the eye. */
  static banner(a, r) {
    const card = Ui.card(a);
    card.setBackground(Glass.hero(a, [0xFFDC2626, 0xFFB91C1C], 18));
    card.setPadding(Ui.dp(a, 16), Ui.dp(a, 14), Ui.dp(a, 16), Ui.dp(a, 14));
    const top = Ui.h(a);
    top.setGravity(Gravity.CENTER_VERTICAL);
    const dot = Ui.tv(a, "⚠", 18, Color.WHITE, true);
    top.addView(dot);
    const lab = Ui.tv(a, "  URGENT · MESSAGE FROM THE HOD", 12, 0xFFFEF3C7, true);
    lab.setLetterSpacing(0.08);
    top.addView(lab, Ui.weight(1));
    card.addView(top);
    const msg = Ui.tv(a, r.get("message"), 17, Color.WHITE, true);
    msg.setPadding(0, Ui.dp(a, 8), 0, Ui.dp(a, 6));
    card.addView(msg);
    card.addView(Ui.tv(a, Ui.nz(r.get("posted_by")) + "  ·  " + Alerts.show(r.get("posted_at")) + "  ·  until " + Alerts.show(r.get("until")), 11, 0xD9FFFFFF, false));
    if (Alerts.canPost(a)) {
      const w = Ui.tv(a, "Withdraw", 13, 0xFFDC2626, true);
      w.setGravity(Gravity.CENTER);
      w.setBackground(Ui.round(a, Color.WHITE, 10));
      w.setPadding(0, Ui.dp(a, 8), 0, Ui.dp(a, 8));
      w.setOnClickListener({
        onClick: (v) => {
          Ui.confirm(a, "Withdraw this message?", "It will disappear from every phone.", "Withdraw", {
            run: () => {
              const cv = new ContentValues();
              cv.put("active", "0");
              a.db.update("alerts", cv, Long.parseLong(r.get("id")));
              a.render();
            }
          });
        }
      });
      card.addView(w);
      Ui.margins(w, 0, 10, 0, 0);
    }
    const pulse = ObjectAnimator.ofFloat(dot, "alpha", 1, 0.15);
    pulse.setDuration(600);
    pulse.setRepeatMode(ValueAnimator.REVERSE);
    pulse.setRepeatCount(ValueAnimator.INFINITE);
    pulse.start();
    const glow = ObjectAnimator.ofFloat(card, "alpha", 1, 0.78);
    glow.setDuration(900);
    glow.setRepeatMode(ValueAnimator.REVERSE);
    glow.setRepeatCount(ValueAnimator.INFINITE);
    glow.start();
    return card;
  }

  /** Pops up each new message once on every phone, so nobody misses it. */
  static popupNew(a) {
    for (const r of Alerts.active(a.db)) {
      const key = "a" + r.get("id");
      if (Alerts.seen(a).getBoolean(key, false)) continue;
      Alerts.seen(a).edit().putBoolean(key, true).apply();
      new AlertDialog.Builder(a)
        .setTitle("⚠  Urgent message from the HOD")
        .setMessage(r.get("message") + "\n\n— " + Ui.nz(r.get("posted_by")) + ", " + Alerts.show(r.get("posted_at")))
        .setPositiveButton("Noted", null)
        .show();
      return;
    }
  }

  static postDialog(a) {
    const f = new Form(a);
    f.multi("message", "Urgent message *", "");
    f.choice("hours", "Show on every phone for", Alerts.DURATIONS, ["2", "6", "12", "24", "72", "168"], "24", null);
    f.text("posted_by", "From", a.db.setting("hod", ""), Form.PLAIN);
    Ui.formDialog(a, "Urgent message to all", f, "Send to all", {
      run: () => {
        if (!f.require("message", "Type the message")) return false;
        const cv = new ContentValues();
        cv.put("message", f.get("message"));
        cv.put("posted_by", f.get("posted_by"));
        cv.put("posted_at", Alerts.now());
        cv.put("until", LocalDateTime.now().plusHours(Long.parseLong(f.get("hours"))).format(Alerts.STAMP));
        cv.put("active", "1");
        const id = a.db.insert("alerts", cv);
        Alerts.seen(a).edit().putBoolean("a" + id, true).apply();
        Ui.toast(a, Cloud.active(a) ? "Sent. It shows on every phone as it syncs." : "Posted on the home page");
        a.render();
        return true;
      }
    });
  }
}
;
