'use strict';
/**
 * Academic calendar: important events, exams, classes and the duties of faculty and students, by month.
 * Events entered here live in cal_events; classes, academics, DAP duty, the duty roster and ward duty are read from their own registers.
 */
class CalendarActivity extends Base {
  static COLOR = 0xFF0891B2;
  static KINDS = ["EVENT", "EXAM", "CLASS", "DUTY", "MEETING", "CME", "HOLIDAY", "DEADLINE"];
  static KIND_LABELS = ["Event", "Exam", "Class", "Duty", "Meeting", "CME / conference", "Holiday", "Deadline"];
  static AUDIENCE = ["ALL", "FAC", "PG", "CRMI", "MBBS"];
  static AUDIENCE_LABELS = ["Everyone", "Faculty", "PGs", "CRMIs", "MBBS students"];

  /** What a calendar entry is, for colours and filters. */
  static EVENTS = "Events";
  static CLASSES = "Classes";
  static DUTIES = "Duties";
  static HOLIDAYS = "Holidays";
  static FILTERS = ["All", "Mine", "Events", "Classes", "Duties"];

  static groupColor(g) {
    if (CalendarActivity.CLASSES.equals(g)) return Ui.PURPLE;
    if (CalendarActivity.DUTIES.equals(g)) return Ui.TEAL;
    if (CalendarActivity.HOLIDAYS.equals(g)) return Ui.RED;
    return Ui.AMBER;
  }

  static groupOf(kind) {
    if ("CLASS".equals(kind)) return CalendarActivity.CLASSES;
    if ("DUTY".equals(kind)) return CalendarActivity.DUTIES;
    if ("HOLIDAY".equals(kind)) return CalendarActivity.HOLIDAYS;
    return CalendarActivity.EVENTS;
  }

  static kindColor(kind) {
    if ("EXAM".equals(kind)) return Ui.ORANGE;
    if ("DEADLINE".equals(kind)) return Ui.PINK;
    if ("MEETING".equals(kind)) return Ui.SLATE;
    if ("CME".equals(kind)) return 0xFF2563EB;
    return CalendarActivity.groupColor(CalendarActivity.groupOf(kind));
  }

  constructor() {
    super();
    this.month = Dates.monthStart(Dates.today());
    this.selected = Dates.today();
    this.filter = "All";
  }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Academic calendar");
    this.subtitle = "Events, exams, classes and duties";
    this.headerColor(CalendarActivity.COLOR);
    const d = this.getIntent().getStringExtra("date");
    if (Dates.parse(d) != null) {
      this.selected = Dates.parse(d);
      this.month = Dates.monthStart(this.selected);
    }
    if (CalendarActivity.canEdit(this)) this.headerAction("+ Event", {
      onClick: (v) => { this.eventDialog(null); }
    });
  }

  /** Faculty and the HOD put up calendar entries; everyone sees them. On a phone without shared login, its user can. */
  static canEdit(c) {
    return SessionAttendance.canRun(c);
  }

  // ---------- gathering entries ----------

  /** Every entry between d0 and d1 (ISO dates, inclusive), sorted by date and time. */
  static items(c, db, d0, d1) {
    const CA = CalendarActivity;
    const out = [];
    const name = Reminders.myName(c, db);
    const me = Reminders.tokens(name);
    const phone = Reminders.myPhone(db, name);
    const myGroup = CA.audienceOf(c, db, name);

    for (const r of db.rows("SELECT * FROM cal_events WHERE date<=? AND (CASE WHEN end_date>date THEN end_date ELSE date END)>=? ORDER BY date, time", d1, d0)) {
      const s = Dates.parse(r.get("date"));
      let e = Dates.parse(r.get("end_date"));
      if (s == null) continue;
      if (e == null || e.isBefore(s)) e = s;
      const from = Dates.parse(d0), to = Dates.parse(d1);
      for (let d = s.isBefore(from) ? from : s; !d.isAfter(e) && !d.isAfter(to); d = d.plusDays(1)) {
        const it = new CA.Item();
        it.src = "cal";
        it.id = r.get("id");
        it.date = d.toString();
        it.time = Ui.nz(r.get("time"));
        it.pill = Db.label(CA.KINDS, CA.KIND_LABELS, r.get("kind"));
        it.color = CA.kindColor(r.get("kind"));
        it.group = CA.groupOf(r.get("kind"));
        it.title = r.get("title");
        const sub = [];
        if (!e.equals(s)) sub.add("Day " + (d.toEpochDay() - s.toEpochDay() + 1) + " of " + (e.toEpochDay() - s.toEpochDay() + 1)
          + " (" + Dates.shortFmt(s) + " to " + Dates.shortFmt(e) + ")");
        if (!Ui.nz(r.get("venue")).isEmpty()) sub.add("At " + r.get("venue"));
        if (!Ui.nz(r.get("audience")).isEmpty() && !"ALL".equals(r.get("audience"))) sub.add("For " + Db.label(CA.AUDIENCE, CA.AUDIENCE_LABELS, r.get("audience")));
        if (!Ui.nz(r.get("people")).isEmpty()) sub.add(r.get("people").split("\n").join(", "));
        if (!Ui.nz(r.get("notes")).isEmpty()) sub.add(r.get("notes"));
        it.sub = CA.join(sub, "\n");
        it.mine = Reminders.anyLine(r.get("people"), me, phone)
          || (!myGroup.isEmpty() && ("ALL".equals(r.get("audience")) || myGroup.equals(r.get("audience"))) && Ui.nz(r.get("people")).isEmpty());
        out.add(it);
      }
    }
    for (const r of db.rows("SELECT * FROM classes WHERE date BETWEEN ? AND ?", d0, d1)) {
      const it = CA.base("class", r, Db.label(Db.CLASS_KINDS, Db.CLASS_LABELS, r.get("kind")), Ui.PRIMARY, CA.CLASSES);
      it.title = r.get("topic").isEmpty() ? "(no topic)" : r.get("topic");
      it.sub = CA.join(CA.list(r.get("taken_by").isEmpty() ? "" : "By " + r.get("taken_by"), CA.unitText(r.get("unit"))), "  ·  ");
      it.mine = Reminders.anyLine(r.get("taken_by"), me, phone);
      out.add(it);
    }
    for (const r of db.rows("SELECT * FROM academics WHERE date BETWEEN ? AND ?", d0, d1)) {
      const it = CA.base("academic", r, Db.label(Db.ACAD_KINDS, Db.ACAD_LABELS, r.get("kind")), Ui.PURPLE, CA.CLASSES);
      it.title = r.get("topic").isEmpty() ? "(no topic)" : r.get("topic");
      it.sub = CA.join(CA.list(r.get("presenter").isEmpty() ? "" : "Presenter: " + r.get("presenter"),
        Ui.nz(r.get("moderator")).isEmpty() ? "" : "Moderator: " + r.get("moderator"), CA.unitText(r.get("unit"))), "  ·  ");
      it.mine = Reminders.anyLine(r.get("presenter"), me, phone) || Reminders.anyLine(r.get("moderator"), me, phone);
      out.add(it);
    }
    for (const r of db.rows("SELECT * FROM dissertations WHERE due_date BETWEEN ? AND ? AND s_submitted=''", d0, d1)) {
      const it = CA.base("diss", r, "Deadline", Ui.PINK, CA.EVENTS);
      it.date = r.get("due_date");
      it.time = "";
      it.title = "Dissertation due: " + r.get("pg");
      it.sub = DissertationActivity.percent(r) + "% done" + (Ui.nz(r.get("guide")).isEmpty() ? "" : "  ·  Guide: " + r.get("guide"));
      it.mine = Reminders.anyLine(r.get("pg"), me, phone) || Reminders.anyLine(r.get("guide"), me, phone);
      out.add(it);
    }
    const dapDays = new JSet();
    for (const r of db.rows("SELECT * FROM dap WHERE date BETWEEN ? AND ? AND dap_name<>''", d0, d1)) {
      const it = CA.base("dap", r, "DAP duty", Ui.TEAL, CA.DUTIES);
      it.time = "07:30";
      it.title = "DAP: " + r.get("dap_name");
      it.sub = "24 hours, 7:30 AM to 7:30 AM next day" + (Ui.nz(r.get("unit")).isEmpty() ? "" : "  ·  " + Db.shortName(r.get("unit")) + " admission day");
      it.mine = Reminders.anyLine(r.get("dap_name"), me, phone);
      dapDays.add(r.get("date"));
      out.add(it);
    }
    for (const r of db.rows("SELECT * FROM duty_roster WHERE date BETWEEN ? AND ?", d0, d1)) {
      const it = CA.base("roster", r, "Duty roster", Ui.TEAL, CA.DUTIES);
      it.time = "07:30";
      it.title = "Duty roster" + (Ui.nz(r.get("unit")).isEmpty() ? "" : " · " + Db.shortName(r.get("unit")));
      const lines = [];
      let mine = false;
      for (let g = 0; g < Roster.FIELDS.length; g++) {
        const who = [];
        for (const f of Roster.FIELDS[g]) {
          const v = Ui.nz(r.get(f[0])).trim();
          if (v.isEmpty() || (f[0].equals("dap") && dapDays.contains(r.get("date")))) continue;
          const names = [];
          for (const l of v.jsplit("\n")) if (!Roster.name(l).isEmpty()) names.add(Roster.name(l));
          if (!names.isEmpty()) who.add(f[1] + ": " + CA.join(names, ", "));
          if (Reminders.anyLine(v, me, phone)) mine = true;
        }
        if (!who.isEmpty()) lines.add(Roster.GROUPS[g] + " · " + CA.join(who, "; "));
      }
      if (lines.isEmpty()) continue;
      it.sub = CA.join(lines, "\n");
      it.mine = mine;
      out.add(it);
    }
    const ward = db.rows("SELECT * FROM ward_duty WHERE date BETWEEN ? AND ? ORDER BY date, unit", d0, d1);
    for (let i = 0; i < ward.size(); ) {
      const date = ward.get(i).get("date");
      const it = CA.base("ward", ward.get(i), "Ward duty", Ui.TEAL, CA.DUTIES);
      it.time = "08:00";
      it.title = "Ward duty PGs and CRRIs";
      const lines = [];
      for (; i < ward.size() && ward.get(i).get("date").equals(date); i++) {
        const r = ward.get(i);
        lines.add(Db.shortName(r.get("unit")) + ": " + CA.join(CA.list(Ui.nz(r.get("pg")).split("\n").join(", "), Ui.nz(r.get("crri")).split("\n").join(", ")), ", "));
        if (Reminders.anyLine(r.get("pg"), me, phone) || Reminders.anyLine(r.get("crri"), me, phone)) it.mine = true;
      }
      it.sub = CA.join(lines, "\n");
      out.add(it);
    }
    Collections.sort(out, {
      compare: (a, b) => {
        const c = a.date.compareTo(b.date);
        if (c !== 0) return c;
        const ta = a.time.isEmpty() ? "99" : a.time, tb = b.time.isEmpty() ? "99" : b.time;
        return ta.compareTo(tb);
      }
    });
    return out;
  }

  static base(src, r, pill, color, group) {
    const it = new CalendarActivity.Item();
    it.src = src;
    it.id = r.get("id");
    it.date = r.get("date");
    it.time = Ui.nz(r.get("time"));
    it.pill = pill;
    it.color = color;
    it.group = group;
    return it;
  }

  /** Faculty, PG, CRMI or MBBS, from this person's staff record. */
  static audienceOf(c, db, name) {
    let s = null;
    const sid = Cloud.myStaff(c);
    if (sid > 0) s = db.row("SELECT role FROM staff WHERE id=?", String(sid));
    if (s == null && !name.isEmpty()) s = db.row("SELECT role FROM staff WHERE name=? LIMIT 1", name);
    const role = s == null ? "" : Ui.nz(s.get("role"));
    if (role.contains("Professor")) return "FAC";
    if (role.equals("Postgraduate")) return "PG";
    if (role.equals("CRMI")) return "CRMI";
    if (role.startsWith("MBBS")) return "MBBS";
    return "";
  }

  static unitText(u) {
    return Ui.nz(u).isEmpty() || "ALL".equals(u) ? "" : Db.unitName(u);
  }

  static list(...s) {
    if (s.length === 1 && Array.isArray(s[0])) s = s[0];
    const out = [];
    for (const x of s) if (x != null && !x.trim().isEmpty()) out.add(x.trim());
    return out;
  }

  static join(parts, sep) {
    const sb = new StringBuilder();
    for (const p of parts) {
      if (p == null || p.trim().isEmpty()) continue;
      if (sb.length() > 0) sb.append(sep);
      sb.append(p.trim());
    }
    return sb.toString();
  }

  passes(it) {
    const CA = CalendarActivity;
    if ("All".equals(this.filter)) return true;
    if ("Mine".equals(this.filter)) return it.mine;
    if (CA.EVENTS.equals(this.filter)) return CA.EVENTS.equals(it.group) || CA.HOLIDAYS.equals(it.group);
    return this.filter.equals(it.group);
  }

  /** Count for the home tile: entries in the next 7 days, today included. */
  static thisWeek(c, db) {
    const t = Dates.today();
    return CalendarActivity.items(c, db, t.toString(), t.plusDays(6).toString()).size();
  }

  // ---------- screen ----------

  render() {
    const CA = CalendarActivity;
    const COLOR = CA.COLOR;
    const page = Ui.v(this);
    const first = this.month, last = this.month.plusMonths(1).minusDays(1);
    const all = CA.items(this, this.db, first.toString(), last.toString());
    const shown = [];
    for (const it of all) if (this.passes(it)) shown.add(it);

    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 2));
    for (const f of CA.FILTERS) {
      const c = Ui.chip(this, f, f.equals(this.filter), "All".equals(f) || "Mine".equals(f) ? COLOR : CA.groupColor(f));
      c.setOnClickListener({
        onClick: (v) => { this.filter = f; this.render(); }
      });
      chips.addView(c);
    }
    page.addView(Ui.hscroll(this, chips));
    page.addView(this.monthCard(shown));

    const sel = this.selected.toString();
    const day = [];
    for (const it of shown) if (it.date.equals(sel)) day.add(it);
    if (!sel.startsWith(this.month.toString().substring(0, 7))) {
      day.clear();
      for (const it of CA.items(this, this.db, sel, sel)) if (this.passes(it)) day.add(it);
    }
    page.addView(Ui.heading(this, (this.selected.equals(Dates.today()) ? "Today, " : "") + Dates.longFmt(this.selected), COLOR));
    if (day.isEmpty()) page.addView(this.emptyNote(CA.canEdit(this) ? "Nothing on this day. Tap “+ Event” to add one." : "Nothing on this day."));
    for (const it of day) page.addView(this.itemCard(it, false));

    const t = Dates.today();
    const next = [];
    const seen = new JSet();
    for (const it of CA.items(this, this.db, t.toString(), t.plusDays(30).toString())) {
      // an event of several days shows once, on its first day still to come
      if (!this.passes(it) || it.date.equals(sel) || ("cal".equals(it.src) && !seen.add(it.id))) continue;
      next.add(it);
    }
    page.addView(Ui.heading(this, "Coming up (next 30 days)", COLOR));
    if (next.isEmpty()) page.addView(this.emptyNote("Nothing else coming up."));
    let n = 0;
    for (const it of next) {
      if (n++ >= 60) break;
      page.addView(this.itemCard(it, true));
    }
    const share = Ui.outlineButton(this, "Share this week's calendar", COLOR, {
      onClick: (v) => { this.shareWeek(); }
    });
    page.addView(share);
    Ui.margins(share, 14, 12, 14, 0);
    this.setPage(page);
  }

  monthCard(shown) {
    const CA = CalendarActivity;
    const COLOR = CA.COLOR;
    const card = Ui.card(this);
    const nav = Ui.h(this);
    nav.setGravity(Gravity.CENTER_VERTICAL);
    nav.addView(this.navButton("‹", -1));
    const m = Ui.tv(this, Dates.month(this.month), 18, Ui.TEXT, true);
    m.setGravity(Gravity.CENTER);
    nav.addView(m, Ui.weight(1));
    nav.addView(this.navButton("›", 1));
    card.addView(nav);
    if (!this.month.equals(Dates.monthStart(Dates.today())) || !this.selected.equals(Dates.today())) {
      const today = Ui.tv(this, "Go to today", 12, COLOR, true);
      today.setGravity(Gravity.CENTER);
      today.setPadding(0, Ui.dp(this, 2), 0, Ui.dp(this, 4));
      today.setOnClickListener({
        onClick: (v) => {
          this.selected = Dates.today();
          this.month = Dates.monthStart(this.selected);
          this.render();
        }
      });
      card.addView(today);
    }

    const head = Ui.h(this);
    for (const d of ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]) {
      const h = Ui.tv(this, d, 11, d.equals("Sun") ? Ui.RED : Ui.MUTED, true);
      h.setGravity(Gravity.CENTER);
      head.addView(h, Ui.weight(1));
    }
    card.addView(head);
    Ui.margins(head, 0, 8, 0, 4);

    const byDay = new JMap();
    for (const it of shown) {
      let l = byDay.get(it.date);
      if (l == null) { l = []; byDay.put(it.date, l); }
      l.add(it);
    }
    let d = this.month.minusDays(Dates.dow(this.month) - 1);
    const end = this.month.plusMonths(1);
    while (d.isBefore(end)) {
      const row = Ui.h(this);
      for (let i = 0; i < 7; i++, d = d.plusDays(1)) row.addView(this.dayCell(d, byDay.get(d.toString())), Ui.weight(1));
      card.addView(row);
    }

    const legend = Ui.h(this);
    legend.setGravity(Gravity.CENTER);
    for (const g of [CA.EVENTS, CA.CLASSES, CA.DUTIES, CA.HOLIDAYS]) {
      legend.addView(this.dot(CA.groupColor(g), 8));
      const l = Ui.tv(this, " " + g + "   ", 11, Ui.MUTED, false);
      legend.addView(l);
    }
    card.addView(legend);
    Ui.margins(legend, 0, 8, 0, 0);
    return card;
  }

  navButton(s, delta) {
    const b = Ui.tv(this, s, 26, CalendarActivity.COLOR, true);
    b.setGravity(Gravity.CENTER);
    b.setMinWidth(Ui.dp(this, 48));
    b.setContentDescription(delta < 0 ? "Previous month" : "Next month");
    b.setOnClickListener({
      onClick: (v) => {
        this.month = this.month.plusMonths(delta);
        this.selected = this.month.equals(Dates.monthStart(Dates.today())) ? Dates.today() : this.month;
        this.render();
      }
    });
    return b;
  }

  dayCell(d, its) {
    const CA = CalendarActivity;
    const COLOR = CA.COLOR;
    const inMonth = d.getMonthValue() === this.month.getMonthValue();
    const today = d.equals(Dates.today()), sel = d.equals(this.selected);
    let holiday = false;
    if (its != null) for (const it of its) if (CA.HOLIDAYS.equals(it.group)) holiday = true;
    const cell = Ui.v(this);
    cell.setGravity(Gravity.CENTER_HORIZONTAL);
    cell.setPadding(0, Ui.dp(this, 4), 0, Ui.dp(this, 4));
    cell.setMinimumHeight(Ui.dp(this, 46));
    const n = Ui.tv(this, String(d.getDayOfMonth()), 14,
      sel ? Color.WHITE : !inMonth ? 0xFFCBD5E1 : holiday || Dates.dow(d) === 7 ? Ui.RED : Ui.TEXT, today || sel);
    n.setGravity(Gravity.CENTER);
    const size = Ui.dp(this, 30);
    if (sel) n.setBackground(Ui.round(this, COLOR, 15));
    else if (today) {
      const g = Ui.round(this, 0x1A0891B2, 15);
      g.setStroke(Ui.dp(this, 2), COLOR);
      n.setBackground(g);
    }
    cell.addView(n, new LinearLayout.LayoutParams(size, size));
    const dots = Ui.h(this);
    dots.setGravity(Gravity.CENTER);
    if (its != null && inMonth) {
      const colors = new JSet();
      for (const it of its) colors.add(CA.groupColor(it.group));
      let k = 0;
      for (const c of colors) if (k++ < 4) dots.addView(this.dot(c, 6));
    }
    cell.addView(dots, new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, Ui.dp(this, 8)));
    cell.setOnClickListener({
      onClick: (v) => {
        this.selected = d;
        if (d.getMonthValue() !== this.month.getMonthValue() || d.getYear() !== this.month.getYear()) this.month = Dates.monthStart(d);
        this.render();
      }
    });
    return cell;
  }

  dot(color, dp) {
    const v = new View(this);
    v.setBackground(Ui.round(this, color, dp / 2));
    const lp = new LinearLayout.LayoutParams(Ui.dp(this, dp), Ui.dp(this, dp));
    lp.setMargins(Ui.dp(this, 1), Ui.dp(this, 1), Ui.dp(this, 1), Ui.dp(this, 1));
    v.setLayoutParams(lp);
    return v;
  }

  itemCard(it, withDate) {
    const d = Dates.parse(it.date);
    const when = (withDate && d != null ? Dates.shortFmt(d) + ", " + d.getDayOfWeek().getDisplayName(TextStyle.SHORT, Locale.ENGLISH) : "")
      + (it.time.isEmpty() ? "" : (withDate ? "  " : "") + it.time);
    const card = this.entryCard(it.pill, it.color, it.title, it.sub, when.trim().isEmpty() ? null : when.trim(), {
      onClick: (v) => { this.open(it); }
    });
    if (it.mine) {
      const mine = Ui.tv(this, "★ You are in this", 12, CalendarActivity.COLOR, true);
      card.addView(mine);
      Ui.margins(mine, 0, 6, 0, 0);
    }
    return card;
  }

  /** Overloaded in Java: open(Item) opens the entry; open(Class, extras...) is Base's. */
  open(it, ...kv) {
    if (typeof it === 'function') { super.open(it, ...kv); return; }
    if ("cal".equals(it.src)) {
      const r = this.db.row("SELECT * FROM cal_events WHERE id=?", it.id);
      if (r == null) return;
      if (CalendarActivity.canEdit(this)) this.eventDialog(r);
      else this.detail(r);
    } else if ("class".equals(it.src) || "academic".equals(it.src)) {
      super.open(FormActivity, "kind", it.src, "id", it.id);
    } else if ("diss".equals(it.src)) {
      super.open(DissertationActivity, "id", it.id);
    } else if ("dap".equals(it.src)) {
      super.open(DapActivity);
    } else {
      super.open(CallDutyActivity);
    }
  }

  detail(r) {
    const CA = CalendarActivity;
    const v = Ui.v(this);
    v.setPadding(Ui.dp(this, 20), Ui.dp(this, 8), Ui.dp(this, 20), 0);
    v.addView(Ui.kv(this, "What", Db.label(CA.KINDS, CA.KIND_LABELS, r.get("kind"))));
    const when = Dates.nice(r.get("date")) + (Ui.nz(r.get("end_date")).isEmpty() || r.get("end_date").equals(r.get("date")) ? "" : " to " + Dates.nice(r.get("end_date")))
      + (Ui.nz(r.get("time")).isEmpty() ? "" : ", " + r.get("time"));
    v.addView(Ui.kv(this, "When", when));
    v.addView(Ui.kv(this, "Where", r.get("venue")));
    v.addView(Ui.kv(this, "For", Db.label(CA.AUDIENCE, CA.AUDIENCE_LABELS, r.get("audience"))));
    v.addView(Ui.kv(this, "Faculty / students", r.get("people")));
    v.addView(Ui.kv(this, "Notes", r.get("notes")));
    v.addView(Ui.kv(this, "Put up by", r.get("by_name")));
    new AlertDialog.Builder(this).setTitle(r.get("title")).setView(v).setPositiveButton("Close", null).show();
  }

  eventDialog(r) {
    const CA = CalendarActivity;
    const f = new Form(this);
    f.text("title", "Title *", r == null ? "" : r.get("title"), Form.PLAIN);
    f.choice("kind", "Type", CA.KIND_LABELS, CA.KINDS, r == null ? "EVENT" : r.get("kind"), null);
    f.date("date", "Date", r == null ? this.selected.toString() : r.get("date"));
    f.optionalDate("end_date", "Till (for events of more than one day)", r == null ? "" : r.get("end_date"));
    f.time("time", "Time", r == null ? "" : r.get("time"));
    f.text("venue", "Venue", r == null ? "" : r.get("venue"), Form.PLAIN);
    f.choice("audience", "For", CA.AUDIENCE_LABELS, CA.AUDIENCE, r == null ? "ALL" : r.get("audience"), null);
    f.multi("people", "Faculty / students on duty or taking part (one per line)", r == null ? "" : r.get("people"));
    f.multi("notes", "Notes", r == null ? "" : r.get("notes"));
    if (r != null) {
      const del = Ui.outlineButton(this, "Delete", Ui.RED, {
        onClick: (v) => {
          Ui.confirm(this, "Delete from calendar?", r.get("title"), "Delete", {
            run: () => { this.db.delete("cal_events", Long.parseLong(r.get("id"))); this.render(); }
          });
        }
      });
      f.view.addView(del);
      Ui.margins(del, 0, 14, 0, 0);
    }
    Ui.formDialog(this, r == null ? "Add to calendar" : "Edit calendar entry", f, "Save", {
      run: () => {
        if (!f.require("title", "Enter a title")) return false;
        const end = f.get("end_date");
        if (!end.isEmpty() && end.compareTo(f.get("date")) < 0) {
          Ui.toast(this, "The end date is before the start date");
          return false;
        }
        const cv = new ContentValues();
        for (const k of ["title", "kind", "date", "end_date", "time", "venue", "audience", "people", "notes"]) cv.put(k, f.get(k).trim());
        if (r == null) {
          cv.put("by_name", Reminders.myName(this, this.db));
          cv.put("added_on", Alerts.now());
          this.db.insert("cal_events", cv);
        } else this.db.update("cal_events", cv, Long.parseLong(r.get("id")));
        this.selected = Dates.parse(f.get("date"));
        this.month = Dates.monthStart(this.selected);
        Reminders.schedule(this);
        this.render();
        return true;
      }
    });
  }

  /** The next 7 days as plain text, for WhatsApp. */
  static weekText(c, db) {
    const t = Dates.today();
    const sb = new StringBuilder("*Academic calendar, Department of Medicine*\n");
    let last = "";
    for (const it of CalendarActivity.items(c, db, t.toString(), t.plusDays(6).toString())) {
      if (!it.date.equals(last)) {
        sb.append("\n*").append(Dates.longFmt(Dates.parse(it.date))).append("*\n");
        last = it.date;
      }
      sb.append("• ").append(it.time.isEmpty() ? "" : it.time + " ").append(it.pill).append(": ").append(it.title).append('\n');
      if (!it.sub.isEmpty()) sb.append("   ").append(it.sub.split("\n").join("\n   ")).append('\n');
    }
    if (last.isEmpty()) sb.append("\nNothing on the calendar this week.\n");
    return sb.toString().trim();
  }

  shareWeek() {
    const i = new Intent(Intent.ACTION_SEND);
    i.setType("text/plain");
    i.putExtra(Intent.EXTRA_TEXT, CalendarActivity.weekText(this, this.db));
    this.startActivity(Intent.createChooser(i, "Share calendar"));
  }
}

/** One line in the calendar. */
CalendarActivity.Item = class {
  constructor() {
    this.date = null; this.time = ""; this.pill = null; this.title = null; this.sub = ""; this.group = null; this.id = ""; this.src = null;
    this.color = 0;
    this.mine = false;
  }
};
;
