/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Call duty desk: the day's call duty PGs (taken from the duty roster message), the DAP and the HOD share one
 * sick case list and a feed of ward issues, so the DAP knows what is happening in every ward overnight.
 */
class CallDutyActivity extends Base {
  constructor() {
    super();
    this.day = null;
    this.tab = 0;
    this.ward = "ALL";
    this.issueForm = null;
  }

  static STATUS = ["Sick", "Critical", "Improving", "Stable", "Shifted to IMCU", "Expired"];
  /** Roster fields that hold the PGs on call. */
  static PG_POSTS = [
    ["triage_pg_day", "Triage (day)"], ["triage_pg_night", "Triage (night)"], ["male_op", "Male OP"], ["female_op", "Female OP"],
    ["fever_op", "Fever OP"], ["imcu_day", "IMCU day"], ["imcu_night", "IMCU night"], ["ccb_day_pg", "CCB day"],
    ["ccb_night_pg", "CCB night"], ["fever_day_pg", "Fever ward day"], ["fever_night", "Fever ward night"]];

  static $clinit() {
    CallDutyActivity.WARDS = ["M1", "M2", "M3", "M4", "M5", "M6", "M7", Db.IMCU, Db.FEVER, Db.CCB, Db.GERI, Db.RHEUM];
  }

  /** Keep a half-typed issue when another phone's changes arrive. */
  liveRefresh() {
    return this.tab === 0 || this.issueForm == null || this.issueForm.get("text").isEmpty();
  }

  onCreate(b) {
    super.onCreate(b);
    // PG call duty runs from 2 PM to 7:30 AM: before 7:30 AM it is still yesterday's duty
    this.day = Dates.admitDay();
    this.setTitle("Call duty");
    this.subtitle = "Call duty PGs · DAP · HOD";
    this.headerColor(Ui.TEAL);
  }

  static myName(c) {
    const n = Cloud.active(c) ? Cloud.prefs(c).getString("name", "") : "";
    if (!n.isEmpty()) return n;
    return c.getApplicationContext().getSharedPreferences("me", Context.MODE_PRIVATE).getString("name", "");
  }

  static rememberName(c, name) {
    if (!Ui.nz(name).trim().isEmpty())
      c.getApplicationContext().getSharedPreferences("me", Context.MODE_PRIVATE).edit().putString("name", name.trim()).apply();
  }

  /** The day's group: DAP and HOD first, then each PG with the post they hold. name → {post, phone}. */
  static members(db, date) {
    const m = new JMap();
    const r = db.row("SELECT * FROM duty_roster WHERE date=? ORDER BY id DESC LIMIT 1", date);
    const dap = db.row("SELECT dap_name FROM dap WHERE date=? ORDER BY id DESC LIMIT 1", date);
    const dapLine = r != null && !Ui.nz(r.get("dap")).trim().isEmpty() ? r.get("dap").trim().jsplit("\n")[0] : dap == null ? "" : dap.get("dap_name");
    if (!dapLine.isEmpty()) m.put(Roster.name(dapLine), ["DAP", CallDutyActivity.phoneOf(db, dapLine)]);
    const hod = db.setting("hod", "");
    if (!hod.isEmpty()) m.put(hod, ["HOD", CallDutyActivity.phoneOf(db, hod)]);
    // ward duty PGs and CRRIs (M1–M7), from the pasted WhatsApp list
    for (const w of db.rows("SELECT * FROM ward_duty WHERE date=? ORDER BY unit", date)) {
      const who = [[Ui.nz(w.get("pg")), "PG"], [Ui.nz(w.get("crri")), "CRRI"]];
      for (const x of who)
        for (const line of x[0].jsplit("\n")) {
          if (line.trim().isEmpty()) continue;
          const np = WardDuty.person(line);
          const post = Db.shortName(w.get("unit")) + " ward" + (x[1].equals("CRRI") ? " CRRI" : "");
          let found = null;
          for (const k of m.keySet()) if (k.replaceAllRx("[^A-Za-z]", "").equalsIgnoreCase(np[0].replaceAllRx("[^A-Za-z]", ""))) found = k;
          if (found != null) {
            const v = m.get(found);
            if (!v[0].equals("DAP") && !v[0].equals("HOD") && !v[0].contains(post)) v[0] = v[0] + ", " + post;
          } else m.put(np[0], [post, np[1].isEmpty() ? CallDutyActivity.phoneOf(db, line) : np[1]]);
        }
    }
    if (r == null) return m;
    for (const post of CallDutyActivity.PG_POSTS) {
      for (const line of Ui.nz(r.get(post[0])).jsplit("\n")) {
        if (line.trim().isEmpty()) continue;
        const name = Roster.name(line);
        const key = name.replaceAllRx("[^A-Za-z]", "").toLowerCase();
        let found = null;
        for (const k of m.keySet()) if (k.replaceAllRx("[^A-Za-z]", "").toLowerCase().equals(key)) found = k;
        if (found != null) {
          const v = m.get(found);
          if (!v[0].equals("DAP") && !v[0].equals("HOD") && !v[0].contains(post[1])) v[0] = v[0] + ", " + post[1];
        } else m.put(name, [post[1], CallDutyActivity.phoneOf(db, line)]);
      }
    }
    return m;
  }

  static phoneOf(db, line) {
    const p = Roster.phone(line);
    if (!p.isEmpty()) return p;
    const s = db.row("SELECT phone FROM staff WHERE name=? AND phone<>'' LIMIT 1", Roster.name(line));
    return s == null ? "" : s.get("phone");
  }

  render() {
    const db = this.db;
    const page = Ui.v(this);
    const iso = this.day.toString();
    this.headerAction(this.tab === 0 ? "+ Sick case" : null, this.tab === 0 ? { onClick: (v) => { this.sickDialog(null); } } : null);

    const nav = Ui.card(this);
    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    row.addView(Ui.outlineButton(this, "‹", Ui.TEAL, { onClick: (v) => { this.day = this.day.minusDays(1); this.render(); } }));
    const mid = Ui.v(this);
    mid.setGravity(Gravity.CENTER);
    mid.addView(Ui.tv(this, "PG call duty 2 PM " + Dates.nice(this.day) + " to 7:30 AM " + Dates.nice(this.day.plusDays(1)), 11, Ui.MUTED, false));
    mid.addView(Ui.tv(this, Dates.longFmt(this.day), 15, Ui.TEXT, true));
    row.addView(mid, Ui.weight(1));
    row.addView(Ui.outlineButton(this, "›", Ui.TEAL, { onClick: (v) => { this.day = this.day.plusDays(1); this.render(); } }));
    nav.addView(row);
    page.addView(nav);

    this.membersCard(page, iso);
    this.wardDutyCard(page, iso);

    const seg = Ui.h(this);
    seg.setBackground(Ui.round(this, 0xFFE2E8F0, 14));
    seg.setPadding(Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4));
    const sick = db.num("SELECT COUNT(*) FROM duty_sick WHERE date=?", iso);
    const notes = db.num("SELECT COUNT(*) FROM duty_notes WHERE date=?", iso);
    const labels = ["Sick case list  " + sick, "Ward issues  " + notes];
    for (let i = 0; i < 2; i++) {
      const idx = i;
      const t = Ui.tv(this, labels[i], 14, i === this.tab ? Ui.TEAL : Ui.MUTED, true);
      t.setGravity(Gravity.CENTER);
      t.setPadding(0, Ui.dp(this, 9), 0, Ui.dp(this, 9));
      if (i === this.tab) t.setBackground(Ui.round(this, 0xFFFFFFFF, 11));
      t.setOnClickListener({ onClick: (v) => { this.tab = idx; this.render(); } });
      seg.addView(t, Ui.weight(1));
    }
    page.addView(seg);
    Ui.margins(seg, 12, 10, 12, 4);

    if (this.tab === 0) this.sickList(page, iso);
    else this.issues(page, iso);
    this.setPage(page);
  }

  // ---------- the group ----------

  membersCard(page, iso) {
    const db = this.db;
    const m = CallDutyActivity.members(db, iso);
    const roster = db.num("SELECT COUNT(*) FROM duty_roster WHERE date=?", iso) > 0;
    page.addView(Ui.heading(this, "Call duty group  ·  " + m.size(), Ui.TEAL));
    const card = Ui.card(this);
    const today = this.day.equals(Dates.admitDay());
    if (today) this.dutyChatRow(card);
    if (today) {
      const ho = db.num("SELECT COUNT(*) FROM handovers WHERE day=?", Dates.admitDay().toString());
      const hb = Ui.outlineButton(this, "🔁 7:30 AM handover · " + ho + (ho === 1 ? " patient" : " patients"), HandoverActivity.COLOR, this.opener(HandoverActivity));
      card.addView(hb);
      Ui.margins(hb, 0, 8, 0, 0);
    }
    const hod = db.setting("hod", "");
    for (const e of m.entrySet()) {
      const r = Ui.h(this);
      r.setGravity(Gravity.CENTER_VERTICAL);
      r.setPadding(0, Ui.dp(this, 4), 0, Ui.dp(this, 4));
      const post = e.getValue()[0];
      const lead = post.equals("DAP") || post.equals("HOD");
      const crri = !lead && post.endsWith("CRRI") && !post.contains(",");
      const badge = Ui.tv(this, lead ? post : crri ? "CRRI" : "PG", 11, Color.WHITE, true);
      badge.setGravity(Gravity.CENTER);
      badge.setBackground(Ui.round(this, post.equals("HOD") ? Ui.PRIMARY_DARK : post.equals("DAP") ? Ui.PRIMARY : crri ? Ui.ORANGE : Ui.TEAL, 10));
      r.addView(badge, Ui.lp(Ui.dp(this, 46), Ui.dp(this, 22)));
      const t = Ui.v(this);
      t.setPadding(Ui.dp(this, 10), 0, Ui.dp(this, 6), 0);
      t.addView(Ui.tv(this, e.getKey(), 14, Ui.TEXT, true));
      if (!lead) t.addView(Ui.tv(this, post, 12, Ui.MUTED, false));
      if (today) {
        const isHod = post.equals("HOD") || (!hod.isEmpty() && Chat.sameName(e.getKey(), hod));
        const linked = Chat.staffId(db, e.getKey()) > 0;
        t.addView(Ui.tv(this, isHod ? "Not in Duty team chat" : linked ? "💬 In Duty team chat"
            : "Not in chat: add to Students/Faculty and link in Members", 11, isHod ? Ui.MUTED : linked ? Chat.GREEN : Ui.ORANGE, false));
      }
      r.addView(t, Ui.weight(1));
      const ph = e.getValue()[1];
      if (!ph.isEmpty()) {
        const call = Ui.softPill(this, "📞 Call", Ui.GREEN);
        call.setOnClickListener({
          onClick: (v) => {
            try { this.startActivity(new Intent(Intent.ACTION_DIAL, Uri.parse("tel:" + ph))); } catch (ignored) {}
          }
        });
        r.addView(call);
      }
      card.addView(r);
    }
    const note = Ui.muted(this, roster ? "Members come from the day's duty roster. The DAP and HOD are always in the group."
        : "Paste the morning roster message from WhatsApp to add the day's call duty PGs automatically.");
    note.setPadding(0, Ui.dp(this, 6), 0, 0);
    card.addView(note);
    const b = Ui.outlineButton(this, roster ? "Update from roster message" : "+ Add PGs from WhatsApp message", Ui.TEAL,
        this.opener(RosterFormActivity, "date", iso));
    card.addView(b);
    Ui.margins(b, 0, 8, 0, 0);
    page.addView(card);
  }

  /** Opens the Duty team chat (today's DAP and duty PGs, never the HOD) from the call duty desk. */
  dutyChatRow(card) {
    const db = this.db;
    const team = Chat.dutyTeam(db).size();
    const inn = !Chat.isHod(this, db) && Chat.inDuty(this, db);
    if (inn) {
      const unread = Chat.unread(this, db, String(Chat.DUTY));
      const b = Ui.button(this, "💬  Duty team chat  ·  " + team + (unread > 0 ? "  ·  " + unread + " new" : ""), Chat.GREEN,
          this.opener(ChatActivity, "chat", String(Chat.DUTY)));
      card.addView(b);
      Ui.margins(b, 0, 0, 0, 8);
    } else {
      const n = Ui.tv(this, "💬 Duty team chat (" + team + " members): only today's DAP and duty PGs/CRRIs can open it"
          + (Chat.isHod(this, db) ? ". The HOD is not in this chat." : ". You are not on today's team."), 12, Ui.MUTED, false);
      n.setPadding(0, 0, 0, Ui.dp(this, 8));
      card.addView(n);
    }
  }

  // ---------- ward duty PGs & CRRIs (M1–M7) ----------

  wardDutyCard(page, iso) {
    const db = this.db;
    const rows = db.rows("SELECT * FROM ward_duty WHERE date=?", iso);
    const byUnit = new JMap();
    for (const r of rows) byUnit.put(r.get("unit"), r);
    page.addView(Ui.heading(this, "Ward duty PGs & CRRIs", Ui.PRIMARY));
    const card = Ui.card(this);
    if (rows.isEmpty()) {
      card.addView(Ui.muted(this, "Paste the morning \"Ward duty PGs & CRRIs list\" message from WhatsApp. Each unit's PG and CRRI, with their numbers, are filled in automatically and added to the call duty group."));
    } else {
      const admitting = Db.WARD_UNITS[Dates.dow(this.day) - 1];
      for (const u of WardDuty.UNITS) {
        const r = byUnit.get(u);
        if (r == null && !Db.isWardUnit(u)) continue;
        const row = Ui.h(this);
        row.setGravity(Gravity.TOP);
        row.setPadding(0, Ui.dp(this, 6), 0, Ui.dp(this, 6));
        const pill = Ui.pill(this, Db.shortName(u), Ui.unitColor(u));
        row.addView(pill, Ui.lp(Ui.dp(this, 52), ViewGroup.LayoutParams.WRAP_CONTENT));
        pill.setGravity(Gravity.CENTER);
        const t = Ui.v(this);
        t.setPadding(Ui.dp(this, 10), 0, 0, 0);
        let note = r == null ? "" : Ui.nz(r.get("note")).split("\n").join(" · ");
        if (u.equals(admitting) && !note.toLowerCase().contains("admission")) note = note.isEmpty() ? "Admission day" : note + " · Admission day";
        if (!note.isEmpty()) t.addView(Ui.tv(this, note, 13, note.toLowerCase().contains("admission") ? Ui.RED : Ui.MUTED, true));
        let any = false;
        if (r != null) {
          const who = [[Ui.nz(r.get("pg")), "PG"], [Ui.nz(r.get("crri")), "CRRI"]];
          for (const x of who)
            for (const line of x[0].jsplit("\n")) {
              if (line.trim().isEmpty()) continue;
              t.addView(this.personRow(x[1], WardDuty.person(line)));
              any = true;
            }
        }
        if (!any && note.isEmpty()) t.addView(Ui.muted(this, "Not in today's list"));
        row.addView(t, Ui.weight(1));
        card.addView(row);
      }
    }
    const btns = Ui.h(this);
    const paste = Ui.button(this, rows.isEmpty() ? "Paste from WhatsApp" : "Paste again", Ui.PRIMARY, { onClick: (v) => { this.pasteWardDuty(iso); } });
    btns.addView(paste, Ui.weight(1));
    if (!rows.isEmpty()) {
      const share = Ui.outlineButton(this, "Share list", Ui.PRIMARY, { onClick: (v) => { ReportActivity.shareText(this, WardDuty.shareText(db, iso)); } });
      btns.addView(share, Ui.weight(1));
      Ui.margins(share, 8, 0, 0, 0);
    }
    card.addView(btns);
    Ui.margins(btns, 0, 10, 0, 0);
    page.addView(card);
  }

  personRow(role, np) {
    const r = Ui.h(this);
    r.setGravity(Gravity.CENTER_VERTICAL);
    r.setPadding(0, Ui.dp(this, 2), 0, Ui.dp(this, 2));
    const rl = Ui.tv(this, role, 11, role.equals("PG") ? Ui.TEAL : Ui.ORANGE, true);
    r.addView(rl, Ui.lp(Ui.dp(this, 36), ViewGroup.LayoutParams.WRAP_CONTENT));
    const n = Ui.tv(this, np[0], 14, Ui.TEXT, true);
    r.addView(n, Ui.weight(1));
    const ph = np[1];
    if (!ph.isEmpty()) {
      const call = Ui.softPill(this, "Call", Ui.GREEN);
      call.setOnClickListener({
        onClick: (v) => {
          try { this.startActivity(new Intent(Intent.ACTION_DIAL, Uri.parse("tel:" + ph))); } catch (ignored) {}
        }
      });
      r.addView(call);
    }
    return r;
  }

  /** Paste box for the WhatsApp message; shows what was found before saving. */
  pasteWardDuty(iso) {
    const db = this.db;
    const f = new Form(this);
    f.multi("text", "Paste the whole WhatsApp message", "");
    Ui.formDialog(this, "Ward duty PGs & CRRIs", f, "Read message", {
      run: () => {
        const p = WardDuty.parse(f.get("text"));
        if (p.units.isEmpty()) {
          Ui.toast(this, "No units (M1 … M7) found in the message");
          return false;
        }
        const date = p.date != null ? p.date : iso;
        const sb = new StringBuilder();
        for (const e of p.units.entrySet()) {
          const en = e.getValue();
          sb.append(Db.shortName(e.getKey())).append(": ");
          const bits = [];
          if (!en.note.isEmpty()) bits.add(en.note.split("\n").join(", "));
          for (const l of en.pg.jsplit("\n")) if (!l.trim().isEmpty()) bits.add("PG " + WardDuty.person(l)[0]);
          for (const l of en.crri.jsplit("\n")) if (!l.trim().isEmpty()) bits.add("CRRI " + WardDuty.person(l)[0]);
          sb.append(bits.isEmpty() ? "nothing listed" : TextUtils.join(", ", bits)).append("\n");
        }
        const exists = db.num("SELECT COUNT(*) FROM ward_duty WHERE date=?", date) > 0;
        Ui.confirm(this, "Save for " + Dates.nice(LocalDate.parse(date)) + "?",
            sb.toString().trim() + (exists ? "\n\nThis replaces the list already saved for that day." : ""), "Save", {
              run: () => {
                WardDuty.save(db, date, p);
                this.day = LocalDate.parse(date);
                this.render();
                Ui.toast(this, p.units.size() + " units saved");
              }
            });
        return true;
      }
    });
  }

  // ---------- sick case list ----------

  static statusColor(s) {
    if ("Critical" === s || "Expired" === s) return Ui.RED;
    if ("Sick" === s) return Ui.ORANGE;
    if ("Shifted to IMCU" === s) return Ui.unitColor(Db.IMCU);
    return Ui.GREEN;
  }

  sickList(page, iso) {
    const db = this.db;
    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 4));
    const opts = [];
    opts.add("ALL");
    for (const w of CallDutyActivity.WARDS) opts.add(w);
    for (const w of opts) {
      const n = w.equals("ALL") ? db.num("SELECT COUNT(*) FROM duty_sick WHERE date=?", iso) : db.num("SELECT COUNT(*) FROM duty_sick WHERE date=? AND ward=?", iso, w);
      if (n === 0 && !w.equals("ALL") && !w.equals(this.ward)) continue;
      const c = Ui.chip(this, (w.equals("ALL") ? "All wards" : Db.shortName(w)) + "  " + n, w.equals(this.ward), w.equals("ALL") ? Ui.TEAL : Ui.unitColor(w));
      c.setOnClickListener({ onClick: (v) => { this.ward = w; this.render(); } });
      chips.addView(c);
    }
    page.addView(Ui.hscroll(this, chips));

    const acts = Ui.h(this);
    acts.setPadding(Ui.dp(this, 12), Ui.dp(this, 4), Ui.dp(this, 12), Ui.dp(this, 4));
    const prev = this.day.minusDays(1).toString();
    const carry = db.num("SELECT COUNT(*) FROM duty_sick WHERE date=? AND status IN ('Sick','Critical')", prev);
    const btns = [];
    btns.add(Ui.button(this, "+ Add sick case", Ui.TEAL, { onClick: (v) => { this.sickDialog(null); } }));
    if (carry > 0 && db.num("SELECT COUNT(*) FROM duty_sick WHERE date=?", iso) === 0)
      btns.add(Ui.outlineButton(this, "Carry over " + carry + " from yesterday", Ui.TEAL, { onClick: (v) => { this.carryOver(prev, iso); } }));
    else btns.add(Ui.outlineButton(this, "Share on WhatsApp", Ui.GREEN, { onClick: (v) => { ReportActivity.shareText(this, this.shareSick(iso)); } }));
    const br = Ui.buttonRow(this, btns.slice());
    page.addView(br);
    Ui.margins(br, 12, 4, 12, 4);

    const w = this.ward.equals("ALL") ? "" : " AND ward='" + this.ward.split("'").join("") + "'";
    const rows = db.rows("SELECT * FROM duty_sick WHERE date=?" + w
        + " ORDER BY CASE status WHEN 'Critical' THEN 0 WHEN 'Sick' THEN 1 ELSE 2 END, ward, id", iso);
    if (rows.isEmpty()) page.addView(this.emptyNote("No sick cases listed for this duty yet."));
    for (const r of rows) {
      let sub = (r.get("bed").isEmpty() ? "" : "Bed " + r.get("bed") + "  ·  ") + (r.get("ip_no").isEmpty() ? "" : "IP " + r.get("ip_no"));
      sub = sub.replaceAllRx("  ·  $", "");
      if (!r.get("issue").isEmpty()) sub += (sub.isEmpty() ? "" : "\n") + r.get("issue");
      sub += "\n" + (r.get("by_name").isEmpty() ? "" : r.get("by_name") + ", ") + Alerts.show(r.get("updated"));
      page.addView(this.entryCard(r.get("status"), CallDutyActivity.statusColor(r.get("status")), r.get("patient") + "  ·  " + Db.shortName(r.get("ward")), sub,
          "", { onClick: (v) => { this.sickDialog(r); } }));
    }
  }

  carryOver(prev, iso) {
    const db = this.db;
    for (const r of db.rows("SELECT * FROM duty_sick WHERE date=? AND status IN ('Sick','Critical')", prev)) {
      const cv = new ContentValues();
      for (const k of ["ward", "patient_id", "patient", "bed", "ip_no", "issue", "status", "by_name", "updated"]) cv.put(k, r.get(k));
      cv.put("date", iso);
      db.insert("duty_sick", cv);
    }
    this.render();
  }

  shareSick(iso) {
    const s = new StringBuilder("*Sick case list · call duty " + Dates.nice(iso) + "*\n");
    let last = "";
    for (const r of this.db.rows("SELECT * FROM duty_sick WHERE date=? ORDER BY ward, CASE status WHEN 'Critical' THEN 0 WHEN 'Sick' THEN 1 ELSE 2 END, id", iso)) {
      if (!r.get("ward").equals(last)) {
        s.append("\n*").append(Db.unitName(r.get("ward"))).append("*\n");
        last = r.get("ward");
      }
      s.append("• ").append(r.get("patient"));
      if (!r.get("bed").isEmpty()) s.append(", bed ").append(r.get("bed"));
      if (!r.get("ip_no").isEmpty()) s.append(", IP ").append(r.get("ip_no"));
      s.append(" – ").append(r.get("status"));
      if (!r.get("issue").isEmpty()) s.append(": ").append(r.get("issue"));
      s.append('\n');
    }
    return s.toString();
  }

  sickDialog(r) {
    const db = this.db;
    const f = new Form(this);
    const w = r != null ? r.get("ward") : this.ward.equals("ALL") ? db.todaysUnit() : this.ward;
    f.choice("ward", "Ward", Db.shortNames(CallDutyActivity.WARDS), CallDutyActivity.WARDS, w, null);
    const names = [];
    for (const p of db.rows("SELECT name FROM patients WHERE status='IN' ORDER BY admit_date DESC LIMIT 400")) names.add(p.get("name"));
    f.suggest("patient", "Patient name *", r == null ? "" : r.get("patient"), names.slice());
    f.text("bed", "Bed", r == null ? "" : r.get("bed"), Form.PLAIN);
    f.text("ip_no", "IP number", r == null ? "" : r.get("ip_no"), Form.PLAIN);
    f.multi("issue", "Problem / plan / what to watch", r == null ? "" : r.get("issue"));
    f.choice("status", "Status", CallDutyActivity.STATUS, CallDutyActivity.STATUS, r == null ? "Sick" : r.get("status"), null);
    f.text("by_name", "Updated by", CallDutyActivity.myName(this), Form.PLAIN);
    if (r != null) {
      const del = Ui.outlineButton(this, "Remove from list", Ui.RED, {
        onClick: (v) => {
          db.delete("duty_sick", Long.parseLong(r.get("id")));
          this.render();
        }
      });
      f.view.addView(del);
      Ui.margins(del, 0, 14, 0, 0);
    }
    Ui.formDialog(this, r == null ? "Add sick case" : "Update sick case", f, "Save", {
      run: () => {
        if (!f.require("patient", "Enter the patient's name")) return false;
        CallDutyActivity.rememberName(this, f.get("by_name"));
        const cv = new ContentValues();
        for (const k of ["ward", "patient", "bed", "ip_no", "issue", "status", "by_name"]) cv.put(k, f.get(k));
        cv.put("updated", Alerts.now());
        const p = db.row("SELECT * FROM patients WHERE status='IN' AND name=? ORDER BY id DESC LIMIT 1", f.get("patient"));
        if (p != null) {
          cv.put("patient_id", p.get("id"));
          if (f.get("bed").isEmpty()) cv.put("bed", p.get("bed"));
          if (f.get("ip_no").isEmpty()) cv.put("ip_no", p.get("ip_no"));
        }
        if (r == null) {
          cv.put("date", this.day.toString());
          db.insert("duty_sick", cv);
        } else db.update("duty_sick", cv, Long.parseLong(r.get("id")));
        this.render();
        return true;
      }
    });
  }

  // ---------- ward issues for the DAP ----------

  issues(page, iso) {
    const db = this.db;
    const box = Ui.card(this);
    const f = new Form(this);
    this.issueForm = f;
    f.choice("ward", "Ward", Db.shortNames(CallDutyActivity.WARDS), CallDutyActivity.WARDS, db.todaysUnit(), null);
    f.multi("text", "Issue / update for the DAP *", "");
    f.check("urgent", "Urgent: needs the DAP now", false);
    f.text("by_name", "From", CallDutyActivity.myName(this), Form.PLAIN);
    box.addView(f.view);
    const post = Ui.button(this, "Post to the group", Ui.TEAL, {
      onClick: (v) => {
        if (!f.require("text", "Write the issue")) return;
        CallDutyActivity.rememberName(this, f.get("by_name"));
        const cv = new ContentValues();
        cv.put("date", iso);
        cv.put("ward", f.get("ward"));
        cv.put("text", f.get("text"));
        cv.put("urgent", f.get("urgent"));
        cv.put("by_name", f.get("by_name"));
        cv.put("time", Alerts.now());
        cv.put("ack_by", "");
        cv.put("ack_time", "");
        db.insert("duty_notes", cv);
        Ui.toast(this, "Posted");
        this.issueForm = null;
        this.render();
      }
    });
    box.addView(post);
    Ui.margins(post, 0, 12, 0, 0);
    page.addView(box);

    const rows = db.rows("SELECT * FROM duty_notes WHERE date=? ORDER BY CASE WHEN urgent='1' AND ack_by='' THEN 0 ELSE 1 END, time DESC, id DESC", iso);
    if (rows.isEmpty()) page.addView(this.emptyNote("No issues posted for this duty."));
    for (const r of rows) {
      const urgent = "1" === r.get("urgent");
      const acked = !r.get("ack_by").isEmpty();
      const card = Ui.card(this);
      if (urgent && !acked) card.setBackground(Ui.outline(this, 0xFFFEF2F2, Ui.RED, 16));
      const top = Ui.h(this);
      top.setGravity(Gravity.CENTER_VERTICAL);
      top.addView(Ui.softPill(this, Db.shortName(r.get("ward")), Ui.unitColor(r.get("ward"))));
      if (urgent) {
        const u = Ui.softPill(this, "URGENT", Ui.RED);
        top.addView(u);
        Ui.margins(u, 6, 0, 0, 0);
      }
      const gap = new View(this);
      top.addView(gap, Ui.weight(1));
      top.addView(Ui.muted(this, Alerts.show(r.get("time"))));
      card.addView(top);
      const body = Ui.tv(this, r.get("text"), 15, Ui.TEXT, false);
      body.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 4));
      card.addView(body);
      card.addView(Ui.muted(this, "— " + (r.get("by_name").isEmpty() ? "call duty PG" : r.get("by_name"))));
      if (acked) {
        const a = Ui.tv(this, "✓ Seen by " + r.get("ack_by") + ", " + Alerts.show(r.get("ack_time")), 13, Ui.GREEN, true);
        a.setPadding(0, Ui.dp(this, 6), 0, 0);
        card.addView(a);
      } else {
        const a = Ui.outlineButton(this, "Seen / acknowledged", Ui.GREEN, { onClick: (v) => { this.acknowledge(r); } });
        card.addView(a);
        Ui.margins(a, 0, 8, 0, 0);
      }
      page.addView(card);
    }
  }

  acknowledge(r) {
    const db = this.db;
    const f = new Form(this);
    f.text("by", "Your name", CallDutyActivity.myName(this), Form.PLAIN);
    Ui.formDialog(this, "Acknowledge", f, "Seen", {
      run: () => {
        if (!f.require("by", "Enter your name")) return false;
        CallDutyActivity.rememberName(this, f.get("by"));
        const cv = new ContentValues();
        cv.put("ack_by", f.get("by"));
        cv.put("ack_time", Alerts.now());
        db.update("duty_notes", cv, Long.parseLong(r.get("id")));
        this.render();
        return true;
      }
    });
  }
}
;
