/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Call over: medicine opinions requested by other departments, and opinions medicine asks of other departments for its own patients. */
class CallOverActivity extends Base {
  constructor() {
    super();
    this.unit = "ALL";
    this.status = "OPEN";
    this.tab = "IN";
  }

  static THEIR_ROLES = ["PG", "Assistant Professor", "Other"];

  onCreate(b) {
    super.onCreate(b);
    const u = this.getIntent().getStringExtra("unit");
    if (u != null) this.unit = u;
    if ("OUT" === this.getIntent().getStringExtra("tab")) this.tab = "OUT";
    this.setTitle("Call over");
    this.subtitle = "Opinions for and from other departments";
    this.headerColor(Ui.TEAL);
  }

  /**
   * Who gives medicine opinions for TAEI ward cases at this hour: the admitting unit's PGs and Assistant Professor
   * from 9 AM to 2 PM, the DAP (with the call-duty PGs) from 2 PM to 7:30 AM.
   */
  static taeiAttending(db) {
    const t = Dates.time();
    const unit = db.todaysUnit();
    if (!t.isBefore(LocalTime.of(9, 0)) && t.isBefore(LocalTime.of(14, 0)))
      return unit + " PGs and Assistant Professor (9 AM to 2 PM)";
    if (!t.isBefore(Dates.CHANGEOVER) && t.isBefore(LocalTime.of(9, 0)))
      return unit + " PGs (Assistant Professor from 9 AM)";
    const dap = Census.dapOf(db, Dates.admitDay().toString());
    return "DAP" + (dap.isEmpty() ? "" : " " + dap) + " with the call-duty PGs (2 PM to 7:30 AM)";
  }

  static taeiCard(a, db) {
    const card = Ui.card(a);
    card.addView(Ui.tv(a, "TAEI ward call over", 15, Ui.unitColor(Db.TAEI), true));
    card.addView(Ui.tv(a, "Attending now: " + CallOverActivity.taeiAttending(db), 13, Ui.TEXT, false));
    card.addView(Ui.muted(a, "9 AM to 2 PM: admitting unit PGs and Assistant Professor  ·  2 PM to 7:30 AM: DAP"));
    const pend = db.num("SELECT COUNT(*) FROM callover WHERE dept=? AND status IN ('Pending','Follow-up')", Db.TAEI_DEPT);
    const b = Ui.button(a, "+ TAEI opinion request" + (pend > 0 ? "  ·  " + pend + " open" : ""), Ui.unitColor(Db.TAEI),
        a.opener(FormActivity, "kind", "callover", "unit", db.todaysUnit(), "dept", Db.TAEI_DEPT));
    card.addView(b);
    Ui.margins(b, 0, 8, 0, 0);
    return card;
  }

  render() {
    const db = this.db;
    const page = Ui.v(this);
    page.addView(this.tabs());
    if ("OUT" === this.tab) {
      this.headerAction("+ Ask", { onClick: (v) => { Opinions.dialog(this, db, null, null, this.refresh()); } });
      this.renderOut(page);
      this.setPage(page);
      return;
    }
    this.headerAction("+ New", this.opener(FormActivity, "kind", "callover", "unit", "ALL" === this.unit ? db.todaysUnit() : this.unit));
    const iso = Dates.todayIso();

    const sum = Ui.card(this);
    sum.addView(Ui.statRow(this,
        Ui.stat(this, String(db.num("SELECT COUNT(*) FROM callover WHERE date=?", iso)), "Today", Ui.TEAL),
        Ui.stat(this, String(db.num("SELECT COUNT(*) FROM callover WHERE status='Pending'")), "Pending", Ui.ORANGE),
        Ui.stat(this, String(db.num("SELECT COUNT(*) FROM callover WHERE status='Follow-up'")), "Follow-up", Ui.AMBER),
        Ui.stat(this, String(db.num("SELECT COUNT(*) FROM callover WHERE date>=?", Dates.monthStart(Dates.today()).toString())), "This month", Ui.PRIMARY)));
    page.addView(sum);
    page.addView(CallOverActivity.taeiCard(this, db));

    const uc = Ui.h(this);
    uc.setPadding(Ui.dp(this, 12), Ui.dp(this, 10), Ui.dp(this, 12), Ui.dp(this, 4));
    const us = [];
    us.add("ALL");
    us.addAll(Db.WARD_UNITS);
    if ("OUT" === this.tab) us.add(Db.IMCU);
    for (const u of us) {
      const c = Ui.chip(this, "ALL" === u ? "All units" : u, u.equals(this.unit), "ALL" === u ? Ui.TEAL : Ui.unitColor(u));
      c.setOnClickListener({ onClick: (v) => { this.unit = u; this.render(); } });
      uc.addView(c);
    }
    page.addView(Ui.hscroll(this, uc));
    const sc = Ui.h(this);
    sc.setPadding(Ui.dp(this, 12), Ui.dp(this, 4), Ui.dp(this, 12), Ui.dp(this, 4));
    const keys = ["OPEN", "ALL", "Seen", "Taken over", "Transferred to medicine"];
    const labels = ["Open", "All", "Seen", "Taken over", "Transferred"];
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i];
      const c = Ui.chip(this, labels[i], k.equals(this.status), Ui.TEAL);
      c.setOnClickListener({ onClick: (v) => { this.status = k; this.render(); } });
      sc.addView(c);
    }
    page.addView(Ui.hscroll(this, sc));

    const sql = new StringBuilder("SELECT * FROM callover WHERE 1=1");
    const args = [];
    if (!"ALL".equals(this.unit)) { sql.append(" AND unit=?"); args.add(this.unit); }
    if ("OPEN".equals(this.status)) sql.append(" AND status IN ('Pending','Follow-up')");
    else if (!"ALL".equals(this.status)) { sql.append(" AND status=?"); args.add(this.status); }
    sql.append(" ORDER BY date DESC, time DESC, id DESC LIMIT 200");
    const rows = db.rows(sql.toString(), args.slice());
    page.addView(Ui.section(this, rows.size() + " call overs"));
    if (rows.isEmpty()) page.addView(this.emptyNote("No call overs here."));
    for (const r of rows) {
      const st = r.get("status");
      const col = "Pending" === st ? Ui.ORANGE : "Follow-up" === st ? Ui.AMBER : Ui.GREEN;
      const card = this.entryCard(r.get("unit") + "  ·  " + st, col,
          r.get("patient") + (r.get("age_sex").isEmpty() ? "" : ", " + r.get("age_sex")),
          r.get("dept") + (r.get("ward").isEmpty() ? "" : " · " + r.get("ward")) + (r.get("reason").isEmpty() ? "" : "\n" + r.get("reason"))
          + (r.get("seen_by").isEmpty() ? "" : "\nSeen by " + r.get("seen_by")) + (r.get("advice").isEmpty() ? "" : ": " + r.get("advice")),
          Dates.nice(r.get("date")) + " " + r.get("time"),
          this.opener(FormActivity, "kind", "callover", "id", r.get("id")));
      page.addView(card);
    }
    this.setPage(page);
  }

  /** The opinion as a WhatsApp message to the other department's doctor. */
  static message(db, r) {
    const sb = new StringBuilder("🩺 *Medicine opinion (call over)*\nDepartment of Medicine, TVMCH\n");
    const doc = Ui.nz(r.get("their_doc")), role = Ui.nz(r.get("their_role"));
    if (!doc.isEmpty() || !Ui.nz(r.get("dept")).isEmpty())
      sb.append("\nTo: ").append(doc.isEmpty() ? "" : doc + (role.isEmpty() || "Other" === role ? "" : " (" + role + ")") + ", ").append(Ui.nz(r.get("dept")));
    sb.append("\nPatient: ").append(Ui.nz(r.get("patient")));
    if (!Ui.nz(r.get("age_sex")).isEmpty()) sb.append(", ").append(r.get("age_sex"));
    if (!Ui.nz(r.get("ip_no")).isEmpty()) sb.append(", IP ").append(r.get("ip_no"));
    if (!Ui.nz(r.get("ward")).isEmpty()) sb.append("\nWard / bed: ").append(r.get("ward"));
    if (!Ui.nz(r.get("reason")).isEmpty()) sb.append("\nReason: ").append(r.get("reason"));
    sb.append("\n\n*Opinion / advice:*\n").append(Ui.nz(r.get("advice")).isEmpty() ? "To be seen" : r.get("advice"));
    sb.append("\n\nSeen by: ").append(Ui.nz(r.get("seen_by")).isEmpty() ? "-" : r.get("seen_by")).append(" (").append(Ui.nz(r.get("unit"))).append(" unit, Medicine)");
    sb.append("\nStatus: ").append(Ui.nz(r.get("status")));
    sb.append("\n").append(Dates.nice(r.get("date"))).append(" ").append(Ui.nz(r.get("time")));
    return sb.toString();
  }

  /** Opens WhatsApp on the other department's doctor's chat with the opinion typed in, ready to send. */
  static sendWhatsApp(a, r) {
    const to = PhoneDirectoryActivity.whatsapp(Ui.nz(r.get("their_phone")));
    const text = CallOverActivity.message(a.db, r);
    const u = Uri.parse("https://wa.me/" + to + "?text=" + Uri.encode(text));
    for (const pkg of ["com.whatsapp", "com.whatsapp.w4b"]) {
      try {
        a.startActivity(new Intent(Intent.ACTION_VIEW, u).setPackage(pkg));
        return;
      } catch (ignored) {
      }
    }
    try {
      a.startActivity(new Intent(Intent.ACTION_VIEW, u));
    } catch (e) {
      Ui.toast(a, "WhatsApp is not installed");
    }
  }

  refresh() {
    return { run: () => { this.render(); } };
  }

  /** Two tabs: opinions we give (for other departments) and opinions we ask (from other departments). */
  tabs() {
    const db = this.db;
    const row = Ui.h(this);
    row.setPadding(Ui.dp(this, 12), Ui.dp(this, 10), Ui.dp(this, 12), Ui.dp(this, 2));
    const t = [["IN", "For other departments", String(db.num("SELECT COUNT(*) FROM callover WHERE status IN ('Pending','Follow-up')"))],
      ["OUT", "From other departments", String(db.num("SELECT COUNT(*) FROM opinions WHERE " + Opinions.OPEN_SQL))]];
    for (let i = 0; i < t.length; i++) {
      const k = t[i][0];
      const on = k.equals(this.tab);
      const b = Ui.v(this);
      b.setGravity(Gravity.CENTER);
      b.setPadding(Ui.dp(this, 8), Ui.dp(this, 10), Ui.dp(this, 8), Ui.dp(this, 10));
      const bg = Ui.round(this, on ? Ui.TEAL : 0xFFFFFFFF, 14);
      if (!on) bg.setStroke(Ui.dp(this, 1), Ui.alpha(Ui.TEAL, 0x55));
      b.setBackground(bg);
      const l = Ui.tv(this, t[i][1], 14, on ? 0xFFFFFFFF : Ui.TEAL, true);
      l.setGravity(Gravity.CENTER);
      b.addView(l);
      const n = Ui.tv(this, t[i][2] + " open", 12, on ? 0xD9FFFFFF : Ui.MUTED, false);
      n.setGravity(Gravity.CENTER);
      b.addView(n);
      b.setOnClickListener({ onClick: (v) => { this.tab = k; this.status = "OPEN"; this.render(); } });
      const lp = Ui.weight(1);
      lp.setMargins(i === 0 ? 0 : Ui.dp(this, 5), 0, i === 0 ? Ui.dp(this, 5) : 0, 0);
      row.addView(b, lp);
    }
    return row;
  }

  /** Opinions medicine asked of other departments for its own patients. */
  renderOut(page) {
    const db = this.db;
    const iso = Dates.todayIso();
    const sum = Ui.card(this);
    sum.addView(Ui.statRow(this,
        Ui.stat(this, String(db.num("SELECT COUNT(*) FROM opinions WHERE date=?", iso)), "Asked today", Ui.TEAL),
        Ui.stat(this, String(db.num("SELECT COUNT(*) FROM opinions WHERE status='Requested'")), "Awaiting", Ui.ORANGE),
        Ui.stat(this, String(db.num("SELECT COUNT(*) FROM opinions WHERE status='Requested' AND urgency<>'Routine'")), "Urgent", Ui.RED),
        Ui.stat(this, String(db.num("SELECT COUNT(*) FROM opinions WHERE date>=?", Dates.monthStart(Dates.today()).toString())), "This month", Ui.PRIMARY)));
    page.addView(sum);

    const uc = Ui.h(this);
    uc.setPadding(Ui.dp(this, 12), Ui.dp(this, 10), Ui.dp(this, 12), Ui.dp(this, 4));
    const us = [];
    us.add("ALL");
    us.addAll(VipActivity.UNITS);
    for (const u of us) {
      const c = Ui.chip(this, "ALL" === u ? "All units" : Db.shortName(u), u.equals(this.unit), "ALL" === u ? Ui.TEAL : Ui.unitColor(u));
      c.setOnClickListener({ onClick: (v) => { this.unit = u; this.render(); } });
      uc.addView(c);
    }
    page.addView(Ui.hscroll(this, uc));
    const sc = Ui.h(this);
    sc.setPadding(Ui.dp(this, 12), Ui.dp(this, 4), Ui.dp(this, 12), Ui.dp(this, 4));
    const keys = ["OPEN", "ALL", "Seen", "Transferred out", "Cancelled"];
    const labels = ["Open", "All", "Seen", "Transferred", "Cancelled"];
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i];
      const c = Ui.chip(this, labels[i], k.equals(this.status), Ui.TEAL);
      c.setOnClickListener({ onClick: (v) => { this.status = k; this.render(); } });
      sc.addView(c);
    }
    page.addView(Ui.hscroll(this, sc));

    const sql = new StringBuilder("SELECT * FROM opinions WHERE 1=1");
    const args = [];
    if (!"ALL".equals(this.unit)) { sql.append(" AND unit=?"); args.add(this.unit); }
    if ("OPEN".equals(this.status)) sql.append(" AND ").append(Opinions.OPEN_SQL);
    else if (!"ALL".equals(this.status)) { sql.append(" AND status=?"); args.add(this.status); }
    sql.append(" ORDER BY CASE urgency WHEN 'Emergency' THEN 0 WHEN 'Urgent' THEN 1 ELSE 2 END, date DESC, time DESC, id DESC LIMIT 200");
    const rows = db.rows(sql.toString(), args.slice());
    page.addView(Ui.section(this, rows.size() + " opinions asked"));
    if (rows.isEmpty()) page.addView(this.emptyNote("No opinions asked here. Tap “+ Ask” to ask cardiology, nephrology, surgery or any other department to see a medicine patient."));
    for (const r of rows) page.addView(Opinions.card(this, db, r, true, this.refresh()));
  }
}
;
