CaseSheet.Field = class {
  constructor(key, label, kind, ...options) {
    if (options.length === 1 && Array.isArray(options[0])) options = options[0];
    this.key = key;
    this.label = label;
    this.kind = kind;
    this.options = options;
    /** Half width: two half fields in a row sit side by side. (Java field "half"; renamed because half() is a method.) */
    this.isHalf = false;
    /** Shown only when field ifKey has the answer ifVal (e.g. X-ray findings only when abnormal). */
    this.ifKey = null;
    this.ifVal = null;
    /** "M" or "F" when the field is asked only for that sex (prostate, uterus). */
    this.sex = null;
    /** WHEEL: the range of the rolling number picker. */
    this.min = 0;
    this.max = 0;
  }

  half() {
    this.isHalf = true;
    return this;
  }

  only(sex) {
    this.sex = sex;
    return this;
  }

  forSex(patientSex) {
    return this.sex == null || this.sex === patientSex;
  }

  when(key, val) {
    this.ifKey = key;
    this.ifVal = val;
    return this;
  }
};

CaseSheet.Section = class {
  constructor(key, number, title, femaleOnly, ...fields) {
    if (fields.length === 1 && Array.isArray(fields[0])) fields = fields[0];
    this.key = key;
    this.number = number;
    this.title = title;
    this.femaleOnly = femaleOnly;
    this.fields = fields;
  }
};

/** The ABG worked out step by step: disorder, compensation, anion gap, delta ratio and oxygenation. */
CaseSheet.AbgCalc = class {
  constructor() {
    this.reading = "";
    this.steps = [];
    this.ag = NaN;
  }
};
;
