/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * The daily census of one admission day (7:30 AM to 7:30 AM): IP census, death diagnosis, TEAI toxicology, stroke and snake bite,
 * in the department's own layout. A snapshot is posted to the census table at 7:30 AM for the day just ended.
 */
class Census {
  static ACTION = "com.tvmchmed.app.CENSUS";
  static REPORTS = ["ip", "deaths", "tox", "stroke", "snake"];
  static REPORT_LABELS = ["IP census", "Death diagnosis", "Toxicology", "Stroke", "Snake bite"];
  static ROWS = ["Triage", "Medicine OPD", "IMCU", "Kandiyaperi", "Callovers", "Transfer in from other departments", "Transfer in from TEAI ward"];
  static SHORT = DateTimeFormatter.ofPattern("d/M/yy", Locale.ENGLISH);
  static DOTS = DateTimeFormatter.ofPattern("d.M.yy", Locale.ENGLISH);
  static SNAKE_COLS = ["Cobra", "Krait", "Russell's viper", "Saw-scaled viper", "Unknown"];

  // ---------- building ----------

  /** "admission day" window: events on day after 7:30, or the next day before 7:30. */
  static window(alias) {
    const d = alias + ".date", t = "IFNULL(" + alias + ".time,'')";
    return "((" + d + "=? AND (" + t + "='' OR " + t + ">='07:30')) OR (" + d + "=? AND " + t + "<>'' AND " + t + "<'07:30'))";
  }

  static unitOf(db, day) {
    const au = db.admittingUnits(Dates.dow(day));
    return au.isEmpty() ? "" : au.get(0);
  }

  static dapOf(db, iso) {
    const r = db.row("SELECT dap FROM duty_roster WHERE date=? AND IFNULL(dap,'')<>'' ORDER BY id DESC LIMIT 1", iso);
    if (r != null) return Roster.name(r.get("dap").trim().jsplit("\n")[0]);
    const d = db.row("SELECT dap_name FROM dap WHERE date=? AND dap_name<>'' ORDER BY id DESC LIMIT 1", iso);
    return d == null ? "" : d.get("dap_name");
  }

  static sexOf(s) {
    const t = Ui.nz(s).trim().toUpperCase();
    if (t.equals("M") || t.equals("F")) return t;
    const m = Pattern.compile("(?i)(?:^|[^a-z])(m|f|male|female)(?:[^a-z]|$)").matcher(Ui.nz(s));
    let last = "";
    while (m.find()) last = m.group(1).substring(0, 1).toUpperCase();
    return last;
  }

  static ageSex(p) {
    return Ui.nz(p.get("age")) + "/" + Ui.nz(p.get("sex")).toLowerCase();
  }

  /** "Ramraj 75/m 117214", as the department writes it. */
  static person(p) {
    return (Ui.nz(p.get("name")) + " " + Census.ageSex(p) + " " + Ui.nz(p.get("ip_no"))).trim();
  }

  static rowOf(p) {
    const to = Ui.nz(p.get("adm_to")), src = Ui.nz(p.get("source"));
    if (Db.KDP.equals(to)) return "Kandiyaperi";
    if ("OPD".equals(src)) return "Medicine OPD";
    if ("OTHER_DEPT".equals(src)) return "Transfer in from other departments";
    if ("TEAI".equals(src)) return "Transfer in from TEAI ward";
    if (Db.IMCU.equals(to)) return "IMCU";
    return "Triage";
  }

  static isStroke(p) {
    return Db.STROKE.equals(p.get("category")) || Db.STROKE.equals(Db.categoryIn(p.get("diagnosis"))) || !Ui.nz(p.get("st_type")).isEmpty();
  }

  static toxGroup(kind) {
    if (kind.equals("Poisoning") || kind.equals(Db.RAT_KILLER)) return "POISONING";
    if (kind.equals("Drowning")) return "DROWNING";
    if (kind.equals("Hanging")) return "HANGING";
    return "BITES";
  }

  static deathPlace(p) {
    const dp = Ui.nz(p.get("death_place"));
    if (!dp.isEmpty()) return dp;
    const loc = Ui.nz(p.get("d_loc"));
    if (Db.IMCU.equals(loc)) return "IMCU";
    if (Db.CCB.equals(loc)) return "Critical care block";
    if (Db.TRIAGE.equals(loc)) return "Triage";
    return "Ward";
  }

  /** Works out the whole census for the admission day starting at 7:30 AM on day. */
  static build(c, db, day) {
    const iso = day.toString(), next = day.plusDays(1).toString();
    const o = new JSONObject();
    o.put("day", iso);
    o.put("unit", Census.unitOf(db, day));
    o.put("dap", Census.dapOf(db, iso));
    o.put("from", day.format(Census.SHORT));
    o.put("to", day.plusDays(1).format(Census.SHORT));
    o.put("weekday", day.getDayOfWeek().getDisplayName(TextStyle.FULL, Locale.ENGLISH).toUpperCase());

    const adm = db.rows("SELECT p.*, e.to_loc AS adm_to, e.date AS adm_date, e.time AS adm_time FROM patients p JOIN events e ON e.patient_id=p.id AND e.type='ADMIT' WHERE "
        + Census.window("e") + " ORDER BY e.date, e.time, p.id", iso, next);

    // IP census table: toxic M, F | non-toxic M, F per row
    const t = new JMap();
    for (const r of Census.ROWS) t.put(r, new Array(4).fill(0));
    let hemo = 0, stroke = 0, isch = 0, haem = 0, snake = 0, tox = 0, mlc = 0, convict = 0, staff = 0, idw = 0;
    const idDis = new JMap();
    for (const p of adm) {
      const toxic = !Ui.nz(p.get("tox_kind")).isEmpty();
      const col = (toxic ? 0 : 2) + ("F".equals(p.get("sex")) ? 1 : 0);
      t.get(Census.rowOf(p))[col]++;
      if (Db.HEMOPHILIA.equals(p.get("category")) || Db.HEMOPHILIA.equals(Db.categoryIn(p.get("diagnosis")))) hemo++;
      if (Census.isStroke(p)) {
        stroke++;
        if ("Ischaemic".equals(p.get("st_type"))) isch++;
        if ("Haemorrhagic".equals(p.get("st_type"))) haem++;
      }
      if (Db.isSnakeBite(p)) snake++;
      if (toxic) tox++;
      if ("MLC".equals(p.get("mlc"))) mlc++;
      if ("1".equals(p.get("convict"))) convict++;
      if ("1".equals(p.get("staff_pt"))) staff++;
      if ("1".equals(p.get("id_ward")) || Db.IDW.equals(p.get("adm_to")) || Db.IDW.equals(p.get("location"))) {
        idw++;
        let d = Ui.nz(p.get("id_disease"));
        if (d.isEmpty()) d = "Other";
        idDis.put(d, idDis.containsKey(d) ? idDis.get(d) + 1 : 1);
      }
    }
    const idText = new StringBuilder();
    for (const e of idDis.entrySet()) idText.append(idText.length() === 0 ? "" : ", ").append(e.getKey()).append(" ").append(e.getValue());
    for (const r of db.rows("SELECT age_sex FROM callover c WHERE " + Census.window("c"), iso, next)) {
      const s = Census.sexOf(r.get("age_sex"));
      t.get("Callovers")[2 + ("F".equals(s) ? 1 : 0)]++;
    }
    const rows = new JSONArray();
    let grand = 0;
    for (const e of t.entrySet()) {
      const v = e.getValue();
      const r = new JSONArray().put(e.getKey());
      for (const x of v) r.put(x);
      rows.put(r);
      grand += v[0] + v[1] + v[2] + v[3];
    }
    o.put("rows", rows);
    o.put("grand", grand);
    const n = new JSONObject();
    n.put("hemophilia", hemo).put("stroke", stroke).put("ischaemic", isch).put("haemorrhagic", haem).put("snake", snake).put("tox", tox)
        .put("mlc", mlc).put("convict", convict).put("staff", staff).put("idward", idw).put("idward_detail", idText.toString()).put("admitted", adm.size());
    o.put("counts", n);

    // deaths in the window, wherever they were
    const deaths = new JSONArray();
    for (const p of db.rows("SELECT p.*, e.note AS cause, e.from_loc AS d_loc FROM events e JOIN patients p ON p.id=e.patient_id WHERE e.type='DEATH' AND "
        + Census.window("e") + " ORDER BY e.date, e.time", iso, next)) {
      deaths.put(new JSONObject().put("place", Census.deathPlace(p)).put("cause", Ui.nz(p.get("cause")).isEmpty() ? Ui.nz(p.get("diagnosis")) : p.get("cause"))
          .put("person", Census.person(p)));
    }
    o.put("deaths", deaths);

    // case sheets written, by PG
    const by = new JMap();
    let sheets = 0;
    for (const p of adm) {
      const w = Ui.nz(p.get("cs_by")).trim();
      if (w.isEmpty()) continue;
      sheets++;
      const k = w + (Ui.nz(p.get("cs_year")).isEmpty() ? "" : " (" + p.get("cs_year") + ")");
      by.put(k, (by.containsKey(k) ? by.get(k) : 0) + 1);
    }
    const sh = new JSONArray();
    for (const e of by.entrySet()) sh.put(new JSONArray().put(e.getKey()).put(e.getValue()));
    o.put("sheets", sh);
    o.put("sheetsTotal", sheets);

    // toxicology (TEAI)
    const tx = new JSONArray();
    for (const p of adm) {
      const k = Ui.nz(p.get("tox_kind"));
      if (k.isEmpty()) continue;
      let cat = Ui.nz(p.get("tox_agent"));
      if (cat.isEmpty()) cat = k.equals("Snake bite") && !Ui.nz(p.get("sb_snake")).isEmpty() && !"Unknown".equals(p.get("sb_snake")) ? "Snake bite (" + p.get("sb_snake") + ")" : k;
      tx.put(new JSONObject().put("group", Census.toxGroup(k)).put("name", p.get("name")).put("age", Census.ageSex(p)).put("ip", Ui.nz(p.get("ip_no")))
          .put("cat", cat).put("reg", Ui.nz(p.get("teai_reg"))).put("upd", Ui.nz(p.get("teai_upd"))));
    }
    o.put("tox", tx);

    // stroke
    const st = new JSONArray();
    for (const p of adm) {
      if (!Census.isStroke(p)) continue;
      const outcome = Db.DIED.equals(p.get("status")) ? "Died" : Db.DISCHARGED.equals(p.get("status")) ? "Recovered" : "In hospital";
      st.put(new JSONObject().put("person", Census.person(p)).put("type", Ui.nz(p.get("st_type"))).put("ct", "1".equals(p.get("st_ct")))
          .put("mri", "1".equals(p.get("st_mri"))).put("window", Ui.nz(p.get("st_window"))).put("lysis", Ui.nz(p.get("st_lysis"))).put("outcome", outcome));
    }
    o.put("stroke", st);

    // snake bite
    const sb = new JSONArray();
    for (const p of adm) {
      if (!Db.isSnakeBite(p)) continue;
      const imcu = Db.IMCU.equals(p.get("adm_to")) || Db.IMCU.equals(p.get("location"));
      sb.put(new JSONObject().put("date", day.format(Census.DOTS)).put("unit", Ui.nz(p.get("home_unit")).isEmpty() ? o.optString("unit") : p.get("home_unit"))
          .put("imcu", imcu).put("sex", Ui.nz(p.get("sex"))).put("person", Census.person(p)).put("dn", Ui.nz(p.get("sb_daynight")))
          .put("part", Ui.nz(p.get("sb_part"))).put("delay", Ui.nz(p.get("sb_delay"))).put("died", Db.DIED.equals(p.get("status")))
          .put("asv", Ui.nz(p.get("sb_asv"))).put("snake", Ui.nz(p.get("sb_snake"))));
    }
    o.put("snake", sb);
    return o;
  }

  // ---------- posting ----------

  static posted(db, iso) {
    return db.row("SELECT * FROM census WHERE day=?", iso);
  }

  static save(db, o, by, auto) {
    const cv = new ContentValues();
    cv.put("day", o.optString("day"));
    cv.put("unit", o.optString("unit"));
    cv.put("dap", o.optString("dap"));
    cv.put("data", o.toString());
    cv.put("posted_at", Alerts.now());
    cv.put("posted_by", by);
    cv.put("auto", auto ? "1" : "");
    db.getWritableDatabase().insertWithOnConflict("census", null, cv, SQLiteDatabase.CONFLICT_REPLACE);
    Sync.kick(db.ctx);
  }

  /** The admission day whose census is due now: the one that ended at 7:30 this morning. */
  static dueDay() {
    return Dates.admitDay().minusDays(1);
  }

  /** Posts the census of the day that just ended, if nobody has yet. Returns it when this phone posted it. */
  static autoPost(c) {
    const db = Db.get(c);
    const day = Census.dueDay();
    if (Census.posted(db, day.toString()) != null) return null;
    try {
      const o = Census.build(c, db, day);
      Census.save(db, o, "Posted automatically at 7:30 AM", true);
      Census.notifyPosted(c, o);
      return o;
    } catch (e) {
      if (e instanceof JSONException) return null;
      throw e;
    }
  }

  /** On opening the app: post a census that is overdue (after fetching the latest records when shared online). */
  static catchUp(c) {
    const db = Db.get(c);
    if (Census.posted(db, Census.dueDay().toString()) != null) return;
    if (!Cloud.active(c)) {
      Census.autoPost(c);
      return;
    }
    Sync.now(c, {
      done: (err) => { Census.autoPost(c); }
    });
  }

  /** Alarm for the next 7:30 AM. */
  static schedule(c) {
    const app = c.getApplicationContext();
    const am = app.getSystemService(Context.ALARM_SERVICE);
    if (am == null) return;
    const pi = PendingIntent.getBroadcast(app, 7, new Intent(app, Reminders.Receiver).setAction(Census.ACTION),
        PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
    const now = LocalDateTime.now();
    let at = Dates.today().atTime(Dates.CHANGEOVER).plusMinutes(1);
    if (!at.isAfter(now)) at = at.plusDays(1);
    const when = Reminders.millis(at);
    if (Build.VERSION.SDK_INT < 31 || am.canScheduleExactAlarms()) am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, when, pi);
    else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, when, pi);
  }

  static notifyPosted(c, o) {
    Reminders.channel(c);
    const nm = c.getSystemService(Context.NOTIFICATION_SERVICE);
    if (nm == null) return;
    const open = new Intent(c, CensusActivity).putExtra("day", o.optString("day"));
    open.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TOP);
    const pi = PendingIntent.getActivity(c, 7307, open, PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
    const text = Census.headline(o);
    const b = Build.VERSION.SDK_INT >= 26 ? new Notification.Builder(c, Reminders.CHANNEL) : new Notification.Builder(c);
    b.setSmallIcon(R.drawable.ic_census).setContentTitle("Daily census posted · " + o.optString("unit") + " admission day")
        .setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text + "\nTap to see it and share it on WhatsApp."))
        .setColor(Ui.PRIMARY).setAutoCancel(true).setContentIntent(pi);
    nm.notify(7307, b.build());
  }

  static headline(o) {
    return Dates.nice(o.optString("day")) + ": " + o.optInt("grand") + " in IP census, " + o.optJSONArray("deaths").length() + " deaths";
  }

  // ---------- text for WhatsApp ----------

  static text(o, report) {
    switch (report) {
      case "deaths": return Census.deathsText(o);
      case "tox": return Census.toxText(o);
      case "stroke": return Census.strokeText(o);
      case "snake": return Census.snakeText(o);
      default: return Census.ipText(o);
    }
  }

  static allText(o) {
    const b = new StringBuilder();
    for (const r of Census.REPORTS) b.append(b.length() === 0 ? "" : "\n\n━━━━━━━━━━\n\n").append(Census.text(o, r));
    return b.toString();
  }

  static head(o) {
    return "*ADMISSION DAY UNIT " + o.optString("unit") + "*\nDATE: " + o.optString("from") + " to " + o.optString("to")
        + "\nDAY: " + o.optString("weekday") + "\nDAP: " + (o.optString("dap").isEmpty() ? "-" : o.optString("dap"));
  }

  static ipText(o) {
    const b = new StringBuilder(Census.head(o)).append("\n\n*GRAND TOTAL IP CENSUS: ").append(o.optInt("grand")).append("*\n");
    const rows = o.optJSONArray("rows");
    for (let i = 0; i < rows.length(); i++) {
      const r = rows.optJSONArray(i);
      const tm = r.optInt(1), tf = r.optInt(2), nm = r.optInt(3), nf = r.optInt(4);
      const call = r.optString(0).equals("Callovers");
      b.append("\n*").append(r.optString(0)).append("*: ");
      if (!call) b.append("Toxic M ").append(tm).append(" F ").append(tf).append(" · Non-toxic M ").append(nm).append(" F ").append(nf).append(" · ");
      b.append("Total M ").append(tm + nm).append(" F ").append(tf + nf);
    }
    const n = o.optJSONObject("counts");
    b.append("\n\nHemophilia: ").append(n.optInt("hemophilia"))
        .append("\nTotal stroke cases: ").append(n.optInt("stroke")).append(" (Ischaemic ").append(n.optInt("ischaemic")).append(", Haemorrhagic ").append(n.optInt("haemorrhagic")).append(")")
        .append("\nSnake bite: ").append(n.optInt("snake"))
        .append("\nToxicology: ").append(n.optInt("tox"))
        .append("\nMLC: ").append(n.optInt("mlc"))
        .append("\nConvict: ").append(n.optInt("convict"))
        .append("\nStudents/Staff: ").append(n.optInt("staff"))
        .append("\nID ward: ").append(n.optInt("idward")).append(n.optString("idward_detail").isEmpty() ? "" : " (" + n.optString("idward_detail") + ")");
    const dp = Census.deathsByPlace(o);
    const total = o.optJSONArray("deaths").length();
    b.append("\n\n*Total no. of deaths: ").append(total).append("*");
    for (const e of dp.entrySet()) b.append("\n").append(e.getKey()).append(" - ").append(e.getValue());
    const sh = o.optJSONArray("sheets");
    b.append("\n\n*No. of case sheets written: ").append(o.optInt("sheetsTotal")).append("*");
    for (let i = 0; i < sh.length(); i++) b.append("\n").append(sh.optJSONArray(i).optString(0)).append("  ").append(sh.optJSONArray(i).optInt(1));
    return b.toString();
  }

  static deathsByPlace(o) {
    const m = new JMap();
    for (const p of Db.DEATH_PLACES) m.put(p, 0);
    const d = o.optJSONArray("deaths");
    for (let i = 0; i < d.length(); i++) {
      const p = d.optJSONObject(i).optString("place");
      m.put(p, (m.containsKey(p) ? m.get(p) : 0) + 1);
    }
    return m;
  }

  static deathsText(o) {
    const d = o.optJSONArray("deaths");
    const b = new StringBuilder("*Death diagnosis – " + d.length() + "*\n" + o.optString("from") + " to " + o.optString("to"));
    if (d.length() === 0) return b.append("\n\nNil").toString();
    for (const place of Db.DEATH_PLACES) {
      const causes = [];
      for (let i = 0; i < d.length(); i++) if (place.equals(d.optJSONObject(i).optString("place"))) causes.add(d.optJSONObject(i).optString("cause"));
      if (causes.isEmpty()) continue;
      b.append("\n\n*").append(place).append(" – ").append(causes.size()).append("*");
      for (let i = 0; i < causes.size(); i++) b.append("\n").append(i + 1).append(". ").append(causes.get(i).split("\n").join(" "));
    }
    return b.toString();
  }

  static toxText(o) {
    const t = o.optJSONArray("tox");
    const b = new StringBuilder("*TEAI TOXICOLOGY CENSUS – " + Census.dayRange(o) + "*");
    for (const g of ["POISONING", "BITES", "DROWNING", "HANGING"]) {
      const inn = [];
      for (let i = 0; i < t.length(); i++) if (g.equals(t.optJSONObject(i).optString("group"))) inn.add(t.optJSONObject(i));
      if (inn.isEmpty()) {
        b.append("\n\n*").append(g).append("* – NIL");
        continue;
      }
      b.append("\n\n*").append(g).append("*");
      for (let i = 0; i < inn.size(); i++) {
        const x = inn.get(i);
        b.append("\n").append(i + 1).append(". ").append(x.optString("name")).append(" ").append(x.optString("age")).append(" – ").append(x.optString("cat"))
            .append(" · TEAI registered: ").append(Census.yn(x.optString("reg"))).append(", updated: ").append(Census.yn(x.optString("upd")));
      }
    }
    return b.toString();
  }

  static yn(s) {
    return s.isEmpty() ? "?" : s.toLowerCase();
  }

  static dayRange(o) {
    const d = Dates.parse(o.optString("day"));
    if (d == null) return "";
    const f = DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH);
    return (d.format(f) + " to " + d.plusDays(1).format(f)).toUpperCase();
  }

  /** The stroke sheet's columns: heading and the names under it. */
  static strokeColumns(o) {
    const s = o.optJSONArray("stroke");
    const cols = [
        ["Names of ischaemic stroke patients", "type", "Ischaemic"], ["Names of haemorrhagic stroke patients", "type", "Haemorrhagic"],
        ["CT scan taken for stroke", "ct", "true"], ["MRI scan taken for stroke", "mri", "true"],
        ["Ischaemic stroke received within 4.5 hours", "window", "Within 4.5 h"], ["Ischaemic stroke received within 4.5 to 6 hours", "window", "4.5 to 6 h"],
        ["Ischaemic stroke received within 6 to 12 hours", "window", "6 to 12 h"], ["Thrombolysed", "lysis", "Yes"],
        ["In window period, not thrombolysed", "nolysis", ""], ["Ischaemic stroke died", "died", "Ischaemic"], ["Haemorrhagic stroke died", "died", "Haemorrhagic"],
        ["Ischaemic stroke recovered", "rec", "Ischaemic"], ["Haemorrhagic stroke recovered", "rec", "Haemorrhagic"]];
    const out = [];
    for (const col of cols) {
      const names = [];
      for (let i = 0; i < s.length(); i++) {
        const x = s.optJSONObject(i);
        let ok;
        switch (col[1]) {
          case "ct": ok = x.optBoolean("ct"); break;
          case "mri": ok = x.optBoolean("mri"); break;
          case "window": ok = col[2].equals(x.optString("window")) && !"Haemorrhagic".equals(x.optString("type")); break;
          case "nolysis": ok = "Within 4.5 h".equals(x.optString("window")) && !"Yes".equals(x.optString("lysis")) && !"Haemorrhagic".equals(x.optString("type")); break;
          case "died": ok = "Died".equals(x.optString("outcome")) && col[2].equals(x.optString("type")); break;
          case "rec": ok = "Recovered".equals(x.optString("outcome")) && col[2].equals(x.optString("type")); break;
          default: ok = col[2].equals(x.optString(col[1]));
        }
        if (ok) names.add(x.optString("person"));
      }
      out.add([col[0], names.join("\n"), String(names.length)]);
    }
    return out;
  }

  static strokeText(o) {
    const s = o.optJSONArray("stroke");
    const b = new StringBuilder("*STROKE – " + o.optString("from") + " to " + o.optString("to") + "*\nNo. of stroke cases reported: " + s.length());
    let typeless = 0;
    for (let i = 0; i < s.length(); i++) if (s.optJSONObject(i).optString("type").isEmpty()) typeless++;
    if (typeless > 0) b.append(" (").append(typeless).append(" type not entered)");
    for (const col of Census.strokeColumns(o)) {
      b.append("\n\n*").append(col[0]).append(": ").append(col[2]).append("*");
      if (!col[1].isEmpty()) b.append("\n").append(col[1]);
    }
    return b.toString();
  }

  static snakeColumn(snake) {
    for (const s of Census.SNAKE_COLS) if (s.equals(snake)) return s;
    return "Unknown";
  }

  static snakeText(o) {
    const s = o.optJSONArray("snake");
    const b = new StringBuilder("*SNAKE BITE CENSUS – " + o.optString("from") + " to " + o.optString("to") + "*\nTotal no. of cases: " + s.length());
    let imcu = 0, died = 0, asv = 0;
    for (let i = 0; i < s.length(); i++) {
      const x = s.optJSONObject(i);
      if (x.optBoolean("imcu")) imcu++;
      if (x.optBoolean("died")) died++;
      asv += Ui.toInt(x.optString("asv"), 0);
    }
    b.append("\nIMCU ").append(imcu).append(" · Ward ").append(s.length() - imcu).append(" · Deaths ").append(died).append(" · ASV vials ").append(asv);
    for (let i = 0; i < s.length(); i++) {
      const x = s.optJSONObject(i);
      b.append("\n\n").append(i + 1).append(". ").append(x.optString("person")).append(" (").append("F".equals(x.optString("sex")) ? "female" : "male").append(")")
          .append("\nUnit ").append(x.optString("unit")).append(" · ").append(x.optBoolean("imcu") ? "IMCU" : "Ward")
          .append("\nBitten: ").append(Census.dash(x.optString("dn"))).append(" · Site: ").append(Census.dash(x.optString("part"))).append(" · Bite to hospital: ").append(Census.dash(x.optString("delay")))
          .append("\nSnake: ").append(Census.snakeColumn(x.optString("snake"))).append(" · ASV: ").append(Census.dash(x.optString("asv"))).append(" vials")
          .append(x.optBoolean("died") ? " · Died" : "");
    }
    return b.toString();
  }

  static dash(s) {
    return s.isEmpty() ? "-" : s;
  }

  // ---------- Word / PDF ----------

  static doc(db, o) {
    const c = Census.c;
    const f = new FormDoc();
    f.college = db.setting("college", "Tirunelveli Medical College Hospital");
    f.address = db.setting("address", "Tirunelveli – 627 011, Tamil Nadu");
    f.dept = db.setting("dept", "Department of General Medicine");
    f.title = "DAILY CENSUS";
    f.footer = "Admission day " + o.optString("from") + " 7:30 AM to " + o.optString("to") + " 7:30 AM  •  " + f.dept + ", " + f.college;
    f.fileBase = "Census_" + o.optString("unit") + "_" + Dates.parse(o.optString("day")).format(Census.DOTS);
    const navy = FormDoc.NAVY, soft = 0xFFE3F2FD;

    const h = f.block(null, 0, 0.25, 0.25, 0.25, 0.25);
    h.row(16, c("ADMISSION DAY UNIT " + o.optString("unit")).b(), c("DATE: " + o.optString("from") + " to " + o.optString("to")).b(),
        c("DAY: " + o.optString("weekday")).b(), c("DAP: " + (o.optString("dap").isEmpty() ? "-" : o.optString("dap"))).b());

    const ip = f.block("IP CENSUS  ·  GRAND TOTAL " + o.optInt("grand"), navy, 0.34, 0.11, 0.11, 0.11, 0.11, 0.11, 0.11);
    ip.row(14, c("").fill(soft), c("Toxic").b().center().span(2).fill(soft), c("Non toxic").b().center().span(2).fill(soft), c("Total").b().center().span(2).fill(soft));
    ip.row(14, c("").fill(soft), c("Male").b().center(), c("Female").b().center(), c("Male").b().center(), c("Female").b().center(), c("Male").b().center(), c("Female").b().center());
    const rows = o.optJSONArray("rows");
    for (let i = 0; i < rows.length(); i++) {
      const r = rows.optJSONArray(i);
      const call = r.optString(0).equals("Callovers");
      ip.row(14, c(r.optString(0)).b(), c(call ? "-" : r.optString(1)).center(), c(call ? "-" : r.optString(2)).center(), c(r.optString(3)).center(),
          c(r.optString(4)).center(), c(String(r.optInt(1) + r.optInt(3))).b().center(), c(String(r.optInt(2) + r.optInt(4))).b().center());
    }
    const n = o.optJSONObject("counts");
    const cnt = f.block(null, 0, 0.34, 0.66);
    cnt.row(14, c("Hemophilia").b(), c(String(n.optInt("hemophilia"))));
    cnt.row(14, c("Total no. of stroke cases").b(), c(n.optInt("stroke") + "   (Ischaemic " + n.optInt("ischaemic") + ", Haemorrhagic " + n.optInt("haemorrhagic") + ")"));
    cnt.row(14, c("Snake bite").b(), c(String(n.optInt("snake"))));
    cnt.row(14, c("Toxicology").b(), c(String(n.optInt("tox"))));
    cnt.row(14, c("MLC").b(), c(String(n.optInt("mlc"))));
    cnt.row(14, c("Convict").b(), c(String(n.optInt("convict"))));
    cnt.row(14, c("Students / staff").b(), c(String(n.optInt("staff"))));
    cnt.row(14, c("ID ward").b(), c(n.optInt("idward") + (n.optString("idward_detail").isEmpty() ? "" : "   (" + n.optString("idward_detail") + ")")));
    const dp = new StringBuilder();
    for (const e of Census.deathsByPlace(o).entrySet()) dp.append(dp.length() === 0 ? "" : "   ").append(e.getKey()).append(" ").append(e.getValue());
    cnt.row(14, c("Total no. of deaths: " + o.optJSONArray("deaths").length()).b(), c(dp.toString()));
    const sh = new StringBuilder();
    const sa = o.optJSONArray("sheets");
    for (let i = 0; i < sa.length(); i++) sh.append(sh.length() === 0 ? "" : "\n").append(sa.optJSONArray(i).optString(0)).append("  ").append(sa.optJSONArray(i).optInt(1));
    cnt.row(14, c("Case sheets written: " + o.optInt("sheetsTotal")).b(), c(sh.toString()));

    const d = o.optJSONArray("deaths");
    const db1 = f.block("DEATH DIAGNOSIS  ·  " + d.length(), 0xFF475569, 0.22, 0.78);
    if (d.length() === 0) db1.row(14, c("Nil").span(2));
    for (const place of Db.DEATH_PLACES) {
      const s = new StringBuilder();
      let k = 0;
      for (let i = 0; i < d.length(); i++)
        if (place.equals(d.optJSONObject(i).optString("place"))) s.append(s.length() === 0 ? "" : "\n").append(++k).append(". ").append(d.optJSONObject(i).optString("cause").split("\n").join(" "));
      if (k > 0) db1.row(14, c(place + " – " + k).b(), c(s.toString()));
    }

    const t = o.optJSONArray("tox");
    const tb = f.block("TEAI TOXICOLOGY CENSUS", 0xFFB45309, 0.07, 0.27, 0.1, 0.32, 0.12, 0.12);
    tb.row(14, c("S.No").b().fill(0xFFFFF3E0), c("Name").b().fill(0xFFFFF3E0), c("Age").b().fill(0xFFFFF3E0), c("Category").b().fill(0xFFFFF3E0),
        c("Registered in TEAI").b().fill(0xFFFFF3E0), c("Updated in TEAI").b().fill(0xFFFFF3E0));
    for (const g of ["POISONING", "BITES", "DROWNING", "HANGING"]) {
      const inn = [];
      for (let i = 0; i < t.length(); i++) if (g.equals(t.optJSONObject(i).optString("group"))) inn.add(t.optJSONObject(i));
      tb.row(14, c(g + (inn.isEmpty() ? " – NIL" : "")).b().span(6));
      for (let i = 0; i < inn.size(); i++) {
        const x = inn.get(i);
        tb.row(14, c(String(i + 1)), c(x.optString("name")), c(x.optString("age")), c(x.optString("cat")), c(Census.yn(x.optString("reg"))), c(Census.yn(x.optString("upd"))));
      }
    }

    const sb = f.block("STROKE  ·  " + o.optJSONArray("stroke").length() + " cases", 0xFF7C3AED, 0.45, 0.43, 0.12);
    for (const col of Census.strokeColumns(o)) sb.row(14, c(col[0]).b(), c(col[1]), c(col[2]).center());

    const s = o.optJSONArray("snake");
    const sn = f.block("SNAKE BITE CENSUS  ·  " + s.length(), 0xFF047857, 0.06, 0.25, 0.1, 0.09, 0.1, 0.13, 0.08, 0.07, 0.12);
    sn.row(14, c("S.No").b(), c("Name, age, IP").b(), c("Unit").b(), c("Day/night").b(), c("Site").b(), c("Bite to hospital").b(), c("ASV").b(), c("Death").b(), c("Snake").b());
    if (s.length() === 0) sn.row(14, c("Nil").span(9));
    for (let i = 0; i < s.length(); i++) {
      const x = s.optJSONObject(i);
      sn.row(14, c(String(i + 1)), c(x.optString("person")), c(x.optString("unit") + (x.optBoolean("imcu") ? " IMCU" : " ward")), c(x.optString("dn")),
          c(x.optString("part")), c(x.optString("delay")), c(x.optString("asv")), c(x.optBoolean("died") ? "Yes" : "No"), c(Census.snakeColumn(x.optString("snake"))));
    }
    return f;
  }

  static c(t) {
    return new FormDoc.Cell(t);
  }

  // ---------- Excel: toxicology, stroke and snake bite sheets, as the department keeps them ----------

  static xlsx(c, o) {
    const rel = SummaryExport.DIR + "/Census_sheets_" + o.optString("unit") + "_" + Dates.parse(o.optString("day")).format(Census.DOTS) + ".xlsx";
    const f = new File(c.getFilesDir(), rel);
    f.getParentFile().mkdirs();
    const sheets = [];
    // toxicology
    const tx = [];
    tx.add(["TEAI TOXICOLOGY CENSUS - " + Census.dayRange(o)]);
    const t = o.optJSONArray("tox");
    for (const g of ["POISONING", "BITES", "DROWNING", "HANGING"]) {
      const inn = [];
      for (let i = 0; i < t.length(); i++) if (g.equals(t.optJSONObject(i).optString("group"))) inn.add(t.optJSONObject(i));
      if (inn.isEmpty()) {
        tx.add([g + " - NIL"]);
        continue;
      }
      tx.add([g]);
      tx.add(["S. No", "Name", "Age", "Category", "Registered in TEAI", "Updated in TEAI"]);
      for (let i = 0; i < inn.size(); i++) {
        const x = inn.get(i);
        tx.add([String(i + 1), x.optString("name"), x.optString("age"), x.optString("cat"), Census.yn(x.optString("reg")), Census.yn(x.optString("upd"))]);
      }
    }
    sheets.add(tx);
    // stroke: one row of headings, names below each
    const st = [];
    st.add([o.optString("from") + " to " + o.optString("to")]);
    const cols = Census.strokeColumns(o);
    const heads = new Array(cols.size() + 1).fill(null), counts = new Array(cols.size() + 1).fill(null);
    heads[0] = "No. of stroke cases reported";
    counts[0] = String(o.optJSONArray("stroke").length());
    let depth = 0;
    for (let i = 0; i < cols.size(); i++) {
      heads[i + 1] = cols.get(i)[0];
      counts[i + 1] = cols.get(i)[2];
      depth = Math.max(depth, cols.get(i)[1].isEmpty() ? 0 : cols.get(i)[1].jsplit("\n").length);
    }
    st.add(heads);
    st.add(counts);
    for (let r = 0; r < depth; r++) {
      const row = new Array(cols.size() + 1).fill(null);
      row[0] = "";
      for (let i = 0; i < cols.size(); i++) {
        const names = cols.get(i)[1].isEmpty() ? [] : cols.get(i)[1].jsplit("\n");
        row[i + 1] = r < names.length ? names[r] : "";
      }
      st.add(row);
    }
    sheets.add(st);
    // snake bite
    const sn = [];
    sn.add(["SNAKE BITE CENSUS"]);
    sn.add(["S.NO", "DATE", "UNIT", "TOTAL NO OF CASES", "IMCU", "WARD", "MALE/AGE", "FEMALE/AGE", "DAY/NIGHT", "HANDS", "LEGS", "BODY",
        "<4 HRS", "4 TO 12 HRS", "12 TO 24 HRS", ">24 HRS", "DEATH", "NO OF ASV", "COBRA", "KRAIT", "RUSSELL VIPER", "SAW SCALED VIPER", "UNKNOWN"]);
    const s = o.optJSONArray("snake");
    for (let i = 0; i < s.length(); i++) {
      const x = s.optJSONObject(i);
      const part = x.optString("part"), delay = x.optString("delay"), snake = Census.snakeColumn(x.optString("snake"));
      const f2 = "F".equals(x.optString("sex"));
      sn.add([String(i + 1), x.optString("date"), x.optString("unit"), "1", x.optBoolean("imcu") ? "1" : "", x.optBoolean("imcu") ? "" : "1",
          f2 ? "" : x.optString("person"), f2 ? x.optString("person") : "", x.optString("dn"),
          part.equals("Hand") ? "1" : "", part.equals("Leg") ? "1" : "", part.equals("Body") ? "1" : "",
          delay.equals("Under 4 h") ? "1" : "", delay.equals("4 to 12 h") ? "1" : "", delay.equals("12 to 24 h") ? "1" : "", delay.equals("Over 24 h") ? "1" : "",
          x.optBoolean("died") ? "1" : "", x.optString("asv"),
          snake.equals("Cobra") ? "1" : "", snake.equals("Krait") ? "1" : "", snake.equals("Russell's viper") ? "1" : "", snake.equals("Saw-scaled viper") ? "1" : "", snake.equals("Unknown") ? "1" : ""]);
    }
    sheets.add(sn);
    Census.Xlsx.write(f, ["Toxicology", "Stroke", "Snake bite"], sheets);
    return rel;
  }
}

/** Smallest valid .xlsx: inline strings, numbers as numbers, the first row of each sheet in bold. */
Census.Xlsx = class {
  static write(f, names, sheets) {
    const z = new ZipOutputStream(new FileOutputStream(f));
    try {
      const ct = new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\">"
          + "<Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/>"
          + "<Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/>"
          + "<Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/>");
      const wb = new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" "
          + "xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets>");
      const rels = new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">");
      for (let i = 0; i < sheets.size(); i++) {
        ct.append("<Override PartName=\"/xl/worksheets/sheet").append(i + 1).append(".xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>");
        wb.append("<sheet name=\"").append(SummaryExport.esc(names[i])).append("\" sheetId=\"").append(i + 1).append("\" r:id=\"rId").append(i + 1).append("\"/>");
        rels.append("<Relationship Id=\"rId").append(i + 1).append("\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet")
            .append(i + 1).append(".xml\"/>");
        SummaryExport.put(z, "xl/worksheets/sheet" + (i + 1) + ".xml", Census.Xlsx.sheet(sheets.get(i)));
      }
      rels.append("<Relationship Id=\"rIdS\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>");
      SummaryExport.put(z, "[Content_Types].xml", ct.append("</Types>").toString());
      SummaryExport.put(z, "_rels/.rels", "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">"
          + "<Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");
      SummaryExport.put(z, "xl/workbook.xml", wb.append("</sheets></workbook>").toString());
      SummaryExport.put(z, "xl/_rels/workbook.xml.rels", rels.toString());
      SummaryExport.put(z, "xl/styles.xml", "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><styleSheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\">"
          + "<fonts count=\"2\"><font><sz val=\"11\"/><name val=\"Calibri\"/></font><font><b/><sz val=\"11\"/><name val=\"Calibri\"/></font></fonts>"
          + "<fills count=\"2\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill></fills>"
          + "<borders count=\"1\"><border><left/><right/><top/><bottom/><diagonal/></border></borders>"
          + "<cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs>"
          + "<cellXfs count=\"3\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\"/><xf numFmtId=\"0\" fontId=\"1\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyFont=\"1\"/>"
          + "<xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyAlignment=\"1\"><alignment wrapText=\"1\" vertical=\"top\"/></xf></cellXfs></styleSheet>");
    } finally {
      z.close();
    }
  }

  static col(i) {
    const s = new StringBuilder();
    for (i++; i > 0; i = Math.floor((i - 1) / 26)) s.insert(0, String.fromCharCode(65 + (i - 1) % 26));
    return s.toString();
  }

  static sheet(rows) {
    const b = new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\">"
        + "<cols><col min=\"1\" max=\"30\" width=\"22\" customWidth=\"1\"/></cols><sheetData>");
    for (let r = 0; r < rows.size(); r++) {
      b.append("<row r=\"").append(r + 1).append("\">");
      const row = rows.get(r);
      const bold = r === 0 || row.length === 1 || (row.length > 1 && row[0].matches("S\\.? ?N[Oo]|No\\. of stroke cases reported"));
      for (let c = 0; c < row.length; c++) {
        const v = row[c] == null ? "" : row[c];
        if (v.isEmpty()) continue;
        const ref = Census.Xlsx.col(c) + (r + 1);
        if (v.matches("\\d{1,6}")) b.append("<c r=\"").append(ref).append("\"").append(bold ? " s=\"1\"" : "").append("><v>").append(v).append("</v></c>");
        else b.append("<c r=\"").append(ref).append("\" t=\"inlineStr\" s=\"").append(bold ? 1 : 2).append("\"><is><t xml:space=\"preserve\">")
            .append(SummaryExport.esc(v)).append("</t></is></c>");
      }
      b.append("</row>");
    }
    return b.append("</sheetData></worksheet>").toString();
  }
};
;
