'use strict';
/** Census: the daily census of each admission day, posted at 7:30 AM, with WhatsApp sharing. */
class CensusActivity extends Base {
  static COLOR = 0xFF0F766E;

  constructor() { super(); this.day = null; this.report = "ip"; this.live = false; }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Census");
    this.subtitle = "Daily census, posted at 7:30 AM";
    this.headerColor(CensusActivity.COLOR);
    const d = Dates.parse(this.getIntent().getStringExtra("day"));
    this.day = d != null ? d : Census.dueDay();
    Census.catchUp(this);
  }

  /** Faculty and the DAP re-post a census after late entries; everyone can see and share it. */
  canPost() {
    return SessionAttendance.canRun(this);
  }

  current() {
    try {
      if (this.live) return Census.build(this, this.db, Dates.admitDay());
      const r = Census.posted(this.db, this.day.toString());
      return r == null ? null : new JSONObject(r.get("data"));
    } catch (e) {
      return null;
    }
  }

  render() {
    const COLOR = CensusActivity.COLOR;
    const page = Ui.v(this);
    const o = this.current();
    const row = this.live ? null : Census.posted(this.db, this.day.toString());

    // live census of every ward (its own screen)
    const lc = Ui.h(this);
    lc.setGravity(Gravity.CENTER_VERTICAL);
    lc.setBackground(Glass.hero(this, Ui.shades(LiveCensusActivity.COLOR), 20));
    lc.setPadding(Ui.dp(this, 16), Ui.dp(this, 14), Ui.dp(this, 16), Ui.dp(this, 14));
    const lt = Ui.v(this);
    lt.addView(Ui.tv(this, "●  Live census", 17, Color.WHITE, true));
    lt.addView(Ui.tv(this, this.db.totalInpatients() + " inpatients now  ·  every ward in one table, updating by itself", 12, 0xD9FFFFFF, false));
    lc.addView(lt, Ui.weight(1));
    lc.addView(Ui.tv(this, "›", 28, Color.WHITE, true));
    lc.setOnClickListener(this.opener(LiveCensusActivity));
    const lcp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lcp.setMargins(Ui.dp(this, 12), Ui.dp(this, 6), Ui.dp(this, 12), Ui.dp(this, 2));
    page.addView(lc, lcp);

    // which day
    const nav = Ui.card(this);
    const r1 = Ui.h(this);
    r1.setGravity(Gravity.CENTER_VERTICAL);
    r1.addView(Ui.outlineButton(this, "‹", COLOR, {
      onClick: (v) => { this.live = false; this.day = this.day.minusDays(1); this.render(); }
    }));
    const mid = Ui.v(this);
    mid.setGravity(Gravity.CENTER);
    const shown = this.live ? Dates.admitDay() : this.day;
    const t1 = Ui.tv(this, Census.unitOf(this.db, shown) + " admission day", 17, Ui.TEXT, true);
    t1.setGravity(Gravity.CENTER);
    mid.addView(t1);
    const t2 = Ui.muted(this, "7:30 AM " + Dates.nice(shown) + " to 7:30 AM " + Dates.nice(shown.plusDays(1)));
    t2.setGravity(Gravity.CENTER);
    mid.addView(t2);
    r1.addView(mid, Ui.weight(1));
    r1.addView(Ui.outlineButton(this, "›", COLOR, {
      onClick: (v) => {
        if (!this.live && this.day.plusDays(1).isAfter(Census.dueDay())) this.live = true;
        else if (!this.live) this.day = this.day.plusDays(1);
        this.render();
      }
    }));
    nav.addView(r1);
    let state;
    if (this.live) state = Ui.tv(this, "● Live: today so far. It is posted at 7:30 AM tomorrow.", 13, Ui.ORANGE, true);
    else if (row == null) state = Ui.tv(this, "Not posted" + (this.day.equals(Census.dueDay()) ? " yet" : ""), 13, Ui.MUTED, true);
    else state = Ui.tv(this, "✓ " + row.get("posted_by") + " · " + Alerts.show(row.get("posted_at")), 13, Ui.GREEN, true);
    state.setGravity(Gravity.CENTER);
    nav.addView(state);
    Ui.margins(state, 0, 6, 0, 0);
    page.addView(nav);

    if (o == null) {
      page.addView(this.emptyNote("No census posted for this day."));
      if (this.canPost() && !this.day.isAfter(Census.dueDay())) {
        const post = Ui.button(this, "Post this day's census now", COLOR, {
          onClick: (v) => { this.repost(); }
        });
        page.addView(post);
        Ui.margins(post, 14, 4, 14, 0);
      }
      const today = Ui.outlineButton(this, "See today so far (live)", COLOR, {
        onClick: (v) => { this.live = true; this.render(); }
      });
      page.addView(today);
      Ui.margins(today, 14, 10, 14, 0);
      this.setPage(page);
      return;
    }

    // headline
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(COLOR), 20));
    const n = o.optJSONObject("counts");
    hero.addView(Ui.statRow(this, this.white(o.optInt("grand"), "IP census"), this.white(n.optInt("admitted"), "Admitted"),
        this.white(o.optJSONArray("deaths").length(), "Deaths"), this.white(n.optInt("tox"), "Toxic")));
    const dap = Ui.tv(this, "DAP: " + (o.optString("dap").isEmpty() ? "not entered" : o.optString("dap")), 13, 0xE6FFFFFF, true);
    dap.setGravity(Gravity.CENTER);
    hero.addView(dap);
    Ui.margins(dap, 0, 8, 0, 0);
    page.addView(hero);

    // WhatsApp
    const share = Ui.card(this);
    share.addView(Ui.buttonRow(this,
        Ui.button(this, "WhatsApp: all 5", 0xFF16A34A, {
          onClick: (v) => { this.whatsappText(Census.allText(o)); }
        }),
        Ui.button(this, "WhatsApp: this one", 0xFF15803D, {
          onClick: (v) => { this.whatsappText(Census.text(o, this.report)); }
        })));
    const files = Ui.buttonRow(this,
        Ui.outlineButton(this, "Word", COLOR, {
          onClick: (v) => { this.file(o, "docx"); }
        }),
        Ui.outlineButton(this, "PDF", COLOR, {
          onClick: (v) => { this.file(o, "pdf"); }
        }),
        Ui.outlineButton(this, "Excel", COLOR, {
          onClick: (v) => { this.file(o, "xlsx"); }
        }));
    share.addView(files);
    Ui.margins(files, 0, 8, 0, 0);
    page.addView(share);

    // the five reports
    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 2));
    for (let i = 0; i < Census.REPORTS.length; i++) {
      const k = Census.REPORTS[i];
      const c = Ui.chip(this, Census.REPORT_LABELS[i], k.equals(this.report), COLOR);
      c.setOnClickListener({
        onClick: (v) => { this.report = k; this.render(); }
      });
      chips.addView(c);
    }
    page.addView(Ui.hscroll(this, chips));
    if (this.report.equals("ip")) page.addView(this.ipTable(o));
    const body = Ui.card(this);
    let txt = Census.text(o, this.report);
    if (this.report.equals("ip")) txt = txt.substring(txt.indexOf("\n\nHemophilia") + 2);
    for (const para of txt.jsplit("\n")) {
      const bold = para.startsWith("*") && para.indexOf("*", 1) > 0;
      const tv = Ui.tv(this, para.split("*").join(""), bold ? 15 : 14, bold ? COLOR : Ui.TEXT, bold);
      tv.setPadding(0, Ui.dp(this, bold ? 6 : 1), 0, Ui.dp(this, 1));
      body.addView(tv);
    }
    page.addView(body);

    if (this.canPost() && (this.live || row != null)) {
      const re = Ui.outlineButton(this, this.live ? "Post today's census now" : "Update this census with late entries", COLOR, {
        onClick: (v) => { this.repost(); }
      });
      page.addView(re);
      Ui.margins(re, 14, 10, 14, 0);
    }
    const hint = Ui.muted(this, "Counts come from the patient records: how the patient came, toxicology, stroke and snake bite details, MLC and the place of death. "
        + "Fill them in when admitting (Edit patient), and the census fills itself.");
    hint.setPadding(Ui.dp(this, 18), Ui.dp(this, 12), Ui.dp(this, 18), 0);
    page.addView(hint);
    this.setPage(page);
  }

  white(n, label) {
    const s = Ui.stat(this, String(n), label, Color.WHITE);
    for (let i = 0; i < s.getChildCount(); i++)
      if (s.getChildAt(i) instanceof TextView) s.getChildAt(i).setTextColor(i === 0 ? Color.WHITE : 0xD9FFFFFF);
    return s;
  }

  /** The IP census grid: rows by where the patient came from, toxic and non-toxic, male and female. */
  ipTable(o) {
    const card = Ui.card(this);
    const h = Ui.tv(this, "GRAND TOTAL IP CENSUS  " + o.optInt("grand"), 16, CensusActivity.COLOR, true);
    card.addView(h);
    const head = ["", "Toxic\nM", "Toxic\nF", "Non-T\nM", "Non-T\nF", "Total\nM", "Total\nF"];
    card.addView(this.gridRow(head, true));
    const rows = o.optJSONArray("rows");
    for (let i = 0; i < rows.length(); i++) {
      const r = rows.optJSONArray(i);
      const call = r.optString(0).equals("Callovers");
      card.addView(this.gridRow([r.optString(0), call ? "-" : r.optString(1), call ? "-" : r.optString(2), r.optString(3), r.optString(4),
          String(r.optInt(1) + r.optInt(3)), String(r.optInt(2) + r.optInt(4))], false));
    }
    return card;
  }

  gridRow(cells, head) {
    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    row.setPadding(0, Ui.dp(this, 5), 0, Ui.dp(this, 5));
    for (let i = 0; i < cells.length; i++) {
      const t = Ui.tv(this, cells[i], i === 0 ? 13 : head ? 11 : 14, head ? Ui.MUTED : i >= 5 ? CensusActivity.COLOR : Ui.TEXT, head || i === 0 || i >= 5);
      t.setGravity(i === 0 ? Gravity.START | Gravity.CENTER_VERTICAL : Gravity.CENTER);
      row.addView(t, Ui.weight(i === 0 ? 2.6 : 1));
    }
    if (!head) row.setBackground(Ui.round(this, 0x0A0F766E, 6));
    const lp = new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(0, Ui.dp(this, 2), 0, 0);
    row.setLayoutParams(lp);
    return row;
  }

  repost() {
    try {
      const d = this.live ? Dates.admitDay() : this.day;
      const o = Census.build(this, this.db, d);
      Census.save(this.db, o, "Posted by " + this.who(), false);
      this.live = false;
      this.day = d;
      Ui.toast(this, "Census posted");
    } catch (e) {
      Ui.toast(this, "Could not make the census: " + e.getMessage());
    }
    this.render();
  }

  who() {
    const n = Reminders.myName(this, this.db);
    return n.isEmpty() ? "this phone" : n;
  }

  /** Straight to WhatsApp (or WhatsApp Business); any other app when neither is installed. */
  whatsappText(text) {
    const i = new Intent(Intent.ACTION_SEND);
    i.setType("text/plain");
    i.putExtra(Intent.EXTRA_TEXT, text);
    for (const pkg of ["com.whatsapp", "com.whatsapp.w4b"]) {
      try {
        this.startActivity(new Intent(i).setPackage(pkg));
        return;
      } catch (ignored) {
      }
    }
    this.startActivity(Intent.createChooser(i, "Share census"));
  }

  file(o, kind) {
    let rel;
    try {
      if (kind.equals("xlsx")) rel = Census.xlsx(this, o);
      else {
        const f = Census.doc(this.db, o);
        rel = kind.equals("pdf") ? f.pdf(this) : f.docx(this);
      }
    } catch (e) {
      Ui.toast(this, "Could not make the file: " + e.getMessage());
      return;
    }
    const subject = "Census " + o.optString("unit") + " " + o.optString("from");
    new AlertDialog.Builder(this).setTitle((kind.equals("xlsx") ? "Excel" : kind.equals("pdf") ? "PDF" : "Word") + " file ready")
        .setItems(["Send on WhatsApp", "Share (email, Drive…)", "Open"], {
          onClick: (d, w) => {
            if (w === 0) this.whatsappFile(rel, subject);
            else if (w === 1) Store.share(this, rel, subject);
            else Store.openWith(this, rel);
          }
        }).setNegativeButton("Close", null).show();
  }

  whatsappFile(rel, subject) {
    const u = Uri.ofRel(rel);
    const i = new Intent(Intent.ACTION_SEND);
    i.setType(DocProvider.mimeOf(rel));
    i.putExtra(Intent.EXTRA_STREAM, u);
    i.setClipData(ClipData.newRawUri(subject, u));
    i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
    for (const pkg of ["com.whatsapp", "com.whatsapp.w4b"]) {
      try {
        this.startActivity(new Intent(i).setPackage(pkg));
        return;
      } catch (ignored) {
      }
    }
    Store.share(this, rel, subject);
  }
}
;
