/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** One patient's bedside chart (BP, diabetic, I/O, OPC or ventilator): trend, entries by day, add / edit, Word and PDF. */
class ChartActivity extends Base {
  constructor() { super(); this.pid = 0; this.code = null; }

  onCreate(b) {
    super.onCreate(b);
    this.pid = Long.parseLong(this.getIntent().getStringExtra("id"));
    this.code = this.getIntent().getStringExtra("kind");
    if (this.code == null) this.code = Charts.BP;
  }

  render() {
    const db = this.db;
    const p = db.row("SELECT * FROM patients WHERE id=?", String(this.pid));
    if (p == null) { this.finish(); return; }
    const k = Charts.kind(this.code);
    this.setTitle(k.name);
    this.subtitle = p.get("name") + (Ui.nz(p.get("bed")).isEmpty() ? "" : "  ·  bed " + p.get("bed")) + "  ·  " + Db.shortName(p.get("location"));
    this.headerColor(k.color);
    this.headerAction("+ Entry", { onClick: (v) => { this.entry(null); } });
    const page = Ui.v(this);

    // the five charts for this patient; suggested ones marked
    const chips = Ui.h(this);
    for (const x of Charts.KINDS) {
      const n = Charts.count(db, this.pid, x.code);
      const label = x.name.split(" chart").join("") + (n > 0 ? " · " + n : Charts.suggested(p, x.code) ? " •" : "");
      const c = Ui.chip(this, label, x.code === this.code, x.color);
      c.setOnClickListener({ onClick: (v) => { this.code = x.code; this.render(); } });
      chips.addView(c);
    }
    chips.setPadding(Ui.dp(this, 14), Ui.dp(this, 10), Ui.dp(this, 14), Ui.dp(this, 4));
    page.addView(Ui.hscroll(this, chips));

    const all = Charts.entries(db, this.pid, this.code);
    const last = all.isEmpty() ? null : all.get(all.size() - 1);

    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(k.color), 20));
    hero.addView(Ui.tv(this, k.about, 13, 0xE6FFFFFF, false));
    if (last == null) {
      hero.addView(Ui.tv(this, "No entries yet", 20, Color.WHITE, true));
      hero.addView(Ui.tv(this, Charts.suggested(p, this.code) ? "Suggested for " + Ui.nz(p.get("diagnosis")) + ". Tap + Entry to start." : "Tap + Entry to start the chart.", 13, 0xE6FFFFFF, false));
    } else {
      const o = Charts.data(last);
      hero.addView(Ui.tv(this, Charts.line(k, o).isEmpty() ? "Entry" : Charts.line(k, o), 19, Color.WHITE, true));
      const when = Dates.nice(last.get("date")) + " " + last.get("time") + (Ui.nz(last.get("by_name")).isEmpty() ? "" : "  ·  " + last.get("by_name"));
      hero.addView(Ui.tv(this, "Last entry " + when + "  ·  " + all.size() + (all.size() === 1 ? " entry" : " entries"), 13, 0xE6FFFFFF, false));
      if (this.code === Charts.OPC && !Charts.opcStatus(o).isEmpty()) {
        const st = Ui.tv(this, Charts.opcStatus(o), 14, Color.WHITE, true);
        st.setBackground(Glass.frost(this, 12));
        st.setPadding(Ui.dp(this, 12), Ui.dp(this, 6), Ui.dp(this, 12), Ui.dp(this, 6));
        hero.addView(st);
        Ui.margins(st, 0, 10, 0, 0);
      }
    }
    const acts = Ui.buttonRow(this,
      this.frost(Ui.button(this, "+ Add entry", k.color, { onClick: (v) => { this.entry(null); } })),
      this.frost(Ui.button(this, "Word", k.color, { onClick: (v) => { this.export(p, "docx"); } })),
      this.frost(Ui.button(this, "PDF", k.color, { onClick: (v) => { this.export(p, "pdf"); } })));
    hero.addView(acts);
    Ui.margins(acts, 0, 12, 0, 0);
    page.addView(hero);

    const days = Charts.byDay(all);
    // trend
    const t = this.trend(k, all, days);
    if (t != null) {
      const tc = Ui.card(this);
      tc.addView(Ui.title(this, "Trend"));
      tc.addView(t, Ui.lp(MATCH_PARENT, Ui.dp(this, 190)));
      page.addView(tc);
    }

    // entries, newest day first
    const order = ArrayList(days.keySet());
    order.reverse();
    const weight = Charts.weight(all);
    for (const d of order) {
      const es = days.get(d);
      page.addView(Ui.heading(this, Dates.nice(d) + "  ·  " + es.size() + (es.size() === 1 ? " entry" : " entries"), k.color));
      if (this.code === Charts.IO) page.addView(this.ioCard(es, weight));
      if (this.code === Charts.DM) page.addView(this.dmCard(k, all, d, es));
      for (let i = es.size() - 1; i >= 0; i--) {
        const e = es.get(i);
        const o = Charts.data(e);
        const w = Charts.worst(k, o);
        const sub = (o.optString("note").isEmpty() ? "" : o.optString("note"))
          + (Ui.nz(e.get("by_name")).isEmpty() ? "" : (o.optString("note").isEmpty() ? "" : "\n") + "By " + e.get("by_name"));
        page.addView(this.entryCard(e.get("time"), w === 0 ? k.color : w, Charts.line(k, o).isEmpty() ? "Entry" : Charts.line(k, o), sub, null,
          { onClick: (v) => { this.entry(e); } }));
      }
    }
    if (all.isEmpty()) page.addView(this.emptyNote("Entries appear here by day (7:30 AM to 7:30 AM), coloured red, amber or green by the readings."));
    this.setPage(page);
  }

  frost(t) {
    t.setBackground(Glass.frost(this, 14));
    return t;
  }

  ioCard(es, weight) {
    const t = Charts.ioTotals(es, weight);
    const c = Ui.card(this);
    const r = Ui.h(this);
    r.addView(this.stat(ChartActivity.fmt(t[0]) + " ml", "Intake", 0xFF2563EB), Ui.weight(1));
    r.addView(this.stat(ChartActivity.fmt(t[1]) + " ml", "Output", Charts.AMBER), Ui.weight(1));
    r.addView(this.stat((t[3] > 0 ? "+" : "") + ChartActivity.fmt(t[3]), "Balance", t[3] >= 0 ? 0xFF2563EB : Charts.AMBER), Ui.weight(1));
    c.addView(r);
    const uo = "Urine " + ChartActivity.fmt(t[2]) + " ml" + (Number.isNaN(t[4]) ? "  (add body weight for ml/kg/hr)" : "  ·  " + jfmt("%.2f", t[4]) + " ml/kg/hr");
    const u = Ui.tv(this, uo, 14, t[2] < 400 || (!Number.isNaN(t[4]) && t[4] < 0.5) ? Charts.RED : Ui.TEXT, true);
    c.addView(u);
    Ui.margins(u, 0, 8, 0, 0);
    return c;
  }

  dmCard(k, all, d, es) {
    const c = Ui.card(this);
    const row = Ui.h(this);
    for (let i = 0; i < Charts.DM_SLOTS.length; i++) {
      let v = "";
      let fl = 0;
      for (const e of es) {
        const o = Charts.data(e);
        if (Charts.DM_SLOTS[i] === o.optString("slot") && !o.optString("grbs").isEmpty()) {
          v = o.optString("grbs");
          fl = Charts.flag(k, o, "grbs");
        }
      }
      const cell = Ui.v(this);
      cell.setGravity(Gravity.CENTER);
      const val = Ui.tv(this, v.isEmpty() ? "–" : v, 14, fl === 0 ? Ui.MUTED : fl, true);
      val.setGravity(Gravity.CENTER);
      cell.addView(val);
      const lab = Ui.tv(this, Charts.DM_SHORT[i], 10, Ui.MUTED, false);
      lab.setGravity(Gravity.CENTER);
      cell.addView(lab);
      row.addView(cell, Ui.weight(1));
    }
    c.addView(row);
    const reg = Charts.regimenUpTo(all, d);
    if (!reg.isEmpty()) {
      const r = Ui.tv(this, "Regimen: " + reg, 13, k.color, true);
      c.addView(r);
      Ui.margins(r, 0, 8, 0, 0);
    }
    return c;
  }

  stat(v, l, color) {
    const s = Ui.v(this);
    s.setGravity(Gravity.CENTER);
    const a = Ui.tv(this, v, 17, color, true);
    a.setGravity(Gravity.CENTER);
    s.addView(a);
    const b = Ui.muted(this, l);
    b.setGravity(Gravity.CENTER);
    s.addView(b);
    return s;
  }

  static fmt(v) {
    if (Number.isNaN(v)) return "-";
    return v === Math.rint(v) ? String(Math.trunc(v)) : jfmt("%.1f", v);
  }

  // ---------- add / edit ----------

  entry(e) {
    const db = this.db;
    const k = Charts.kind(this.code);
    const o = e == null ? new JSONObject() : Charts.data(e);
    const f = new Form(this);
    const time = e != null ? e.get("time") : this.code === Charts.BP ? jfmt("%02d:00", Dates.time().getHour()) : Dates.time().format(DateTimeFormatter.ofPattern("HH:mm"));
    const date = e != null ? e.get("date") : Dates.today().toString();
    f.beginRow();
    f.date("date", "Date", date);
    f.time("time", "Time", time);
    f.endRow();
    let carry = null;
    if (e == null && this.code === Charts.VENT) {
      const last = Charts.last(db, this.pid, this.code);
      if (last != null) {
        carry = Charts.data(last);
        const n = Ui.muted(this, "Settings are carried over from the last entry. Change only what was changed.");
        n.setTextSize(12);
        f.view.addView(n);
      }
    }
    if (e == null && this.code === Charts.DM) {
      const reg = Charts.regimenUpTo(Charts.entries(db, this.pid, this.code), Dates.admitDay());
      if (!reg.isEmpty()) {
        const n = Ui.muted(this, "Current regimen: " + reg + ". Write a new regimen only when it changes.");
        n.setTextSize(12);
        f.view.addView(n);
      }
    }
    let open = false;
    for (const fd of k.fields) {
      let v = o.optString(fd.key);
      if (e == null && carry != null && fd._setting) v = carry.optString(fd.key);
      const label = fd.label + (fd.unit.isEmpty() ? "" : " (" + fd.unit + ")");
      if (fd.type === Charts.NUM || fd.type === Charts.DEC) {
        if (!open) { f.beginRow(); open = true; }
        f.text(fd.key, label, v, fd.type === Charts.NUM ? Form.NUMBER : Form.DECIMAL);
        if (ChartActivity.rowFull(f)) { f.endRow(); open = false; }
      } else {
        if (open) { f.endRow(); open = false; }
        if (fd.type === Charts.SEG) f.segment(fd.key, label, fd.opts, v);
        else f.text(fd.key, label, v, Form.PLAIN);
      }
    }
    if (open) f.endRow();
    f.text("by", "Recorded by", e != null ? e.get("by_name") : CallDutyActivity.myName(this), Form.TEXT);
    if (e != null) {
      const del = Ui.outlineButton(this, "Delete entry", Ui.RED, {
        onClick: (v) => {
          Ui.confirm(this, "Delete this entry?", Dates.nice(e.get("date")) + " " + e.get("time"), "Delete", {
            run: () => { db.delete("charts", Long.parseLong(e.get("id"))); this.render(); }
          });
        }
      });
      f.view.addView(del);
      Ui.margins(del, 0, 14, 0, 0);
    }
    Ui.formDialog(this, (e == null ? "New " : "Edit ") + k.name.toLowerCase() + " entry", f, "Save", {
      run: () => {
        const n = new JSONObject();
        let any = false;
        try {
          for (const fd of k.fields) {
            const v = f.get(fd.key).trim();
            if (!v.isEmpty()) { n.put(fd.key, v); any = true; }
          }
        } catch (ignored) {
        }
        if (!any) { Ui.toast(this, "Enter at least one reading"); return false; }
        if (this.code === Charts.BP && (n.optString("sbp").isEmpty() !== n.optString("dbp").isEmpty())) {
          Ui.toast(this, "Enter both systolic and diastolic BP");
          return false;
        }
        const t = f.get("time").isEmpty() ? Dates.now() : f.get("time");
        Charts.save(db, e == null ? 0 : Long.parseLong(e.get("id")), this.pid, this.code, f.get("date"), t, n, f.get("by").trim());
        CallDutyActivity.rememberName(this, f.get("by"));
        this.render();
        return true;
      }
    });
  }

  /** Numbers sit two to a row. (Java reads Form's private field "row" by reflection.) */
  static rowFull(f) {
    try {
      const row = f._row !== undefined ? f._row : f.row;
      if (row != null && typeof row.getChildCount !== 'function') return true;
      return row != null && row.getChildCount() >= 2;
    } catch (ex) {
      return true;
    }
  }

  // ---------- Word / PDF ----------

  export(p, kind) {
    const labels = ["Today (from 7:30 AM)", "Last 3 days", "Whole stay"];
    new AlertDialog.Builder(this).setTitle((kind === "pdf" ? "PDF" : "Word") + ": which days?")
      .setItems(labels, {
        onClick: (d, w) => {
          const to = Dates.admitDay();
          const from = w === 0 ? to : w === 1 ? to.minusDays(2) : null;
          this.file(p, kind, from, w === 2 ? null : to);
        }
      }).setNegativeButton("Cancel", null).show();
  }

  file(p, kind, from, to) {
    let rel;
    try {
      const f = Charts.doc(this.db, p, this.code, from, to);
      rel = kind === "pdf" ? f.pdf(this) : f.docx(this);
    } catch (ex) {
      Ui.toast(this, "Could not make the file: " + ex.getMessage());
      return;
    }
    const subject = Charts.kind(this.code).name + " " + p.get("name");
    new AlertDialog.Builder(this).setTitle((kind === "pdf" ? "PDF" : "Word") + " file ready")
      .setItems(["Send on WhatsApp", "Share (email, Drive…)", "Open"], {
        onClick: (d, w) => {
          if (w === 0) this.whatsapp(rel, subject);
          else if (w === 1) Store.share(this, rel, subject);
          else Store.openWith(this, rel);
        }
      }).setNegativeButton("Close", null).show();
  }

  whatsapp(rel, subject) {
    const u = Uri.ofRel(rel);
    const i = new Intent(Intent.ACTION_SEND);
    i.setType(mimeOf(rel));
    i.putExtra(Intent.EXTRA_STREAM, u);
    i.setClipData(ClipData.newRawUri(subject, u));
    i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
    for (const pkg of ["com.whatsapp", "com.whatsapp.w4b"]) {
      try {
        this.startActivity(new Intent(i).setPackage(pkg));
        return;
      } catch (ignored) {
      }
    }
    Store.share(this, rel, subject);
  }

  // ---------- trend ----------

  trend(k, all, days) {
    const t = new ChartActivity.Trend(this);
    const tail = ChartActivity.tail;
    if (this.code === Charts.IO) {
      const xs = [];
      const inn = [], out = [], urine = [];
      const w = Charts.weight(all);
      for (const d of days.entrySet()) {
        const tt = Charts.ioTotals(d.getValue(), w);
        xs.add(d.getKey().format(DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH)));
        inn.add(tt[0]); out.add(tt[1]); urine.add(tt[2]);
      }
      if (xs.size() < 2) return null;
      t.x = tail(xs);
      t.add("Intake", 0xFF2563EB, tail(inn));
      t.add("Output", Charts.AMBER, tail(out));
      t.add("Urine", 0xFF0891B2, tail(urine));
      t.ref(400, Charts.RED, "400 ml");
      return t;
    }
    const xs = [];
    for (const e of all) xs.add(e.get("time"));
    let series;
    switch (this.code) {
      case Charts.BP: series = [["sbp", "SBP", "" + 0xFFDC2626], ["dbp", "DBP", "" + 0xFF2563EB], ["map", "MAP", "" + 0xFF7C3AED]];
        t.ref(140, Charts.AMBER, "140"); t.ref(90, Charts.RED, "90"); break;
      case Charts.DM: series = [["grbs", "GRBS", "" + 0xFF7C3AED]];
        t.ref(180, Charts.AMBER, "180"); t.ref(70, Charts.RED, "70"); break;
      case Charts.OPC: series = [["hr", "Pulse", "" + 0xFFDC2626], ["sbp", "SBP", "" + 0xFF2563EB]];
        t.ref(80, Charts.GREEN, "80"); break;
      default: series = [["fio2", "FiO2 %", "" + 0xFF0F766E], ["spo2", "SpO2 %", "" + 0xFF2563EB]];
        t.ref(90, Charts.RED, "90"); break;
    }
    let points = 0;
    for (const s of series) {
      const v = [];
      let n = 0;
      for (const e of all) {
        const o = Charts.data(e);
        const d = s[0] === "map" ? Charts.map(o) : Charts.num(o, s[0]);
        v.add(d);
        if (!Number.isNaN(d)) n++;
      }
      points = Math.max(points, n);
      t.add(s[1], Integer.parseInt(s[2]), tail(v));
    }
    if (points < 2) return null;
    t.x = tail(xs);
    return t;
  }

  static tail(l) {
    return l.size() <= 24 ? l : ArrayList(l.subList(l.size() - 24, l.size()));
  }
}

/** A small line chart: several series over the entries, with reference lines. */
ChartActivity.Trend = class extends View {
  constructor(c) {
    super(c);
    this.x = [];
    this.names = [];
    this.colors = [];
    this.values = [];
    this.refs = [];
    this.refLabels = [];
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.d = c.getResources().getDisplayMetrics().density;
  }

  add(name, color, v) { this.names.add(name); this.colors.add(color); this.values.add(v); }

  ref(v, color, label) { this.refs.add([v, color]); this.refLabels.add(label); }

  onDraw(cv) {
    const p = this.p, d = this.d, x = this.x, names = this.names, colors = this.colors, values = this.values, refs = this.refs;
    const w = this.getWidth(), h = this.getHeight();
    const left = 30 * d, right = w - 8 * d, top = 22 * d, bottom = h - 18 * d;
    let lo = Number.MAX_VALUE, hi = -Number.MAX_VALUE;
    for (const s of values) for (const v of s) if (!Number.isNaN(v)) { lo = Math.min(lo, v); hi = Math.max(hi, v); }
    for (const r of refs) { lo = Math.min(lo, r[0]); hi = Math.max(hi, r[0]); }
    if (lo === Number.MAX_VALUE) return;
    const pad = Math.max(5, (hi - lo) * 0.1);
    lo = Math.max(0, lo - pad);
    hi += pad;
    const n = Math.max(2, x.size());
    // legend
    p.setTextSize(11 * d);
    p.setStyle(Paint.Style.FILL);
    let lx = left;
    for (let i = 0; i < names.size(); i++) {
      p.setColor(colors.get(i));
      cv.drawCircle(lx + 4 * d, 10 * d, 4 * d, p);
      p.setColor(0xFF334155);
      cv.drawText(names.get(i), lx + 11 * d, 14 * d, p);
      lx += p.measureText(names.get(i)) + 26 * d;
    }
    // reference lines
    p.setStrokeWidth(1.2 * d);
    for (let i = 0; i < refs.size(); i++) {
      const y = bottom - (refs.get(i)[0] - lo) / (hi - lo) * (bottom - top);
      p.setStyle(Paint.Style.STROKE);
      p.setColor(Ui.alpha(refs.get(i)[1], 0x99));
      p.setPathEffect(new DashPathEffect([6 * d, 5 * d], 0));
      cv.drawLine(left, y, right, y, p);
      p.setPathEffect(null);
      p.setStyle(Paint.Style.FILL);
      p.setTextSize(10 * d);
      cv.drawText(this.refLabels.get(i), 2 * d, y + 4 * d, p);
    }
    // axis
    p.setColor(0xFFCBD5E1);
    p.setStrokeWidth(1 * d);
    cv.drawLine(left, bottom, right, bottom, p);
    p.setColor(0xFF64748B);
    p.setTextSize(10 * d);
    if (!x.isEmpty()) {
      cv.drawText(x.get(0), left, h - 4 * d, p);
      const lastX = x.get(x.size() - 1);
      cv.drawText(lastX, right - p.measureText(lastX), h - 4 * d, p);
    }
    // series
    for (let s = 0; s < values.size(); s++) {
      const v = values.get(s);
      const path = new Path();
      let started = false;
      p.setColor(colors.get(s));
      for (let i = 0; i < v.size(); i++) {
        if (Number.isNaN(v.get(i))) continue;
        const px = left + (right - left) * i / (n - 1);
        const py = bottom - (v.get(i) - lo) / (hi - lo) * (bottom - top);
        if (!started) { path.moveTo(px, py); started = true; } else path.lineTo(px, py);
        p.setStyle(Paint.Style.FILL);
        cv.drawCircle(px, py, 3.2 * d, p);
      }
      p.setStyle(Paint.Style.STROKE);
      p.setStrokeWidth(2.2 * d);
      cv.drawPath(path, p);
    }
    p.setStyle(Paint.Style.FILL);
  }
};
;
