'use strict';
/** Bedside charts across the wards: for each chart, the inpatients on it or whose diagnosis calls for it. */
class ChartsActivity extends Base {
  constructor() { super(); this.code = Charts.BP; }

  static COLOR = 0xFFDC2626;

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Bedside charts");
    this.subtitle = "BP, diabetic, I/O, OP poisoning and ventilator";
    const k = this.getIntent().getStringExtra("kind");
    if (k != null) this.code = k;
  }

  /** Inpatients on a chart (entries) or suggested for it by their diagnosis. */
  static patients(db, code) {
    const out = [];
    for (const p of db.rows("SELECT * FROM patients WHERE status='IN' ORDER BY admit_date DESC, id DESC")) {
      const last = Charts.last(db, Long.parseLong(p.get("id")), code);
      if (last == null && !Charts.suggested(p, code)) continue;
      p.put("_last", last == null ? "" : Charts.stamp(last));
      p.put("_line", last == null ? "" : Charts.line(Charts.kind(code), Charts.data(last)));
      p.put("_worst", last == null ? "0" : String(Charts.worst(Charts.kind(code), Charts.data(last))));
      out.add(p);
    }
    Collections.sort(out, { compare: (a, b) => b.get("_last").compareTo(a.get("_last")) });
    return out;
  }

  /** Hourly BP not written for over an hour. */
  static overdue(code, stamp) {
    if (Charts.BP !== code || stamp.isEmpty()) return false;
    try {
      const t = LocalDateTime.parse(stamp.split(" ").join("T"));
      return t.isBefore(LocalDateTime.of(Dates.today(), Dates.time()).minusMinutes(75));
    } catch (e) {
      return false;
    }
  }

  render() {
    const k = Charts.kind(this.code);
    this.headerColor(k.color);
    const page = Ui.v(this);
    const chips = Ui.h(this);
    for (const x of Charts.KINDS) {
      const c = Ui.chip(this, x.name.split(" chart").join(""), x.code === this.code, x.color);
      c.setOnClickListener({ onClick: (v) => { this.code = x.code; this.render(); } });
      chips.addView(c);
    }
    chips.setPadding(Ui.dp(this, 14), Ui.dp(this, 10), Ui.dp(this, 14), Ui.dp(this, 4));
    page.addView(Ui.hscroll(this, chips));

    const ps = ChartsActivity.patients(this.db, this.code);
    let started = 0, due = 0;
    for (const p of ps) {
      if (!p.get("_last").isEmpty()) started++;
      if (ChartsActivity.overdue(this.code, p.get("_last"))) due++;
    }
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(k.color), 20));
    hero.addView(Ui.tv(this, k.name, 20, Color.WHITE, true));
    hero.addView(Ui.tv(this, k.about + ".  " + started + " on the chart, " + (ps.size() - started) + " suggested by diagnosis"
      + (due > 0 ? ", " + due + " due for BP" : "") + ".", 13, 0xE6FFFFFF, false));
    page.addView(hero);

    if (ps.isEmpty()) page.addView(this.emptyNote("No inpatient needs this chart yet. Open a patient and tap Bedside charts to start one."));
    for (const p of ps) {
      const none = p.get("_last").isEmpty();
      const late = ChartsActivity.overdue(this.code, p.get("_last"));
      const w = Integer.parseInt(p.get("_worst"));
      const pill = Db.shortName(p.get("location")) + (Ui.nz(p.get("bed")).isEmpty() ? "" : " · bed " + p.get("bed"));
      const sub = Ui.nz(p.get("diagnosis")) + (none ? "\nNot started (suggested by the diagnosis)" : "\n" + p.get("_line"));
      const right = none ? "Start" : late ? "Due · " + p.get("_last").substring(11) : Dates.nice(p.get("_last").substring(0, 10)) + " " + p.get("_last").substring(11);
      page.addView(this.entryCard(pill, late ? Charts.RED : none ? Ui.SLATE : w === 0 ? k.color : w, p.get("name"), sub, right,
        this.opener(ChartActivity, "id", p.get("id"), "kind", this.code)));
    }
    this.setPage(page);
  }
}
;
