    if (ge[5]) gen.add("pedal edema: " + edema.toLowerCase());
    if (!s(o, "ge_other").isEmpty()) gen.add(s(o, "ge_other"));
    b5.row(26, lbl("General Examination", ORANGE, ORANGE_L), c(FormDoc.boxes(["Pallor", "Icterus", "Cyanosis", "Clubbing", "Lymphadenopathy", "Pedal oedema"], ge)
        + "\nBuilt / nourishment / other findings: " + joinLines(gen, ", ")).span(7));
    b5.row(26, lbl("CVS", ORANGE, ORANGE_L), c(CaseSheet.cvsText(o)).span(3), lbl("RS", ORANGE, ORANGE_L), c(CaseSheet.rsText(o)).span(3));
    b5.row(26, lbl("Per Abdomen", ORANGE, ORANGE_L), c(CaseSheet.abdText(o)).span(3), lbl("CNS", ORANGE, ORANGE_L), c(CaseSheet.cnsText(o)).span(3));

    // 6. investigations
    const b6 = f.block("6.  INVESTIGATIONS", INDIGO, 0.2, 0.1, 0.1, 0.1, 0.2, 0.1, 0.1, 0.1);
    b6.pageBefore = true;
    const ih = b6.row(14);
    for (const h of ["Test", "Admission", "Repeat", "Discharge", "Test", "Admission", "Repeat", "Discharge"])
      ih.cells.add(c(h).b().size(7.5).color(0xFFFFFFFF).fill(0xFF5C6BC0).center());
    const plt = s(o, "cbc_plt").isEmpty() ? Ui.nz(p.get("platelet")) : s(o, "cbc_plt");
    const labs = [
      ["Haemoglobin (g/dL)", s(o, "cbc_hb"), "hb", "Bilirubin Total / Direct", slash(s(o, "lft_tb"), s(o, "lft_db")), "bili"],
      ["Total count (/cu.mm)", s(o, "cbc_tc"), "tc", "SGOT / SGPT (U/L)", slash(s(o, "lft_sgot"), s(o, "lft_sgpt")), "sgot"],
      ["DC (P / L / E)", slash(s(o, "cbc_p"), s(o, "cbc_l"), s(o, "cbc_e")), "dc", "ALP (U/L)", s(o, "lft_alp"), "alp"],
      ["Platelets (lakh/cu.mm)", plt, "plt", "Total protein / Albumin", slash(s(o, "lft_prot"), s(o, "lft_alb")), "prot"],
      ["PCV (%) / ESR (mm/hr)", slash(s(o, "cbc_hct"), s(o, "esr")), "pcv", "PT / INR", slash(s(o, "pt"), s(o, "inr")), "inr"],
      ["RBS (mg/dL)", s(o, "rbs"), "rbs", "Urine Alb / Sugar / Deposits", slash(s(o, "u_albumin"), s(o, "u_sugar"), s(o, "u_deposits")), "urine"],
      ["Urea (mg/dL)", s(o, "rft_urea"), "urea", "FBS / PPBS / HbA1c", slash(s(o, "fbs"), s(o, "ppbs"), s(o, "hba1c")), ""],
      ["Creatinine (mg/dL)", s(o, "rft_creat"), "creat", "Lipid profile", CaseSheet.lipidText(o), ""],
      ["Na⁺ / K⁺ (mEq/L)", slash(s(o, "na"), s(o, "k")), "nak", "Thyroid (TSH / T4 / T3)", CaseSheet.thyroidText(o), ""],
      ["Bicarbonate / Chloride", s(o, "abg_hco3"), "hco3", "Others", DischargeForm.othersLab(o), ""]];
    for (const r of labs) {
      const sx = p.get("sex");
      const row = b6.row(13, lbl(r[0], INDIGO, INDIGO_L).size(7.5), lab(c(r[1]).center().size(8), r[2], r[1], sx, o),
          lab(c(s(o, "r_" + r[2])).center().size(8), r[2], s(o, "r_" + r[2]), sx, o),
          lab(c(s(o, "d_" + r[2])).center().size(8), r[2], s(o, "d_" + r[2]), sx, o), lbl(r[3], INDIGO, INDIGO_L).size(7.5));
      if (r[5].isEmpty()) row.cells.add(c(r[4]).size(8).span(3));
      else {
        row.cells.add(lab(c(r[4]).center().size(8), r[5], r[4], sx, o));
        row.cells.add(lab(c(s(o, "r_" + r[5])).center().size(8), r[5], s(o, "r_" + r[5]), sx, o));
        row.cells.add(lab(c(s(o, "d_" + r[5])).center().size(8), r[5], s(o, "d_" + r[5]), sx, o));
      }
    }
    let dengue = CaseSheet.dengueText(o);
