    if (!s(o, "inv_other").isEmpty()) oth.add(s(o, "inv_other"));
    if (!CaseSheet.abgText(o).isEmpty()) oth.add("ABG: " + CaseSheet.abgText(o).split(" (suggested from the values)").join("")
        .split("high anion gap metabolic acidosis").join("HAGMA").split("normal anion gap metabolic acidosis").join("NAGMA"));
    if (!s(o, "smear").isEmpty()) oth.add("Smear: " + s(o, "smear"));
    if (!s(o, "cul_sputum").isEmpty()) oth.add("Sputum C&S: " + s(o, "cul_sputum"));
    if (!s(o, "cul_pus").isEmpty()) oth.add("Pus C&S: " + s(o, "cul_pus"));
    const two = [
      ["HIV / HBsAg / Anti-HCV", slash(s(o, "hiv"), s(o, "hbsag"), s(o, "hcv")), "MP / MF (smear / card)", CaseSheet.mpText(o)],
      ["Dengue NS1 / IgM / IgG", dengue, "Scrub / Leptospira IgM", CaseSheet.scrubLeptoText(o)],
      ["Widal / Blood C&S", slash(CaseSheet.widalText(o), s(o, "cul_blood")), "Urine C&S / CBNAAT", slash(s(o, "cul_urine"), CaseSheet.cbnaatText(o))],
      ["ECG", CaseSheet.ecgText(o), "Chest X-ray", CaseSheet.cxrText(o)],
      ["USG Abdomen", CaseSheet.usgText(o), "Echocardiography", CaseSheet.echoText(o)],
      ["CT / MRI", ctmri, "Other investigations", joinLines(oth, "; ")]];
    for (const r of two)
      b6.row(13, lbl(r[0], PINK, PINK_L).size(7.5), c(r[1]).size(8).span(3), lbl(r[2], PINK, PINK_L).size(7.5), c(r[3]).size(8).span(3));

    // 7. course and treatment
    const b7 = f.block("7.  COURSE IN HOSPITAL & TREATMENT GIVEN", GREEN, 0.2, 0.3, 0.2, 0.3);
    const course = new StringBuilder(Ui.nz(secs.get("Course in the hospital")));
    const tx = Ui.nz(secs.get("Treatment given")).split("• ").join("").split("\n").join("; ");
    if (!tx.isEmpty()) course.append(course.length() > 0 ? "\n" : "").append("Treatment given: ").append(tx);
    b7.row(44, c(course.toString()).span(4));
    let icu = s(o, "icu_stay");
    if (icu.isEmpty() && been.contains(Db.IMCU)) icu = "IMCU stay" + ("1".equals(p.get("vent")) ? ", ventilator" : "");
    const ops = [];
    const opk = [["op_surgery", "Surgery"], ["op_pulmo", "Pulmonology"], ["op_cardio", "Cardiology"], ["op_neuro", "Neurology"], ["op_uro", "Urology"],
      ["op_cts", "CTS"], ["op_vascular", "Vascular surgery"], ["op_rheum", "Rheumatology"], ["op_other", "Others"]];
    for (const x of opk) if (!s(o, x[0]).isEmpty()) ops.add(x[1]);
    const proc = [];
