    if (s(o, "mg_ryles").equals("Yes")) proc.add(s(o, "mg_ryles_type").equals("Ryles tube feeding") ? "Ryles tube feeding"
        : "Ryles tube" + (s(o, "mg_ryles_type").isEmpty() ? "" : " (" + s(o, "mg_ryles_type").toLowerCase() + ")"));
    const trans = s(o, "transfusion").isEmpty() ? CaseSheet.cap(CaseSheet.transfusionText(o)) : s(o, "transfusion");
    b7.row(14, lbl("Procedures done", GREEN, GREEN_L), c(joinLines(proc, "; ")), lbl("Blood transfusion", GREEN, GREEN_L), c(trans));
    b7.row(14, lbl("IMCU stay / Ventilator / NIV", GREEN, GREEN_L), c(icu), lbl("Cross-consultations", GREEN, GREEN_L), c(joinLines(ops, ", ")));

    // 8. condition at discharge
    const b8 = f.block("8.  CONDITION AT DISCHARGE", TEAL, 0.17, 0.83);
    let st = s(o, "dis_status");
    if (st.isEmpty()) {
      if (cond.startsWith("Improved") || cond.startsWith("Symptomatically")) st = "Improved";
      else if (cond.startsWith("Stable") || cond.startsWith("Hemodynamically")) st = "Stable";
      else if (cond.startsWith("Referred")) st = "Needs higher-centre care";
    }
    const stL = ["Recovered", "Improved", "Stable", "Unchanged", "Needs higher-centre care"];
    const stOn = new Array(stL.length).fill(false);
    for (let i = 0; i < stL.length; i++) stOn[i] = stL[i].equals(st);
    b8.row(14, lbl("Status", TEAL, TEAL_L), c(FormDoc.boxes(stL, stOn) + (s(o, "dis_note").isEmpty() ? "" : "      " + s(o, "dis_note"))));
    const blank = DischargeForm.blank;
    b8.row(14, lbl("Vitals at discharge", TEAL, TEAL_L), c("Pulse " + blank(s(o, "dv_pr")) + " /min      BP " + blank(s(o, "dv_sbp")) + " / " + blank(s(o, "dv_dbp"))
        + " mmHg      RR " + blank(s(o, "dv_rr")) + " /min      SpO₂ " + blank(s(o, "dv_spo2")) + " %      Temp " + blank(s(o, "dv_temp")) + " °F"));

