    let act = s(o, "activity");
    if (act.isEmpty()) act = s(o, "adv_activity").split(" activity").join("").split("Normal").join("Normal").split("Restricted").join("Restricted");
    b10.row(14, lbl("Diet", ORANGE, ORANGE_L), c(FormDoc.boxes(["Normal", "Diabetic", "Low salt", "Renal"], dietOn)),
        lbl("Activity", ORANGE, ORANGE_L), c(FormDoc.boxes(["Normal", "Restricted", "Bed rest"],
            [act.equals("Normal"), act.equals("Restricted"), act.equals("Bed rest")])));
    const special = [];
    if (!s(o, "special").isEmpty()) special.add(s(o, "special").split("\n").join("; "));
    for (const l of CaseSheet.adviceLines(o)) if (!l.equals(s(o, "adv_diet")) && !l.equals(s(o, "adv_activity"))) special.add(l);
    for (const l of s(o, "advice").jsplit("\n")) {
      const t = l.trim().replaceAllRx("^[•\\-*]\\s*", "");
      if (!t.isEmpty() && SummaryExport.med(t) == null && !t.toLowerCase().matches("(diabetic|low salt|renal|normal) diet\\.?")) special.add(t);
    }
