'use strict';
/** Reads the text and tables out of Word (.docx), Excel (.xlsx), CSV, plain text and text-based PDF files, on the phone. */
class Extract {
  static read(fileName, data) {
    const n = fileName.toLowerCase();
    let r;
    if (n.endsWith('.docx') || Extract.isZipWith(data, 'word/document.xml')) r = Extract.docx(data);
    else if (n.endsWith('.xlsx') || Extract.isZipWith(data, 'xl/workbook.xml')) r = Extract.xlsx(data);
    else if (n.endsWith('.pdf') || Extract.startsWith(data, '%PDF')) r = Extract.pdf(data);
    else if (n.endsWith('.doc') || n.endsWith('.xls'))
      throw new IOException('Old Word/Excel format (.doc/.xls). Open it and save it as .docx or .xlsx, then try again.');
    else r = Extract.text(new TextDecoder(Extract.guessCharset(data)).decode(data), n.endsWith('.csv') ? ',' : n.endsWith('.tsv') ? '\t' : '\u0000');
    return r;
  }

  // ---------- plain text / CSV ----------

  static text(s, sep) {
    if (sep == null || sep === 0) sep = '\u0000';
    const r = new Extract.Result();
    r.kind = sep === ',' ? 'CSV' : 'Text';
    s = s.split('\r\n').join('\n').split('\r').join('\n');
    if (sep === '\u0000' && Extract.looksCsv(s)) sep = ',';
    if (sep !== '\u0000') {
      const t = [];
      for (const line of s.jsplit('\n')) {
        if (line.trim().isEmpty()) continue;
        t.add(Extract.splitCsv(line, sep));
      }
      r.tables.add(t);
      for (const row of t) r.text.append(Extract.join(row, '\t')).append('\n');
    } else {
      r.text.append(s);
      const t = Extract.tabTable(s);
      if (t != null) r.tables.add(t);
    }
    return r;
  }

  static looksCsv(s) {
    const lines = s.jsplit('\n');
    if (lines.length < 2) return false;
    const c0 = Extract.count(lines[0], ',');
    if (c0 < 2) return false;
    let same = 0;
    for (let i = 1; i < Math.min(lines.length, 6); i++) if (Math.abs(Extract.count(lines[i], ',') - c0) <= 1) same++;
    return same >= Math.min(lines.length - 1, 5) - 1;
  }

  static count(s, c) {
    let n = 0;
    for (let i = 0; i < s.length; i++) if (s.charAt(i) === c) n++;
    return n;
  }

  static splitCsv(line, sep) {
    const out = [];
    const cur = new StringBuilder();
    let q = false;
    for (let i = 0; i < line.length; i++) {
      const c = line.charAt(i);
      if (q) {
        if (c === '"' && i + 1 < line.length && line.charAt(i + 1) === '"') { cur.append('"'); i++; }
        else if (c === '"') q = false;
        else cur.append(c);
      } else if (c === '"') q = true;
      else if (c === sep) { out.add(cur.toString().trim()); cur.setLength(0); }
      else cur.append(c);
    }
    out.add(cur.toString().trim());
    return out;
  }

  /** Lines whose cells are separated by tabs (or 3+ spaces), as in text copied from a table. */
  static tabTable(s) {
    const t = [];
    for (const line of s.jsplit('\n')) {
      if (line.trim().isEmpty()) continue;
      const cells = line.contains('\t') ? line.jsplit('\t') : line.trim().jsplit(' {3,}');
      if (cells.length < 2) continue;
      const row = [];
      for (const c of cells) row.add(c.trim());
      t.add(row);
    }
    return t.size() >= 2 ? t : null;
  }

  static guessCharset(d) {
    if (d.length >= 2 && (d[0] & 0xFF) === 0xFF && (d[1] & 0xFF) === 0xFE) return 'UTF-16LE';
    if (d.length >= 2 && (d[0] & 0xFF) === 0xFE && (d[1] & 0xFF) === 0xFF) return 'UTF-16BE';
    return 'UTF-8';
  }

  static join(l, sep) {
    const b = new StringBuilder();
    for (const s of l) {
      if (b.length() > 0) b.append(sep);
      b.append(s);
    }
    return b.toString();
  }

  // ---------- zip helpers ----------

  static startsWith(d, s) {
    if (d.length < s.length) return false;
    for (let i = 0; i < s.length; i++) if (d[i] !== s.charCodeAt(i)) return false;
    return true;
  }

  static isZipWith(d, entry) {
    if (!Extract.startsWith(d, 'PK')) return false;
    try { return Extract.unzip(d).containsKey(entry); } catch (e) { return false; }
  }

  static unzip(d) {
    const m = new JMap();
    const z = new ZipInputStream(new ByteArrayInputStream(d));
    let e;
    while ((e = z.getNextEntry()) != null) {
      if (e.isDirectory()) continue;
      const n = e.getName();
      if (!n.endsWith('.xml') && !n.endsWith('.rels')) continue;
      m.put(n, Extract.readAll(z));
    }
    z.close();
    return m;
  }

  static readAll(inp) {
    const o = new ByteArrayOutputStream();
    const buf = new Uint8Array(16384);
    let n;
    while ((n = inp.read(buf)) > 0) {
      o.write(buf, 0, n);
      if (o.size() > 60000000) throw new IOException('File too large');
    }
    return o.toByteArray();
  }

  static parser(xml) {
    const f = XmlPullParserFactory.newInstance();
    f.setNamespaceAware(false);
    const p = f.newPullParser();
    p.setInput(new StringReader(jstr(xml)));
    return p;
  }

  // ---------- Word ----------

  static docx(data) {
    const r = new Extract.Result();
    r.kind = 'Word';
    const xml = Extract.unzip(data).get('word/document.xml');
    if (xml == null) throw new IOException('Not a Word document');
    const p = Extract.parser(xml);
    const para = new StringBuilder(), cell = new StringBuilder();
    const stack = [];
    let row = null;
    let tblDepth = 0;
    for (let ev = p.getEventType(); ev !== XmlPullParser.END_DOCUMENT; ev = p.next()) {
      const tag = p.getName();
      if (ev === XmlPullParser.START_TAG) {
        if (tag.equals('w:tbl')) { tblDepth++; stack.add([]); }
        else if (tag.equals('w:tr') && tblDepth > 0) row = [];
        else if (tag.equals('w:tc')) cell.setLength(0);
        else if (tag.equals('w:tab')) para.append('\t');
        else if (tag.equals('w:br') || tag.equals('w:cr')) para.append('\n');
        else if (tag.equals('w:t')) para.append(p.nextText());
      } else if (ev === XmlPullParser.END_TAG) {
        if (tag.equals('w:p')) {
          if (tblDepth > 0) {
            if (cell.length() > 0 && para.length() > 0) cell.append(' ');
            cell.append(para.toString().trim());
          } else r.text.append(para).append('\n');
          para.setLength(0);
        } else if (tag.equals('w:tc') && row != null) row.add(cell.toString().trim());
        else if (tag.equals('w:tr') && row != null && !stack.isEmpty()) {
          stack.get(stack.size() - 1).add(row);
          r.text.append(Extract.join(row, '\t')).append('\n');
          row = null;
        } else if (tag.equals('w:tbl')) {
          tblDepth--;
          const t = stack.removeAt(stack.size() - 1);
          if (!t.isEmpty()) r.tables.add(t);
        }
      }
    }
    return r;
  }

  // ---------- Excel ----------

  static xlsx(data) {
    const r = new Extract.Result();
    r.kind = 'Excel';
    const z = Extract.unzip(data);
    const shared = [];
    const ss = z.get('xl/sharedStrings.xml');
    if (ss != null) {
      const p = Extract.parser(ss);
      let cur = null;
      for (let ev = p.getEventType(); ev !== XmlPullParser.END_DOCUMENT; ev = p.next()) {
        if (ev === XmlPullParser.START_TAG && p.getName().equals('si')) cur = new StringBuilder();
        else if (ev === XmlPullParser.START_TAG && p.getName().equals('t') && cur != null) cur.append(p.nextText());
        else if (ev === XmlPullParser.END_TAG && p.getName().equals('si') && cur != null) { shared.add(cur.toString()); cur = null; }
      }
    }
    // date-formatted cells: style indexes whose number format is a date
    const dateStyles = Extract.dateStyles(z.get('xl/styles.xml'));
    const sheets = new TreeMap();
    for (const n of z.keySet()) {
      const m = Pattern.compile('xl/worksheets/sheet(\\d+)\\.xml').matcher(n);
      if (m.matches()) sheets.put(Integer.parseInt(m.group(1)), n);
    }
    for (const sheet of sheets.values()) {
      const p = Extract.parser(z.get(sheet));
      const grid = new TreeMap();
      let ref = null, type = null;
      let style = -1;
      let val = null;
      for (let ev = p.getEventType(); ev !== XmlPullParser.END_DOCUMENT; ev = p.next()) {
        if (ev === XmlPullParser.START_TAG) {
          const tag = p.getName();
          if (tag.equals('c')) {
            ref = p.getAttributeValue(null, 'r');
            type = p.getAttributeValue(null, 't');
            const s = p.getAttributeValue(null, 's');
            style = s == null ? -1 : Integer.parseInt(s);
            val = null;
          } else if (tag.equals('v')) val = p.nextText();
          else if (tag.equals('t') && 'inlineStr'.equals(type)) val = (val == null ? '' : val) + p.nextText();
        } else if (ev === XmlPullParser.END_TAG && p.getName().equals('c') && ref != null && val != null) {
          let v = val;
          if ('s'.equals(type)) v = shared.get(Integer.parseInt(val.trim()));
          else if ((type == null || 'n'.equals(type)) && dateStyles.contains(style)) v = Extract.serialDate(val);
          else if (type == null || 'n'.equals(type)) v = val.replaceAllRx('\\.0+$', '');
          const rc = Extract.cellRef(ref);
          let row = grid.get(rc[0]);
          if (row == null) grid.put(rc[0], row = new TreeMap());
          row.put(rc[1], v.trim());
          ref = null;
        }
      }
      const t = [];
      let maxCol = 0;
      for (const row of grid.values()) if (!row.isEmpty()) maxCol = Math.max(maxCol, row.lastKey());
      for (const row of grid.values()) {
        const l = [];
        for (let c = 0; c <= maxCol; c++) l.add(row.containsKey(c) ? row.get(c) : '');
        let any = false;
        for (const s of l) if (!s.isEmpty()) any = true;
        if (any) t.add(l);
      }
      if (!t.isEmpty()) {
        r.tables.add(t);
        for (const row of t) r.text.append(Extract.join(row, '\t')).append('\n');
        r.text.append('\n');
      }
    }
    return r;
  }

  static dateStyles(styles) {
    const out = new JSet();
    if (styles == null) return out;
    const dateFmts = new JSet();
    for (let i = 14; i <= 22; i++) dateFmts.add(i);
    dateFmts.add(45); dateFmts.add(46); dateFmts.add(47);
    const p = Extract.parser(styles);
    let inXfs = false;
    let idx = 0;
    for (let ev = p.getEventType(); ev !== XmlPullParser.END_DOCUMENT; ev = p.next()) {
      if (ev === XmlPullParser.START_TAG) {
        const tag = p.getName();
        if (tag.equals('numFmt')) {
          const code = Ui.nz(p.getAttributeValue(null, 'formatCode')).toLowerCase();
          if ((code.contains('d') && code.contains('m')) || code.contains('yy'))
            dateFmts.add(Integer.parseInt(p.getAttributeValue(null, 'numFmtId')));
        } else if (tag.equals('cellXfs')) inXfs = true;
        else if (tag.equals('xf') && inXfs) {
          const id = p.getAttributeValue(null, 'numFmtId');
          if (id != null && dateFmts.contains(Integer.parseInt(id))) out.add(idx);
          idx++;
        }
      } else if (ev === XmlPullParser.END_TAG && p.getName().equals('cellXfs')) inXfs = false;
    }
    return out;
  }

  static serialDate(v) {
    try {
      const d = Double.parseDouble(v.trim());
      return LocalDate.of(1899, 12, 30).plusDays(Math.floor(d)).toString();
    } catch (e) {
      return v;
    }
  }

  static cellRef(ref) {
    let col = 0, i = 0;
    while (i < ref.length && Character.isLetter(ref.charAt(i))) {
      col = col * 26 + (Character.toUpperCase(ref.charAt(i)).charCodeAt(0) - 'A'.charCodeAt(0) + 1);
      i++;
    }
    return [Integer.parseInt(ref.substring(i)), col - 1];
  }

  // ---------- PDF (text-based; scanned PDFs have no text to read) ----------

  static pdf(d) {
    const r = new Extract.Result();
    r.kind = 'PDF';
    const p = new Extract.Pdf(d);
    r.text.append(p.text());
    r.tables.addAll(p.tables());
    return r;
  }
}

Extract.Result = class {
  constructor() {
    this.text = new StringBuilder();
    this.tables = [];
    this.kind = '';
  }
};

/** A piece of text drawn at a place on a page. */
const ExtractFrag = class {
  constructor(page, x, y, size, text) { this.page = page; this.x = x; this.y = y; this.size = size; this.text = text; }
};

/** A small PDF text reader: objects, Flate streams, ToUnicode maps and the text operators. */
Extract.Pdf = class {
  constructor(d) {
    this.data = d;
    this.objs = new JMap();          // obj number → {dict start, dict end, stream start, stream end}
    this.cmaps = new JMap();
    this.cmapBytes = new JMap();
    this.fontByName = new JMap();
    this.embedded = new JMap();
    this.frags = [];
    this.page = 0;
    const raw = this.raw = ShimE.latin1(d);
    if (raw.contains('/Encrypt')) throw new IOException('This PDF is password-protected or encrypted.');
    const m = Pattern.compile('(\\d+)\\s+(\\d+)\\s+obj\\b').matcher(raw);
    while (m.find()) {
      const start = m.end();
      const end = raw.indexOf('endobj', start);
      if (end < 0) break;
      const st = raw.indexOf('stream', start);
      let o;
      if (st >= 0 && st < end && !raw.startsWith('endstream', st - 3)) {
        let s0 = st + 6;
        if (raw.charAt(s0) === '\r') s0++;
        if (raw.charAt(s0) === '\n') s0++;
        const s1 = raw.lastIndexOf('endstream', end);
        o = [start, st, s0, s1];
      } else o = [start, end, -1, -1];
      this.objs.put(Integer.parseInt(m.group(1)), o);
    }
    // object streams (PDF 1.5) hold more objects: unpack fonts' dictionaries from them too
    for (const e of ArrayList(this.objs.entrySet())) {
      const dict = this.dict(e.getKey());
      if (!dict.contains('/ObjStm')) continue;
      const s = this.stream(e.getKey());
      if (s == null) continue;
      const body = ShimE.latin1(s);
      const first = Extract.Pdf.intAfter(dict, '/First');
      const hdr = body.substring(0, Math.max(0, Math.min(first, body.length))).trim().jsplit('\\s+');
      for (let i = 0; i + 1 < hdr.length; i += 2) {
        try {
          const num = Integer.parseInt(hdr[i]), off = Integer.parseInt(hdr[i + 1]);
          const nextOff = i + 3 < hdr.length ? Integer.parseInt(hdr[i + 3]) : body.length - first;
          this.embedded.put(num, body.substring(first + off, Math.min(body.length, first + nextOff)));
        } catch (ignored) {}
      }
    }
    // fonts: resource name → font object, and each font's ToUnicode map
    const fontRef = Pattern.compile('/([A-Za-z0-9_+.-]+)\\s+(\\d+)\\s+0\\s+R');
    for (const n of this.allObjects()) {
      const dict = this.dict(n);
      const fi = dict.indexOf('/Font');
      if (fi < 0) continue;
      const after = dict.substring(fi + 5).trim();
      let fontDict = null;
      if (after.startsWith('<<')) fontDict = Extract.Pdf.balanced(after);
      else {
        const rm = Pattern.compile('^(\\d+)\\s+0\\s+R').matcher(after);
        if (rm.find()) fontDict = this.dict(Integer.parseInt(rm.group(1)));
      }
      if (fontDict == null) continue;
      const fm = fontRef.matcher(fontDict);
      while (fm.find()) {
        const obj = Integer.parseInt(fm.group(2));
        if (this.dict(obj).contains('/Font') || this.dict(obj).contains('/BaseFont')) this.fontByName.put(fm.group(1), obj);
      }
    }
    for (const f of new JSet(this.fontByName.values())) this.loadCmap(f);
  }

  allObjects() {
    const s = new TreeSet(this.objs.keySet());
    s.addAll(this.embedded.keySet());
    return s;
  }

  static intAfter(dict, key) {
    const m = Pattern.compile(Pattern.quote(key) + '\\s+(\\d+)').matcher(dict);
    return m.find() ? Integer.parseInt(m.group(1)) : 0;
  }

  static balanced(s) {
    let depth = 0;
    for (let i = 0; i + 1 < s.length; i++) {
      if (s.charAt(i) === '<' && s.charAt(i + 1) === '<') { depth++; i++; }
      else if (s.charAt(i) === '>' && s.charAt(i + 1) === '>') {
        depth--;
        i++;
        if (depth === 0) return s.substring(0, i + 1);
      }
    }
    return s;
  }

  dict(n) {
    const o = this.objs.get(n);
    if (o == null) return this.embedded.containsKey(n) ? this.embedded.get(n) : '';
    return this.raw.substring(o[0], o[1]);
  }

  stream(n) {
    const o = this.objs.get(n);
    if (o == null || o[2] < 0) return null;
    const dict = this.dict(n);
    let len = o[3] - o[2];
    const lm = Pattern.compile('/Length\\s+(\\d+)(\\s+0\\s+R)?').matcher(dict);
    if (lm.find()) {
      let l = Integer.parseInt(lm.group(1));
      if (lm.group(2) != null) {
        const v = Pattern.compile('^\\s*(\\d+)').matcher(this.dict(l));
        l = v.find() ? Integer.parseInt(v.group(1)) : len;
      }
      if (l > 0 && o[2] + l <= this.data.length) len = l;
    }
    let s = new Uint8Array(Math.max(0, len));
    s.set(this.data.subarray(o[2], o[2] + s.length));
    const fm = Pattern.compile('/Filter\\s*(\\[[^\\]]*\\]|/[A-Za-z0-9]+)').matcher(dict);
    if (!fm.find()) return s;
    const each = Pattern.compile('/([A-Za-z0-9]+)').matcher(fm.group(1));
    while (each.find()) {
      const f = each.group(1);
      if (f.equals('FlateDecode') || f.equals('Fl')) s = Extract.Pdf.inflate(s);
      else if (f.equals('ASCII85Decode') || f.equals('A85')) s = Extract.Pdf.ascii85(s);
      else return null;    // images and other filters: no text
    }
    return s;
  }

  static ascii85(inp) {
    const o = new ByteArrayOutputStream();
    let acc = 0;
    let n = 0;
    for (const b of inp) {
      const c = String.fromCharCode(b & 0xFF);
      if (c === '~') break;
      if (Character.isWhitespace(c) || c === '<' && n === 0 && acc === 0 && o.size() === 0) continue;
      if (c === 'z' && n === 0) { o.write(0); o.write(0); o.write(0); o.write(0); continue; }
      if (c < '!' || c > 'u') continue;
      acc = acc * 85 + (c.charCodeAt(0) - 33);
      if (++n === 5) {
        for (let k = 3; k >= 0; k--) o.write(Math.floor(acc / Math.pow(2, 8 * k)) & 0xFF);
        acc = 0;
        n = 0;
      }
    }
    if (n > 0) {
      for (let k = n; k < 5; k++) acc = acc * 85 + 84;
      for (let k = 3; k > 3 - (n - 1); k--) o.write(Math.floor(acc / Math.pow(2, 8 * k)) & 0xFF);
    }
    return o.toByteArray();
  }

  static inflate(s) {
    const inf = new Inflater();
    inf.setInput(s);
    const o = new ByteArrayOutputStream();
    const buf = new Uint8Array(16384);
    try {
      while (!inf.finished()) {
        const n = inf.inflate(buf);
        if (n === 0 && (inf.needsInput() || (inf.needsDictionary ? inf.needsDictionary() : true))) break;
        o.write(buf, 0, n);
      }
    } catch (ignored) {}
    inf.end();
    return o.toByteArray();
  }

  loadCmap(font) {
    const fd = this.dict(font);
    const m = Pattern.compile('/ToUnicode\\s+(\\d+)\\s+0\\s+R').matcher(fd);
    const identity = fd.contains('/Identity-H') || fd.contains('/Identity-V');
    this.cmapBytes.put(font, identity ? 2 : 1);
    if (!m.find()) return;
    const s = this.stream(Integer.parseInt(m.group(1)));
    if (s == null) return;
    const c = ShimE.latin1(s);
    const map = new JMap();
    const cs = Pattern.compile('begincodespacerange\\s*<([0-9A-Fa-f]+)>').matcher(c);
    if (cs.find()) this.cmapBytes.put(font, idiv(cs.group(1).length, 2));
    let blk = Pattern.compile('beginbfchar(.*?)endbfchar', Pattern.DOTALL).matcher(c);
    while (blk.find()) {
      const e = Pattern.compile('<([0-9A-Fa-f]+)>\\s*<([0-9A-Fa-f]+)>').matcher(blk.group(1));
      while (e.find()) map.put(parseInt(e.group(1), 16), Extract.Pdf.hexUtf16(e.group(2)));
    }
    blk = Pattern.compile('beginbfrange(.*?)endbfrange', Pattern.DOTALL).matcher(c);
    while (blk.find()) {
      const e = Pattern.compile('<([0-9A-Fa-f]+)>\\s*<([0-9A-Fa-f]+)>\\s*(<([0-9A-Fa-f]+)>|\\[([^\\]]*)\\])').matcher(blk.group(1));
      while (e.find()) {
        const a = parseInt(e.group(1), 16), b = parseInt(e.group(2), 16);
        if (b - a > 65535) continue;
        if (e.group(4) != null) {
          const base = Extract.Pdf.hexUtf16(e.group(4));
          if (base.isEmpty()) continue;
          for (let k = a; k <= b; k++) {
            const last = (base.charCodeAt(base.length - 1) + (k - a)) & 0xFFFF;
            map.put(k, base.substring(0, base.length - 1) + String.fromCharCode(last));
          }
        } else {
          const h = Pattern.compile('<([0-9A-Fa-f]+)>').matcher(e.group(5));
          let k = a;
          while (h.find() && k <= b) map.put(k++, Extract.Pdf.hexUtf16(h.group(1)));
        }
      }
    }
    this.cmaps.put(font, map);
  }

  static hexUtf16(h) {
    const b = new StringBuilder();
    for (let i = 0; i + 4 <= h.length; i += 4) b.append(String.fromCharCode(parseInt(h.substring(i, i + 4), 16)));
    if (h.length === 2) b.append(String.fromCharCode(parseInt(h, 16)));
    return b.toString();
  }

  /** Page content streams in page order (following /Kids), else every stream that holds text. */
  contentStreams() {
    const out = [];
    for (const n of new TreeSet(this.objs.keySet())) {
      const d = this.dict(n);
      if (!/\/Type\s*\/Page\b(?!s)/.test(d)) continue;
      const c = Pattern.compile('/Contents\\s*(\\[(.*?)\\]|(\\d+)\\s+0\\s+R)', Pattern.DOTALL).matcher(d);
      if (!c.find()) continue;
      const r = Pattern.compile('(\\d+)\\s+0\\s+R').matcher(c.group(0));
      while (r.find()) {
        const obj = Integer.parseInt(r.group(1));
        if (!out.contains(obj)) out.add(obj);
      }
    }
    if (out.isEmpty()) for (const n of new TreeSet(this.objs.keySet())) out.add(n);
    return out;
  }

  /** Text laid out line by line from where it sits on the page; a tab where a gap separates columns. */
  text() {
    const lines = this.lines();
    const out = new StringBuilder();
    let lastPage = -1;
    for (const line of lines) {
      if (lastPage >= 0 && line.get(0).page !== lastPage) out.append('\n');
      lastPage = line.get(0).page;
      let prev = null;
      for (const f of line) {
        if (prev != null) {
          const end = prev.x + Extract.Pdf.width(prev);
          out.append(f.x - end > Math.max(prev.size, f.size) * 1.2 ? '\t' : f.x - end > prev.size * 0.15 && !prev.text.endsWith(' ') && !f.text.startsWith(' ') ? ' ' : '');
        }
        out.append(f.text);
        prev = f;
      }
      out.append('\n');
    }
    return out.toString().replaceAllRx('[ ]+\n', '\n').replaceAllRx('\n{3,}', '\n\n');
  }

  static width(f) {
    return f.text.length * f.size * 0.5;
  }

  /** Fragments grouped into lines (top to bottom, page by page), each line left to right. */
  lines() {
    if (this.frags.isEmpty()) {
      for (const n of this.contentStreams()) {
        const st = this.stream(n);
        if (st == null || st.length === 0) continue;
        const c = ShimE.latin1(st);
        if (!c.contains('BT')) continue;
        this.run(c, null);
        this.page++;
      }
    }
    const all = [];
    for (const f of this.frags) if (!f.text.trim().isEmpty()) all.add(f);
    Collections.sort(all, {
      compare: (a, b) => {
        if (a.page !== b.page) return a.page - b.page;
        return Double.compare(b.y, a.y);
      }
    });
    const lines = [];
    let cur = null;
    let cy = 0;
    for (const f of all) {
      if (cur == null || f.page !== cur.get(0).page || Math.abs(f.y - cy) > Math.max(1, f.size * 0.4)) {
        cur = [];
        lines.add(cur);
        cy = f.y;
      }
      cur.add(f);
    }
    for (const l of lines) Collections.sort(l, { compare: (a, b) => Double.compare(a.x, b.x) });
    return lines;
  }

  /**
   * Rebuilds a table from positions: the header line gives the column edges, every later line drops its
   * pieces into those columns, and a line with nothing in the first column continues the row above (wrapped cells).
   */
  table(lines, headerLine) {
    const head = lines.get(headerLine);
    const starts = [];
    for (const f of head) {
      if (!starts.isEmpty()) {
        let prevF = null;
        for (const g of head) if (g.x === starts.get(starts.size() - 1)) prevF = g;
        if (prevF != null && f.x - (prevF.x + Extract.Pdf.width(prevF)) < f.size * 0.6) continue;   // same cell, next word
      }
      starts.add(f.x);
    }
    const t = [];
    let row = null;
    let lastY = head.get(0).y;
    let pageNo = head.get(0).page;
    for (let i = headerLine; i < lines.size(); i++) {
      const line = lines.get(i);
      const first = line.get(0);
      const size = first.size;
      if (first.page !== pageNo) { pageNo = first.page; lastY = first.y + size * 1.4; }
      if (lastY - first.y > size * 3.2 && i > headerLine) break;           // a gap: the table has ended
      lastY = first.y;
      const cells = new Array(starts.size()).fill('');
      for (const f of line) {
        let col = 0;
        for (let k = 0; k < starts.size(); k++) if (f.x >= starts.get(k) - f.size * 0.8) col = k;
        cells[col] = cells[col].isEmpty() ? f.text.trim() : cells[col] + ' ' + f.text.trim();
      }
      const cont = cells[0].isEmpty() && row != null;
      if (cont) {
        for (let k = 0; k < cells.length; k++)
          if (!cells[k].isEmpty()) row.set(k, row.get(k).isEmpty() ? cells[k] : Extract.Pdf.joinWrapped(row.get(k), cells[k]));
      } else {
        row = cells.slice();
        t.add(row);
      }
    }
    return t;
  }

  static joinWrapped(a, b) {
    // a word broken across lines ("manageme" + "nt") joins without a space
    if (a.matches('.*[a-z]$') && b.matches('^[a-z].*') && !a.contains(' ' + b)) {
      const lastWord = a.substring(a.lastIndexOf(' ') + 1);
      if (lastWord.length >= 6 && b.length <= 3) return a + b;
    }
    return a + ' ' + b;
  }

  /** Every table in the document whose header row names known columns. */
  tables() {
    const out = [];
    const lines = this.lines();
    for (let i = 0; i < lines.size(); i++) {
      const l = lines.get(i);
      if (l.size() < 2) continue;
      let known = 0;
      let name = false;
      for (const f of l) {
        const fd = Importer.fieldOf(f.text);
        if (fd != null) known++;
        if ('name'.equals(fd)) name = true;
      }
      if (known >= 2 && name) {
        const t = this.table(lines, i);
        if (t.size() >= 2) out.add(t);
        i += t.size();
      }
    }
    return out;
  }

  run(c, unused) {
    const ops = [];
    const Frag = ExtractFrag;
    let font = -1;
    let fontSize = 10, leading = 0;
    let tm = [1, 0, 0, 1, 0, 0], lm = [1, 0, 0, 1, 0, 0];
    let adv = 0;   // estimated advance along the line since the last positioning
    let i = 0;
    const len = c.length;
    const num = Extract.Pdf.num, last = Extract.Pdf.last;
    while (i < len) {
      const ch = c.charAt(i);
      if (Character.isWhitespace(ch)) { i++; continue; }
      if (ch === '%') { while (i < len && c.charAt(i) !== '\n' && c.charAt(i) !== '\r') i++; continue; }
      if (ch === '(') {
        const b = new StringBuilder();
        let depth = 1;
        i++;
        while (i < len && depth > 0) {
          const k = c.charAt(i);
          if (k === '\\' && i + 1 < len) {
            const e = c.charAt(++i);
            if (e === 'n') b.append('\n');
            else if (e === 'r') b.append('\r');
            else if (e === 't') b.append('\t');
            else if (e === 'b' || e === 'f') { /* skip */ }
            else if (e >= '0' && e <= '7') {
              let v = 0, cnt = 0;
              while (cnt < 3 && i < len && c.charAt(i) >= '0' && c.charAt(i) <= '7') { v = v * 8 + (c.charCodeAt(i) - 48); i++; cnt++; }
              i--;
              b.append(String.fromCharCode(v & 0xFF));
            } else if (e === '\r' || e === '\n') { /* line continuation */ }
            else b.append(e);
          } else if (k === '(') { depth++; b.append(k); }
          else if (k === ')') { depth--; if (depth > 0) b.append(k); }
          else b.append(k);
          i++;
        }
        ops.add({ bytes: ShimE.latin1Bytes(b.toString()) });
        continue;
      }
      if (ch === '<' && i + 1 < len && c.charAt(i + 1) !== '<') {
        const e = c.indexOf('>', i);
        if (e < 0) break;
        let h = c.substring(i + 1, e).replaceAllRx('\\s', '');
        if (h.length % 2 === 1) h += '0';
        const b = new Uint8Array(idiv(h.length, 2));
        for (let k = 0; k < b.length; k++) b[k] = parseInt(h.substring(2 * k, 2 * k + 2), 16) & 255;
        ops.add({ bytes: b });
        i = e + 1;
        continue;
      }
      if (ch === '[') { ops.add('['); i++; continue; }
      if (ch === ']') {
        const arr = [];
        let k = ops.size() - 1;
        while (k >= 0 && !'['.equals(ops.get(k))) k--;
        if (k >= 0) {
          arr.addAll(ops.subList(k + 1, ops.size()));
          while (ops.size() > k) ops.removeAt(ops.size() - 1);
        }
        ops.add({ list: arr });
        i++;
        continue;
      }
      if (ch === '<' || ch === '>') { // inline dictionaries (marked content): skip
        if (ch === '<') {
          let depth = 0;
          while (i + 1 < len) {
            if (c.charAt(i) === '<' && c.charAt(i + 1) === '<') { depth++; i += 2; }
            else if (c.charAt(i) === '>' && c.charAt(i + 1) === '>') { depth--; i += 2; if (depth === 0) break; }
            else i++;
          }
        } else i++;
        continue;
      }
      const s0 = i;
      if (ch === '/') i++;
      while (i < len) {
        const k = c.charAt(i);
        if (Character.isWhitespace(k) || k === '(' || k === ')' || k === '<' || k === '>' || k === '[' || k === ']' || (k === '/' && i > s0)) break;
        i++;
      }
      const tok = c.substring(s0, i);
      if (tok.isEmpty()) { i++; continue; }
      const f = tok.charAt(0);
      if (f === '/' || f === '-' || f === '+' || f === '.' || Character.isDigit(f)) { ops.add(tok); continue; }
      // an operator
      switch (tok) {
        case 'BT': tm = [1, 0, 0, 1, 0, 0]; lm = tm.slice(); adv = 0; break;
        case 'Tf':
          if (ops.size() >= 2) {
            const fo = this.fontByName.get(String(ops.get(ops.size() - 2)).split('/').join(''));
            font = fo == null ? -1 : fo;
            fontSize = num(ops.get(ops.size() - 1), 10);
          }
          break;
        case 'TL': leading = num(last(ops), 0); break;
        case 'Td': case 'TD':
          if (ops.size() >= 2) {
            const tx = num(ops.get(ops.size() - 2), 0), ty = num(ops.get(ops.size() - 1), 0);
            if (tok.equals('TD')) leading = -ty;
            lm[4] += tx * lm[0] + ty * lm[2];
            lm[5] += tx * lm[1] + ty * lm[3];
            tm = lm.slice();
            adv = 0;
          }
          break;
        case 'Tm':
          if (ops.size() >= 6) {
            for (let k = 0; k < 6; k++) lm[k] = num(ops.get(ops.size() - 6 + k), k === 0 || k === 3 ? 1 : 0);
            tm = lm.slice();
            adv = 0;
          }
          break;
        case 'T*':
          lm[5] -= (leading === 0 ? fontSize : leading) * lm[3];
          tm = lm.slice();
          adv = 0;
          break;
        case 'Tj': case '\'': case '"': case 'TJ': {
          if (tok.equals('\'') || tok.equals('"')) { lm[5] -= (leading === 0 ? fontSize : leading) * lm[3]; tm = lm.slice(); adv = 0; }
          const scale = Math.abs(tm[3]) > 0 ? Math.abs(tm[3]) : Math.abs(tm[0]);
          const size = fontSize * (scale === 0 ? 1 : scale);
          const arg = last(ops);
          const piece = new StringBuilder();
          if (arg != null && arg.bytes) piece.append(this.decode(font, arg.bytes));
          else if (arg != null && arg.list) {
            for (const o of arg.list) {
              if (o != null && o.bytes) piece.append(this.decode(font, o.bytes));
              else {
                const a2 = num(o, 0);
                if (a2 < -2500) {
                  // a wide gap inside one text run: start a new fragment there
                  this.frags.add(new Frag(this.page, tm[4] + adv, tm[5], size, piece.toString()));
                  adv += piece.length() * size * 0.5 - a2 / 1000 * size;
                  piece.setLength(0);
                } else if (a2 < -180) piece.append(' ');
              }
            }
          }
          this.frags.add(new Frag(this.page, tm[4] + adv, tm[5], size, piece.toString()));
          adv += piece.length() * size * 0.5;
          break;
        }
        default: break;
      }
      ops.clear();
    }
  }

  static last(ops) {
    return ops.isEmpty() ? null : ops.get(ops.size() - 1);
  }

  static num(o, def) {
    try { return Double.parseDouble(String(o)); } catch (e) { return def; }
  }

  decode(font, b) {
    const map = this.cmaps.get(font);
    const w = this.cmapBytes.containsKey(font) ? this.cmapBytes.get(font) : 1;
    const s = new StringBuilder();
    if (w === 2) {
      for (let i = 0; i + 1 < b.length; i += 2) {
        const code = ((b[i] & 0xFF) << 8) | (b[i + 1] & 0xFF);
        const u = map == null ? null : map.get(code);
        s.append(u != null ? u : code < 0x80 && code >= 0x20 ? String.fromCharCode(code) : '');
      }
    } else {
      for (const x of b) {
        const code = x & 0xFF;
        const u = map == null ? null : map.get(code);
        s.append(u != null ? u : Extract.Pdf.winAnsi(code));
      }
    }
    return s.toString();
  }

  static winAnsi(c) {
    if (c === 0x92) return '\'';
    if (c === 0x93 || c === 0x94) return '"';
    if (c === 0x96 || c === 0x97) return '-';
    if (c < 0x20) return '';
    return String.fromCharCode(c);
  }
};
Extract.Pdf.Frag = ExtractFrag;
;
