'use strict';
/** Faculty: 7 Professors, 1 Associate Professor and 23 Assistant Professors, with photos and service documents. */
class FacultyActivity extends Base {
  constructor() { super(); this.query = ""; }

  /** Documents every faculty member is expected to have (all types except "Other document"). */
  static $clinit() {
    FacultyActivity.REQUIRED_DOCS = Db.DOC_TYPES.length - 1;
  }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Faculty");
    this.headerColor(Ui.PRIMARY);
  }

  liveRefresh() {
    return false;
  }

  render() {
    const REQ = FacultyActivity.REQUIRED_DOCS;
    if (!Cloud.canSeeFaculty(this)) {
      Ui.toast(this, "The Faculty section is only for the HOD and Professors");
      this.finish();
      return;
    }
    if (Store.locked(this.db)) {
      this.subtitle = "Locked";
      this.headerAction(null, null);
      this.setPage(FacultyActivity.lockPage(this));
      return;
    }
    const total = this.db.num("SELECT COUNT(*) FROM staff WHERE role IN ('Professor','Associate Professor','Assistant Professor')");
    this.subtitle = total + " of 31 posts filled";
    this.headerAction("+ Add", {
      onClick: (v) => { this.add("Assistant Professor"); }
    });
    const page = Ui.v(this);
    const docCount = this.docCounts();

    // Hero: strength by cadre and overall document completion.
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.HERO, 20));
    hero.addView(Ui.tv(this, this.db.setting("dept", ""), 13, 0xD9FFFFFF, true));
    hero.addView(Ui.tv(this, "Faculty strength", 20, Color.WHITE, true));
    const ws = new Array(3).fill(null);
    for (let r = 0; r < 3; r++) {
      const n = this.db.num("SELECT COUNT(*) FROM staff WHERE role=?", Db.FACULTY_ROLES[r]);
      ws[r] = this.whiteStat(n + "/" + Db.FACULTY_STRENGTH[r], r === 0 ? "Professors" : r === 1 ? "Assoc. Prof." : "Asst. Prof.");
    }
    const s = Ui.statRow(this, ws);
    s.setBackground(Glass.frost(this, 14));
    s.setPadding(0, Ui.dp(this, 10), 0, Ui.dp(this, 10));
    hero.addView(s);
    Ui.margins(s, 0, 12, 0, 0);
    let have = 0;
    for (const v of docCount.values()) have += Math.min(v, REQ);
    const pct = total === 0 ? 0 : Math.round(100 * have / (total * REQ));
    const done = Ui.tv(this, "Documents on file: " + pct + "%  ·  " + this.db.num("SELECT COUNT(*) FROM docs") + " files", 13, Color.WHITE, true);
    hero.addView(done);
    Ui.margins(done, 0, 12, 0, 0);
    const track = Ui.h(this);
    track.setBackground(Ui.round(this, 0x33FFFFFF, 4));
    const fill = new View(this);
    fill.setBackground(Ui.round(this, Color.WHITE, 4));
    track.addView(fill, new LinearLayout.LayoutParams(0, Ui.dp(this, 6), pct));
    track.addView(new View(this), new LinearLayout.LayoutParams(0, Ui.dp(this, 6), 100 - pct));
    hero.addView(track);
    Ui.margins(track, 0, 6, 0, 0);
    page.addView(hero);

    // Search
    const search = new EditText(this);
    search.setHint("Search faculty by name or unit");
    search.setSingleLine(true);
    search.setText(this.query);
    search.setBackground(Ui.outline(this, Ui.CARD, Ui.LINE, 14));
    search.setPadding(Ui.dp(this, 16), Ui.dp(this, 12), Ui.dp(this, 16), Ui.dp(this, 12));
    search.setImeOptions(EditorInfo.IME_ACTION_SEARCH);
    page.addView(search);
    Ui.margins(search, 14, 12, 14, 0);
    const list = Ui.v(this);
    page.addView(list);
    this.fillList(list, docCount);
    search.addTextChangedListener({
      beforeTextChanged: (c, a, b, d) => {},
      onTextChanged: (c, a, b, d) => {},
      afterTextChanged: (e) => {
        this.query = e.toString().trim();
        this.fillList(list, this.docCounts());
      }
    });

    // Which documents are missing across the department (shared mode: admin only).
    const allDocs = !Cloud.active(this) || Cloud.isAdmin(this);
    const ds = Ui.card(this);
    if (allDocs) page.addView(Ui.heading(this, "Document status", Ui.PRIMARY));
    if (total === 0) ds.addView(Ui.muted(this, "Add faculty members to track their documents."));
    else for (let i = 0; i < REQ; i++) {
      const type = Db.DOC_TYPES[i];
      const n = this.db.num("SELECT COUNT(DISTINCT d.staff_id) FROM docs d JOIN staff s ON s.id=d.staff_id WHERE d.type=?", type);
      const row = Ui.v(this);
      row.setPadding(0, Ui.dp(this, 4), 0, 0);
      const top = Ui.h(this);
      top.addView(Ui.tv(this, type, 14, Ui.TEXT, false), Ui.weight(1));
      top.addView(Ui.tv(this, n + "/" + total, 13, n >= total ? Ui.GREEN : Ui.MUTED, true));
      row.addView(top);
      row.addView(Ui.bar(this, n, total, n >= total ? Ui.GREEN : Ui.PRIMARY));
      if (n < total) {
        Ui.ripple(row, Ui.alpha(Ui.PRIMARY, 0x1A));
        row.setOnClickListener({
          onClick: (v) => { this.showMissing(type); }
        });
      }
      ds.addView(row);
    }
    if (allDocs) page.addView(ds);

    // PIN
    page.addView(Ui.heading(this, "Privacy", Ui.SLATE));
    const pc = Ui.card(this);
    const pr = Ui.h(this);
    pr.addView(Ui.iconBadge(this, R.drawable.ic_lock, Ui.SLATE, 40));
    const pt = Ui.v(this);
    pt.setPadding(Ui.dp(this, 12), 0, 0, 0);
    const has = Store.hasPin(this.db);
    pt.addView(Ui.tv(this, has ? "PIN lock is on" : "PIN lock is off", 15, Ui.TEXT, true));
    pt.addView(Ui.muted(this, has ? "The faculty section locks after 5 minutes away." : "Set a PIN so only you can open faculty documents."));
    pr.addView(pt, Ui.weight(1));
    pc.addView(pr);
    if (has) {
      pc.addView(Ui.buttonRow(this,
        Ui.outlineButton(this, "Change PIN", Ui.PRIMARY, {
          onClick: (v) => { this.pinDialog(); }
        }),
        Ui.outlineButton(this, "Lock now", Ui.SLATE, {
          onClick: (v) => { Store.lock(); this.render(); }
        }),
        Ui.outlineButton(this, "Remove", Ui.RED, {
          onClick: (v) => {
            Ui.confirm(this, "Remove PIN?", "Anyone using this phone will be able to open faculty documents.", "Remove", {
              run: () => { Store.setPin(this.db, null); this.render(); }
            });
          }
        })));
    } else {
      const set = Ui.button(this, "Set a PIN", Ui.PRIMARY, {
        onClick: (v) => { this.pinDialog(); }
      });
      pc.addView(set);
      Ui.margins(set, 0, 10, 0, 0);
    }
    page.addView(pc);
    this.setPage(page);
  }

  docCounts() {
    const m = new JMap();
    for (const r of this.db.rows("SELECT staff_id, COUNT(DISTINCT type) n FROM docs WHERE type<>'Other document' GROUP BY staff_id"))
      m.put(r.get("staff_id"), Ui.toInt(r.get("n"), 0));
    return m;
  }

  fillList(list, docCount) {
    list.removeAllViews();
    const q = "%" + this.query + "%";
    for (let r = 0; r < Db.FACULTY_ROLES.length; r++) {
      const role = Db.FACULTY_ROLES[r];
      const strength = Db.FACULTY_STRENGTH[r];
      const rows = this.db.rows("SELECT s.* FROM staff s LEFT JOIN units u ON u.code=s.unit WHERE s.role=? AND (s.name LIKE ? OR s.unit LIKE ?) ORDER BY COALESCE(u.sort, 99), s.name", role, q, q);
      const all = this.db.num("SELECT COUNT(*) FROM staff WHERE role=?", role);
      if (!this.query.isEmpty() && rows.isEmpty()) continue;
      const color = Store.roleColor(role);
      list.addView(Ui.heading(this, (r === 1 ? "Associate Professor" : role + "s") + "  ·  " + all + " of " + strength, color));
      for (const s of rows) list.addView(this.personRow(s, docCount.containsKey(s.get("id")) ? docCount.get(s.get("id")) : 0, color));
      if (this.query.isEmpty() && all < strength) {
        const add = Ui.outlineButton(this, "+ Add " + role + "  (" + (strength - all) + (strength - all === 1 ? " post" : " posts") + " to fill)", color, {
          onClick: (v) => { this.add(role); }
        });
        list.addView(add);
        Ui.margins(add, 14, 6, 14, 2);
      }
    }
    if (!this.query.isEmpty() && list.getChildCount() === 0) list.addView(this.emptyNote("No faculty member matches “" + this.query + "”."));
  }

  personRow(s, docs, color) {
    const REQ = FacultyActivity.REQUIRED_DOCS;
    const card = Ui.card(this);
    card.setOrientation(LinearLayout.HORIZONTAL);
    card.setGravity(Gravity.CENTER_VERTICAL);
    card.addView(Store.avatar(this, s, 52, color));
    const t = Ui.v(this);
    t.setPadding(Ui.dp(this, 14), 0, 0, 0);
    t.addView(Ui.tv(this, s.get("name"), 16, Ui.TEXT, true));
    const ap = Approvals.pill(this, s);
    if (ap != null) {
      t.addView(ap, new LinearLayout.LayoutParams(LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT));
      Ui.margins(ap, 0, 2, 0, 2);
    }
    let sub = Db.unitName(s.get("unit"));
    if (!s.get("qualification").isEmpty()) sub = s.get("qualification") + "  ·  " + sub;
    const st = Ui.muted(this, sub);
    st.setSingleLine(true);
    st.setEllipsize(TextUtils.TruncateAt.END);
    t.addView(st);
    const prog = Ui.h(this);
    prog.setGravity(Gravity.CENTER_VERTICAL);
    const bar = Ui.bar(this, docs, REQ, docs >= REQ ? Ui.GREEN : color);
    prog.addView(bar, Ui.weight(1));
    const n = Ui.tv(this, docs + "/" + REQ + " docs", 12, docs >= REQ ? Ui.GREEN : Ui.MUTED, true);
    n.setPadding(Ui.dp(this, 8), 0, 0, 0);
    prog.addView(n);
    if (Cloud.canSeeDocs(this, Long.parseLong(s.get("id")))) t.addView(prog);
    card.addView(t, Ui.weight(1));
    Ui.ripple(card, Ui.alpha(color, 0x1A));
    card.setOnClickListener(this.opener(FacultyProfileActivity, "id", s.get("id")));
    return card;
  }

  add(role) {
    FacultyProfileActivity.editDialog(this, null, role, {
      saved: (id) => { this.open(FacultyProfileActivity, "id", String(id)); }
    });
  }

  showMissing(type) {
    const sb = new StringBuilder();
    for (const r of this.db.rows("SELECT name, role FROM staff WHERE role IN ('Professor','Associate Professor','Assistant Professor') AND id NOT IN (SELECT staff_id FROM docs WHERE type=?) ORDER BY CASE role WHEN 'Professor' THEN 0 WHEN 'Associate Professor' THEN 1 ELSE 2 END, name", type))
      sb.append("• ").append(r.get("name")).append("  (").append(r.get("role")).append(")\n");
    new AlertDialog.Builder(this).setTitle(type + " not uploaded").setMessage(sb.toString().trim()).setPositiveButton("Close", null).show();
  }

  whiteText(s, sp, bold) {
    const t = Ui.tv(this, s, sp, Color.WHITE, bold);
    t.setGravity(Gravity.CENTER);
    return t;
  }

  whiteStat(v, label) {
    const l = Ui.v(this);
    l.setGravity(Gravity.CENTER_HORIZONTAL);
    l.addView(this.whiteText(v, 22, true));
    const t = this.whiteText(label, 11, false);
    t.setTextColor(0xD9FFFFFF);
    l.addView(t);
    return l;
  }

  pinDialog() {
    const f = new Form(this);
    const a = f.text("pin", "New PIN (4 to 8 digits)", "", InputType.TYPE_CLASS_NUMBER | InputType.TYPE_NUMBER_VARIATION_PASSWORD);
    const b = f.text("pin2", "Enter it again", "", InputType.TYPE_CLASS_NUMBER | InputType.TYPE_NUMBER_VARIATION_PASSWORD);
    a.setTransformationMethod(PasswordTransformationMethod.getInstance());
    b.setTransformationMethod(PasswordTransformationMethod.getInstance());
    const note = Ui.muted(this, "Keep the PIN safe. If it is forgotten, the faculty section can only be opened again by restoring a backup made before the PIN was set, or by clearing the app's data.");
    f.view.addView(note);
    Ui.margins(note, 0, 12, 0, 0);
    Ui.formDialog(this, Store.hasPin(this.db) ? "Change PIN" : "Set PIN", f, "Save", {
      run: () => {
        const p = f.get("pin");
        if (!p.matches("[0-9]{4,8}")) { a.setError("Use 4 to 8 digits"); return false; }
        if (!p.equals(f.get("pin2"))) { b.setError("PINs do not match"); return false; }
        Store.setPin(this.db, p);
        Ui.toast(this, "PIN set");
        this.render();
        return true;
      }
    });
  }

  /** Full-page PIN entry shown instead of faculty content while locked. */
  static lockPage(a) {
    const page = Ui.v(a);
    const card = Ui.card(a);
    card.setGravity(Gravity.CENTER_HORIZONTAL);
    card.setPadding(Ui.dp(a, 24), Ui.dp(a, 28), Ui.dp(a, 24), Ui.dp(a, 24));
    card.addView(Ui.iconBadge(a, R.drawable.ic_lock, Ui.PRIMARY, 64));
    const t = Ui.tv(a, "Faculty records are locked", 18, Ui.TEXT, true);
    t.setGravity(Gravity.CENTER);
    card.addView(t);
    Ui.margins(t, 0, 14, 0, 0);
    const m = Ui.muted(a, "Enter the PIN to view photos and documents.");
    m.setGravity(Gravity.CENTER);
    card.addView(m);
    const pin = new EditText(a);
    pin.setInputType(InputType.TYPE_CLASS_NUMBER | InputType.TYPE_NUMBER_VARIATION_PASSWORD);
    pin.setTransformationMethod(PasswordTransformationMethod.getInstance());
    pin.setGravity(Gravity.CENTER);
    pin.setTextSize(24);
    pin.setLetterSpacing(0.4);
    pin.setHint("PIN");
    card.addView(pin, Ui.lp(Ui.dp(a, 200), LinearLayout.LayoutParams.WRAP_CONTENT));
    Ui.margins(pin, 0, 14, 0, 0);
    const go = {
      onClick: (v) => {
        if (Store.unlock(a.db, pin.getText().toString().trim())) a.render();
        else {
          pin.setText("");
          pin.setError("Wrong PIN");
        }
      }
    };
    pin.setImeOptions(EditorInfo.IME_ACTION_DONE);
    pin.setOnEditorActionListener({
      onEditorAction: (v, id, e) => {
        go.onClick(v);
        return true;
      }
    });
    const b = Ui.button(a, "Unlock", Ui.PRIMARY, go);
    card.addView(b, Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT));
    Ui.margins(b, 0, 14, 0, 0);
    page.addView(card);
    return page;
  }
}
;
/* ---- app/FacultyLeaveActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Faculty leave (week off, CL, COL, PL). Only faculty can open it. */
class FacultyLeaveActivity extends Base {
  constructor() { super(); this.view = 0; this.year = 0; }

  static $clinit() {
    FacultyLeaveActivity.TYPE_COLORS = [Ui.SLATE, Ui.AMBER, Ui.TEAL, Ui.PURPLE];
  }

  onCreate(b) {
    super.onCreate(b);
    this.year = Dates.today().getYear();
    this.setTitle("Faculty leave");
    this.subtitle = "Week off · CL · COL · PL";
    this.headerColor(Ui.PRIMARY_DARK);
  }

  /** HOD and Professors approve faculty leave in the shared database; anyone on a phone that isn't shared. */
  approver() {
    return !Cloud.active(this) || Cloud.isAdmin(this) || "professor" === Cloud.role(this);
  }

  render() {
    if (!Cloud.canSeeFacultyLeave(this)) {
      Ui.toast(this, "Faculty leave is only for faculty members");
      this.finish();
      return;
    }
    this.headerAction("+ Apply", {
      onClick: (v) => { this.leaveDialog(null); }
    });
    const page = Ui.v(this);
    const iso = Dates.todayIso();
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, [Ui.PRIMARY_DARK, Ui.PRIMARY], 20));
    hero.addView(Ui.statRow(this,
      this.white(String(this.db.num("SELECT COUNT(DISTINCT staff_id) FROM faculty_leaves WHERE status='Approved' AND ? BETWEEN from_date AND to_date", iso)), "On leave today"),
      this.white(String(this.db.num("SELECT COUNT(*) FROM faculty_leaves WHERE status='Applied'")), "Awaiting approval"),
      this.white(String(this.db.num("SELECT COUNT(*) FROM faculty_leaves WHERE status='Approved' AND from_date>?", iso)), "Upcoming")));
    const lock = Ui.tv(this, "🔒  Visible only to the HOD, Professors, Associate and Assistant Professors", 12, 0xE6FFFFFF, false);
    lock.setGravity(Gravity.CENTER);
    hero.addView(lock);
    Ui.margins(lock, 0, 10, 0, 0);
    page.addView(hero);

    const seg = Ui.h(this);
    seg.setBackground(Ui.round(this, 0xFFE2E8F0, 14));
    seg.setPadding(Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4));
    const labels = ["Leave register", this.year + " summary"];
    for (let i = 0; i < 2; i++) {
      const idx = i;
      const t = Ui.tv(this, labels[i], 14, i === this.view ? Ui.PRIMARY : Ui.MUTED, true);
      t.setGravity(Gravity.CENTER);
      t.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 8));
      if (i === this.view) t.setBackground(Ui.round(this, Color.WHITE, 11));
      t.setOnClickListener({
        onClick: (v) => { this.view = idx; this.render(); }
      });
      seg.addView(t, Ui.weight(1));
    }
    page.addView(seg);
    Ui.margins(seg, 12, 8, 12, 4);
    if (this.view === 0) this.register(page);
    else this.summary(page);
    this.setPage(page);
  }

  register(page) {
    const rows = this.db.rows("SELECT l.*, s.name, s.role, s.unit FROM faculty_leaves l LEFT JOIN staff s ON s.id=l.staff_id "
      + "ORDER BY CASE l.status WHEN 'Applied' THEN 0 ELSE 1 END, l.from_date DESC LIMIT 300");
    if (rows.isEmpty()) page.addView(this.emptyNote("No faculty leave recorded yet. Tap “+ Apply”."));
    for (const r of rows) {
      const st = r.get("status");
      const col = "Approved" === st ? Ui.GREEN : "Rejected" === st ? Ui.RED : Ui.ORANGE;
      const range = Dates.nice(r.get("from_date")) + (r.get("to_date").equals(r.get("from_date")) ? "" : " to " + Dates.nice(r.get("to_date")));
      const sub = r.get("type") + "  ·  " + range + "  ·  " + FacultyLeaveActivity.days(r.get("days"))
        + (Ui.nz(r.get("approved_by")).isEmpty() ? "" : "\n" + st + " by " + r.get("approved_by"))
        + (r.get("reason").isEmpty() ? "" : "\n" + r.get("reason"));
      const card = this.entryCard(st, col, Ui.nz(r.get("name")).isEmpty() ? "(removed)" : r.get("name"), sub,
        Db.shortName(Ui.nz(r.get("unit"))), {
          onClick: (v) => { this.leaveDialog(r); }
        });
      if ("Applied" === st && this.approver()) {
        const b = Ui.buttonRow(this,
          Ui.outlineButton(this, "Approve", Ui.GREEN, {
            onClick: (v) => { this.setStatus(r, "Approved"); }
          }),
          Ui.outlineButton(this, "Reject", Ui.RED, {
            onClick: (v) => { this.setStatus(r, "Rejected"); }
          }));
        card.addView(b);
        Ui.margins(b, 0, 8, 0, 0);
      }
      page.addView(card);
    }
  }

  summary(page) {
    const nav = Ui.h(this);
    nav.setPadding(Ui.dp(this, 14), Ui.dp(this, 6), Ui.dp(this, 14), 0);
    nav.addView(Ui.outlineButton(this, "‹ " + (this.year - 1), Ui.PRIMARY, {
      onClick: (v) => { this.year--; this.render(); }
    }));
    const y = Ui.tv(this, "Approved days in " + this.year, 15, Ui.TEXT, true);
    y.setGravity(Gravity.CENTER);
    nav.addView(y, Ui.weight(1));
    const nx = Ui.outlineButton(this, (this.year + 1) + " ›", Ui.PRIMARY, {
      onClick: (v) => { this.year++; this.render(); }
    });
    if (this.year >= Dates.today().getYear()) nx.setVisibility(View.INVISIBLE);
    nav.addView(nx);
    page.addView(nav);
    const y0 = this.year + "-01-01", y1 = this.year + "-12-31";
    for (let r = 0; r < Db.FACULTY_ROLES.length; r++) {
      const staff = this.db.rows("SELECT id, name, unit FROM staff WHERE role=? AND " + Approvals.APPROVED_SQL + " ORDER BY name", Db.FACULTY_ROLES[r]);
      if (staff.isEmpty()) continue;
      page.addView(Ui.heading(this, r === 1 ? "Associate Professor" : Db.FACULTY_ROLES[r] + "s", Store.roleColor(Db.FACULTY_ROLES[r])));
      const card = Ui.card(this);
      const head = Ui.h(this);
      head.addView(Ui.muted(this, "Name"), Ui.weight(2));
      for (const t of Db.FACULTY_LEAVE) {
        const h = Ui.tv(this, t, 12, Ui.MUTED, true);
        h.setGravity(Gravity.CENTER);
        head.addView(h, Ui.weight(0.8));
      }
      card.addView(head);
      for (const s of staff) {
        const row = Ui.h(this);
        row.setPadding(0, Ui.dp(this, 6), 0, Ui.dp(this, 6));
        const nm = Ui.v(this);
        nm.addView(Ui.tv(this, s.get("name"), 14, Ui.TEXT, true));
        nm.addView(Ui.muted(this, Db.shortName(s.get("unit"))));
        row.addView(nm, Ui.weight(2));
        for (let i = 0; i < Db.FACULTY_LEAVE.length; i++) {
          const d = this.db.dbl("SELECT SUM(days) FROM faculty_leaves WHERE staff_id=? AND type=? AND status='Approved' AND from_date BETWEEN ? AND ?",
            s.get("id"), Db.FACULTY_LEAVE[i], y0, y1);
          const t = Ui.tv(this, d === 0 ? "–" : FacultyLeaveActivity.days(String(d)).split(" days").join("").split(" day").join(""), 15, d === 0 ? 0xFFCBD5E1 : FacultyLeaveActivity.TYPE_COLORS[i], true);
          t.setGravity(Gravity.CENTER);
          row.addView(t, Ui.weight(0.8));
        }
        card.addView(row);
      }
      page.addView(card);
    }
  }

  static days(d) {
    let v;
    try { v = Double.parseDouble(d); } catch (e) { return d; }
    return (v === Math.floor(v) ? String(Math.trunc(v)) : String(v)) + (v === 1 ? " day" : " days");
  }

  setStatus(r, st) {
    const cv = new ContentValues();
    cv.put("status", st);
    cv.put("approved_by", Cloud.active(this) ? Cloud.prefs(this).getString("name", "") : this.db.setting("hod", ""));
    this.db.update("faculty_leaves", cv, Long.parseLong(r.get("id")));
    this.render();
  }

  leaveDialog(r) {
    const staff = this.db.rows("SELECT id, name, role FROM staff WHERE role IN ('Professor','Associate Professor','Assistant Professor') AND " + Approvals.APPROVED_SQL + " "
      + "ORDER BY CASE role WHEN 'Professor' THEN 0 WHEN 'Associate Professor' THEN 1 ELSE 2 END, name");
    if (staff.isEmpty()) {
      Ui.toast(this, "Add faculty members first");
      return;
    }
    const ids = new Array(staff.size()).fill(null), names = new Array(staff.size()).fill(null);
    for (let i = 0; i < staff.size(); i++) {
      ids[i] = staff.get(i).get("id");
      names[i] = staff.get(i).get("name");
    }
    const me = Cloud.myStaff(this) > 0 ? String(Cloud.myStaff(this)) : ids[0];
    const f = new Form(this);
    f.choice("staff_id", "Faculty member", names, ids, r == null ? me : r.get("staff_id"), null);
    f.choice("type", "Leave type", Db.FACULTY_LEAVE, Db.FACULTY_LEAVE, r == null ? "CL" : r.get("type"), null);
    f.date("from_date", "From", r == null ? Dates.todayIso() : r.get("from_date"));
    f.date("to_date", "To", r == null ? Dates.todayIso() : r.get("to_date"));
    f.check("half", "Half day", r != null && "0.5" === r.get("days"));
    f.multi("reason", "Reason / remarks", r == null ? "" : r.get("reason"));
    if (this.approver()) f.choice("status", "Status", Db.LEAVE_STATUS, Db.LEAVE_STATUS, r == null ? "Applied" : r.get("status"), null);
    if (r != null) {
      const del = Ui.outlineButton(this, "Delete this leave", Ui.RED, {
        onClick: (v) => {
          this.db.delete("faculty_leaves", Long.parseLong(r.get("id")));
          this.render();
        }
      });
      f.view.addView(del);
      Ui.margins(del, 0, 14, 0, 0);
    }
    Ui.formDialog(this, r == null ? "Apply for leave" : "Edit leave", f, "Save", {
      run: () => {
        const a = Dates.parse(f.get("from_date")), b = Dates.parse(f.get("to_date"));
        if (a == null || b == null || b.isBefore(a)) {
          Ui.toast(this, "“To” date must be on or after “From”");
          return false;
        }
        const cv = new ContentValues();
        cv.put("staff_id", f.get("staff_id"));
        cv.put("type", f.get("type"));
        cv.put("from_date", a.toString());
        cv.put("to_date", b.toString());
        cv.put("days", "1" === f.get("half") ? 0.5 : ChronoUnit.DAYS.between(a, b) + 1);
        cv.put("reason", f.get("reason"));
        const st = this.approver() ? f.get("status") : (r == null ? "Applied" : r.get("status"));
        cv.put("status", st);
        if (this.approver() && !st.equals("Applied") && (r == null || !st.equals(r.get("status"))))
          cv.put("approved_by", Cloud.active(this) ? Cloud.prefs(this).getString("name", "") : this.db.setting("hod", ""));
        if (r == null) {
          cv.put("applied", Dates.todayIso());
          this.db.insert("faculty_leaves", cv);
        } else this.db.update("faculty_leaves", cv, Long.parseLong(r.get("id")));
        this.render();
        return true;
      }
    });
  }

  white(v, label) {
    const l = Ui.v(this);
    l.setGravity(Gravity.CENTER_HORIZONTAL);
    const n = Ui.tv(this, v, 22, Color.WHITE, true);
    n.setGravity(Gravity.CENTER);
    l.addView(n);
    const t = Ui.tv(this, label, 11, 0xD9FFFFFF, false);
    t.setGravity(Gravity.CENTER);
    l.addView(t);
    return l;
  }
}
;
/* ---- app/FacultyProfileActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** One faculty member: photo, service details and the document folder. */
class FacultyProfileActivity extends Base {
  constructor() {
    super();
    this.id = 0;
    this.s = null;
    // What the pending picker or camera result is for; kept across process death.
    this.pendingType = null;
    this.pendingCapture = null;
    this.pendingReplace = -1;
  }

  static REQ_PICK_DOC = 41;
  static REQ_CAPTURE_DOC = 42;
  static REQ_PICK_PHOTO = 43;
  static REQ_CAPTURE_PHOTO = 44;

  // interface Saved { void saved(long id); }  → an object { saved: (id) => … }

  onCreate(b) {
    super.onCreate(b);
    this.id = Long.parseLong(this.getIntent().getStringExtra("id"));
    if (b != null) {
      this.pendingType = b.getString("pendingType");
      this.pendingCapture = b.getString("pendingCapture");
      this.pendingReplace = b.getLong("pendingReplace", -1);
    }
  }

  onSaveInstanceState(b) {
    super.onSaveInstanceState(b);
    b.putString("pendingType", this.pendingType);
    b.putString("pendingCapture", this.pendingCapture);
    b.putLong("pendingReplace", this.pendingReplace);
  }

  render() {
    this.s = this.db.row("SELECT * FROM staff WHERE id=?", String(this.id));
    const s = this.s;
    if (s == null || !Cloud.canSeeFaculty(this)) { this.finish(); return; }
    const color = Store.roleColor(s.get("role"));
    this.headerColor(color);
    this.setTitle(s.get("name"));
    this.subtitle = s.get("role");
    if (Store.locked(this.db)) {
      this.headerAction(null, null);
      this.setPage(FacultyActivity.lockPage(this));
      return;
    }
    this.headerAction("Edit", {
      onClick: (v) => { this.edit(); }
    });
    const page = Ui.v(this);

    // Hero with photo
    const hero = Ui.card(this);
    hero.setGravity(Gravity.CENTER_HORIZONTAL);
    hero.setBackground(Glass.hero(this, [color, Ui.mix(color, 0xFF0EA5E9, 0.45)], 20));
    hero.setPadding(Ui.dp(this, 18), Ui.dp(this, 22), Ui.dp(this, 18), Ui.dp(this, 18));
    const ph = new FrameLayout(this);
    const av = Store.avatar(this, s, 104, Ui.mix(color, 0xFFFFFFFF, 0.25));
    av.setLayoutParams(new FrameLayout.LayoutParams(Ui.dp(this, 104), Ui.dp(this, 104)));
    ph.addView(av);
    const cam = new ImageView(this);
    cam.setImageResource(R.drawable.ic_camera);
    cam.setColorFilter(color);
    cam.setBackground(Ui.round(this, Color.WHITE, 17));
    const p = Ui.dp(this, 7);
    cam.setPadding(p, p, p, p);
    const cp = new FrameLayout.LayoutParams(Ui.dp(this, 34), Ui.dp(this, 34), Gravity.END | Gravity.BOTTOM);
    ph.addView(cam, cp);
    ph.setOnClickListener({
      onClick: (v) => { this.photoOptions(); }
    });
    hero.addView(ph, Ui.lp(Ui.dp(this, 108), Ui.dp(this, 108)));
    const name = Ui.tv(this, s.get("name"), 21, Color.WHITE, true);
    name.setGravity(Gravity.CENTER);
    hero.addView(name);
    Ui.margins(name, 0, 10, 0, 0);
    const line = s.get("role") + "  ·  " + Db.unitName(s.get("unit"));
    const rl = Ui.tv(this, line, 14, 0xE6FFFFFF, false);
    rl.setGravity(Gravity.CENTER);
    hero.addView(rl);
    if (!s.get("qualification").isEmpty()) {
      const q = Ui.tv(this, s.get("qualification"), 13, 0xCCFFFFFF, false);
      q.setGravity(Gravity.CENTER);
      hero.addView(q);
    }
    const acts = [];
    if (!s.get("phone").isEmpty()) acts.add(this.heroButton("Call", {
      onClick: (v) => { this.startActivity(new Intent(Intent.ACTION_DIAL, Uri.parse("tel:" + s.get("phone")))); }
    }));
    if (!s.get("email").isEmpty()) acts.add(this.heroButton("Email", {
      onClick: (v) => {
        try { this.startActivity(new Intent(Intent.ACTION_SENDTO, Uri.parse("mailto:" + s.get("email")))); }
        catch (e) { Ui.toast(this, "No email app found"); }
      }
    }));
    acts.add(this.heroButton(s.get("photo").isEmpty() ? "Add photo" : "Photo", {
      onClick: (v) => { this.photoOptions(); }
    }));
    const ar = Ui.h(this);
    ar.setGravity(Gravity.CENTER_HORIZONTAL);
    for (const a of acts) ar.addView(a);
    hero.addView(ar);
    Ui.margins(ar, 0, 14, 0, 0);
    page.addView(hero);

    // Details
    page.addView(Ui.heading(this, "Service details", color));
    const d = Ui.card(this);
    d.addView(Ui.kv(this, "Employee / GPF / CPS no.", s.get("emp_id")));
    d.addView(Ui.kv(this, "Qualification", s.get("qualification")));
    d.addView(Ui.kv(this, "Medical council reg. no.", s.get("reg_no")));
    d.addView(Ui.kv(this, "Date of birth", s.get("dob").isEmpty() ? "" : Dates.nice(s.get("dob"))));
    d.addView(Ui.kv(this, "Joined department", s.get("doj").isEmpty() ? "" : Dates.nice(s.get("doj"))));
    d.addView(Ui.kv(this, "Phone", s.get("phone")));
    d.addView(Ui.kv(this, "Email", s.get("email")));
    d.addView(Ui.kv(this, "Address", s.get("address")));
    const ed = Ui.outlineButton(this, "Edit details", color, {
      onClick: (v) => { this.edit(); }
    });
    d.addView(ed);
    Ui.margins(ed, 0, 10, 0, 0);
    page.addView(d);

    // Documents
    if (!Cloud.canSeeDocs(this, this.id)) {
      page.addView(Ui.heading(this, "Documents", color));
      const pv = Ui.card(this);
      pv.addView(Ui.iconBadge(this, R.drawable.ic_lock, Ui.SLATE, 44));
      pv.addView(Ui.body(this, "Documents are private. Only the admin and " + s.get("name") + " can see or upload them."));
      page.addView(pv);
      this.setPage(page);
      return;
    }
    const docs = this.db.docs(this.id);
    let have = 0;
    for (let i = 0; i < FacultyActivity.REQUIRED_DOCS; i++) if (FacultyProfileActivity.count(docs, Db.DOC_TYPES[i]) > 0) have++;
    page.addView(Ui.heading(this, "Documents  ·  " + have + " of " + FacultyActivity.REQUIRED_DOCS, color));
    const hint = Ui.muted(this, (Cloud.active(this) ? "Upload a PDF or photo of each certificate and order, or scan it with the camera. Only the HOD and Professors can see these files." : "Upload a PDF or photo of each certificate and order, or scan it with the camera. Files stay on this phone and go into backups."));
    hint.setPadding(Ui.dp(this, 18), 0, Ui.dp(this, 18), Ui.dp(this, 4));
    page.addView(hint);
    const card = Ui.card(this);
    card.setPadding(Ui.dp(this, 14), Ui.dp(this, 6), Ui.dp(this, 14), Ui.dp(this, 6));
    for (let i = 0; i < Db.DOC_TYPES.length; i++) {
      const type = Db.DOC_TYPES[i];
      const mine = [];
      for (const x of docs) if (type.equals(x.get("type"))) mine.add(x);
      if (i > 0) card.addView(Ui.divider(this));
      if (mine.isEmpty()) {
        card.addView(this.docRow(type, null, false, color));
      } else if (!Db.multiDoc(type)) {
        card.addView(this.docRow(type, mine.get(0), false, color));
      } else {
        for (let k = 0; k < mine.size(); k++) card.addView(this.docRow(type, mine.get(k), k > 0, color));
        const more = Ui.tv(this, "+ Add another " + type.toLowerCase(), 13, color, true);
        more.setPadding(Ui.dp(this, 52), Ui.dp(this, 2), 0, Ui.dp(this, 10));
        more.setOnClickListener({
          onClick: (v) => { this.uploadOptions(type, -1); }
        });
        card.addView(more);
      }
    }
    page.addView(card);
    this.setPage(page);
  }

  static count(docs, type) {
    let n = 0;
    for (const d of docs) if (type.equals(d.get("type"))) n++;
    return n;
  }

  heroButton(label, l) {
    const t = Ui.tv(this, label, 13, Color.WHITE, true);
    t.setBackground(Ui.round(this, 0x33FFFFFF, 16));
    t.setPadding(Ui.dp(this, 16), Ui.dp(this, 7), Ui.dp(this, 16), Ui.dp(this, 7));
    Ui.ripple(t, 0x44FFFFFF);
    t.setOnClickListener(l);
    const lp = Ui.lp(LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(Ui.dp(this, 4), 0, Ui.dp(this, 4), 0);
    t.setLayoutParams(lp);
    return t;
  }

  docRow(type, doc, repeat, color) {
    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    row.setPadding(0, Ui.dp(this, 10), 0, Ui.dp(this, 10));
    const ok = doc != null && Store.exists(this, doc.get("file"));
    const badge = Ui.iconBadge(this, ok ? R.drawable.ic_verified : R.drawable.ic_doc, ok ? Ui.GREEN : 0xFF94A3B8, 40);
    if (repeat) badge.setVisibility(View.INVISIBLE);
    row.addView(badge);
    const t = Ui.v(this);
    t.setPadding(Ui.dp(this, 12), 0, Ui.dp(this, 8), 0);
    let title = type;
    if (doc != null && Db.multiDoc(type) && !doc.get("title").isEmpty() && !doc.get("title").equals(type)) title = doc.get("title");
    const tt = Ui.tv(this, title, 15, Ui.TEXT, true);
    tt.setMaxLines(2);
    t.addView(tt);
    let sub;
    if (doc == null) sub = "Not uploaded";
    else if (!ok) sub = "File missing, upload again";
    else sub = Store.kindLabel(doc.get("file")) + "  ·  " + Store.sizeLabel(Store.size(this, doc.get("file"))) + "  ·  " + Dates.nice(doc.get("added"));
    if (doc != null && Db.multiDoc(type) && !title.equals(type)) sub = type + "  ·  " + sub;
    t.addView(Ui.tv(this, sub, 12, doc == null ? 0xFF94A3B8 : ok ? Ui.MUTED : Ui.RED, false));
    row.addView(t, Ui.weight(1));
    const act = doc == null || !ok ? Ui.softPill(this, "Upload", color) : Ui.softPill(this, "View", Ui.GREEN);
    row.addView(act);
    Ui.ripple(row, Ui.alpha(color, 0x1A));
    const l = {
      onClick: (v) => {
        if (doc == null) this.uploadOptions(type, -1);
        else if (!Store.exists(this, doc.get("file"))) this.uploadOptions(type, Long.parseLong(doc.get("id")));
        else this.open(ViewerActivity, "file", doc.get("file"), "title", this.s.get("name") + " · " + type);
      }
    };
    row.setOnClickListener(l);
    act.setOnClickListener(l);
    if (doc != null) {
      row.setOnLongClickListener({
        onLongClick: (v) => { this.docOptions(type, doc); return true; }
      });
      const more = Ui.tv(this, "⋮", 22, Ui.MUTED, true);
      more.setPadding(Ui.dp(this, 10), 0, Ui.dp(this, 2), 0);
      more.setOnClickListener({
        onClick: (v) => { this.docOptions(type, doc); }
      });
      row.addView(more);
    }
    return row;
  }

  docOptions(type, doc) {
    const docId = Long.parseLong(doc.get("id"));
    const ok = Store.exists(this, doc.get("file"));
    const items = [];
    if (ok) { items.add("View"); items.add("Share"); items.add("Open with another app"); }
    items.add("Replace");
    if (Db.multiDoc(type)) items.add("Rename");
    items.add("Remove");
    new AlertDialog.Builder(this).setTitle(type).setItems(items.slice(), {
      onClick: (di, w) => {
        const it = items.get(w);
        const f = doc.get("file");
        if (it.equals("View")) this.open(ViewerActivity, "file", f, "title", this.s.get("name") + " · " + type);
        else if (it.equals("Share")) Store.share(this, f, this.s.get("name") + " - " + type);
        else if (it.equals("Open with another app")) Store.openWith(this, f);
        else if (it.equals("Replace")) this.uploadOptions(type, docId);
        else if (it.equals("Rename")) this.rename(doc);
        else if (it.equals("Remove")) {
          Ui.confirm(this, "Remove " + type.toLowerCase() + "?", "The file will be deleted from this phone.", "Remove", {
            run: () => { this.db.deleteDoc(docId); this.render(); }
          });
        }
      }
    }).show();
  }

  rename(doc) {
    const f = new Form(this);
    f.text("title", "Title", doc.get("title"), Form.PLAIN);
    Ui.formDialog(this, "Rename", f, "Save", {
      run: () => {
        const cv = new ContentValues();
        cv.put("title", f.get("title").isEmpty() ? doc.get("type") : f.get("title"));
        this.db.update("docs", cv, Long.parseLong(doc.get("id")));
        this.render();
        return true;
      }
    });
  }

  uploadOptions(type, replaceId) {
    new AlertDialog.Builder(this).setTitle((replaceId >= 0 ? "Replace " : "Upload ") + type.toLowerCase())
      .setItems(["Choose a PDF or image", "Scan with camera"], {
        onClick: (di, w) => {
          this.pendingType = type;
          this.pendingReplace = replaceId;
          if (w === 0) {
            Store.pick(this, ["application/pdf", "image/*"], FacultyProfileActivity.REQ_PICK_DOC);
          } else {
            this.pendingCapture = this.dir() + "/" + Store.safeName(type) + "_" + System.currentTimeMillis() + ".jpg";
            Store.capture(this, this.pendingCapture, FacultyProfileActivity.REQ_CAPTURE_DOC);
          }
        }
      }).show();
  }

  photoOptions() {
    const items = [];
    items.add("Choose from gallery");
    items.add("Take a photo");
    if (!this.s.get("photo").isEmpty()) { items.add("View photo"); items.add("Remove photo"); }
    new AlertDialog.Builder(this).setTitle("Profile photo").setItems(items.slice(), {
      onClick: (di, w) => {
        const it = items.get(w);
        if (it.startsWith("Choose")) Store.pick(this, ["image/*"], FacultyProfileActivity.REQ_PICK_PHOTO);
        else if (it.startsWith("Take")) {
          this.pendingCapture = this.dir() + "/capture_" + System.currentTimeMillis() + ".jpg";
          Store.capture(this, this.pendingCapture, FacultyProfileActivity.REQ_CAPTURE_PHOTO);
        } else if (it.startsWith("View")) Ui.showImage(this, this.db.file(this.s.get("photo")));
        else this.setPhoto(null);
      }
    }).show();
  }

  dir() {
    return "faculty/" + this.id;
  }

  setPhoto(rel) {
    const cur = this.db.row("SELECT photo FROM staff WHERE id=?", String(this.id));
    if (cur != null) this.db.forgetFile(cur.get("photo"));
    const cv = new ContentValues();
    cv.put("photo", rel == null ? "" : rel);
    this.db.update("staff", cv, this.id);
  }

  /** Records an uploaded file, replacing the earlier one if asked. */
  saveDoc(type, rel, title, replaceId) {
    const cv = new ContentValues();
    cv.put("staff_id", this.id);
    cv.put("type", type);
    cv.put("title", title);
    cv.put("file", rel);
    cv.put("mime", DocProvider.mimeOf(rel));
    cv.put("added", Dates.todayIso());
    const old = replaceId >= 0 ? this.db.row("SELECT * FROM docs WHERE id=?", String(replaceId)) : null;
    if (old != null) {
      if (!old.get("file").equals(rel)) this.db.forgetFile(old.get("file"));
      if (Db.multiDoc(type) && !old.get("title").isEmpty()) cv.put("title", old.get("title"));
      this.db.update("docs", cv, replaceId);
    } else {
      this.db.insert("docs", cv);
    }
  }

  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    const P = FacultyProfileActivity;
    try {
      if (req === P.REQ_CAPTURE_DOC || req === P.REQ_CAPTURE_PHOTO) {
        const f = this.pendingCapture == null ? null : this.db.file(this.pendingCapture);
        if (res !== RESULT_OK || f == null || !f.exists() || f.length() === 0) {
          if (f != null) f.delete();
          return;
        }
        if (req === P.REQ_CAPTURE_PHOTO) {
          const rel = Store.savePhoto(this, null, f, this.id);
          f.delete();
          this.setPhoto(rel);
        } else {
          if (!Store.shrink(f, 2400)) throw new Error("The camera did not return a picture");
          this.saveDoc(this.pendingType, this.pendingCapture, this.pendingType, this.pendingReplace);
          Ui.toast(this, this.pendingType + " saved");
        }
        this.pendingCapture = null;
        return;
      }
      if (res !== RESULT_OK || data == null || data.getData() == null) return;
      const uri = data.getData();
      if (req === P.REQ_PICK_PHOTO) {
        this.setPhoto(Store.savePhoto(this, uri, null, this.id));
      } else if (req === P.REQ_PICK_DOC && this.pendingType != null) {
        const name = Store.displayName(this, uri);
        const rel = Store.importUri(this, uri, this.dir(), this.pendingType);
        let title = this.pendingType;
        if (Db.multiDoc(this.pendingType) && !name.isEmpty()) title = name.replaceAllRx("\\.[A-Za-z0-9]{1,5}$", "");
        this.saveDoc(this.pendingType, rel, title, this.pendingReplace);
        Ui.toast(this, this.pendingType + " saved");
      }
    } catch (e) {
      Ui.toast(this, "Could not save: " + e.getMessage());
    }
  }

  edit() {
    FacultyProfileActivity.editDialog(this, this.s, this.s.get("role"), {
      saved: (x) => { this.render(); }
    });
  }

  /** Add (s == null) or edit a faculty member, with every service detail. */
  static editDialog(a, s, role, done) {
    const db = Db.get(a);
    const f = new Form(a);
    f.text("name", "Name *", s == null ? "Dr. " : s.get("name"), Form.TEXT);
    f.choice("role", "Designation", Db.FACULTY_ROLES, Db.FACULTY_ROLES, s == null ? role : s.get("role"), null);
    f.choice("unit", "Unit", StaffActivity.UNIT_LABELS, StaffActivity.UNIT_VALUES, s == null ? "M1" : s.get("unit"), null);
    f.text("qualification", "Qualification", s == null ? "MBBS, MD (General Medicine)" : s.get("qualification"), Form.PLAIN);
    f.text("emp_id", "Employee / GPF / CPS no.", s == null ? "" : s.get("emp_id"), Form.PLAIN);
    f.text("reg_no", "Medical council registration no.", s == null ? "" : s.get("reg_no"), Form.PLAIN);
    f.text("phone", "Phone", s == null ? "" : s.get("phone"), Form.PHONE);
    f.text("email", "Email", s == null ? "" : s.get("email"),
      InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);
    f.optionalDate("dob", "Date of birth", s == null ? "" : s.get("dob"));
    f.optionalDate("doj", "Date of joining the department", s == null ? "" : s.get("doj"));
    f.multi("address", "Address", s == null ? "" : s.get("address"));
    const waiting = s != null && !Ui.nz(s.get("approval")).isEmpty();
    if (waiting) StaffActivity.approvalBlock(a, f, s);
    else if (s == null && !Approvals.canApprove(a, role))
      f.view.addView(Ui.muted(a, "New faculty entries wait for approval by the HOD."), 0);
    if (s != null) {
      const del = Ui.outlineButton(a, "Remove from faculty", Ui.RED, null);
      f.view.addView(del);
      Ui.margins(del, 0, 16, 0, 0);
      del.setOnClickListener({
        onClick: (v) => {
          Ui.confirm(a, "Remove " + s.get("name") + "?", "Their photo, all uploaded documents, attendance and leave records will be deleted from this phone.", "Remove", {
            run: () => {
              db.deleteStaff(Long.parseLong(s.get("id")));
              a.finish();
            }
          });
        }
      });
    }
    Ui.formDialog(a, s == null ? "Add faculty member" : "Edit details", f, "Save", {
      run: () => {
        const name = f.get("name");
        if (name.isEmpty() || name.equals("Dr.")) {
          Ui.toast(a, "Enter a name");
          return false;
        }
        const cv = new ContentValues();
        cv.put("name", name);
        for (const k of ["role", "unit", "qualification", "emp_id", "reg_no", "phone", "email", "dob", "doj", "address"])
          cv.put(k, f.get(k));
        let sid;
        if (s == null) {
          sid = db.insert("staff", cv);
          if (Approvals.PENDING.equals(cv.getAsString("approval"))) Ui.toast(a, "Saved. Waiting for approval by the HOD");
        } else {
          sid = Long.parseLong(s.get("id"));
          Approvals.stamp(a, cv, s);
          db.update("staff", cv, sid);
          if (waiting && "1" === f.get("approve_now") && Approvals.canApprove(a, f.get("role"))) Approvals.approve(db, a, sid);
        }
        done.saved(sid);
        return true;
      }
    });
  }
}
;
