  // ---------- notice ----------

  noticeForm() {
    const form = this.form, v = FormActivity.v;
    const r = this.existing();
    this.image = v(r, "image", "");
    form.choice("category", "Type", Db.NOTICE_CATS, Db.NOTICE_CATS, v(r, "category", Db.NOTICE_CATS[0]), null);
    form.text("title", "Title *", v(r, "title", ""), Form.PLAIN);
    form.multi("body", "Details (who, when, where)", v(r, "body", ""));
    form.date("date", "Date of notice", v(r, "date", Dates.todayIso()));
    form.optionalDate("until", "Valid till (optional; long-press to clear)", v(r, "until", ""));
    form.check("pinned", "Pin to the top of the board", r != null && "1".equals(r.get("pinned")));
    this.imageBox = Ui.v(this);
    this.imageBox.setPadding(0, Ui.dp(this, 12), 0, 0);
    form.view.addView(this.imageBox);
    this.drawImage();
  }

  drawImage() {
    const imageBox = this.imageBox;
    imageBox.removeAllViews();
    if (!this.image.isEmpty()) {
      const bm = Ui.loadScaled(new File(this.getFilesDir(), this.image), 900);
      if (bm != null) {
        const iv = new ImageView(this);
        iv.setImageBitmap(bm);
        iv.setAdjustViewBounds(true);
        imageBox.addView(iv, Ui.lp(MATCH_PARENT, WRAP_CONTENT));
      }
    }
    const row = Ui.buttonRow(this,
        Ui.outlineButton(this, this.image.isEmpty() ? "Attach photo of roster / order" : "Change photo", Ui.AMBER, {
          onClick: (v) => {
            const i = new Intent(Intent.ACTION_OPEN_DOCUMENT);
            i.addCategory(Intent.CATEGORY_OPENABLE);
            i.setType("image/*");
            this.startActivityForResult(i, FormActivity.REQ_IMAGE);
          }
        }));
    if (!this.image.isEmpty()) {
      row.addView(Ui.outlineButton(this, "Remove", Ui.RED, {
        onClick: (v) => { this.image = ""; this.drawImage(); }
      }), Ui.weight(0.5));
      row.getChildAt(1).getLayoutParams().leftMargin = Ui.dp(this, 8);
      row.getChildAt(1).setLayoutParams(row.getChildAt(1).getLayoutParams());
    }
    imageBox.addView(row);
    Ui.margins(row, 0, 8, 0, 0);
  }

  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    if (req !== FormActivity.REQ_IMAGE || res !== RESULT_OK || data == null || data.getData() == null) return;
    try {
      const uri = data.getData();
      let o = new BitmapFactory.Options();
      o.inJustDecodeBounds = true;
      let inp = this.getContentResolver().openInputStream(uri);
      BitmapFactory.decodeStream(inp, null, o);
      inp.close();
      let sample = 1;
      while (Math.max(o.outWidth, o.outHeight) / (sample * 2) >= 1600) sample *= 2;
      o = new BitmapFactory.Options();
      o.inSampleSize = sample;
      inp = this.getContentResolver().openInputStream(uri);
      const bm = BitmapFactory.decodeStream(inp, null, o);
      inp.close();
      if (bm == null) throw new Error("not an image");
      const dir = new File(this.getFilesDir(), "notices");
      dir.mkdirs();
      const name = "notices/n" + System.currentTimeMillis() + ".jpg";
      const out = new FileOutputStream(new File(this.getFilesDir(), name));
      bm.compress(Bitmap.CompressFormat.JPEG, 85, out);
      out.close();
      this.image = name;
      this.drawImage();
    } catch (e) {
      Ui.toast(this, "Could not attach image: " + e.getMessage());
    }
  }

  saveNotice() {
    const form = this.form;
    if (!form.require("title", "Enter a title")) return false;
    const cv = new ContentValues();
    for (const k of ["category", "title", "body", "date", "pinned"]) cv.put(k, form.get(k));
    cv.put("until", form.get("until"));
    cv.put("image", this.image);
    if (this.id < 0) this.db.insert("notices", cv);
    else this.db.update("notices", cv, this.id);
    return true;
  }

