/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * A printed form made of coloured section bars and bordered tables (the department's discharge summary layout),
 * written both as an A4 PDF and as a Word file from the same description. "☐" and "☑" in cell text are tick boxes.
 */
class FormDoc {
  constructor() {
    this.upper = 'GOVERNMENT OF TAMIL NADU'; this.college = ''; this.address = ''; this.dept = ''; this.title = ''; this.footer = ''; this.fileBase = 'form';
    this.blocks = [];
  }

  static BOX = '☐';
  static TICK = '☑';

  static box(on, label) {
    return (on ? FormDoc.TICK : FormDoc.BOX) + ' ' + label;
  }

  /** "☑ A   ☐ B   ☐ C": the options, with the chosen ones ticked. */
  static boxes(labels, on) {
    const b = new StringBuilder();
    for (let i = 0; i < labels.length; i++) b.append(i === 0 ? '' : '   ').append(FormDoc.box(on[i], labels[i]));
    return b.toString();
  }

  block(bar, color, ...cols) {
    if (cols.length === 1 && Array.isArray(cols[0])) cols = cols[0];
    const b = new FormDoc.Block();
    b.bar = bar;
    b.barColor = color;
    b.border = color === 0 ? 0xFFB0BEC5 : color;
    b.cols = cols;
    this.blocks.push(b);
    return b;
  }

  /** A block without lines, for letter text between the tables. */
  plain(...cols) {
    if (cols.length === 1 && Array.isArray(cols[0])) cols = cols[0];
    const b = this.block(null, 0, cols);
    b.border = 0;
    return b;
  }

  static NAVY = 0xFF0D3B66;
  static AMBER = 0xFFF6A623;
  static GOLD = 0xFFF9C74F;
  static CYAN = 0xFF7FDBFF;

  // ---------- PDF ----------

  static W = 595;
  static H = 842;
  static M = 28;
  static CW = 595 - 2 * 28;
  static BOTTOM = 842 - 28 - 12;

  /** Writes files/exports/{fileBase}.pdf and returns its path under files/. */
  pdf(c) {
    const W = FormDoc.W, H = FormDoc.H;
    const rel = SummaryExport.DIR + '/' + this.fileBase + '.pdf';
    const f = new File(c.getFilesDir(), rel);
    f.getParentFile().mkdirs();
    let logo = null;
    try {
      logo = ShimE.logo();   // BitmapFactory.decodeResource(c.getResources(), R.drawable.dept_logo), ready now
    } catch (ignored) {
    }
    // first pass on a throwaway canvas (the phone records android.graphics.Picture) to count the pages for "Page n of N"
    const scratchBm = Bitmap.createBitmap(W, H);
    const total = this.draw(logo, 0, {
      start: (n) => { scratchBm.eraseColor(0); return new Canvas(scratchBm); },
      end: () => {}
    });
    const doc = new PdfDocument();
    try {
      let page = null;
      this.draw(logo, total, {
        start: (n) => {
          page = doc.startPage(new PdfDocument.PageInfo.Builder(W, H, n).create());
          return page.getCanvas();
        },
        end: () => { doc.finishPage(page); }
      });
      const out = new FileOutputStream(f);
      try {
        doc.writeTo(out);
      } finally {
        out.close();
      }
    } finally {
      doc.close();
    }
    scratchBm.canvas.width = 1;
    return rel;
  }

  static paint(size, bold, color) {
    const p = new Paint(Paint.ANTI_ALIAS_FLAG);
    p.setTextSize(size);
    p.setColor(color);
    p.setTypeface(Typeface.create(Typeface.SANS_SERIF, bold ? Typeface.BOLD : Typeface.NORMAL));
    return p;
  }

  draw(logo, total, pages) {
    const M = FormDoc.M, CW = FormDoc.CW, H = FormDoc.H;
    const pen = new FormDoc.Pen(this, pages, total);
    this.banner(pen, logo);
    for (const b of this.blocks) {
      let first = b.rows.isEmpty() ? 0 : this.rowHeight(b, b.rows.get(0));
      const barH = b.bar == null ? 0 : 14;
      if (b.pageBefore && pen.y > M + 1) pen.need(H);
      if (b.keep) for (let i = 1; i < b.rows.size(); i++) first += this.rowHeight(b, b.rows.get(i));
      pen.need(barH + first + 3);
      pen.y += 3;
      if (b.bar != null) {
        const fill = new Paint();
        fill.setColor(b.barColor);
        pen.cv.drawRect(M, pen.y, M + CW, pen.y + barH, fill);
        pen.cv.drawText(b.bar, M + 5, pen.y + 10, FormDoc.paint(8.5, true, 0xFFFFFFFF));
        pen.y += barH;
      }
      for (const r of b.rows) {
        const h = this.rowHeight(b, r);
        pen.need(h);
        this.drawRow(pen.cv, b, r, pen.y, h);
        pen.y += h;
      }
    }
    pen.end();
    return pen.n;
  }

  banner(pen, logo) {
    const M = FormDoc.M, CW = FormDoc.CW;
    const cv = pen.cv;
    const top = pen.y, h = 64;
    const bg = new Paint();
    bg.setColor(FormDoc.NAVY);
    cv.drawRect(M, top, M + CW, top + h, bg);
    if (logo != null) {
      const white = new Paint(Paint.ANTI_ALIAS_FLAG);
      white.setColor(0xFFFFFFFF);
      cv.drawCircle(M + 34, top + h / 2, 26, white);
      cv.drawBitmap(logo, null, new RectF(M + 12, top + h / 2 - 22, M + 56, top + h / 2 + 22), new Paint(Paint.FILTER_BITMAP_FLAG));
    }
    const cx = M + CW / 2;
    const a = FormDoc.paint(6.5, true, FormDoc.GOLD), b = FormDoc.paint(13, true, 0xFFFFFFFF), c = FormDoc.paint(6.5, false, 0xFFE2E8F0), d = FormDoc.paint(9, true, FormDoc.CYAN);
    for (const p of [a, b, c, d]) p.setTextAlign(Paint.Align.CENTER);
    a.setLetterSpacing(0.15);
    d.setLetterSpacing(0.08);
    cv.drawText(this.upper, cx, top + 12, a);
    cv.drawText(this.college.toUpperCase(), cx, top + 29, b);
    cv.drawText(this.address, cx, top + 40, c);
    cv.drawText(this.dept.toUpperCase(), cx, top + 55, d);
    const am = new Paint();
    am.setColor(FormDoc.AMBER);
    cv.drawRect(M, top + h, M + CW, top + h + 20, am);
    const t = FormDoc.paint(12, true, FormDoc.NAVY);
    t.setTextAlign(Paint.Align.CENTER);
    t.setLetterSpacing(0.3);
    cv.drawText(this.title, cx, top + h + 14.5, t);
    pen.y = top + h + 22;
  }

  xs(b, r) {
    const M = FormDoc.M, CW = FormDoc.CW;
    const out = new Array(r.cells.size() + 1).fill(0);
    out[0] = M;
    let col = 0;
    for (let i = 0; i < r.cells.size(); i++) {
      let w = 0;
      for (let k = 0; k < r.cells.get(i)._span && col < b.cols.length; k++) w += b.cols[col++];
      out[i + 1] = out[i] + w * CW;
    }
    out[out.length - 1] = M + CW;
    return out;
  }

  static lineH(c) { return c._size * 1.27; }

  rowHeight(b, r) {
    const x = this.xs(b, r);
    let h = r.minH;
    for (let i = 0; i < r.cells.size(); i++) {
      const c = r.cells.get(i);
      h = Math.max(h, FormDoc.lines(c, FormDoc.paint(c._size, c.bold, c._color), x[i + 1] - x[i] - 8).size() * FormDoc.lineH(c) + 5);
    }
    return h;
  }

  drawRow(cv, b, r, y, h) {
    const x = this.xs(b, r);
    const line = new Paint();
    line.setStyle(Paint.Style.STROKE);
    line.setStrokeWidth(0.6);
    line.setColor(b.border);
    for (let i = 0; i < r.cells.size(); i++) {
      const c = r.cells.get(i);
      if (c._fill !== 0) {
        const f = new Paint();
        f.setColor(c._fill);
        cv.drawRect(x[i], y, x[i + 1], y + h, f);
      }
      if (b.border !== 0) cv.drawRect(x[i], y, x[i + 1], y + h, line);
      const p = FormDoc.paint(c._size, c.bold, c._color);
      const ls = FormDoc.lines(c, p, x[i + 1] - x[i] - 8);
      let ty = c._bottom ? y + h - ls.size() * FormDoc.lineH(c) - 2 + c._size : y + (h - ls.size() * FormDoc.lineH(c)) / 2 + c._size;
      for (const l of ls) {
        const tx = c._center ? (x[i] + x[i + 1]) / 2 - FormDoc.width(l, p) / 2 : x[i] + 4;
        FormDoc.text(cv, l, tx, ty, p);
        ty += FormDoc.lineH(c);
      }
    }
  }

  /** Width of text, tick boxes counted as squares. */
  static width(s, p) {
    let w = 0;
    let start = 0;
    for (let i = 0; i < s.length; i++) {
      const ch = s.charAt(i);
      if (ch === FormDoc.BOX || ch === FormDoc.TICK) {
        w += p.measureText(s.substring(start, i)) + p.getTextSize() * 0.95;
        start = i + 1;
      }
    }
    return w + p.measureText(s.substring(start, s.length));
  }

  /** Draws text, drawing ☐ and ☑ as squares (with a tick) so they look the same on every phone. */
  static text(cv, s, x, y, p) {
    let start = 0;
    const sz = p.getTextSize();
    for (let i = 0; i <= s.length; i++) {
      const ch = i < s.length ? s.charAt(i) : '\u0000';
      if (i === s.length || ch === FormDoc.BOX || ch === FormDoc.TICK) {
        if (i > start) {
          cv.drawText(s, start, i, x, y, p);
          x += p.measureText(s.substring(start, i));
        }
        if (i === s.length) break;
        const bs = sz * 0.72, top = y - bs;
        const q = new Paint(Paint.ANTI_ALIAS_FLAG);
        q.setStyle(Paint.Style.STROKE);
        q.setStrokeWidth(0.7);
        q.setColor(0xFF334155);
        cv.drawRect(x + 0.5, top, x + 0.5 + bs, top + bs, q);
        if (ch === FormDoc.TICK) {
          q.setStrokeWidth(1.3);
          q.setColor(0xFF047857);
          const t = new Path();
          t.moveTo(x + 0.5 + bs * 0.18, top + bs * 0.52);
          t.lineTo(x + 0.5 + bs * 0.42, top + bs * 0.8);
          t.lineTo(x + 0.5 + bs * 0.95, top - bs * 0.05);
          cv.drawPath(t, q);
        }
        x += sz * 0.95;
        start = i + 1;
      }
    }
  }

  static lines(c, p, w) {
    const out = [];
    for (const para of c.text.jsplit('\n', -1)) {
      const cur = new StringBuilder();
      for (const word of para.jsplit(' ', -1)) {
        const t = cur.length() === 0 ? word : cur + ' ' + word;
        if (FormDoc.width(t, p) <= w || cur.length() === 0) {
          cur.setLength(0);
          cur.append(t);
        } else {
          out.add(cur.toString());
          cur.setLength(0);
          cur.append(word);
        }
      }
      out.add(cur.toString());
    }
    while (out.size() > 1 && out.get(out.size() - 1).trim().isEmpty()) out.removeAt(out.size() - 1);
    return out;
  }

  // ---------- Word ----------

  static TW = 10770;   // text width in twips: A4 11906 minus 2 x 568 margins

  /** Writes files/exports/{fileBase}.docx and returns its path under files/. */
  docx(c) {
    const rel = SummaryExport.DIR + '/' + this.fileBase + '.docx';
    const f = new File(c.getFilesDir(), rel);
    f.getParentFile().mkdirs();
    const logo = SummaryExport.logoPng(c, 200);
    const z = new ZipOutputStream(new FileOutputStream(f));
    try {
      SummaryExport.put(z, '[Content_Types].xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          + '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
          + '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
          + '<Default Extension="xml" ContentType="application/xml"/>'
          + '<Default Extension="png" ContentType="image/png"/>'
          + '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
          + '<Override PartName="/word/footer1.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml"/>'
          + '</Types>');
      SummaryExport.put(z, '_rels/.rels', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          + '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
          + '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>'
          + '</Relationships>');
      SummaryExport.put(z, 'word/_rels/document.xml.rels', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          + '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
          + '<Relationship Id="rIdFoot" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/footer" Target="footer1.xml"/>'
          + (logo == null ? '' : '<Relationship Id="rIdLogo" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/logo.png"/>')
          + '</Relationships>');
      if (logo != null) {
        z.putNextEntry(new ZipEntry('word/media/logo.png'));
        z.write(logo);
        z.closeEntry();
      }
      SummaryExport.put(z, 'word/footer1.xml', this.footerXml());
      SummaryExport.put(z, 'word/document.xml', this.documentXml(logo != null));
    } finally {
      z.close();
    }
    return rel;
  }

  static hex(c) {
    return jfmt('%06X', c & 0xFFFFFF);
  }

  /** Runs for one line of text: tick boxes in a symbol font, the rest as given. */
  static runs(s, bold, size, color) {
    const b = new StringBuilder();
    const rpr = (bold ? '<w:b/>' : '') + '<w:color w:val="' + FormDoc.hex(color) + '"/><w:sz w:val="' + Math.round(size * 2) + '"/>';
    let start = 0;
    for (let i = 0; i <= s.length; i++) {
      const ch = i < s.length ? s.charAt(i) : '\u0000';
      if (i === s.length || ch === FormDoc.BOX || ch === FormDoc.TICK) {
        if (i > start) b.append('<w:r><w:rPr>').append(rpr).append('</w:rPr><w:t xml:space="preserve">')
            .append(SummaryExport.esc(s.substring(start, i))).append('</w:t></w:r>');
        if (i === s.length) break;
        b.append('<w:r><w:rPr><w:rFonts w:ascii="Segoe UI Symbol" w:hAnsi="Segoe UI Symbol" w:cs="Segoe UI Symbol"/>')
            .append('<w:color w:val="').append(ch === FormDoc.TICK ? '047857' : '334155').append('"/><w:sz w:val="').append(Math.round(size * 2)).append('"/></w:rPr><w:t>')
            .append(ch).append('</w:t></w:r>');
        start = i + 1;
      }
    }
    return b.toString();
  }

  static para(text, bold, size, color, center) {
    const b = new StringBuilder();
    for (const l of text.jsplit('\n', -1)) {
      b.append('<w:p><w:pPr><w:spacing w:before="0" w:after="0" w:line="240" w:lineRule="auto"/>')
          .append(center ? '<w:jc w:val="center"/>' : '').append('</w:pPr>').append(FormDoc.runs(l, bold, size, color)).append('</w:p>');
    }
    return b.toString();
  }

  static tblStart(grid, border) {
    const b = new StringBuilder('<w:tbl><w:tblPr><w:tblW w:w="' + FormDoc.TW + '" w:type="dxa"/><w:tblLayout w:type="fixed"/><w:tblBorders>');
    for (const side of ['top', 'left', 'bottom', 'right', 'insideH', 'insideV'])
      b.append('<w:').append(side).append(border === 0 ? ' w:val="nil"/>' : ' w:val="single" w:sz="4" w:color="' + FormDoc.hex(border) + '"/>');
    b.append('</w:tblBorders><w:tblCellMar><w:top w:w="20" w:type="dxa"/><w:left w:w="70" w:type="dxa"/>')
        .append('<w:bottom w:w="20" w:type="dxa"/><w:right w:w="70" w:type="dxa"/></w:tblCellMar></w:tblPr><w:tblGrid>');
    for (const g of grid) b.append('<w:gridCol w:w="').append(g).append('"/>');
    return b.append('</w:tblGrid>').toString();
  }

  static cell(w, span, fill, content, bottom) {
    bottom = !!bottom;
    return '<w:tc><w:tcPr><w:tcW w:w="' + w + '" w:type="dxa"/>' + (span > 1 ? '<w:gridSpan w:val="' + span + '"/>' : '')
        + (fill !== 0 ? '<w:shd w:val="clear" w:color="auto" w:fill="' + FormDoc.hex(fill) + '"/>' : '')
        + '<w:vAlign w:val="' + (bottom ? 'bottom' : 'center') + '"/></w:tcPr>' + content + '</w:tc>';
  }

  documentXml(logo) {
    const TW = FormDoc.TW, NAVY = FormDoc.NAVY, AMBER = FormDoc.AMBER;
    const b = new StringBuilder('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        + '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"'
        + ' xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"'
        + ' xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing"'
        + ' xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"'
        + ' xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><w:body>');
    // letterhead: logo | name of the hospital | (balance)
    const side = 1300;
    b.append(FormDoc.tblStart([side, TW - 2 * side, side], NAVY)).append('<w:tr>');
    let img = '';
    if (logo) {
      const emu = 640000;
      img = '<w:p><w:pPr><w:jc w:val="center"/><w:spacing w:after="0"/></w:pPr><w:r><w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0">'
          + '<wp:extent cx="' + emu + '" cy="' + emu + '"/><wp:docPr id="1" name="Logo"/>'
          + '<a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic>'
          + '<pic:nvPicPr><pic:cNvPr id="1" name="logo.png"/><pic:cNvPicPr/></pic:nvPicPr>'
          + '<pic:blipFill><a:blip r:embed="rIdLogo"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill>'
          + '<pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="' + emu + '" cy="' + emu + '"/></a:xfrm>'
          + '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>';
    }
    b.append(FormDoc.cell(side, 1, NAVY, img.isEmpty() ? '<w:p/>' : img));
    b.append(FormDoc.cell(TW - 2 * side, 1, NAVY, FormDoc.para(this.upper, true, 6.5, FormDoc.GOLD, true) + FormDoc.para(this.college.toUpperCase(), true, 14, 0xFFFFFFFF, true)
        + FormDoc.para(this.address, false, 7, 0xFFE2E8F0, true) + FormDoc.para(this.dept.toUpperCase(), true, 9.5, FormDoc.CYAN, true)));
    b.append(FormDoc.cell(side, 1, NAVY, '<w:p/>')).append('</w:tr></w:tbl>');
    b.append(FormDoc.tblStart([TW], AMBER)).append('<w:tr>').append(FormDoc.cell(TW, 1, AMBER,
        '<w:p><w:pPr><w:jc w:val="center"/><w:spacing w:after="0"/></w:pPr><w:r><w:rPr><w:b/><w:color w:val="' + FormDoc.hex(NAVY)
            + '"/><w:spacing w:val="60"/><w:sz w:val="26"/></w:rPr><w:t>' + SummaryExport.esc(this.title) + '</w:t></w:r></w:p>')).append('</w:tr></w:tbl>');

    for (const blk of this.blocks) {
      b.append(blk.pageBefore ? '<w:p><w:pPr><w:spacing w:before="0" w:after="0"/></w:pPr><w:r><w:br w:type="page"/></w:r></w:p>'
          : '<w:p><w:pPr><w:spacing w:before="0" w:after="0" w:line="120" w:lineRule="exact"/></w:pPr></w:p>');
      const grid = new Array(blk.cols.length).fill(0);
      let used = 0;
      for (let i = 0; i < grid.length; i++) {
        grid[i] = i === grid.length - 1 ? TW - used : Math.round(blk.cols[i] * TW);
        used += grid[i];
      }
      b.append(FormDoc.tblStart(grid, blk.border));
      if (blk.bar != null) b.append('<w:tr><w:trPr><w:cantSplit/></w:trPr>')
          .append(FormDoc.cell(TW, grid.length, blk.barColor, FormDoc.para(blk.bar, true, 9, 0xFFFFFFFF, false))).append('</w:tr>');
      for (const r of blk.rows) {
        b.append('<w:tr><w:trPr><w:cantSplit/><w:trHeight w:val="').append(Math.round(r.minH * 20)).append('" w:hRule="atLeast"/></w:trPr>');
        let col = 0;
        for (const c of r.cells) {
          let w = 0;
          for (let k = 0; k < c._span && col < grid.length; k++) w += grid[col++];
          b.append(FormDoc.cell(w, c._span, c._fill, FormDoc.para(c.text, c.bold, c._size + 0.5, c._color, c._center), c._bottom));
        }
        b.append('</w:tr>');
      }
      b.append('</w:tbl>');
    }
    b.append('<w:sectPr><w:footerReference w:type="default" r:id="rIdFoot"/><w:pgSz w:w="11906" w:h="16838"/>')
        .append('<w:pgMar w:top="560" w:right="568" w:bottom="560" w:left="568" w:header="300" w:footer="300" w:gutter="0"/></w:sectPr>');
    return b.append('</w:body></w:document>').toString();
  }

  footerXml() {
    const r = '<w:rPr><w:color w:val="64748B"/><w:sz w:val="13"/></w:rPr>';
    return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        + '<w:ftr xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:p><w:pPr><w:jc w:val="center"/></w:pPr>'
        + '<w:r>' + r + '<w:t xml:space="preserve">' + SummaryExport.esc(this.footer) + '  •  Page </w:t></w:r>'
        + '<w:r>' + r + '<w:fldChar w:fldCharType="begin"/></w:r><w:r>' + r + '<w:instrText xml:space="preserve"> PAGE </w:instrText></w:r>'
        + '<w:r>' + r + '<w:fldChar w:fldCharType="separate"/></w:r><w:r>' + r + '<w:t>1</w:t></w:r><w:r>' + r + '<w:fldChar w:fldCharType="end"/></w:r>'
        + '<w:r>' + r + '<w:t xml:space="preserve"> of </w:t></w:r>'
        + '<w:r>' + r + '<w:fldChar w:fldCharType="begin"/></w:r><w:r>' + r + '<w:instrText xml:space="preserve"> NUMPAGES </w:instrText></w:r>'
        + '<w:r>' + r + '<w:fldChar w:fldCharType="separate"/></w:r><w:r>' + r + '<w:t>2</w:t></w:r><w:r>' + r + '<w:fldChar w:fldCharType="end"/></w:r>'
        + '</w:p></w:ftr>';
  }
}

/** One table cell. Fields carry a "_" (fill, color, span, size, center, bottom are also the builder methods). */
FormDoc.Cell = class {
  constructor(t) {
    this.text = t == null ? '' : String(t);
    this.bold = false;
    this._fill = 0; this._color = 0xFF0F172A; this._span = 1;
    this._size = 8;
    this._center = false; this._bottom = false;
  }
  b() { this.bold = true; return this; }
  fill(c) { this._fill = c; return this; }
  color(c) { this._color = c; return this; }
  span(n) { this._span = n; return this; }
  size(s) { this._size = s; return this; }
  center() { this._center = true; return this; }
  bottom() { this._bottom = true; return this; }
};

FormDoc.Row = class {
  constructor() { this.cells = []; this.minH = 15; }
};

FormDoc.Block = class {
  constructor() {
    this.bar = null;
    this.barColor = 0; this.border = 0xFFB0BEC5;
    this.pageBefore = false; this.keep = false;
    this.cols = null;
    this.rows = [];
  }
  row(minH, ...cells) {
    if (cells.length === 1 && Array.isArray(cells[0])) cells = cells[0];
    const r = new FormDoc.Row();
    r.minH = minH;
    for (const c of cells) r.cells.add(c);
    this.rows.add(r);
    return r;
  }
};

/** Page handling (an inner class on the phone): the outer FormDoc is passed in. */
FormDoc.Pen = class {
  constructor(outer, pages, total) {
    this.outer = outer;
    this.pages = pages;
    this.total = total;
    this.cv = null;
    this.y = 0;
    this.n = 0;
    this.next();
  }
  next() {
    this.n++;
    this.cv = this.pages.start(this.n);
    this.y = FormDoc.M;
  }
  need(h) {
    if (this.y + h <= FormDoc.BOTTOM) return;
    this.end();
    this.next();
  }
  end() {
    const f = FormDoc.paint(6.5, false, 0xFF64748B);
    f.setTextAlign(Paint.Align.CENTER);
    this.cv.drawText(this.outer.footer + '  •  Page ' + this.n + (this.total > 0 ? ' of ' + this.total : ''), FormDoc.W / 2, FormDoc.H - FormDoc.M + 4, f);
    this.pages.end();
  }
};
;
