/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Imaging (7.84): each patient's chest X-rays and CT scans (brain, chest, abdomen), with photos of the films and the
 * radiologist's report (photo, PDF or typed impression). Shared with every member through the files folder imaging/.
 */
class Imaging {
  constructor() {}

  static TABLE = "imaging";
  static FILES = "imaging_files";
  static DIR = "imaging";
  static FILM = "film";
  static REPORT = "report";
  static COLOR = 0xFF0E7490;
  static KINDS = ["Chest X-ray", "CT brain", "CT chest", "CT abdomen", "Other"];
  static KIND_COLORS = [0xFF0284C7, 0xFF7C3AED, 0xFF0D9488, 0xFFC2410C, 0xFF475569];

  static color(kind) {
    const i = Imaging.KINDS.indexOf(kind);
    return Imaging.KIND_COLORS[i < 0 ? Imaging.KINDS.length - 1 : i];
  }

  static label(s) {
    const k = Ui.nz(s.get("kind"));
    return "Other" === k && !Ui.nz(s.get("other")).isEmpty() ? s.get("other") : k;
  }

  static studies(db, pid) {
    return db.rows("SELECT * FROM " + Imaging.TABLE + " WHERE patient_id=? ORDER BY date DESC, id DESC", String(pid));
  }

  static files(db, studyId, part) {
    return db.rows("SELECT * FROM " + Imaging.FILES + " WHERE study_id=? AND part=? ORDER BY id", studyId, part);
  }

  static addFile(db, studyId, part, rel) {
    const cv = new ContentValues();
    cv.put("study_id", studyId);
    cv.put("part", part);
    cv.put("file", rel);
    db.insert(Imaging.FILES, cv);
  }

  static removeFile(db, fileId) {
    const f = db.row("SELECT file FROM " + Imaging.FILES + " WHERE id=?", fileId);
    db.delete(Imaging.FILES, Long.parseLong(fileId));
    if (f != null) db.file(f.get("file")).delete();
  }

  static delete(db, studyId) {
    for (const f of db.rows("SELECT id FROM " + Imaging.FILES + " WHERE study_id=?", String(studyId))) Imaging.removeFile(db, f.get("id"));
    db.delete(Imaging.TABLE, studyId);
  }

  /** The patient page section: each study with its film thumbnails and report; tap to open. */
  static section(a, db, pid) {
    const box = Ui.v(a);
    box.addView(Ui.heading(a, "X-ray and CT", Imaging.COLOR));
    const st = Imaging.studies(db, pid);
    const card = Ui.card(a);
    if (st.isEmpty()) card.addView(Ui.muted(a, "No imaging yet. Add the chest X-ray or CT film photos and the report."));
    for (const s of st) {
      const col = Imaging.color(s.get("kind"));
      const row = Ui.v(a);
      row.setPadding(0, Ui.dp(a, 6), 0, Ui.dp(a, 6));
      const top = Ui.h(a);
      top.setGravity(Gravity.CENTER_VERTICAL);
      top.addView(Ui.softPill(a, Imaging.label(s), col));
      const films = Imaging.files(db, s.get("id"), Imaging.FILM).size(), reps = Imaging.files(db, s.get("id"), Imaging.REPORT).size();
      const meta = Ui.tv(a, "  " + Dates.nice(s.get("date")) + "  ·  " + films + (films === 1 ? " film" : " films")
        + (reps > 0 || !Ui.nz(s.get("impression")).isEmpty() ? "  ·  report ✓" : "  ·  no report yet"), 12, Ui.MUTED, false);
      top.addView(meta, Ui.weight(1));
      row.addView(top);
      if (!Ui.nz(s.get("impression")).isEmpty()) {
        const imp = Ui.tv(a, Ui.nz(s.get("impression")), 13, Ui.TEXT, false);
        imp.setMaxLines(3);
        row.addView(imp);
        Ui.margins(imp, 0, 4, 0, 0);
      }
      const th = Imaging.thumbs(a, db, s.get("id"), 64, false);
      if (th != null) {
        row.addView(th);
        Ui.margins(th, 0, 6, 0, 0);
      }
      Ui.ripple(row, Ui.alpha(col, 0x22));
      row.setOnClickListener(a.opener(ImagingActivity, "patient", String(pid), "id", s.get("id")));
      card.addView(row);
    }
    const add = Ui.outlineButton(a, "+ Add X-ray / CT films and report", Imaging.COLOR, a.opener(ImagingActivity, "patient", String(pid)));
    card.addView(add);
    Ui.margins(add, 0, 8, 0, 0);
    box.addView(card);
    return box;
  }

  /** A row of small pictures (films first, then report pages); null when there are none. */
  static thumbs(a, db, studyId, sizeDp, reportsToo) {
    const r = Ui.h(a);
    let n = 0;
    for (const part of reportsToo ? [Imaging.FILM, Imaging.REPORT] : [Imaging.FILM]) {
      for (const f of Imaging.files(db, studyId, part)) {
        const rel = f.get("file");
        const v = Imaging.thumb(a, db, rel, sizeDp, Imaging.REPORT === part);
        v.setOnClickListener({ onClick: (x) => { Imaging.open(a, db, rel); } });
        r.addView(v);
        Ui.margins(v, 0, 0, 6, 0);
        n++;
      }
    }
    if (n === 0) return null;
    const hs = new HorizontalScrollView(a);
    hs.setHorizontalScrollBarEnabled(false);
    hs.addView(r);
    return hs;
  }

  static thumb(a, db, rel, sizeDp, report) {
    const f = db.file(rel);
    const px = Ui.dp(a, sizeDp);
    if (f.exists() && Store.isImage(rel)) {
      const iv = new ImageView(a);
      iv.setScaleType(ImageView.ScaleType.CENTER_CROP);
      iv.setImageBitmap(Ui.loadScaled(f, 300));
      iv.setBackgroundColor(Color.BLACK);
      iv.setLayoutParams(new LinearLayoutParams(px, px));
      return iv;
    }
    const t = Ui.tv(a, !f.exists() ? "⏳" : report ? "📄 PDF" : "📄", 12, Ui.TEXT, true);
    t.setGravity(Gravity.CENTER);
    t.setBackground(Ui.round(a, Ui.alpha(Imaging.COLOR, 0x22), 8));
    t.setLayoutParams(new LinearLayoutParams(px, px));
    return t;
  }

  static open(a, db, rel) {
    if (!db.file(rel).exists()) {
      Ui.toast(a, "Still downloading. Try again in a moment.");
      Sync.kick(a);
      return;
    }
    a.open(ViewerActivity, "file", rel, "title", "Imaging");
  }
}
;
/* ---- app/ImagingActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** One X-ray or CT study of a patient: the films (camera or gallery) and the report (photo, PDF or typed impression). */
class ImagingActivity extends Base {
  constructor() { super(); this.pid = 0; this.id = -1; this.form = null; this.pendingCamera = null; this.pendingPart = null; }

  static REQ_CAMERA = 71;
  static REQ_PICK = 72;

  onCreate(b) {
    super.onCreate(b);
    this.pid = Long.parseLong(this.getIntent().getStringExtra("patient"));
    const s = this.getIntent().getStringExtra("id");
    if (s != null) this.id = Long.parseLong(s);
    if (b != null) {
      this.id = b.getLong("id", this.id);
      this.pendingCamera = b.getString("camera");
      this.pendingPart = b.getString("part");
    }
    const p = this.db.row("SELECT name FROM patients WHERE id=?", String(this.pid));
    this.setTitle(this.id >= 0 ? "X-ray / CT" : "Add X-ray / CT");
    this.subtitle = p == null ? "" : p.get("name");
    this.headerColor(Imaging.COLOR);
    this.headerAction("Save", { onClick: (v) => { this.save(true); } });
  }

  onSaveInstanceState(out) {
    super.onSaveInstanceState(out);
    out.putLong("id", this.id);
    if (this.pendingCamera != null) out.putString("camera", this.pendingCamera);
    if (this.pendingPart != null) out.putString("part", this.pendingPart);
  }

  liveRefresh() {
    return false;
  }

  canChange() {
    const p = this.db.row("SELECT * FROM patients WHERE id=?", String(this.pid));
    return p != null && CaseSheet.canEdit(this, this.db, p);
  }

  render() {
    const db = this.db;
    const v = ImagingActivity.v;
    const r = this.id >= 0 ? db.row("SELECT * FROM " + Imaging.TABLE + " WHERE id=?", String(this.id)) : null;
    const edit = this.canChange();
    const page = Ui.v(this);
    const form0 = this.form;
    const keepKind = form0 != null ? form0.get("kind") : null, keepDate = form0 != null ? form0.get("date") : null,
      keepOther = form0 != null ? form0.get("other") : null, keepImp = form0 != null ? form0.get("impression") : null;
    this.form = new Form(this);
    this.form.choice("kind", "Study", Imaging.KINDS, Imaging.KINDS, keepKind != null ? keepKind : v(r, "kind", Imaging.KINDS[0]), {
      changed: (val) => { this.form.show("other", "Other" === val); }
    });
    this.form.text("other", "Which study (e.g. USG abdomen, MRI brain, CT KUB)", keepOther != null ? keepOther : v(r, "other", ""), Form.PLAIN);
    this.form.show("other", "Other" === this.form.get("kind"));
    this.form.date("date", "Date of the study", keepDate != null ? keepDate : v(r, "date", Dates.todayIso()));
    this.form.multi("impression", "Report impression (type the radiologist's impression, optional)", keepImp != null ? keepImp : v(r, "impression", ""));
    const fc = Ui.card(this);
    fc.addView(this.form.view);
    page.addView(fc);

    page.addView(this.part(Imaging.FILM, "🎞 Films", "Photograph the film against a light box or window, or the screen. Several films can be added.", edit));
    page.addView(this.part(Imaging.REPORT, "📄 Report", "Photograph the printed report, or pick the report PDF.", edit));
    if (r != null) page.addView(Ui.muted(this, "  Added by " + Ui.nz(r.get("by_name")) + "  ·  " + Chat.when(r.get("time"))));
    if (!edit) page.addView(Ui.muted(this, "  View only: the patient's unit can add or change imaging."));
    else if (this.id >= 0) {
      const del = Ui.outlineButton(this, "Delete this study", Ui.RED, {
        onClick: (x) => {
          Ui.confirm(this, "Delete this study?", "The films and the report are removed for everyone.", "Delete", {
            run: () => {
              Imaging.delete(db, this.id);
              this.finish();
            }
          });
        }
      });
      const w = Ui.v(this);
      w.setPadding(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12), 0);
      w.addView(del);
      page.addView(w);
    }
    this.setPage(page);
  }

  part(part, title, hint, edit) {
    const db = this.db;
    const c = Ui.card(this);
    const fs = this.id >= 0 ? Imaging.files(db, String(this.id), part) : [];
    c.addView(Ui.title(this, title + (fs.isEmpty() ? "" : "  ·  " + fs.size())));
    if (fs.isEmpty()) c.addView(Ui.muted(this, hint));
    const row = Ui.h(this);
    for (const f of fs) {
      const t = Imaging.thumb(this, db, f.get("file"), 96, Imaging.REPORT === part);
      t.setOnClickListener({ onClick: (v) => { Imaging.open(this, db, f.get("file")); } });
      if (edit) t.setOnLongClickListener({
        onLongClick: (v) => {
          Ui.confirm(this, "Remove this picture?", "", "Remove", {
            run: () => {
              Imaging.removeFile(db, f.get("id"));
              this.render();
            }
          });
          return true;
        }
      });
      row.addView(t);
      Ui.margins(t, 0, 0, 8, 0);
    }
    if (!fs.isEmpty()) {
      const hs = new HorizontalScrollView(this);
      hs.addView(row);
      c.addView(hs);
      Ui.margins(hs, 0, 8, 0, 4);
      if (edit) c.addView(Ui.muted(this, "Tap to view large  ·  long-press to remove"));
    }
    if (edit) {
      const mimes = Imaging.REPORT === part ? ["image/*", "application/pdf"] : ["image/*"];
      c.addView(Ui.buttonRow(this,
        Ui.button(this, "Camera", Imaging.COLOR, {
          onClick: (v) => {
            if (!this.save(false)) return;
            this.pendingPart = part;
            this.pendingCamera = Imaging.DIR + "/" + part + "_" + this.id + "_" + System.currentTimeMillis() + ".jpg";
            if (!Store.capture(this, this.pendingCamera, ImagingActivity.REQ_CAMERA)) this.pendingCamera = null;
          }
        }),
        Ui.outlineButton(this, Imaging.REPORT === part ? "Gallery / PDF" : "Gallery", Imaging.COLOR, {
          onClick: (v) => {
            if (!this.save(false)) return;
            this.pendingPart = part;
            Store.pick(this, mimes, ImagingActivity.REQ_PICK);
          }
        })));
    }
    return c;
  }

  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    const db = this.db;
    if (res !== RESULT_OK || this.id < 0 || this.pendingPart == null) return;
    try {
      if (req === ImagingActivity.REQ_CAMERA && this.pendingCamera != null) {
        const f = db.file(this.pendingCamera);
        if (!f.exists() || f.length() === 0) return;
        Store.shrink(f, 2400);
        Imaging.addFile(db, this.id, this.pendingPart, this.pendingCamera);
        this.pendingCamera = null;
      } else if (req === ImagingActivity.REQ_PICK && data != null && data.getData() != null) {
        const rel = Store.importUri(this, data.getData(), Imaging.DIR, this.pendingPart + "_" + this.id);
        const pdf = rel.toLowerCase().endsWith(".pdf");
        if (!Store.isImage(rel) && !(pdf && Imaging.REPORT === this.pendingPart)) {
          db.file(rel).delete();
          Ui.toast(this, Imaging.REPORT === this.pendingPart ? "Pick a photo or a PDF" : "Pick a photo (JPG or PNG)");
          return;
        }
        if (Store.isImage(rel)) Store.shrink(db.file(rel), 2400);
        Imaging.addFile(db, this.id, this.pendingPart, rel);
      }
      this.render();
    } catch (e) {
      Ui.toast(this, "Could not add the picture: " + e.getMessage());
    }
  }

  /** For tests: attach a file already in filesDir. */
  attach(part, rel) {
    this.save(false);
    Imaging.addFile(this.db, this.id, part, rel);
    this.render();
  }

  /** Saves the study (creating it the first time). close: finish the screen afterwards. */
  save(close) {
    const form = this.form;
    if (form == null) return false;
    if (!this.canChange()) {
      if (close) this.finish();
      return false;
    }
    if ("Other" === form.get("kind") && form.get("other").trim().isEmpty()) {
      Ui.toast(this, "Write which study it is");
      return false;
    }
    const cv = new ContentValues();
    cv.put("kind", form.get("kind"));
    cv.put("other", "Other" === form.get("kind") ? form.get("other").trim() : "");
    cv.put("date", form.get("date"));
    cv.put("impression", form.get("impression").trim());
    if (this.id < 0) {
      cv.put("patient_id", this.pid);
      cv.put("by_name", Chat.myName(this, this.db));
      cv.put("time", Chat.now());
      this.id = this.db.insert(Imaging.TABLE, cv);
    } else this.db.update(Imaging.TABLE, cv, this.id);
    if (close) {
      Ui.toast(this, "Saved");
      this.finish();
    }
    return true;
  }

  static v(r, k, def) {
    return r == null || Ui.nz(r.get(k)).isEmpty() ? def : r.get(k);
  }
}
;
/* ---- app/ImcuSpecialActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** IMCU registers: rat killer poisoning, snake bite and plasma exchange (PLEX) therapy. */
class ImcuSpecialActivity extends Base {
  constructor() { super(); this.tab = 0; }

  static RK_COLOR = 0xFFB45309;
  static PLEX_COLOR = 0xFF7E22CE;
  static SB_COLOR = 0xFF047857;
  /** Tabs, as passed in "tab": 0 rat killer, 1 PLEX, 2 snake bite (shown rat killer, snake bite, PLEX). */
  static RK = 0;
  static PLEX = 1;
  static SNAKE = 2;
  static SNAKES = ["Russell's viper", "Saw-scaled viper", "Krait", "Cobra", "Hump-nosed viper", "Unknown"];
  static ENVENOM = ["Haemotoxic", "Neurotoxic", "Both", "No envenomation"];
  static WBCT = ["Non-clotting", "Clotting", "Not done"];
  static AKI = ["No AKI", "AKI", "On dialysis"];
  static AGENTS = ["Yellow phosphorus", "Zinc phosphide", "Aluminium phosphide", "Superwarfarin", "Unknown"];
  static LIVER = ["No liver injury", "Hepatitis", "Acute liver failure"];
  static INDICATIONS = ["Rat killer (liver failure)", "GBS", "Myasthenic crisis", "TTP / HUS", "Snake bite", "Other"];
  static FLUIDS = ["FFP", "Albumin 5%", "Albumin + saline", "FFP + albumin"];
  static ACCESS = ["Femoral", "Internal jugular", "Subclavian"];

  onCreate(b) {
    super.onCreate(b);
    const t = this.getIntent().getStringExtra("tab");
    this.tab = "1".equals(t) ? ImcuSpecialActivity.PLEX : "2".equals(t) ? ImcuSpecialActivity.SNAKE : ImcuSpecialActivity.RK;
    this.setTitle("IMCU registers");
    this.subtitle = "Rat killer, snake bite and PLEX therapy";
    this.headerColor(Ui.unitColor(Db.IMCU));
    this.headerAction("+ Add", {
      onClick: (v) => {
        if (this.tab === ImcuSpecialActivity.RK) this.ratDialog(null);
        else if (this.tab === ImcuSpecialActivity.SNAKE) this.snakeDialog(null);
        else this.sessionDialog(null, null);
      }
    });
  }

  render() {
    const C = ImcuSpecialActivity;
    const page = Ui.v(this);
    const seg = Ui.h(this);
    seg.setBackground(Ui.round(this, 0xFFE2E8F0, 14));
    seg.setPadding(Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4));
    const labels = ["Rat killer", "Snake bite", "PLEX therapy"];
    const colors = [C.RK_COLOR, C.SB_COLOR, C.PLEX_COLOR];
    const tabs = [C.RK, C.SNAKE, C.PLEX];
    for (let i = 0; i < 3; i++) {
      const idx = tabs[i];
      const t = Ui.tv(this, labels[i], 14, idx === this.tab ? colors[i] : Ui.MUTED, true);
      t.setGravity(Gravity.CENTER);
      t.setSingleLine(true);
      t.setPadding(0, Ui.dp(this, 9), 0, Ui.dp(this, 9));
      if (idx === this.tab) t.setBackground(Ui.round(this, 0xFFFFFFFF, 11));
      t.setOnClickListener({
        onClick: (v) => { this.tab = idx; this.render(); }
      });
      seg.addView(t, Ui.weight(1));
    }
    page.addView(seg);
    Ui.margins(seg, 12, 12, 12, 4);
    if (this.tab === C.RK) this.ratPage(page);
    else if (this.tab === C.SNAKE) this.snakePage(page);
    else this.plexPage(page);
    this.setPage(page);
  }

  // ---------- rat killer poisoning ----------

  ratPage(page) {
    const C = ImcuSpecialActivity;
    const inn = this.db.rows("SELECT * FROM patients WHERE status='IN' AND " + Db.RAT_SQL + " ORDER BY admit_date DESC, id DESC");
    const past = this.db.rows("SELECT * FROM patients WHERE status<>'IN' AND " + Db.RAT_SQL + " ORDER BY outcome_date DESC, id DESC LIMIT 100");
    let alf = 0, plex = 0;
    for (const p of inn) {
      if (C.LIVER[2].equals(p.get("rk_liver"))) alf++;
      if (this.sessions(p.get("id")) > 0) plex++;
    }
    let died = 0;
    for (const p of past) if (Db.DIED.equals(p.get("status"))) died++;
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(C.RK_COLOR), 20));
    hero.addView(Ui.statRow(this, this.white(String(inn.size()), "In hospital"), this.white(String(alf), "Liver failure"),
        this.white(String(plex), "On PLEX"), this.white(past.size() + "", "Earlier"), this.white(String(died), "Deaths")));
    page.addView(hero);

    page.addView(Ui.heading(this, "In hospital  ·  " + inn.size(), C.RK_COLOR));
    if (inn.isEmpty()) page.addView(this.emptyNote("No rat killer poisoning patients now. Tap + Add, or set the type to Rat killer in the IMCU toxicology wing."));
    for (const p of inn) {
      page.addView(this.patientRow(p));
      page.addView(this.ratStrip(p));
    }
    if (!past.isEmpty()) {
      page.addView(Ui.heading(this, "Discharged / died", Ui.SLATE));
      for (const p of past) {
        page.addView(this.patientRow(p));
        page.addView(this.ratStrip(p));
      }
    }
  }

  /** Compound, amount, time of intake, liver status and PLEX count under a patient. */
  ratStrip(p) {
    const C = ImcuSpecialActivity;
    const box = Ui.v(this);
    box.setPadding(Ui.dp(this, 26), 0, Ui.dp(this, 14), Ui.dp(this, 8));
    const tags = new Bands.Flow(this);
    const agent = Ui.nz(p.get("rk_agent"));
    tags.addView(Ui.softPill(this, agent.isEmpty() ? "Compound not set" : agent, C.RK_COLOR));
    if (!Ui.nz(p.get("rk_amount")).isEmpty()) tags.addView(Ui.softPill(this, p.get("rk_amount"), Ui.SLATE));
    const liver = Ui.nz(p.get("rk_liver"));
    if (!liver.isEmpty()) tags.addView(Ui.softPill(this, liver, liver.equals(C.LIVER[0]) ? Ui.GREEN : liver.equals(C.LIVER[1]) ? Ui.ORANGE : Ui.RED));
    const n = this.sessions(p.get("id"));
    if (n > 0) tags.addView(Ui.softPill(this, "PLEX × " + n, C.PLEX_COLOR));
    box.addView(tags);
    const time = Ui.nz(p.get("rk_time"));
    const notes = Ui.nz(p.get("rk_notes"));
    if (!time.isEmpty() || !notes.isEmpty())
      box.addView(Ui.muted(this, (time.isEmpty() ? "" : "Consumed " + time + (notes.isEmpty() ? "" : "  ·  ")) + notes));
    const btns = Ui.h(this);
    btns.setGravity(Gravity.END);
    const d = Ui.pill(this, "Details", C.RK_COLOR);
    d.setOnClickListener({
      onClick: (v) => { this.ratDialog(p); }
    });
    btns.addView(d);
    if ("IN".equals(p.get("status"))) {
      const x = Ui.pill(this, "+ PLEX session", C.PLEX_COLOR);
      x.setOnClickListener({
        onClick: (v) => { this.sessionDialog(p, null); }
      });
      btns.addView(x);
      Ui.margins(x, 8, 0, 0, 0);
    }
    box.addView(btns);
    Ui.margins(btns, 0, 6, 0, 0);
    return box;
  }

  sessions(patientId) {
    return this.db.num("SELECT COUNT(*) FROM plex WHERE patient_id=?", Ui.nz(patientId));
  }

  /** Inpatients by "name · IP" for the patient box. */
  inpatients() {
    const m = new JMap();
    for (const p of this.db.rows("SELECT * FROM patients WHERE status='IN' ORDER BY location='IMCU' DESC, admit_date DESC LIMIT 400"))
      m.put(ImcuSpecialActivity.label(p), p);
    return m;
  }

  static label(p) {
    return p.get("name") + (Ui.nz(p.get("ip_no")).isEmpty() ? "" : " · IP " + p.get("ip_no"));
  }

  static find(all, typed) {
    if (all.containsKey(typed)) return all.get(typed);
    for (const p of all.values()) if (p.get("name").equalsIgnoreCase(typed.trim())) return p;
    return null;
  }

  ratDialog(p) {
    const C = ImcuSpecialActivity;
    const f = new Form(this);
    const all = p == null ? this.inpatients() : null;
    if (p == null) f.suggest("patient", "Patient (admitted) *", "", all.keySet().slice());
    f.choice("rk_agent", "Compound", C.AGENTS, C.AGENTS, p == null ? "" : Ui.nz(p.get("rk_agent")), null);
    f.text("rk_amount", "Amount consumed (e.g. 10 g paste, 1 sachet)", p == null ? "" : p.get("rk_amount"), Form.PLAIN);
    f.text("rk_time", "When consumed (e.g. 8 Oct, 9 PM; 36 h before arrival)", p == null ? "" : p.get("rk_time"), Form.PLAIN);
    f.choice("rk_liver", "Liver", C.LIVER, C.LIVER, p == null ? "" : Ui.nz(p.get("rk_liver")), null);
    f.multi("rk_notes", "INR, bilirubin, SGOT/SGPT, course", p == null ? "" : p.get("rk_notes"));
    Ui.formDialog(this, p == null ? "Rat killer poisoning" : "Rat killer · " + p.get("name"), f, "Save", {
      run: () => {
        let pt = p;
        if (pt == null) {
          if (!f.require("patient", "Choose the patient")) return false;
          pt = C.find(all, f.get("patient"));
          if (pt == null) {
            Ui.toast(this, "Admit the patient first, then add here");
            return false;
          }
        }
        const cv = new ContentValues();
        const agent = f.get("rk_agent");
        cv.put("rk_agent", agent.isEmpty() ? "Unknown" : agent);
        for (const k of ["rk_amount", "rk_time", "rk_liver", "rk_notes"]) cv.put(k, f.get(k));
        if (Db.IMCU.equals(pt.get("location")) && Db.TOX.equals(Db.imcuWing(pt))) cv.put("tox_kind", Db.RAT_KILLER);
        this.db.update("patients", cv, Long.parseLong(pt.get("id")));
        this.render();
        return true;
      }
    });
  }

  // ---------- snake bite ----------

  snakePage(page) {
    const C = ImcuSpecialActivity;
    const inn = this.db.rows("SELECT * FROM patients WHERE status='IN' AND " + Db.SNAKE_SQL + " ORDER BY admit_date DESC, id DESC");
    const past = this.db.rows("SELECT * FROM patients WHERE status<>'IN' AND " + Db.SNAKE_SQL + " ORDER BY outcome_date DESC, id DESC LIMIT 100");
    let haem = 0, neuro = 0, vent = 0, asv = 0;
    for (const p of inn) {
      const ty = Ui.nz(p.get("sb_type"));
      if (ty.equals("Haemotoxic") || ty.equals("Both")) haem++;
      if (ty.equals("Neurotoxic") || ty.equals("Both")) neuro++;
      if ("1".equals(p.get("vent"))) vent++;
      asv += Ui.toInt(p.get("sb_asv"), 0);
    }
    let died = 0;
    for (const p of past) if (Db.DIED.equals(p.get("status"))) died++;
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(C.SB_COLOR), 20));
    hero.addView(Ui.statRow(this, this.white(String(inn.size()), "In hospital"), this.white(String(haem), "Haemotoxic"),
        this.white(String(neuro), "Neurotoxic"), this.white(String(vent), "Ventilator"), this.white(String(asv), "ASV vials")));
    page.addView(hero);

    page.addView(Ui.heading(this, "In hospital  ·  " + inn.size(), C.SB_COLOR));
    if (inn.isEmpty()) page.addView(this.emptyNote("No snake bite patients now. Tap + Add, or set the type to Snake bite in the IMCU toxicology wing."));
    for (const p of inn) {
      page.addView(this.patientRow(p));
      page.addView(this.snakeStrip(p));
    }
    if (!past.isEmpty()) {
      page.addView(Ui.heading(this, "Discharged / died  ·  " + died + (died === 1 ? " death" : " deaths"), Ui.SLATE));
      for (const p of past) {
        page.addView(this.patientRow(p));
        page.addView(this.snakeStrip(p));
      }
    }
  }

  /** The snake as set, or as named in the diagnosis. */
  static snakeOf(p) {
    const s = Ui.nz(p.get("sb_snake"));
    if (!s.isEmpty()) return s;
    const d = Ui.nz(p.get("diagnosis")).toLowerCase();
    if (d.contains("russell")) return ImcuSpecialActivity.SNAKES[0];
    if (d.contains("saw")) return ImcuSpecialActivity.SNAKES[1];
    if (d.contains("krait")) return ImcuSpecialActivity.SNAKES[2];
    if (d.contains("cobra")) return ImcuSpecialActivity.SNAKES[3];
    if (d.contains("hump")) return ImcuSpecialActivity.SNAKES[4];
    return "";
  }

  /** Snake, envenomation, 20WBCT, ASV given, kidney and ventilator under a patient. */
  snakeStrip(p) {
    const C = ImcuSpecialActivity;
    const box = Ui.v(this);
    box.setPadding(Ui.dp(this, 26), 0, Ui.dp(this, 14), Ui.dp(this, 8));
    const tags = new Bands.Flow(this);
    const snake = C.snakeOf(p);
    tags.addView(Ui.softPill(this, snake.isEmpty() ? "Snake not set" : snake, C.SB_COLOR));
    const ty = Ui.nz(p.get("sb_type"));
    if (!ty.isEmpty()) tags.addView(Ui.softPill(this, ty, ty.equals("No envenomation") ? Ui.GREEN : ty.equals("Neurotoxic") ? Ui.PURPLE : Ui.RED));
    const w = Ui.nz(p.get("sb_wbct"));
    if (!w.isEmpty() && !w.equals("Not done")) tags.addView(Ui.softPill(this, "20WBCT " + w.toLowerCase(), w.equals("Non-clotting") ? Ui.RED : Ui.GREEN));
    const asv = Ui.toInt(p.get("sb_asv"), 0);
    if (asv > 0) tags.addView(Ui.softPill(this, "ASV " + asv + " vials", Ui.SKY));
    const aki = Ui.nz(p.get("sb_aki"));
    if (!aki.isEmpty() && !aki.equals("No AKI")) tags.addView(Ui.softPill(this, aki, Ui.ORANGE));
    if ("1".equals(p.get("vent"))) tags.addView(Ui.softPill(this, "Ventilator", Ui.RED));
    box.addView(tags);
    const line = new StringBuilder();
    if (!Ui.nz(p.get("sb_time")).isEmpty()) line.append("Bitten ").append(p.get("sb_time"));
    if (!Ui.nz(p.get("sb_site")).isEmpty()) line.append(line.length() > 0 ? "  ·  " : "").append("Site: ").append(p.get("sb_site"));
    if (!Ui.nz(p.get("sb_notes")).isEmpty()) line.append(line.length() > 0 ? "  ·  " : "").append(p.get("sb_notes"));
    if (line.length() > 0) box.addView(Ui.muted(this, line.toString()));
    const log = Ui.nz(p.get("sb_log")).trim();
    if (!log.isEmpty()) {
      const l = Ui.muted(this, "ASV: " + log.split("\n").join("  ·  "));
      l.setMaxLines(3);
      box.addView(l);
    }
    const btns = Ui.h(this);
    btns.setGravity(Gravity.END);
    const d = Ui.pill(this, "Details", C.SB_COLOR);
    d.setOnClickListener({
      onClick: (v) => { this.snakeDialog(p); }
    });
    btns.addView(d);
    if ("IN".equals(p.get("status"))) {
      const x = Ui.pill(this, "+ ASV dose", Ui.SKY);
      x.setOnClickListener({
        onClick: (v) => { this.asvDialog(p); }
      });
      btns.addView(x);
      Ui.margins(x, 8, 0, 0, 0);
    }
    box.addView(btns);
    Ui.margins(btns, 0, 6, 0, 0);
    return box;
  }

  snakeDialog(p) {
    const C = ImcuSpecialActivity;
    const f = new Form(this);
    const all = p == null ? this.inpatients() : null;
    if (p == null) f.suggest("patient", "Patient (admitted) *", "", all.keySet().slice());
    f.choice("sb_snake", "Snake", C.SNAKES, C.SNAKES, p == null ? "" : C.snakeOf(p), null);
    f.text("sb_site", "Bite site (e.g. right foot)", p == null ? "" : p.get("sb_site"), Form.PLAIN);
    f.text("sb_time", "When bitten (e.g. 8 Oct, 11 PM; 4 h before arrival)", p == null ? "" : p.get("sb_time"), Form.PLAIN);
    f.segment("sb_part", "Bite site (for the census)", FormActivity.SB_PARTS, p == null ? "" : Ui.nz(p.get("sb_part")));
    f.segment("sb_daynight", "Bitten in the", FormActivity.DAY_NIGHT, p == null ? "" : Ui.nz(p.get("sb_daynight")));
    f.segment("sb_delay", "Bite to hospital", FormActivity.SB_DELAYS, p == null ? "" : Ui.nz(p.get("sb_delay")));
    f.choice("sb_type", "Envenomation", C.ENVENOM, C.ENVENOM, p == null ? "" : Ui.nz(p.get("sb_type")), null);
    f.choice("sb_wbct", "20 minute whole blood clotting test", C.WBCT, C.WBCT, p == null ? "" : Ui.nz(p.get("sb_wbct")), null);
    f.text("sb_asv", "ASV vials given so far", p == null ? "" : p.get("sb_asv"), Form.NUMBER);
    f.choice("sb_aki", "Kidney", C.AKI, C.AKI, p == null ? "" : Ui.nz(p.get("sb_aki")), null);
    f.check("vent", "On ventilator", p != null && "1".equals(p.get("vent")));
    f.multi("sb_notes", "Ptosis, bleeding, INR, creatinine, course", p == null ? "" : p.get("sb_notes"));
    Ui.formDialog(this, p == null ? "Snake bite" : "Snake bite · " + p.get("name"), f, "Save", {
      run: () => {
        let pt = p;
        if (pt == null) {
          if (!f.require("patient", "Choose the patient")) return false;
          pt = C.find(all, f.get("patient"));
          if (pt == null) {
            Ui.toast(this, "Admit the patient first, then add here");
            return false;
          }
        }
        const cv = new ContentValues();
        const snake = f.get("sb_snake");
        cv.put("sb_snake", snake.isEmpty() ? "Unknown" : snake);
        for (const k of ["sb_site", "sb_time", "sb_type", "sb_wbct", "sb_asv", "sb_aki", "sb_notes", "vent", "sb_part", "sb_daynight", "sb_delay"]) cv.put(k, f.get(k));
        cv.put("tox_kind", "Snake bite");
        this.db.update("patients", cv, Long.parseLong(pt.get("id")));
        this.tab = C.SNAKE;
        this.render();
        return true;
      }
    });
  }

  /** Adds an ASV dose: the total goes up and the dose is logged with the time. */
  asvDialog(p) {
    const f = new Form(this);
    f.text("vials", "Vials given now *", "10", Form.NUMBER);
    f.text("why", "Reason (loading, repeat after 6 h WBCT, neuro worsening)", "", Form.PLAIN);
    Ui.formDialog(this, "ASV · " + p.get("name"), f, "Add", {
      run: () => {
        const n = f.getInt("vials", 0);
        if (n <= 0) {
          Ui.toast(this, "Enter the number of vials");
          return false;
        }
        const line = Alerts.show(Alerts.now()) + " " + n + " vials" + (f.get("why").isEmpty() ? "" : " (" + f.get("why") + ")");
        const old = Ui.nz(p.get("sb_log")).trim();
        const cv = new ContentValues();
        cv.put("sb_asv", String(Ui.toInt(p.get("sb_asv"), 0) + n));
        cv.put("sb_log", old.isEmpty() ? line : old + "\n" + line);
        if (Ui.nz(p.get("sb_snake")).isEmpty()) cv.put("sb_snake", "Unknown");
        this.db.update("patients", cv, Long.parseLong(p.get("id")));
        this.render();
        return true;
      }
    });
  }

  // ---------- PLEX therapy ----------

  plexPage(page) {
    const C = ImcuSpecialActivity;
    const pts = this.db.rows("SELECT p.*, MAX(x.date) AS last_plex FROM plex x JOIN patients p ON p.id=x.patient_id "
        + "GROUP BY p.id ORDER BY p.status='IN' DESC, last_plex DESC LIMIT 150");
    let now = 0;
    for (const p of pts) if ("IN".equals(p.get("status"))) now++;
    const m0 = Dates.monthStart(Dates.today()).toString();
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(C.PLEX_COLOR), 20));
    hero.addView(Ui.statRow(this, this.white(String(now), "On PLEX now"),
        this.white(String(this.db.num("SELECT COUNT(*) FROM plex WHERE date>=?", m0)), "Sessions this month"),
        this.white(String(pts.size()), "Patients"),
        this.white(String(this.db.num("SELECT COUNT(*) FROM plex")), "All sessions")));
    page.addView(hero);
    if (pts.isEmpty()) page.addView(this.emptyNote("No PLEX sessions yet. Tap + Add to record one."));
    let pastHead = false;
    for (const p of pts) {
      if (!"IN".equals(p.get("status")) && !pastHead) {
        page.addView(Ui.heading(this, "Discharged / died", Ui.SLATE));
        pastHead = true;
      }
      page.addView(this.plexCard(p));
    }
  }

  plexCard(p) {
    const C = ImcuSpecialActivity;
    const ss = this.db.rows("SELECT * FROM plex WHERE patient_id=? ORDER BY date, session_no, id", p.get("id"));
    const ind = ss.isEmpty() ? "" : ss.get(ss.size() - 1).get("indication");
    const age = p.get("age").isEmpty() ? "" : p.get("age") + " y, ";
    const card = this.entryCard(ind.isEmpty() ? "PLEX" : ind, C.PLEX_COLOR, p.get("name") + "  ·  " + age + Base.sexLabel(p.get("sex")),
        (p.get("ip_no").isEmpty() ? "" : "IP " + p.get("ip_no") + "  ·  ") + Base.where(p) + (p.get("diagnosis").isEmpty() ? "" : "\n" + p.get("diagnosis")),
        ss.size() + (ss.size() === 1 ? " session" : " sessions"), this.opener(PatientActivity, "id", p.get("id")));
    if (!"IN".equals(p.get("status"))) card.setAlpha(0.7);
    for (const s of ss) {
      const r = Ui.h(this);
      r.setGravity(Gravity.CENTER_VERTICAL);
      r.setPadding(0, Ui.dp(this, 6), 0, 0);
      const no = Ui.tv(this, "#" + s.get("session_no"), 12, Color.WHITE, true);
      no.setGravity(Gravity.CENTER);
      no.setBackground(Ui.round(this, C.PLEX_COLOR, 13));
      r.addView(no, new LinearLayout.LayoutParams(Ui.dp(this, 30), Ui.dp(this, 26)));
      const t = new StringBuilder(Dates.nice(s.get("date")));
      for (const k of ["volume", "fluid", "access"]) if (!Ui.nz(s.get(k)).isEmpty()) t.append("  ·  ").append(s.get(k));
      if (!Ui.nz(s.get("inr")).isEmpty()) t.append("  ·  INR ").append(s.get("inr"));
      if (!Ui.nz(s.get("complications")).isEmpty()) t.append("\nComplications: ").append(s.get("complications"));
      if (!Ui.nz(s.get("notes")).isEmpty()) t.append("\n").append(s.get("notes"));
      const tv = Ui.body(this, t.toString());
      tv.setTextSize(13);
      tv.setPadding(Ui.dp(this, 10), 0, 0, 0);
      r.addView(tv, Ui.weight(1));
      Ui.ripple(r, Ui.alpha(C.PLEX_COLOR, 0x1A));
      r.setOnClickListener({
        onClick: (v) => { this.sessionDialog(p, s); }
      });
      card.addView(r);
    }
    if ("IN".equals(p.get("status"))) {
      const add = Ui.outlineButton(this, "+ PLEX session", C.PLEX_COLOR, {
        onClick: (v) => { this.sessionDialog(p, null); }
      });
      card.addView(add);
      Ui.margins(add, 0, 10, 0, 0);
    }
    return card;
  }

  sessionDialog(p, s) {
    const C = ImcuSpecialActivity;
    const f = new Form(this);
    const all = p == null ? this.inpatients() : null;
    if (p == null) f.suggest("patient", "Patient (admitted) *", "", all.keySet().slice());
    let lastInd = "";
    let next = 1;
    if (p != null) {
      const last = this.db.row("SELECT indication, MAX(session_no) AS n FROM plex WHERE patient_id=?", p.get("id"));
      if (last != null) {
        lastInd = Ui.nz(last.get("indication"));
        next = Ui.toInt(last.get("n"), 0) + 1;
      }
      if (lastInd.isEmpty() && Db.isRatKiller(p)) lastInd = C.INDICATIONS[0];
      if (lastInd.isEmpty() && Db.isSnakeBite(p)) lastInd = "Snake bite";
    }
    f.choice("indication", "Indication", C.INDICATIONS, C.INDICATIONS, s != null ? s.get("indication") : lastInd, null);
    f.beginRow();
    f.date("date", "Date", s != null ? s.get("date") : Dates.todayIso());
    f.text("session_no", "Session number", s != null ? s.get("session_no") : String(next), Form.NUMBER);
    f.endRow();
    f.text("volume", "Volume exchanged (e.g. 2.5 L, 1.5 PV)", s == null ? "" : s.get("volume"), Form.PLAIN);
    f.choice("fluid", "Replacement fluid", C.FLUIDS, C.FLUIDS, s == null ? "FFP" : s.get("fluid"), null);
    f.choice("access", "Catheter", C.ACCESS, C.ACCESS, s == null ? "" : s.get("access"), null);
    f.text("inr", "INR before session", s == null ? "" : s.get("inr"), Form.PLAIN);
    f.text("complications", "Complications (hypotension, allergy, tetany, bleeding)", s == null ? "" : s.get("complications"), Form.PLAIN);
    f.multi("notes", "Notes", s == null ? "" : s.get("notes"));
    f.text("by_name", "Done by", s != null ? s.get("by_name") : CallDutyActivity.myName(this), Form.PLAIN);
    if (s != null) {
      const del = Ui.outlineButton(this, "Delete session", Ui.RED, {
        onClick: (v) => {
          Ui.confirm(this, "Delete this PLEX session?", p.get("name") + " · session " + s.get("session_no"), "Delete", {
            run: () => { this.db.delete("plex", Long.parseLong(s.get("id"))); this.render(); }
          });
        }
      });
      f.view.addView(del);
      Ui.margins(del, 0, 14, 0, 0);
    }
    Ui.formDialog(this, p == null ? "PLEX session" : "PLEX · " + p.get("name"), f, "Save", {
      run: () => {
        let pt = p;
        if (pt == null) {
          if (!f.require("patient", "Choose the patient")) return false;
          pt = C.find(all, f.get("patient"));
          if (pt == null) {
            Ui.toast(this, "Admit the patient first, then add the session");
            return false;
          }
        }
        const cv = new ContentValues();
        cv.put("patient_id", pt.get("id"));
        cv.put("patient", pt.get("name"));
        cv.put("ip_no", pt.get("ip_no"));
        for (const k of ["indication", "date", "volume", "fluid", "access", "inr", "complications", "notes", "by_name"]) cv.put(k, f.get(k));
        let no = f.getInt("session_no", 0);
        if (no <= 0) no = this.sessions(pt.get("id")) + 1;
        cv.put("session_no", no);
        CallDutyActivity.rememberName(this, f.get("by_name"));
        if (s == null) {
          cv.put("added_on", Alerts.now());
          this.db.insert("plex", cv);
        } else this.db.update("plex", cv, Long.parseLong(s.get("id")));
        this.tab = C.PLEX;
        this.render();
        return true;
      }
    });
  }

  white(v, label) {
    const l = Ui.v(this);
    l.setGravity(Gravity.CENTER_HORIZONTAL);
    const n = Ui.tv(this, v, 22, Color.WHITE, true);
    n.setGravity(Gravity.CENTER);
    l.addView(n);
    const t = Ui.tv(this, label, 11, 0xD9FFFFFF, false);
    t.setGravity(Gravity.CENTER);
    l.addView(t);
    return l;
  }
}
;
