/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Import from a file or pasted text: reads Word, Excel, PDF, CSV and text, and adds what it recognises to the right sections. */
class ImportActivity extends Base {
  static REQ_FILE = 61;
  static MIMES = ["application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "application/pdf", "text/plain", "text/csv",
    "text/comma-separated-values", "application/msword", "application/vnd.ms-excel", "application/octet-stream"];

  constructor() {
    super();
    this.fileName = null; this.savedRel = null; this.error = null;
    this.result = null;            // Extract.Result
    this.findings = null;          // List<Importer.Finding>
    this.done = new JMap();        // Map<Integer, String>
    this.unitForms = new JMap();   // Map<Integer, Form>
    this.busy = false; this.showAll = false; this.posted = false; this.started = false;
  }

  onResume() {
    this.started = true;
    super.onResume();
  }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Import from file");
    this.subtitle = "Word · Excel · PDF · CSV · text";
    this.headerColor(Ui.SKY);
    this.handleShare(this.getIntent());
  }

  liveRefresh() {
    return false;
  }

  /** Files and text shared to the app from WhatsApp, e-mail or a file manager. */
  handleShare(i) {
    if (i == null) return;
    try {
      let uri = null;
      if (Intent.ACTION_SEND.equals(i.getAction())) {
        uri = i.getParcelableExtra(Intent.EXTRA_STREAM);
        const text = i.getStringExtra(Intent.EXTRA_TEXT);
        if (uri == null && text != null) { this.load("Shared text", jbytes(text), false); return; }
      } else if (Intent.ACTION_VIEW.equals(i.getAction())) uri = i.getData();
      if (uri != null) this.loadUri(uri);
    } catch (e) {
      this.error = e.getMessage();
    }
  }

  loadUri(uri) {
    this.busy = true;
    this.error = null;
    if (this.started) this.render();
    new Thread({
      run: () => {
        let name = "file";
        let data = null;
        let err = null;
        try {
          name = Store.displayName(this, uri);
          const inp = this.getContentResolver().openInputStream(uri);
          if (inp == null) throw new IOException("Cannot open the file");
          try { data = Extract.readAll(inp); } finally { inp.close(); }
        } catch (e) {
          err = e.getMessage();
        }
        const n = name, er = err;
        const d = data;
        this.runOnUiThread({
          run: () => {
            this.busy = false;
            if (er != null) { this.error = er; this.render(); return; }
            this.load(n, d, true);
          }
        });
      }
    }).start();
  }

  /** Reads the document and works out what can be added. */
  load(name, data, keepFile) {
    if (this.savedRel != null && !this.posted) this.db.file(this.savedRel).delete();
    this.fileName = name;
    this.result = null;
    this.findings = null;
    this.error = null;
    this.savedRel = null;
    this.posted = false;
    this.done.clear();
    this.unitForms.clear();
    try {
      this.result = Extract.read(name, data);
      this.findings = Importer.analyze(this.db, this.result);
      if (keepFile) {
        const ext = Store.extOf(name);
        this.savedRel = "notices/import_" + System.currentTimeMillis() + (ext.isEmpty() ? "" : "." + ext);
        const f = this.db.file(this.savedRel);
        f.getParentFile().mkdirs();
        const o = new FileOutputStream(f);
        o.write(data);
        o.close();
      }
      if (this.result.text.toString().trim().isEmpty())
        this.error = "No text found in this file. If it is a scanned page or photo, the phone cannot read it; type or paste the details instead.";
    } catch (e) {
      this.error = "Could not read " + name + ": " + e.getMessage();
    }
    if (this.started) this.render();
  }

  render() {
    const page = Ui.v(this);
    const top = Ui.card(this);
    top.addView(Ui.title(this, "Add information from a document"));
    top.addView(Ui.muted(this, "Choose a Word, Excel, PDF, CSV or text file, or paste text. The app finds duty rosters, staff lists, "
      + "patient lists, CMCHIS lists and sick case lists, shows you what it found, and adds it when you tap Add. "
      + "You can also share a file to TVMCHMED from WhatsApp or your file manager."));
    const btns = Ui.buttonRow(this,
      Ui.button(this, "Choose file", Ui.SKY, {
        onClick: (v) => { Store.pick(this, ImportActivity.MIMES, ImportActivity.REQ_FILE); }
      }),
      Ui.outlineButton(this, "Paste text", Ui.SKY, {
        onClick: (v) => { this.pasteDialog(); }
      }));
    top.addView(btns);
    Ui.margins(btns, 0, 12, 0, 0);
    page.addView(top);

    if (this.busy) page.addView(this.emptyNote("Reading the file…"));
    if (this.error != null) {
      const e = Ui.card(this);
      e.addView(Ui.tv(this, this.error, 14, Ui.RED, true));
      page.addView(e);
    }
    if (this.result != null) {
      const txt = this.result.text.toString().trim();
      const lines = txt.isEmpty() ? [] : txt.jsplit("\n");
      page.addView(Ui.heading(this, "📄 " + this.fileName, Ui.SKY));
      const prev = Ui.card(this);
      prev.addView(Ui.muted(this, this.result.kind + "  ·  " + lines.length + " lines" + (this.result.tables.isEmpty() ? "" : "  ·  " + this.result.tables.size() + " table(s)")));
      let sb = "";
      for (let i = 0; i < lines.length && (this.showAll || i < 12); i++) sb += lines[i].split("\t").join("│") + '\n';
      const t = Ui.tv(this, sb.trim(), 12, Ui.TEXT, false);
      t.setTypeface(Typeface.MONOSPACE);
      t.setPadding(0, Ui.dp(this, 8), 0, 0);
      t.setTextIsSelectable(true);
      prev.addView(t);
      if (lines.length > 12) {
        const more = Ui.tv(this, this.showAll ? "Show less" : "Show all " + lines.length + " lines", 13, Ui.SKY, true);
        more.setPadding(0, Ui.dp(this, 8), 0, 0);
        more.setOnClickListener({
          onClick: (v) => { this.showAll = !this.showAll; this.render(); }
        });
        prev.addView(more);
      }
      page.addView(prev);

      if (this.findings != null && !this.findings.isEmpty()) {
        page.addView(Ui.heading(this, "Found in this document", Ui.GREEN));
        for (let i = 0; i < this.findings.size(); i++) page.addView(this.findingCard(i, this.findings.get(i)));
      } else if (!txt.isEmpty()) {
        page.addView(this.emptyNote("Nothing here looked like a duty roster, staff list, patient list, CMCHIS list or sick case list. "
          + "Lists need a heading row such as Name, IP No, Age/Sex, Diagnosis, Unit."));
      }
      if (!txt.isEmpty() || this.savedRel != null) page.addView(this.boardCard(txt));
    }
    this.setPage(page);
  }

  findingCard(idx, f) {
    const db = this.db;
    const card = Ui.card(this);
    const col = f.kind.equals(Importer.ROSTER) ? Ui.PRIMARY : f.kind.equals(Importer.STAFF) ? Ui.SLATE
      : f.kind.equals(Importer.CMCHIS) ? Ui.PINK : f.kind.equals(Importer.SICK) ? Ui.TEAL : Ui.GREEN;
    card.addView(Ui.tv(this, f.title, 17, col, true));
    card.addView(Ui.muted(this, f.detail));
    if (f.kind.equals(Importer.ROSTER)) {
      let s = "";
      for (let g = 0; g < Roster.FIELDS.length && s.length < 400; g++)
        for (const fl of Roster.FIELDS[g]) {
          const v = f.roster.fields.get(fl[0]);
          if (v != null) s += fl[1] + ": " + Roster.name(v.jsplit("\n")[0]) + (v.contains("\n") ? " +" + (v.jsplit("\n").length - 1) : "") + '\n';
        }
      const t = Ui.tv(this, s.trim(), 13, Ui.TEXT, false);
      t.setPadding(0, Ui.dp(this, 6), 0, 0);
      card.addView(t);
    } else {
      for (let i = 0; i < Math.min(5, f.rows.size()); i++) {
        const r = f.rows.get(i);
        let s = "• " + r.get("name");
        for (const k of ["role", "unit", "ip_no", "age", "sex", "diagnosis", "status", "phone", "date"])
          if (r.containsKey(k)) s += "  ·  " + (k.equals("unit") ? Db.shortName(r.get(k)) : k.equals("date") ? Dates.nice(r.get(k)) : r.get(k));
        const t = Ui.tv(this, s, 13, Ui.TEXT, false);
        t.setPadding(0, Ui.dp(this, 4), 0, 0);
        card.addView(t);
      }
      if (f.rows.size() > 5) card.addView(Ui.muted(this, "… and " + (f.rows.size() - 5) + " more"));
    }
    if (this.done.containsKey(idx)) {
      const ok = Ui.tv(this, "✓ " + this.done.get(idx), 14, Ui.GREEN, true);
      ok.setPadding(0, Ui.dp(this, 10), 0, 0);
      card.addView(ok);
      return card;
    }
    const uf = new Form(this);
    const ask = f.needsUnit || (f.kind.equals(Importer.ROSTER) && f.roster.unit == null);
    if (ask && f.fresh > 0) {
      const units = f.kind.equals(Importer.STAFF) ? Db.ALL_LOCS : CallDutyActivity.WARDS;
      uf.choice("unit", f.kind.equals(Importer.ROSTER) ? "Admitting unit" : "Unit for rows without one", Db.shortNames(units), units, db.todaysUnit(), null);
      card.addView(uf.view);
      this.unitForms.put(idx, uf);
    }
    if (f.fresh == 0) {
      card.addView(Ui.tv(this, "Everything here is already in the app.", 13, Ui.MUTED, true));
      return card;
    }
    const label = f.kind.equals(Importer.ROSTER) ? "Save duty roster"
      : "Add " + f.fresh + (f.kind.equals(Importer.STAFF) ? " to staff list" : f.kind.equals(Importer.PATIENTS) ? " admissions"
        : f.kind.equals(Importer.CMCHIS) ? " to CMCHIS" : " to call duty sick list");
    const add = Ui.button(this, label, col, {
      onClick: (v) => { this.apply(idx, f); }
    });
    card.addView(add);
    Ui.margins(add, 0, 12, 0, 0);
    return card;
  }

  apply(idx, f) {
    const uf = this.unitForms.get(idx);
    const unit = uf != null ? uf.get("unit") : this.db.todaysUnit();
    const duty = Dates.admitDay().toString();
    try {
      const n = Importer.apply(this.db, f, unit, duty);
      Sync.kick(this);
      const where = f.kind.equals(Importer.ROSTER) ? "Saved in DAP register → Daily duty roster" + (f.roster.date == null ? "" : " for " + Dates.nice(f.roster.date))
        : f.kind.equals(Importer.STAFF) ? "Added " + n + " to the staff directory"
        : f.kind.equals(Importer.PATIENTS) ? "Admitted " + n + " patients"
        : f.kind.equals(Importer.CMCHIS) ? "Added " + n + " to CMCHIS"
        : "Added " + n + " to the call duty sick case list";
      this.done.put(idx, where);
      Ui.toast(this, where);
    } catch (e) {
      Ui.toast(this, "Could not add: " + e.getMessage());
    }
    this.render();
  }

  boardCard(txt) {
    const card = Ui.card(this);
    card.addView(Ui.tv(this, "Post on the information board", 16, Ui.AMBER, true));
    if (this.posted) {
      card.addView(Ui.tv(this, "✓ Posted on the board", 14, Ui.GREEN, true));
      return card;
    }
    card.addView(Ui.muted(this, "For orders, circulars and anything else: everyone sees it on the Board" + (this.savedRel != null ? ", with the file attached." : ".")));
    const f = new Form(this);
    const title = this.fileName == null ? "" : this.fileName.replaceAllRx("\\.[A-Za-z0-9]+$", "").split("_").join(" ");
    f.text("title", "Title", title, Form.PLAIN);
    f.choice("category", "Category", Db.NOTICE_CATS, Db.NOTICE_CATS, "Order / circular", null);
    const clean = txt.replaceAllRx("\t+$", "").replaceAllRx("(?m)\t+$", "").split("\t").join("  ·  ");
    const body = f.multi("body", "Text", clean.length > 3000 ? clean.substring(0, 3000) + "…" : clean);
    body.setMaxLines(8);
    card.addView(f.view);
    const b = Ui.outlineButton(this, "Post on the board", Ui.AMBER, {
      onClick: (v) => {
        if (!f.require("title", "Enter a title")) return;
        const cv = new ContentValues();
        cv.put("date", Dates.todayIso());
        cv.put("title", f.get("title"));
        cv.put("category", f.get("category"));
        cv.put("body", f.get("body"));
        cv.put("until", "");
        cv.put("image", this.savedRel == null ? "" : this.savedRel);
        this.db.insert("notices", cv);
        this.posted = true;
        Ui.toast(this, "Posted on the board");
        this.render();
      }
    });
    card.addView(b);
    Ui.margins(b, 0, 10, 0, 0);
    return card;
  }

  pasteDialog() {
    const f = new Form(this);
    const e = f.multi("text", "Paste the text here", "");
    e.setMinLines(8);
    e.setHint("A WhatsApp message, rows copied from Excel or Word, a list…");
    Ui.formDialog(this, "Paste text", f, "Read", {
      run: () => {
        if (!f.require("text", "Paste something first")) return false;
        this.load("Pasted text", jbytes(f.get("text")), false);
        return true;
      }
    });
  }

  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    if (req == ImportActivity.REQ_FILE && res == RESULT_OK && data != null && data.getData() != null) this.loadUri(data.getData());
  }

  onNewIntent(i) {
    super.onNewIntent(i);
    this.handleShare(i);
  }

  onDestroy() {
    super.onDestroy();
    // the kept copy is only needed if it went on the board
    if (this.savedRel != null && !this.posted) this.db.file(this.savedRel).delete();
  }
}
;
