'use strict';
/**
 * Intercom (voice calls and pages between members). Browser stub: the Intercom works only in the Android app, so
 * available() is always false (the Intercom tile is hidden on the web) and nothing connects. The public API and the
 * constants stay so other classes keep working.
 * Interfaces Mic { read(buf); close(); }, Speaker { play(pcm); speaker(loud); close(); }, Audio { mic(); speaker(); }
 * and Listener { changed(); } are duck-typed.
 */
class Intercom {
  static RATE = 16000;
  static CHUNK = 3200;
  static CHUNK_MS = 200;
  static LOBBY = "tvm:lobby";
  static RING_SECONDS = 45;
  static SILENCE_SECONDS = 20;

  /** enum State */
  static State = Object.freeze({ IDLE: "IDLE", CALLING: "CALLING", RINGING: "RINGING", CONNECTED: "CONNECTED" });

  static inst = null;

  constructor(ctx, uid, myName, myRole, wsUrl, restUrl, apiKey, tokens, audio) {
    this.ctx = ctx;
    this.uid = uid || "";
    this.myName = myName || "";
    this.myRole = myRole || "";
    this.sent = 0;
    this.heard = 0;
    this.bad = 0;
    this.played = 0;
    this.micPeak = 0;
    this.lastProblem = "";
    this._listeners = [];
  }

  /** The phone's intercom. Web: an inert object (callers only reach it when available() is true, which it never is). */
  static get(c) {
    const uid = Cloud.prefs(c).getString("user_id", "");
    if (Intercom.inst == null || Intercom.inst.uid !== uid) Intercom.inst = new Intercom(c.getApplicationContext(), uid, "", Cloud.role(c), "", "", "", null, null);
    return Intercom.inst;
  }

  static current() {
    return null;
  }

  /** Only the Android app has the intercom. */
  static available(c) {
    return false;
  }

  static inbox(uid) {
    return "tvm:in:" + uid;
  }

  token() { return ""; }

  start() {
  }

  stop() {
  }

  isRunning() { return false; }

  isConnected() { return false; }

  problem() { return "The Intercom works in the Android app."; }

  peers() { return []; }

  addListener(l) { this._listeners.push(l); }

  removeListener(l) { this._listeners = this._listeners.filter(x => x !== l); }

  state() { return Intercom.State.IDLE; }

  peerName() { return ""; }

  peerUid() { return ""; }

  callId() { return ""; }

  isCaller() { return false; }

  isMuted() { return false; }

  isLoud() { return true; }

  setMuted(m) {
  }

  setLoud(l) {
  }

  call(toUid, toName) { return false; }

  accept() { return false; }

  decline() {
  }

  hangup() {
  }

  seconds() { return 0; }

  levelIn() { return 0; }

  levelOut() { return 0; }

  page(scope, text) { return false; }

  static isFaculty(role) {
    return role.equals("admin") || role.equals("hod") || role.equals("registrar") || role.equals("professor") || role.equals("faculty");
  }

  /** The recent calls: {time, out|in, name, seconds, result} (none in the browser unless an earlier log was kept). */
  static log(c) {
    const out = [];
    const s = c.getSharedPreferences("intercom", Context.MODE_PRIVATE).getString("log", "");
    if (s.isEmpty()) return out;
    for (const r of s.jsplit("\n")) {
      const f = r.jsplit("\\|", -1);
      if (f.length >= 5) out.add(f);
    }
    return out;
  }

  static standby(c) {
    return false;
  }
}

Intercom.Peer = class {
  constructor() { this.uid = ""; this.name = ""; this.role = ""; this.busy = false; }
};

/** The real microphone and speaker. Web: none. */
Intercom.RealAudio = class {
  constructor(c) { this.c = c; }
  mic() { throw new IOException("The microphone is not available in the browser"); }
  speaker() { throw new IOException("The speaker is not available in the browser"); }
};
