/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Daily lab values (Hb, counts, renal, electrolytes, sugar, bilirubin) and the small trend graphs on the patient page. */
class Labs {
  constructor() {}

  static COLOR = 0xFF7C3AED;

  /** Usual adult reference ranges; values outside them show in red. */
  static $clinit() {
    const Param = Labs.Param;
    Labs.PARAMS = [
      new Param("hb", "Hb", "g/dL", 12, 17),
      new Param("wbc", "Total count", "/µL", 4000, 11000),
      new Param("plt", "Platelets", "lakh/µL", 1.5, 4.5),
      new Param("urea", "Urea", "mg/dL", 15, 40),
      new Param("creat", "Creatinine", "mg/dL", 0.6, 1.3),
      new Param("na", "Sodium", "mEq/L", 135, 145),
      new Param("k", "Potassium", "mEq/L", 3.5, 5.0),
      new Param("sugar", "Blood sugar", "mg/dL", 70, 140),
      new Param("bili", "Bilirubin", "mg/dL", 0.2, 1.2)];
  }

  static param(key) {
    for (const p of Labs.PARAMS) if (p.key === key) return p;
    return null;
  }

  static num(s) {
    try {
      const t = Ui.nz(s).trim();
      return t.isEmpty() ? null : Double.parseDouble(t);
    } catch (e) {
      return null;
    }
  }

  static abnormal(p, v) {
    return v < p.lo || v > p.hi;
  }

  static fmt(v) {
    return v === Math.rint(v) && Math.abs(v) < 1e7 ? String(Math.trunc(v)) : jfmt("%.1f", v);
  }

  static rows(db, pid) {
    return db.rows("SELECT * FROM labs WHERE patient_id=? ORDER BY date, time, id", String(pid));
  }

  /** The values of one test, oldest first, with their dates. */
  static series(rows, key, dates) {
    const out = [];
    for (const r of rows) {
      const v = Labs.num(r.get(key));
      if (v == null) continue;
      out.add([v]);
      if (dates != null) dates.add(r.get("date"));
    }
    return out;
  }

  static arr(s) {
    const a = new Array(s.size()).fill(0);
    for (let i = 0; i < a.length; i++) a[i] = s.get(i)[0];
    return a;
  }

  /** The patient page's "Lab trends": the latest value of each test with its small graph, and + Add. */
  static section(a, db, pid) {
    const box = Ui.v(a);
    box.addView(Ui.heading(a, "Lab trends", Labs.COLOR));
    const rows = Labs.rows(db, pid);
    const card = Ui.card(a);
    let shown = 0;
    for (const p of Labs.PARAMS) {
      const s = Labs.series(rows, p.key, null);
      if (s.isEmpty()) continue;
      shown++;
      const last = s.get(s.size() - 1)[0];
      const r = Ui.h(a);
      r.setGravity(Gravity.CENTER_VERTICAL);
      const l = Ui.v(a);
      l.addView(Ui.tv(a, p.name, 13, Ui.TEXT, true));
      let trend = "";
      if (s.size() > 1) {
        const prev = s.get(s.size() - 2)[0];
        trend = last > prev ? "  ▲" : last < prev ? "  ▼" : "";
      }
      l.addView(Ui.tv(a, Labs.fmt(last) + " " + p.unit + trend, 12, Labs.abnormal(p, last) ? Ui.RED : Ui.GREEN, true));
      r.addView(l, Ui.lp(Ui.dp(a, 118), WRAP_CONTENT));
      r.addView(new Labs.Spark(a, p, Labs.arr(s), null, false), Ui.weight(1));
      const glp = r.getChildAt(1).getLayoutParams();
      glp.height = Ui.dp(a, 38);
      r.getChildAt(1).setLayoutParams(glp);
      card.addView(r);
      Ui.margins(r, 0, 4, 0, 4);
    }
    if (shown === 0) card.addView(Ui.muted(a, "No lab values yet. Add Hb, counts, urea, creatinine, sodium, potassium, sugar or bilirubin to see them as a graph."));
    else card.addView(Ui.muted(a, rows.size() + (rows.size() === 1 ? " entry" : " entries") + " · tap for the full table"));
    Ui.ripple(card, Ui.alpha(Labs.COLOR, 0x22));
    card.setOnClickListener(a.opener(LabsActivity, "id", String(pid)));
    box.addView(card);
    const add = Ui.outlineButton(a, "+ Add today's labs", Labs.COLOR, { onClick: (v) => { Labs.addDialog(a, db, pid, null); } });
    const wrap = Ui.v(a);
    wrap.setPadding(Ui.dp(a, 12), 0, Ui.dp(a, 12), 0);
    wrap.addView(add);
    box.addView(wrap);
    return box;
  }

  static addDialog(a, db, pid, r) {
    const f = new Form(a);
    f.date("date", "Date", r == null ? Dates.todayIso() : r.get("date"));
    f.time("time", "Time", r == null ? Dates.now() : r.get("time"));
    for (const p of Labs.PARAMS) {
      f.text(p.key, p.name + " (" + p.unit + ")", r == null ? "" : Ui.nz(r.get(p.key)), Form.DECIMAL);
    }
    Ui.formDialog(a, r == null ? "Add lab values" : "Edit lab values", f, "Save", {
      run: () => {
        const cv = new ContentValues();
        let any = false;
        for (const p of Labs.PARAMS) {
          const v = f.get(p.key).trim();
          if (!v.isEmpty() && Labs.num(v) == null) {
            Ui.toast(a, p.name + ": enter a number");
            return false;
          }
          any = any || !v.isEmpty();
          cv.put(p.key, v);
        }
        if (!any) {
          Ui.toast(a, "Enter at least one value");
          return false;
        }
        cv.put("date", f.get("date"));
        cv.put("time", f.get("time"));
        cv.put("patient_id", pid);
        cv.put("by_name", CallDutyActivity.myName(a));
        if (r == null) db.insert("labs", cv);
        else db.update("labs", cv, Long.parseLong(r.get("id")));
        a.render();
        return true;
      }
    });
  }

  /** The graph for one test, full width, with values and dates. */
  static bigGraph(c, p, rows) {
    const dates = [];
    const s = Labs.series(rows, p.key, dates);
    if (s.isEmpty()) return null;
    const card = Ui.card(c);
    const last = s.get(s.size() - 1)[0];
    const top = Ui.h(c);
    top.addView(Ui.tv(c, p.name, 15, Ui.TEXT, true), Ui.weight(1));
    top.addView(Ui.tv(c, Labs.fmt(last) + " " + p.unit, 14, Labs.abnormal(p, last) ? Ui.RED : Ui.GREEN, true));
    card.addView(top);
    card.addView(Ui.muted(c, "Normal " + Labs.fmt(p.lo) + " to " + Labs.fmt(p.hi) + " " + p.unit));
    const g = new Labs.Spark(c, p, Labs.arr(s), dates, true);
    card.addView(g, Ui.lp(MATCH_PARENT, Ui.dp(c, 120)));
    return card;
  }
}

Labs.Param = class {
  constructor(key, name, unit, lo, hi) {
    this.key = key;
    this.name = name;
    this.unit = unit;
    this.lo = lo;
    this.hi = hi;
  }
};

/** A small line graph: the normal range as a soft band, red dots outside it. */
Labs.Spark = class extends View {
  constructor(c, p, v, dates, labels) {
    super(c);
    this.v = v;
    this.p = p;
    this.dates = dates;
    this.labels = labels;
    this.line = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.dot = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.band = new Paint();
    this.text = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.line.setStyle(Paint.Style.STROKE);
    this.line.setStrokeWidth(Ui.dp(c, 2));
    this.line.setColor(Labs.COLOR);
    this.band.setColor(0x2216A34A);
    this.text.setColor(Ui.MUTED);
    this.text.setTextSize(Ui.dp(c, 9));
  }

  onDraw(cv) {
    const v = this.v, p = this.p, text = this.text, labels = this.labels, dates = this.dates;
    const w = this.getWidth(), h = this.getHeight(), pad = Ui.dp(this.getContext(), 6), bottom = labels ? Ui.dp(this.getContext(), 14) : 0;
    let min = p.lo, max = p.hi;
    for (const x of v) { min = Math.min(min, x); max = Math.max(max, x); }
    const span = max - min === 0 ? 1 : max - min;
    min -= span * 0.1;
    max += span * 0.1;
    const top = pad, bot = h - pad - bottom;
    const yLo = bot - (p.lo - min) / (max - min) * (bot - top), yHi = bot - (p.hi - min) / (max - min) * (bot - top);
    cv.drawRect(new RectF(pad, yHi, w - pad, yLo), this.band);
    const path = new Path();
    const xs = new Array(v.length).fill(0), ys = new Array(v.length).fill(0);
    for (let i = 0; i < v.length; i++) {
      xs[i] = v.length === 1 ? w / 2 : pad + i * (w - 2 * pad) / (v.length - 1);
      ys[i] = bot - (v[i] - min) / (max - min) * (bot - top);
      if (i === 0) path.moveTo(xs[i], ys[i]);
      else path.lineTo(xs[i], ys[i]);
    }
    if (v.length > 1) cv.drawPath(path, this.line);
    const r = Ui.dp(this.getContext(), 3.5);
    for (let i = 0; i < v.length; i++) {
      this.dot.setColor(Labs.abnormal(p, v[i]) ? Ui.RED : Labs.COLOR);
      cv.drawCircle(xs[i], ys[i], r, this.dot);
      if (labels) {
        const s = Labs.fmt(v[i]);
        cv.drawText(s, Math.max(0, Math.min(w - text.measureText(s), xs[i] - text.measureText(s) / 2)), Math.max(text.getTextSize(), ys[i] - r - 2), text);
        if (dates != null && i < dates.size() && (v.length <= 8 || i % 2 === 0 || i === v.length - 1)) {
          const d = Dates.shortFmt(Dates.parse(dates.get(i)));
          cv.drawText(d, Math.max(0, Math.min(w - text.measureText(d), xs[i] - text.measureText(d) / 2)), h - 2, text);
        }
      }
    }
  }
};
;
