'use strict';
/** One patient's lab values: a graph per test and every entry, newest first (tap to edit or delete). */
class LabsActivity extends Base {
  constructor() { super(); this.id = 0; }

  onCreate(b) {
    super.onCreate(b);
    this.id = Long.parseLong(this.getIntent().getStringExtra("id"));
    const p = this.db.row("SELECT name, location, bed FROM patients WHERE id=?", String(this.id));
    this.setTitle("Lab trends");
    this.subtitle = p == null ? "" : p.get("name") + "  ·  " + Db.shortName(p.get("location")) + (Ui.nz(p.get("bed")).isEmpty() ? "" : " bed " + p.get("bed"));
    this.headerColor(Labs.COLOR);
    this.headerAction("+ Add", { onClick: (v) => { Labs.addDialog(this, this.db, this.id, null); } });
  }

  render() {
    const page = Ui.v(this);
    const rows = Labs.rows(this.db, this.id);
    if (rows.isEmpty()) page.addView(this.emptyNote("No lab values yet. Tap + Add."));
    for (const p of Labs.PARAMS) {
      const g = Labs.bigGraph(this, p, rows);
      if (g != null) page.addView(g);
    }
    if (!rows.isEmpty()) page.addView(Ui.heading(this, "All entries  ·  " + rows.size(), Labs.COLOR));
    for (let i = rows.size() - 1; i >= 0; i--) {
      const r = rows.get(i);
      const s = new StringBuilder();
      let bad = false;
      for (const p of Labs.PARAMS) {
        const v = Labs.num(r.get(p.key));
        if (v == null) continue;
        const ab = Labs.abnormal(p, v);
        bad = bad || ab;
        s.append(s.length() === 0 ? "" : "  ·  ").append(p.name).append(" ").append(Labs.fmt(v)).append(ab ? " ⚠" : "");
      }
      page.addView(this.entryCard(bad ? "Abnormal" : "Normal", bad ? Ui.RED : Ui.GREEN, Dates.nice(r.get("date")) + "  " + Ui.nz(r.get("time")),
        s + (Ui.nz(r.get("by_name")).isEmpty() ? "" : "\nBy " + r.get("by_name")), null, { onClick: (v) => { this.entryMenu(r); } }));
    }
    this.setPage(page);
  }

  entryMenu(r) {
    new AlertDialog.Builder(this).setTitle(Dates.nice(r.get("date")))
      .setItems(["Edit", "Delete"], {
        onClick: (d, w) => {
          if (w === 0) Labs.addDialog(this, this.db, this.id, r);
          else Ui.confirm(this, "Delete these lab values?", "This entry is removed from every phone.", "Delete", {
            run: () => { this.db.delete("labs", Long.parseLong(r.get("id"))); this.render(); }
          });
        }
      }).show();
  }
}
;
