/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Learning board: each day the admin sets one topic, faculty and students add their points for 24 hours, and then the
 * points are consolidated (in the app, or written up by an AI) into notes to download as Word or PDF or send on WhatsApp.
 */
class Learning {
  constructor() {}

  static KINDS = ["Pearl", "Fact", "Clinical tip", "Case", "Question", "Reference"];
  static EMOJI = ["💡", "📌", "🩺", "🏥", "❓", "📚"];
  static COLORS = [0xFFF59E0B, 0xFF3B82F6, 0xFF10B981, 0xFF8B5CF6, 0xFFEC4899, 0xFF0EA5E9];
  /** Pastel paper for the sticky notes, one per kind. */
  static PAPER = [0xFFFFF4CC, 0xFFDDEBFF, 0xFFD9F7EA, 0xFFEDE4FF, 0xFFFFE0EF, 0xFFD8F3FC];
  static HEADINGS = ["KEY PEARLS", "FACTS", "CLINICAL TIPS", "CASES SHARED", "QUESTIONS RAISED", "REFERENCES"];
  static HERO = [0xFF6D28D9, 0xFFDB2777, 0xFFF59E0B];
  static COLOR = 0xFF7C3AED;
  static OPEN_MS = 24 * 3600 * 1000;

  static kindIndex(k) {
    const i = Learning.KINDS.indexOf(k);
    return i < 0 ? 0 : i;
  }

  /** The admin (also the HOD and the Medical Registrar) sets the day's topic; anyone on a phone without shared login can. */
  static canSetTopic(c) {
    return !Cloud.active(c) || Cloud.isAdmin(c);
  }

  /** Consolidating: the admin and the faculty (Claude's default: Professors and Assistant Professors too). */
  static canConsolidate(c) {
    if (!Cloud.active(c) || Cloud.isAdmin(c)) return true;
    const r = Cloud.role(c);
    return r.equals("professor") || r.equals("faculty");
  }

  /** Today's topic, else the most recent one; null when there is none yet. */
  static current(db) {
    const t = db.row("SELECT * FROM learn_topics WHERE day=? ORDER BY id DESC LIMIT 1", Dates.todayIso());
    return t != null ? t : db.row("SELECT * FROM learn_topics ORDER BY day DESC, id DESC LIMIT 1");
  }

  static opened(t) {
    try {
      const tm = Ui.nz(t.get("time"));
      return LocalDateTime.parse(t.get("day") + "T" + (tm.length >= 5 ? tm.substring(0, 5) : "00:00"));
    } catch (e) {
      return Dates.today().atStartOfDay();
    }
  }

  static now() {
    return LocalDateTime.of(Dates.today(), Dates.time());
  }

  /** Milliseconds left to add points (0 when the 24 hours are over). */
  static msLeft(t) {
    const left = Duration.between(Learning.now(), Learning.opened(t).plusHours(24)).toMillis();
    return Math.max(0, Math.min(Learning.OPEN_MS, left));
  }

  static open(t) {
    return Learning.msLeft(t) > 0;
  }

  static leftText(ms) {
    const m = Math.trunc(ms / 60000);
    return m >= 60 ? Math.trunc(m / 60) + " h " + (m % 60) + " min left" : m + " min left";
  }

  static points(db, topicId) {
    return db.rows("SELECT p.*, (SELECT COUNT(*) FROM learn_likes l WHERE l.point_id=p.id) AS likes FROM learn_points p WHERE topic_id=? ORDER BY id", topicId);
  }

  static liked(db, pointId, me) {
    return db.num("SELECT COUNT(*) FROM learn_likes WHERE point_id=? AND by_name=?", pointId, me) > 0;
  }

  static contributors(pts) {
    const s = new JSet();
    for (const p of pts) if (!Ui.nz(p.get("by_name")).isEmpty()) s.add(p.get("by_name"));
    return ArrayList(s);
  }

  // ---------- consolidating in the app (no AI) ----------

  static STOP = new JSet(("the and for with that this from are was were has have had not but can may "
      + "its into than then also any all our their there which when what who how why should would could will been being more most "
      + "very such each other some only over under per").jsplit(" "));

  static words(s) {
    const out = new JSet();
    for (const w of Ui.nz(s).toLowerCase().jsplit("[^a-z0-9]+"))
      if (w.length > 2 && !Learning.STOP.contains(w)) out.add(w);
    return out;
  }

  /** How alike two points are: shared words over all words (0 to 1). */
  static alike(a, b) {
    const x = Learning.words(a), y = Learning.words(b);
    if (x.isEmpty() || y.isEmpty()) return 0;
    const both = new JSet(x);
    both.retainAll(y);
    const any = new JSet(x);
    any.addAll(y);
    return both.size() / any.size();
  }

  /**
   * Groups the points by kind, merges points that say the same thing (most of their words shared), keeps the fullest
   * wording with every contributor's name, and puts the most liked first.
   */
  static smart(t, pts) {
    const groups = new JMap();
    for (let k = 0; k < Learning.KINDS.length; k++) groups.put(k, []);
    for (const p of pts) {
      const text = Ui.nz(p.get("text")).trim();
      if (text.isEmpty()) continue;
      const g = groups.get(Learning.kindIndex(p.get("kind")));
      let same = null;
      for (const m of g) if (Learning.alike(m.text, text) >= 0.6) { same = m; break; }
      if (same == null) {
        same = new Learning.Merged();
        same.text = text;
        g.add(same);
      } else if (text.length > same.text.length) {
        same.text = text;
      }
      if (!Ui.nz(p.get("by_name")).isEmpty()) same.by.add(p.get("by_name"));
      same.likes += Ui.toInt(p.get("likes"), 0);
    }
    const b = new StringBuilder();
    b.append("TOPIC: ").append(t.get("title")).append('\n');
    if (!Ui.nz(t.get("about")).isEmpty()) b.append(t.get("about")).append('\n');
    let merged = 0;
    for (const g of groups.values()) merged += g.size();
    b.append("Consolidated from ").append(pts.size()).append(" points by ").append(Learning.contributors(pts).size()).append(" contributors (")
        .append(merged).append(" after joining repeats)  ·  ").append(Dates.nice(t.get("day"))).append('\n');
    for (const e of groups.entrySet()) {
      const g = e.getValue();
      if (g.isEmpty()) continue;
      Collections.sort(g, { compare: (a, c) => c.likes - a.likes });
      b.append('\n').append(Learning.HEADINGS[e.getKey()]).append('\n');
      let n = 1;
      for (const m of g) {
        b.append(n++).append(". ").append(m.text.split('\n').join(' '));
        const who = new StringBuilder();
        for (const w of m.by) who.append(who.isEmpty() ? "" : ", ").append(w);
        if (!who.isEmpty() || m.likes > 0)
          b.append("  (").append(who).append(m.likes > 0 ? (!who.isEmpty() ? " · " : "") + "♥ " + m.likes : "").append(')');
        b.append('\n');
      }
    }
    const c = Learning.contributors(pts);
    if (!c.isEmpty()) b.append("\nCONTRIBUTORS\n").append(TextUtils.join(", ", c)).append('\n');
    return b.toString().trim();
  }

  // ---------- consolidating with an AI ----------

  static AI_MARK = "Consolidate these learning-board points";

  static aiSystem() {
    return "You are a senior physician and medical teacher in the Department of General Medicine at Tirunelveli Medical College "
        + "Hospital, India. Faculty and students posted short points on one topic during the day. Write consolidated teaching notes "
        + "from them.\n- Use the points as the source. Correct a point only when it is clearly wrong, and say so briefly.\n"
        + "- Join repeated points; keep every distinct useful idea.\n"
        + "- Organise under short headings in CAPITALS (for example DEFINITION, CAUSES, CLINICAL FEATURES, INVESTIGATIONS, "
        + "MANAGEMENT, CLINICAL PEARLS, QUESTIONS FOR DISCUSSION), only those that fit, each followed by numbered points.\n"
        + "- Plain text only: no markdown, no asterisks, no tables. 250 to 700 words. End with 3 take-home messages.";
  }

  static aiPrompt(t, pts) {
    const b = new StringBuilder(Learning.AI_MARK + " into teaching notes.\n\nTopic: ").append(t.get("title")).append('\n');
    if (!Ui.nz(t.get("about")).isEmpty()) b.append("About: ").append(t.get("about")).append('\n');
    b.append("\nPoints posted (kind: text):\n");
    let n = 1;
    for (const p of pts) {
      const text = Ui.nz(p.get("text")).trim().split('\n').join(' ');
      if (!text.isEmpty()) b.append(n++).append(". ").append(Ui.nz(p.get("kind"))).append(": ").append(text).append('\n');
    }
    return b.toString();
  }

  /** The chat apps' request with the instructions in front, for pasting into a free AI app. */
  static chatPrompt(t, pts) {
    return Learning.aiSystem() + "\n\n" + Learning.aiPrompt(t, pts);
  }

  /** Markdown the chat apps add (**bold**, # headings, bullets) turned into plain text. */
  static plain(s) {
    let out = Ui.nz(s).split("\r").join("");
    out = out.replace(/^#{1,6}\s*/gm, "").replaceAllRx("\\*\\*(.+?)\\*\\*", "$1").replace(/^\s*[*-]\s+/gm, "• ").split("**").join("");
    return out.trim();
  }

  // ---------- the notes as a document and as a WhatsApp message ----------

  static doc(db, t, pts) {
    const f = new FormDoc();
    f.college = db.setting("college", "Tirunelveli Medical College Hospital");
    f.address = db.setting("address", "Tirunelveli – 627 011, Tamil Nadu");
    f.dept = db.setting("dept", "Department of General Medicine");
    f.title = "LEARNING BOARD · " + Dates.nice(t.get("day")).toUpperCase();
    f.footer = "Learning board  •  " + f.dept + ", " + f.college;
    f.fileBase = "Learning_" + t.get("day") + "_" + Ui.nz(t.get("title")).replaceAllRx("[^A-Za-z0-9]+", "_");
    const top = f.block("TOPIC OF THE DAY", Learning.COLOR, 1);
    top.row(18, new FormDoc.Cell(t.get("title")).b().size(13).color(Learning.COLOR));
    if (!Ui.nz(t.get("about")).isEmpty()) top.row(14, new FormDoc.Cell(t.get("about")).size(9));
    top.row(12, new FormDoc.Cell("Set by " + Ui.nz(t.get("by_name")) + "  ·  " + pts.size() + " points by " + Learning.contributors(pts).size() + " contributors").size(8).color(0xFF64748B));
    let sum = Ui.nz(t.get("summary"));
    if (sum.isEmpty()) sum = Learning.smart(t, pts);
    const s = f.block("CONSOLIDATED NOTES" + (Ui.nz(t.get("summary_how")).isEmpty() ? "" : " (" + t.get("summary_how") + ")"), 0xFFDB2777, 1);
    for (const para of sum.jsplit("\n\n")) s.row(14, new FormDoc.Cell(para).size(9.5));
    const all = f.block("ALL POINTS POSTED", 0xFFF59E0B, 0.06, 0.16, 0.56, 0.22);
    all.row(14, new FormDoc.Cell("No").b().fill(0xFFFFF4CC), new FormDoc.Cell("Kind").b().fill(0xFFFFF4CC),
        new FormDoc.Cell("Point").b().fill(0xFFFFF4CC), new FormDoc.Cell("By").b().fill(0xFFFFF4CC));
    let n = 1;
    for (const p of pts)
      all.row(13, new FormDoc.Cell(String(n++)).center(), new FormDoc.Cell(Ui.nz(p.get("kind"))),
          new FormDoc.Cell(p.get("text")), new FormDoc.Cell(Ui.nz(p.get("by_name"))
              + (Ui.toInt(p.get("likes"), 0) > 0 ? "  ♥ " + p.get("likes") : "")));
    return f;
  }

  static whatsapp(t, pts) {
    let sum = Ui.nz(t.get("summary"));
    if (sum.isEmpty()) sum = Learning.smart(t, pts);
    const b = new StringBuilder("*📚 LEARNING BOARD – ").append(Dates.nice(t.get("day"))).append("*\n*Topic: ").append(t.get("title")).append("*\n\n");
    for (const line of sum.jsplit("\n")) {
      const l = line.trim();
      if (l.startsWith("TOPIC:")) continue;
      const head = l.length > 2 && l.equals(l.toUpperCase()) && l.matches(".*[A-Z].*") && !l.matches("^\\d+\\..*");
      b.append(head ? "*" + l + "*" : l).append('\n');
    }
    b.append("\n_Department of General Medicine, TVMCH · TVMCHMED app_");
    return b.toString();
  }
}

/** A merged point: the fullest wording, everyone who made it, and its likes. */
Learning.Merged = class {
  constructor() { this.text = null; this.by = new JSet(); this.likes = 0; }
};
;
/* ---- app/LearningActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Learning board: the day's topic (set by the admin) on a bright banner, a box to add a point, everyone's points as
 * coloured sticky notes with likes, and, after 24 hours, the consolidated notes to download or send on WhatsApp.
 */
class LearningActivity extends Base {
  constructor() {
    super();
    this.topicId = null;
    this.kind = 0;
    this.draft = "";
    this.busy = false;
  }

  onCreate(b) {
    super.onCreate(b);
    this.topicId = this.getIntent().getStringExtra("topic");
    this.setTitle("Learning board");
    this.headerColor(Learning.COLOR);
  }

  me() {
    const n = Reminders.myName(this, this.db);
    return n.isEmpty() ? "Me" : n;
  }

  topic() {
    if (this.topicId != null) {
      const t = this.db.row("SELECT * FROM learn_topics WHERE id=?", this.topicId);
      if (t != null) return t;
    }
    return Learning.current(this.db);
  }

  render() {
    const t = this.topic();
    const page = Ui.v(this);
    if (Learning.canSetTopic(this)) this.headerAction("+ Topic", { onClick: (v) => { this.topicDialog(null); } });
    if (t == null) {
      this.subtitle = "One topic a day · everyone adds points";
      page.addView(this.emptyHero());
      this.setPage(page);
      return;
    }
    const pts = Learning.points(this.db, t.get("id"));
    const open = Learning.open(t);
    this.subtitle = (Dates.todayIso().equals(t.get("day")) ? "Today's topic" : Dates.nice(t.get("day"))) + "  ·  " + pts.size() + " points";

    page.addView(this.hero(t, pts, open));
    if (open) page.addView(this.composer(t));
    else page.addView(this.closedNote(t));

    // the consolidated notes (or the button to make them)
    page.addView(Ui.heading(this, "Consolidated notes", 0xFFDB2777));
    page.addView(this.summaryCard(t, pts, open));

    // the board
    page.addView(Ui.heading(this, "The board  ·  " + pts.size() + " points", Learning.COLOR));
    page.addView(this.kindsBar(pts));
    if (pts.isEmpty()) page.addView(this.emptyNote(open ? "No points yet. Be the first to add one." : "No points were added."));
    else page.addView(this.board(pts));

    // earlier topics
    const past = this.db.rows("SELECT t.*, (SELECT COUNT(*) FROM learn_points p WHERE p.topic_id=t.id) AS n FROM learn_topics t "
        + "WHERE t.id<>? ORDER BY day DESC, id DESC LIMIT 30", t.get("id"));
    if (!past.isEmpty()) {
      page.addView(Ui.heading(this, "Earlier topics", Ui.PRIMARY));
      page.addView(this.pastStrip(past));
    }
    this.setPage(page);
  }

  // ---------- banner ----------

  emptyHero() {
    const h = Ui.v(this);
    h.setBackground(Glass.hero(this, Learning.HERO, 24));
    h.setPadding(Ui.dp(this, 20), Ui.dp(this, 22), Ui.dp(this, 20), Ui.dp(this, 22));
    h.addView(Ui.tv(this, "📚  Learning board", 22, Color.WHITE, true));
    h.addView(Ui.tv(this, "Every day one topic. Faculty and students add pearls, facts, clinical tips, cases, questions and references "
        + "for 24 hours. Then the points become consolidated notes to download as Word or PDF or send on WhatsApp.", 13, 0xE6FFFFFF, false));
    if (Learning.canSetTopic(this)) {
      const b = Ui.button(this, "+  Set today's topic", Color.WHITE, { onClick: (v) => { this.topicDialog(null); } });
      b.setTextColor(Learning.COLOR);
      h.addView(b);
      Ui.margins(b, 0, 14, 0, 0);
    } else {
      h.addView(Ui.tv(this, "The admin sets the topic. It will appear here.", 13, Color.WHITE, true));
    }
    return this.wrap(h);
  }

  wrap(v) {
    const p = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    p.setMargins(Ui.dp(this, 12), Ui.dp(this, 6), Ui.dp(this, 12), Ui.dp(this, 6));
    v.setLayoutParams(p);
    return v;
  }

  hero(t, pts, open) {
    const h = Ui.v(this);
    h.setBackground(Glass.hero(this, Learning.HERO, 24));
    h.setPadding(Ui.dp(this, 18), Ui.dp(this, 16), Ui.dp(this, 18), Ui.dp(this, 16));
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    const tag = Ui.tv(this, Dates.todayIso().equals(t.get("day")) ? "✨ TOPIC OF THE DAY" : "📅 " + Dates.nice(t.get("day")).toUpperCase(), 11, Color.WHITE, true);
    tag.setLetterSpacing(0.12);
    tag.setBackground(Ui.round(this, 0x33FFFFFF, 12));
    tag.setPadding(Ui.dp(this, 10), Ui.dp(this, 3), Ui.dp(this, 10), Ui.dp(this, 3));
    top.addView(tag);
    const sp = new View(this);
    top.addView(sp, Ui.weight(1));
    if (Learning.canSetTopic(this)) {
      const ed = Ui.tv(this, "Edit", 12, Color.WHITE, true);
      ed.setBackground(Glass.frost(this, 12));
      ed.setPadding(Ui.dp(this, 12), Ui.dp(this, 4), Ui.dp(this, 12), Ui.dp(this, 4));
      ed.setOnClickListener({ onClick: (v) => { this.topicDialog(t); } });
      top.addView(ed);
    }
    h.addView(top);
    const title = Ui.tv(this, t.get("title"), 26, Color.WHITE, true);
    h.addView(title);
    Ui.margins(title, 0, 10, 0, 2);
    if (!Ui.nz(t.get("about")).isEmpty()) h.addView(Ui.tv(this, t.get("about"), 13, 0xE6FFFFFF, false));
    h.addView(Ui.tv(this, "Set by " + Ui.nz(t.get("by_name")), 11, 0xB3FFFFFF, false));

    // time left to add points
    const left = Learning.msLeft(t);
    const track = Ui.h(this);
    track.setBackground(Ui.round(this, 0x33FFFFFF, 5));
    const fill = new View(this);
    fill.setBackground(Ui.round(this, Color.WHITE, 5));
    const frac = left / Learning.OPEN_MS;
    track.addView(fill, new LinearLayout.LayoutParams(0, Ui.dp(this, 8), Math.max(0.001, frac)));
    track.addView(new View(this), new LinearLayout.LayoutParams(0, Ui.dp(this, 8), Math.max(0.001, 1 - frac)));
    const tp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, Ui.dp(this, 8));
    tp.setMargins(0, Ui.dp(this, 12), 0, Ui.dp(this, 4));
    h.addView(track, tp);
    h.addView(Ui.tv(this, open ? "⏳ " + Learning.leftText(left) + " to add points" : "✅ The 24 hours are over: ready to consolidate", 12, Color.WHITE, true));

    // numbers and faces
    const people = Learning.contributors(pts);
    const likes = this.db.num("SELECT COUNT(*) FROM learn_likes WHERE point_id IN (SELECT id FROM learn_points WHERE topic_id=?)", t.get("id"));
    const stats = Ui.h(this);
    stats.addView(this.heroStat(String(pts.size()), "points"), Ui.weight(1));
    stats.addView(this.heroStat(String(people.size()), "contributors"), Ui.weight(1));
    stats.addView(this.heroStat(String(likes), "likes"), Ui.weight(1));
    h.addView(stats);
    Ui.margins(stats, 0, 12, 0, 0);
    if (!people.isEmpty()) {
      const faces = Ui.h(this);
      for (let i = 0; i < Math.min(people.size(), 8); i++) {
        const a = this.avatar(people.get(i), 30);
        faces.addView(a);
        Ui.margins(a, i === 0 ? 0 : -6, 0, 0, 0);
      }
      if (people.size() > 8) faces.addView(Ui.tv(this, "  +" + (people.size() - 8), 13, Color.WHITE, true));
      h.addView(faces);
      Ui.margins(faces, 0, 10, 0, 0);
    }
    return this.wrap(h);
  }

  heroStat(v, label) {
    const l = Ui.v(this);
    l.setGravity(Gravity.CENTER_HORIZONTAL);
    l.setBackground(Glass.frost(this, 14));
    l.setPadding(0, Ui.dp(this, 6), 0, Ui.dp(this, 6));
    const n = Ui.tv(this, v, 20, Color.WHITE, true);
    n.setGravity(Gravity.CENTER);
    l.addView(n);
    const t = Ui.tv(this, label, 11, 0xD9FFFFFF, false);
    t.setGravity(Gravity.CENTER);
    l.addView(t);
    const w = Ui.v(this);
    w.setPadding(Ui.dp(this, 3), 0, Ui.dp(this, 3), 0);
    w.addView(l);
    return w;
  }

  /** A round face with the person's initials, coloured by their name. */
  avatar(name, sizeDp) {
    const parts = Ui.nz(name).replaceAllRx("(?i)^(dr|prof)\\.?\\s+", "").replaceAllRx("(?i)^(dr|prof)\\.?\\s+", "").trim().jsplit("[\\s.]+");
    const ini = new StringBuilder();
    for (const p of parts) if (!p.isEmpty() && ini.toString().length < 2 && Character.isLetter(p.charAt(0))) ini.append(Character.toUpperCase(p.charAt(0)));
    const a = Ui.tv(this, ini.isEmpty() ? "?" : ini.toString(), sizeDp * 0.4, Color.WHITE, true);
    a.setGravity(Gravity.CENTER);
    const c = Ui.UNIT_COLORS[Math.abs(Ui.nz(name).hashCode()) % Ui.UNIT_COLORS.length];
    const g = new GradientDrawable(GradientDrawable.Orientation.TL_BR, [c, Ui.mix(c, Color.BLACK, 0.25)]);
    g.setShape(GradientDrawable.OVAL);
    g.setStroke(Ui.dp(this, 2), Color.WHITE);
    a.setBackground(g);
    a.setLayoutParams(Ui.lp(Ui.dp(this, sizeDp), Ui.dp(this, sizeDp)));
    return a;
  }

  // ---------- adding a point ----------

  composer(t) {
    const card = Ui.card(this);
    card.addView(Ui.tv(this, "Add your point", 16, Ui.TEXT, true));
    card.addView(Ui.muted(this, "Short and useful: one idea per note. Everyone in the department sees it."));
    const chips = Ui.h(this);
    chips.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 6));
    for (let i = 0; i < Learning.KINDS.length; i++) {
      const k = i;
      const c = Ui.chip(this, Learning.EMOJI[i] + " " + Learning.KINDS[i], i === this.kind, Learning.COLORS[i]);
      c.setOnClickListener({
        onClick: (v) => {
          this.kind = k;
          this.render();
        }
      });
      chips.addView(c);
    }
    card.addView(Ui.hscroll(this, chips));
    const box = new EditText(this);
    box.setHint("e.g. " + LearningActivity.example(this.kind));
    box.setText(this.draft);
    box.setMinLines(3);
    box.setGravity(Gravity.TOP | Gravity.START);
    box.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_MULTI_LINE | InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);
    const bg = Ui.round(this, Learning.PAPER[this.kind], 16);
    bg.setStroke(Ui.dp(this, 2), Ui.alpha(Learning.COLORS[this.kind], 0x88));
    box.setBackground(bg);
    box.setPadding(Ui.dp(this, 14), Ui.dp(this, 12), Ui.dp(this, 14), Ui.dp(this, 12));
    box.addTextChangedListener({
      beforeTextChanged: (s, a, b, c) => {},
      onTextChanged: (s, a, b, c) => {},
      afterTextChanged: (e) => { this.draft = e.toString(); }
    });
    card.addView(box);
    const add = Ui.button(this, "Post to the board  " + Learning.EMOJI[this.kind], Learning.COLORS[this.kind], {
      onClick: (v) => {
        const text = box.getText().toString().trim();
        if (text.isEmpty()) {
          Ui.toast(this, "Write your point first");
          return;
        }
        if (!Learning.open(t)) {
          Ui.toast(this, "The 24 hours for this topic are over");
          return;
        }
        const cv = new ContentValues();
        cv.put("topic_id", Long.parseLong(t.get("id")));
        cv.put("kind", Learning.KINDS[this.kind]);
        cv.put("text", text);
        cv.put("by_name", this.me());
        cv.put("by_role", Cloud.active(this) ? Cloud.roleLabel(Cloud.role(this)) : "");
        cv.put("time", Dates.todayIso() + " " + Dates.now());
        this.db.insert("learn_points", cv);
        this.draft = "";
        Ui.toast(this, "Posted. Thank you!");
        this.render();
      }
    });
    card.addView(add);
    Ui.margins(add, 0, 10, 0, 0);
    return card;
  }

  static example(k) {
    switch (k) {
      case 1: return "Normal serum sodium is 135 to 145 mmol/L";
      case 2: return "Correct chronic hyponatraemia by no more than 8 to 10 mmol/L in 24 h";
      case 3: return "A 60-year-old on thiazide came with confusion, Na 112...";
      case 4: return "When is hypertonic saline preferred over normal saline?";
      case 5: return "Harrison's 21st ed., chapter 53; ESE guideline 2014";
      default: return "Always check urine osmolality before treating hyponatraemia";
    }
  }

  closedNote(t) {
    const card = Ui.card(this);
    card.setBackground(Ui.round(this, 0xFFF0FDF4, 18));
    card.addView(Ui.tv(this, "✅ Points closed for this topic", 15, Ui.GREEN, true));
    card.addView(Ui.muted(this, "Points can be added for 24 hours from when the topic was set. "
        + (Learning.canSetTopic(this) ? "Set a new topic with + Topic." : "Watch for the next topic.")));
    return card;
  }

  // ---------- the board ----------

  kindsBar(pts) {
    const row = Ui.h(this);
    row.setPadding(Ui.dp(this, 14), 0, Ui.dp(this, 14), Ui.dp(this, 4));
    for (let i = 0; i < Learning.KINDS.length; i++) {
      let n = 0;
      for (const p of pts) if (Learning.kindIndex(p.get("kind")) === i) n++;
      if (n === 0) continue;
      const c = Ui.softPill(this, Learning.EMOJI[i] + " " + n, Learning.COLORS[i]);
      row.addView(c);
      Ui.margins(c, 0, 0, 6, 0);
    }
    return Ui.hscroll(this, row);
  }

  /** Two columns of sticky notes, each placed in the shorter column (by the length of the text). */
  board(pts) {
    const cols = Ui.h(this);
    cols.setGravity(Gravity.TOP);
    cols.setPadding(Ui.dp(this, 8), Ui.dp(this, 4), Ui.dp(this, 8), 0);
    const a = Ui.v(this), b = Ui.v(this);
    cols.addView(a, Ui.weight(1));
    cols.addView(b, Ui.weight(1));
    let ha = 0, hb = 0;
    // the newest first, the most liked rising to the top of each column
    for (let i = pts.size() - 1; i >= 0; i--) {
      const p = pts.get(i);
      const h = 90 + Ui.nz(p.get("text")).length;
      const note = this.note(p, i);
      if (ha <= hb) {
        a.addView(note);
        ha += h;
      } else {
        b.addView(note);
        hb += h;
      }
    }
    return cols;
  }

  note(p, index) {
    const k = Learning.kindIndex(p.get("kind"));
    const color = Learning.COLORS[k];
    const n = Ui.v(this);
    const bg = Ui.round(this, Learning.PAPER[k], 16);
    n.setBackground(bg);
    n.setElevation(Ui.dp(this, 3));
    n.setRotation(index % 3 === 0 ? -1.4 : index % 3 === 1 ? 1.1 : -0.4);
    n.setPadding(Ui.dp(this, 12), 0, Ui.dp(this, 12), Ui.dp(this, 10));
    // a strip of coloured tape across the top
    const tape = new View(this);
    tape.setBackground(Ui.round(this, Ui.alpha(color, 0xCC), 3));
    const tp = Ui.lp(Ui.dp(this, 46), Ui.dp(this, 9));
    tp.gravity = Gravity.CENTER_HORIZONTAL;
    tp.setMargins(0, Ui.dp(this, 6), 0, Ui.dp(this, 6));
    n.addView(tape, tp);
    const kindv = Ui.tv(this, Learning.EMOJI[k] + "  " + Learning.KINDS[k].toUpperCase(), 10, Ui.mix(color, Color.BLACK, 0.3), true);
    kindv.setLetterSpacing(0.1);
    n.addView(kindv);
    const text = Ui.tv(this, p.get("text"), 14, Ui.TEXT, false);
    text.setLineSpacing(0, 1.12);
    n.addView(text);
    Ui.margins(text, 0, 4, 0, 8);
    const foot = Ui.h(this);
    foot.setGravity(Gravity.CENTER_VERTICAL);
    foot.addView(this.avatar(p.get("by_name"), 24));
    const who = Ui.v(this);
    who.setPadding(Ui.dp(this, 6), 0, Ui.dp(this, 4), 0);
    const nm = Ui.tv(this, Ui.nz(p.get("by_name")), 11, Ui.TEXT, true);
    nm.setSingleLine(true);
    nm.setEllipsize(TextUtils.TruncateAt.END);
    who.addView(nm);
    if (!Ui.nz(p.get("by_role")).isEmpty()) who.addView(Ui.tv(this, p.get("by_role"), 10, Ui.MUTED, false));
    foot.addView(who, Ui.weight(1));
    const mine = Learning.liked(this.db, p.get("id"), this.me());
    const likes = Ui.toInt(p.get("likes"), 0);
    const heart = Ui.tv(this, (mine ? "♥ " : "♡ ") + likes, 13, mine ? Ui.PINK : Ui.MUTED, true);
    heart.setBackground(Ui.round(this, mine ? 0x22DB2777 : 0x10000000, 12));
    heart.setPadding(Ui.dp(this, 8), Ui.dp(this, 2), Ui.dp(this, 8), Ui.dp(this, 2));
    heart.setOnClickListener({ onClick: (v) => { this.like(p.get("id"), mine); } });
    foot.addView(heart);
    n.addView(foot);
    n.setOnLongClickListener({
      onLongClick: (v) => {
        this.noteMenu(p);
        return true;
      }
    });
    const lp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(Ui.dp(this, 5), Ui.dp(this, 7), Ui.dp(this, 5), Ui.dp(this, 7));
    n.setLayoutParams(lp);
    return n;
  }

  like(pointId, mine) {
    if (mine) {
      for (const l of this.db.rows("SELECT id FROM learn_likes WHERE point_id=? AND by_name=?", pointId, this.me()))
        this.db.delete("learn_likes", Long.parseLong(l.get("id")));
    } else {
      const cv = new ContentValues();
      cv.put("point_id", Long.parseLong(pointId));
      cv.put("by_name", this.me());
      this.db.insert("learn_likes", cv);
    }
    this.render();
  }

  /** Long press: copy; the author or the admin can also delete the note. */
  noteMenu(p) {
    const may = this.me().equals(p.get("by_name")) || Learning.canSetTopic(this);
    const items = may ? ["Copy text", "Delete this note"] : ["Copy text"];
    new AlertDialog.Builder(this).setItems(items, {
      onClick: (d, w) => {
        if (w === 0) {
          const cm = this.getSystemService(Context.CLIPBOARD_SERVICE);
          if (cm != null) cm.setPrimaryClip(ClipData.newPlainText("Point", p.get("text")));
          Ui.toast(this, "Copied");
        } else {
          Ui.confirm(this, "Delete this note?", p.get("text"), "Delete", {
            run: () => {
              for (const l of this.db.rows("SELECT id FROM learn_likes WHERE point_id=?", p.get("id")))
                this.db.delete("learn_likes", Long.parseLong(l.get("id")));
              this.db.delete("learn_points", Long.parseLong(p.get("id")));
              this.render();
            }
          });
        }
      }
    }).show();
  }

  pastStrip(past) {
    const row = Ui.h(this);
    row.setPadding(Ui.dp(this, 12), Ui.dp(this, 4), Ui.dp(this, 12), Ui.dp(this, 8));
    let i = 0;
    for (const p of past) {
      const c = Learning.COLORS[i++ % Learning.COLORS.length];
      const card = Ui.v(this);
      card.setBackground(Ui.gradient(this, Ui.shades(c), 18));
      card.setPadding(Ui.dp(this, 14), Ui.dp(this, 12), Ui.dp(this, 14), Ui.dp(this, 12));
      card.addView(Ui.tv(this, Dates.nice(p.get("day")), 11, 0xD9FFFFFF, true));
      const tt = Ui.tv(this, p.get("title"), 15, Color.WHITE, true);
      tt.setMaxLines(2);
      tt.setEllipsize(TextUtils.TruncateAt.END);
      card.addView(tt);
      card.addView(Ui.tv(this, p.get("n") + " points" + (Ui.nz(p.get("summary")).isEmpty() ? "" : "  ·  notes ready"), 11, Color.WHITE, false));
      card.setOnClickListener(this.opener(LearningActivity, "topic", p.get("id")));
      const lp = Ui.lp(Ui.dp(this, 170), LinearLayout.LayoutParams.WRAP_CONTENT);
      lp.rightMargin = Ui.dp(this, 10);
      row.addView(card, lp);
    }
    return Ui.hscroll(this, row);
  }

  // ---------- consolidated notes ----------

  pending(t) {
    return Ai.prefs(this).getBoolean("learn_wait_" + t.get("id"), false);
  }

  summaryCard(t, pts, open) {
    const card = Ui.card(this);
    const bg = Ui.round(this, Color.WHITE, 20);
    bg.setStroke(Ui.dp(this, 2), 0x55DB2777);
    card.setBackground(bg);
    const sum = Ui.nz(t.get("summary"));
    const may = Learning.canConsolidate(this);
    if (!sum.isEmpty()) {
      const hr = Ui.h(this);
      hr.setGravity(Gravity.CENTER_VERTICAL);
      hr.addView(Ui.tv(this, "📝 Notes ready", 16, 0xFFBE185D, true), Ui.weight(1));
      hr.addView(Ui.softPill(this, Ui.nz(t.get("summary_how")).isEmpty() ? "Edited" : t.get("summary_how"), 0xFFDB2777));
      card.addView(hr);
      card.addView(Ui.muted(this, "By " + Ui.nz(t.get("summary_by")) + (Ui.nz(t.get("summary_time")).isEmpty() ? "" : "  ·  " + t.get("summary_time"))));
      const body = Ui.tv(this, sum, 13, Ui.TEXT, false);
      body.setLineSpacing(0, 1.15);
      body.setTextIsSelectable(true);
      card.addView(body);
      Ui.margins(body, 0, 8, 0, 6);
    } else if (open) {
      card.addView(Ui.tv(this, "🕒 Notes after the 24 hours", 15, 0xFFBE185D, true));
      card.addView(Ui.muted(this, "When the time is up, the points are joined into one set of notes" + (may ? ". You can also do it now." : ".")));
    } else {
      card.addView(Ui.tv(this, "Ready to consolidate", 15, 0xFFBE185D, true));
      card.addView(Ui.muted(this, may ? "Choose how to join the points into notes." : "A faculty member or the admin will consolidate the points."));
    }

    // ways to consolidate
    if (may && !pts.isEmpty()) {
      if (this.pending(t)) {
        const paste = Ui.button(this, "📋  Paste the AI's notes", 0xFFDB2777, { onClick: (v) => { this.pasteAnswer(t); } });
        card.addView(paste);
        Ui.margins(paste, 0, 10, 0, 0);
      }
      const r = Ui.h(this);
      const smart = Ui.button(this, "⚡ Consolidate", Learning.COLOR, { onClick: (v) => { this.saveSummary(t, Learning.smart(t, pts), "In the app"); } });
      r.addView(smart, Ui.weight(1));
      const ai = Ui.button(this, "✨ With AI", 0xFFDB2777, { onClick: (v) => { this.chooseAi(t, pts); } });
      r.addView(ai, Ui.weight(1));
      Ui.margins(ai, 8, 0, 0, 0);
      card.addView(r);
      Ui.margins(r, 0, 10, 0, 0);
      if (!sum.isEmpty()) {
        const ed = Ui.outlineButton(this, "Edit the notes", 0xFFDB2777, { onClick: (v) => { this.editSummary(t); } });
        card.addView(ed);
        Ui.margins(ed, 0, 8, 0, 0);
      }
    }

    // download and send (also before consolidating: then the in-app consolidation is used)
    if (!pts.isEmpty()) {
      const r2 = Ui.h(this);
      r2.addView(this.exportButton("Word", 0xFF2563EB, { onClick: (v) => { this.file(t, pts, false); } }), Ui.weight(1));
      r2.addView(this.exportButton("PDF", 0xFFDC2626, { onClick: (v) => { this.file(t, pts, true); } }), Ui.weight(1));
      r2.addView(this.exportButton("WhatsApp", 0xFF16A34A, { onClick: (v) => { this.whatsappText(Learning.whatsapp(t, pts)); } }), Ui.weight(1));
      card.addView(r2);
      Ui.margins(r2, 0, 10, 0, 0);
    }
    return card;
  }

  exportButton(label, color, l) {
    const b = Ui.outlineButton(this, label, color, l);
    const w = Ui.v(this);
    w.setPadding(Ui.dp(this, 3), 0, Ui.dp(this, 3), 0);
    w.addView(b);
    return w;
  }

  saveSummary(t, text, how) {
    const cv = new ContentValues();
    cv.put("summary", text);
    cv.put("summary_by", this.me());
    cv.put("summary_time", Dates.todayIso() + " " + Dates.now());
    cv.put("summary_how", how);
    this.db.update("learn_topics", cv, Long.parseLong(t.get("id")));
    Ai.prefs(this).edit().remove("learn_wait_" + t.get("id")).apply();
    Ui.toast(this, "Notes saved for everyone");
    this.render();
  }

  editSummary(t) {
    const f = new Form(this);
    f.multi("summary", "Consolidated notes", Ui.nz(t.get("summary")));
    Ui.formDialog(this, "Edit the notes", f, "Save", {
      run: () => {
        this.saveSummary(t, f.get("summary").trim(), Ui.nz(t.get("summary_how")).isEmpty() ? "Edited" : t.get("summary_how") + ", edited");
        return true;
      }
    });
  }

  chooseAi(t, pts) {
    const engines = Ai.engines(this);
    const apps = DischargeActivity.CHAT_APPS;
    const items = new Array(engines.size() + apps.length).fill(null);
    for (let i = 0; i < engines.size(); i++) items[i] = Ai.engineLabel(engines.get(i));
    for (let i = 0; i < apps.length; i++) items[engines.size() + i] = "Free " + apps[i][0] + " app (copy and paste)";
    new AlertDialog.Builder(this).setTitle("Consolidate with AI").setItems(items, {
      onClick: (d, w) => {
        if (w < engines.size()) this.runAi(t, pts, engines.get(w));
        else this.freeApp(t, pts, apps[w - engines.size()]);
      }
    }).setNegativeButton("Cancel", null).show();
  }

  /** Claude or Gemini writes the notes inside the app (with the key saved in Settings). */
  runAi(t, pts, engine) {
    if (this.busy) return;
    this.busy = true;
    const wait = new AlertDialog.Builder(this).setTitle("✨ Writing the notes").setMessage(Ai.company(engine) + " is reading " + pts.size() + " points…").setCancelable(false).show();
    const main = new Handler(Looper.getMainLooper());
    new Thread({
      run: () => {
        let out = null, err = null;
        try {
          out = Learning.plain(Ai.single(this, engine, Learning.aiSystem(), Learning.aiPrompt(t, pts), 8000));
        } catch (f) {
          if (f instanceof Ai.Failure) err = f.getMessage();
          else err = "Could not reach the AI: " + f.getMessage();
        }
        const o = out, e = err;
        main.post({
          run: () => {
            this.busy = false;
            try { wait.dismiss(); } catch (ignored) { }
            if (o != null && !o.isEmpty()) this.saveSummary(t, o, Ai.GEMINI.equals(engine) ? "Gemini AI" : "Claude AI");
            else new AlertDialog.Builder(this).setTitle("Not done").setMessage(e == null ? "No answer" : e).setPositiveButton("OK", null).show();
          }
        });
      }
    }).start();
  }

  /** A free chat app: the request is sent there (and copied); the answer comes back with "Paste the AI's notes". */
  freeApp(t, pts, app) {
    const prompt = Learning.chatPrompt(t, pts);
    const cm = this.getSystemService(Context.CLIPBOARD_SERVICE);
    if (cm != null) cm.setPrimaryClip(ClipData.newPlainText("Points for AI", prompt));
    Ai.prefs(this).edit().putBoolean("learn_wait_" + t.get("id"), true).putString("learn_app_" + t.get("id"), app[0]).apply();
    const i = new Intent(Intent.ACTION_SEND);
    i.setType("text/plain");
    i.putExtra(Intent.EXTRA_TEXT, prompt);
    i.setPackage(app[1]);
    i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
    try {
      this.startActivity(i);
      Ui.toast(this, "In " + app[0] + ": send it, tap Copy under the answer, come back and tap Paste");
    } catch (noApp) {
      try {
        this.startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(app[2])).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
        Ui.toast(this, "Copied: paste it in " + app[0]);
      } catch (e) {
        Ui.toast(this, "Copied: open " + app[0] + " and paste it");
      }
    }
    this.render();
  }

  pasteAnswer(t) {
    const cm = this.getSystemService(Context.CLIPBOARD_SERVICE);
    let text = "";
    if (cm != null && cm.hasPrimaryClip() && cm.getPrimaryClip().getItemCount() > 0) {
      const s = cm.getPrimaryClip().getItemAt(0).coerceToText(this);
      text = s == null ? "" : s.toString().trim();
    }
    if (text.isEmpty() || text.contains(Learning.AI_MARK)) {
      new AlertDialog.Builder(this).setTitle("Nothing to paste yet").setMessage(text.isEmpty()
          ? "Copy the AI's answer first (tap Copy under it), then come back and tap Paste."
          : "That is still the request sent to the AI. In the AI app, tap Copy under its answer first.").setPositiveButton("OK", null).show();
      return;
    }
    const app = Ai.prefs(this).getString("learn_app_" + t.get("id"), "AI");
    this.saveSummary(t, Learning.plain(text), app + " AI");
  }

  // ---------- files and WhatsApp ----------

  file(t, pts, pdf) {
    let rel;
    try {
      const f = Learning.doc(this.db, t, pts);
      rel = pdf ? f.pdf(this) : f.docx(this);
    } catch (e) {
      Ui.toast(this, "Could not make the file: " + e.getMessage());
      return;
    }
    const subject = "Learning board: " + t.get("title");
    new AlertDialog.Builder(this).setTitle((pdf ? "PDF" : "Word") + " file ready")
        .setItems(["Send on WhatsApp", "Share (email, Drive…)", "Open"], {
          onClick: (d, w) => {
            if (w === 0) this.whatsappFile(rel, subject);
            else if (w === 1) Store.share(this, rel, subject);
            else Store.openWith(this, rel);
          }
        }).setNegativeButton("Close", null).show();
  }

  whatsappText(text) {
    const i = new Intent(Intent.ACTION_SEND);
    i.setType("text/plain");
    i.putExtra(Intent.EXTRA_TEXT, text);
    for (const pkg of ["com.whatsapp", "com.whatsapp.w4b"]) {
      try {
        this.startActivity(new Intent(i).setPackage(pkg));
        return;
      } catch (ignored) {
      }
    }
    this.startActivity(Intent.createChooser(i, "Share the notes"));
  }

  whatsappFile(rel, subject) {
    const u = Uri.ofRel(rel);
    const i = new Intent(Intent.ACTION_SEND);
    i.setType(mimeOf(rel));
    i.putExtra(Intent.EXTRA_STREAM, u);
    i.setClipData(ClipData.newRawUri(subject, u));
    i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
    for (const pkg of ["com.whatsapp", "com.whatsapp.w4b"]) {
      try {
        this.startActivity(new Intent(i).setPackage(pkg));
        return;
      } catch (ignored) {
      }
    }
    Store.share(this, rel, subject);
  }

  // ---------- the topic ----------

  topicDialog(t) {
    const f = new Form(this);
    f.text("title", "Topic *  (e.g. Hyponatraemia)", t == null ? "" : t.get("title"), Form.TEXT);
    f.multi("about", "What to focus on (optional)", t == null ? "" : Ui.nz(t.get("about")));
    Ui.formDialog(this, t == null ? "Today's topic" : "Edit the topic", f, t == null ? "Start the board" : "Save", {
      run: () => {
        const title = f.get("title").trim();
        if (title.isEmpty()) {
          Ui.toast(this, "Enter the topic");
          return false;
        }
        const cv = new ContentValues();
        cv.put("title", title);
        cv.put("about", f.get("about").trim());
        if (t == null) {
          cv.put("day", Dates.todayIso());
          cv.put("time", Dates.now());
          cv.put("by_name", this.me());
          this.topicId = String(this.db.insert("learn_topics", cv));
        } else {
          this.db.update("learn_topics", cv, Long.parseLong(t.get("id")));
        }
        this.render();
        return true;
      }
    });
  }
}
;
