/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** The department's Postgraduate Leave Application, filled in from a PG leave entry, as PDF or Word. */
class LeaveForm {
  static TYPES = ['Casual leave', 'Medical leave', 'Examination leave', 'Conference / academic', 'Maternity leave', 'Other'];
  static ROMAN = ['I', 'II', 'III'];
  static LABEL = 0xFFE3EAF4;
  static HEAD = 0xFF1E3A5F;
  static OK = 0xFF047857;
  static NO = 0xFFB91C1C;

  static c(t) { return new FormDoc.Cell(t).size(8.5); }
  static lbl(t) { return new FormDoc.Cell(t).b().size(8.5).fill(LeaveForm.LABEL); }
  static hd(t) { return new FormDoc.Cell(t).b().size(8.5).fill(LeaveForm.LABEL).color(LeaveForm.HEAD).center(); }

  /** "____" when the value is not known yet, so the printed form can still be filled by hand. */
  static or(v, blank) { return v == null || v.trim().isEmpty() ? blank : v.trim(); }

  static resume(r) {
    const v = Ui.nz(r.get('resume_date'));
    if (!v.isEmpty()) return v;
    const to = Dates.parse(r.get('to_date'));
    return to == null ? '' : to.plusDays(1).toString();
  }

  static nice(iso) { return iso == null || iso.isEmpty() ? '' : Dates.nice(iso); }

  static build(db, r) {
    const c = LeaveForm.c, lbl = LeaveForm.lbl, hd = LeaveForm.hd, or = LeaveForm.or, nice = LeaveForm.nice, HEAD = LeaveForm.HEAD;
    const pg = db.row('SELECT * FROM staff WHERE id=?', Ui.nz(r.get('staff_id')));
    const name = pg == null ? '' : nz(pg.get('name'));
    const unit = pg == null ? '' : Db.shortName(Ui.nz(pg.get('unit')));
    const year = pg == null ? 0 : CaseSheet.pgYear(pg.get('batch'), Dates.parse(Ui.nz(r.get('applied'))) == null ? Dates.today() : Dates.parse(r.get('applied')));
    const days = Ui.nz(r.get('days')).replaceAllRx('\\.0$', '');
    const from = nice(r.get('from_date')), to = nice(r.get('to_date')), back = nice(LeaveForm.resume(r));
    const duty = Ui.nz(r.get('duty_pg'));
    const dpg = duty.isEmpty() ? null : db.row("SELECT unit FROM staff WHERE name=? AND role='Postgraduate' LIMIT 1", duty);
    const dutyUnit = dpg == null ? '' : Db.shortName(Ui.nz(dpg.get('unit')));

    const f = new FormDoc();
    f.upper = '';
    f.college = db.setting('college', 'Tirunelveli Medical College');
    f.address = 'Tirunelveli';
    f.dept = db.setting('dept', 'Department of General Medicine');
    f.title = 'POSTGRADUATE LEAVE APPLICATION';
    f.footer = 'Leave application of ' + or(name, 'PG') + '  •  ' + f.dept + ', ' + f.college;
    f.fileBase = 'PG_Leave_' + or(name, 'PG').replaceAllRx('[^A-Za-z0-9]+', '_') + '_' + Ui.nz(r.get('from_date'));

    f.plain(1).row(12, new FormDoc.Cell('(For one day or more)').size(7.5).color(0xFF64748B).center());

    const a = f.block('APPLICANT DETAILS', HEAD, 0.18, 0.32, 0.2, 0.3);
    a.row(18, lbl('Name (Dr.)'), c(name.replace(/^dr\.?\s*/i, '')), lbl('Course & Year'),
        c('MD Gen. Med. — ' + (year > 0 ? LeaveForm.ROMAN[year - 1] + ' year' : 'I / II / III')));
    a.row(18, lbl('Unit'), c(unit), lbl('Date of Application'), c(nice(r.get('applied'))));

    const l = f.block('LEAVE DETAILS', HEAD, 0.26, 0.19, 0.19, 0.14, 0.22);
    l.row(16, hd('Type of Leave'), hd('From'), hd('To'), hd('No. of Days'), hd('Resuming Duty On'));
    l.row(22, c(Ui.nz(r.get('leave_type'))).center(), c(from).center(), c(to).center(), c(days).center(), c(back).center());

    const u = or(unit, '________');
    const t = new StringBuilder();
    t.append('To\n      The Professor & Head of the Department\n      ').append(f.dept)
        .append('\n      ').append(f.college).append(', Tirunelveli\n\n');
    t.append('Through: The Assistant Professor and the Unit Chief, Unit ').append(u).append('\n');
    t.append('Subject: Request for grant of leave\n\n');
    t.append('Respected Sir/Madam,\n\n');
    t.append('I respectfully request you to kindly grant me leave for ').append(or(days, '______')).append(' day(s), from ')
        .append(or(from, '______________')).append(' to ').append(or(to, '______________'))
        .append(' (both days inclusive), on account of ').append(or(r.get('reason'), '________________________________')).append('.\n\n');
    t.append('During my absence, Dr. ').append(or(duty.replace(/^dr\.?\s*/i, ''), '______________________'))
        .append(', Postgraduate, Unit ').append(or(dutyUnit, '______'))
        .append(', has kindly agreed to attend to my assigned academic and clinical duties for the above period, subject to the approval of the Unit Chief / Head of the Department.\n\n');
    t.append('I shall resume duty on ').append(or(back, '______________'))
        .append(' and shall ensure that my academic and clinical responsibilities are duly attended to. I kindly request you to consider my application favourably.\n\n');
    t.append('Thanking you,\nYours faithfully,');
    f.plain(1).row(20, new FormDoc.Cell(t.toString()).size(9));

    const s = f.block('SIGNATURES', HEAD, 0.16, 0.21, 0.21, 0.21, 0.21);
    s.row(16, lbl(''), hd('Applicant'), hd('Doing-Duty PG'), hd('Assistant Professor'), hd('Unit Chief'));
    s.row(20, lbl('Name'), c(name), c(duty), c(Ui.nz(r.get('ap_by'))), c(Ui.nz(r.get('prof_by'))));
    s.row(30, lbl('Signature'), c(''), c(''), LeaveForm.sig(r, 'ap'), LeaveForm.sig(r, 'prof'));
    s.row(18, lbl('Date'), c(nice(r.get('applied'))), c(''), c(nice(r.get('ap_date'))), c(nice(r.get('prof_date'))));

    const hs = Ui.nz(r.get('hod_status'));
    const yes = hs.equals('Approved'), no = hs.equals('Not approved');
    const o = f.block('FOR OFFICE USE — HEAD OF THE DEPARTMENT', HEAD, 1);
    o.keep = true;
    o.row(18, c('Decision:   ' + FormDoc.boxes(['Approved', 'Not Approved'], [yes, no])).b());
    o.row(18, c('Leave sanctioned for ' + (yes ? days : '______') + ' day(s), from ' + (yes ? from : '______________') + ' to ' + (yes ? to : '______________')));
    o.row(18, c('Remarks: ' + (no ? 'Not approved in the TVMCHMED app' : '____________________________________________________________')));
    o.row(30, c('Signature: ' + (hs.isEmpty() || hs.equals('Pending') ? '______________________' : '(' + hs.toLowerCase() + ' in the app by ' + Ui.nz(r.get('hod_by')) + ')')
        + '                    Date: ' + or(nice(r.get('hod_date')), '______________')
        + '\nProfessor & HOD, ' + f.dept).bottom());
    return f;
  }

  /** An approval given in the app, shown in the signature box; the box stays blank for a wet signature otherwise. */
  static sig(r, level) {
    const st = Ui.nz(r.get(level + '_status'));
    if (st.equals('Approved')) return LeaveForm.c('Approved in the app').color(LeaveForm.OK).center();
    if (st.equals('Not approved')) return LeaveForm.c('Not approved in the app').color(LeaveForm.NO).center();
    return LeaveForm.c('');
  }

  /** Makes the PDF or Word file and offers to share or open it. */
  static make(a, r, pdf) {
    let rel;
    try {
      const f = LeaveForm.build(a.db, r);
      rel = pdf ? f.pdf(a) : f.docx(a);
    } catch (e) {
      Ui.toast(a, 'Could not make the leave form: ' + e.getMessage());
      return;
    }
    new AlertDialog.Builder(a).setTitle((pdf ? 'PDF' : 'Word') + ' leave form ready')
        .setItems(['Share (WhatsApp, email…)', 'Open'], {
          onClick: (d, w) => {
            if (w === 0) Store.share(a, rel, 'PG leave application');
            else Store.openWith(a, rel);
          }
        }).setNegativeButton('Close', null).show();
  }

  /** Asks PDF or Word. */
  static choose(a, r) {
    new AlertDialog.Builder(a).setTitle('Download leave form')
        .setItems(['PDF', 'Word'], {
          onClick: (d, w) => { LeaveForm.make(a, r, w === 0); }
        }).setNegativeButton('Cancel', null).show();
  }
}
;
/* ---- app/LiveCensusActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Live census: every ward of the department on one screen, with the numbers changing as patients are admitted,
 * moved, discharged or die on any phone. Today's movement counts from 7:30 AM (the admission day). A number that
 * just changed pulses and shows its change for two minutes.
 */
class LiveCensusActivity extends Base {
  static COLOR = 0xFF0E7490;
  static REFRESH_MS = 15000;
  static CHANGE_SHOWN_MS = 120000;

  /** The last value seen of each number, and when and by how much it last changed (kept while the app runs). */
  static last = new JMap();
  static delta = new JMap();
  static changedAt = new JMap();

  static TABLE_HEAD = ["Ward", "Now", "Male", "Female", "Admitted", "Moved in", "Moved out", "Discharged", "Died", "Usual"];

  constructor() {
    super();
    this.handler = new Handler(Looper.getMainLooper());
    this.refresher = {
      run: () => {
        Sync.kick(this);
        this.render();
        this.handler.postDelayed(this.refresher, LiveCensusActivity.REFRESH_MS);
      }
    };
  }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Live census");
    this.headerColor(LiveCensusActivity.COLOR);
  }

  onResume() {
    super.onResume();
    this.handler.removeCallbacks(this.refresher);
    this.handler.postDelayed(this.refresher, LiveCensusActivity.REFRESH_MS);
  }

  onPause() {
    super.onPause();
    this.handler.removeCallbacks(this.refresher);
  }

  /** The admission day's start (7:30 AM) as a condition on events.date / events.time. */
  static since(day) {
    return "(date>'" + day + "' OR (date='" + day + "' AND IFNULL(time,'')>='07:30'))";
  }

  n(sql, ...args) {
    if (args.length === 1 && Array.isArray(args[0])) args = args[0];
    return this.db.num(sql, ...args);
  }

  /** Records a number and returns its change since it was last different (0 when unchanged for 2 minutes). */
  track(key, value) {
    const L = LiveCensusActivity;
    const now = System.currentTimeMillis();
    const old = L.last.get(key);
    if (old != null && old !== value) {
      L.delta.put(key, value - old);
      L.changedAt.put(key, now);
    }
    L.last.put(key, value);
    const at = L.changedAt.get(key);
    return at != null && now - at < L.CHANGE_SHOWN_MS ? L.delta.get(key) : 0;
  }

  render() {
    const day = Dates.admitDay().toString();
    const sinceSql = LiveCensusActivity.since(day);
    this.subtitle = "All wards at once  ·  updated " + Dates.time().toString().substring(0, 5);
    const page = Ui.v(this);

    // ---- hero: the whole department ----
    const total = this.db.totalInpatients();
    const male = this.n("SELECT COUNT(*) FROM patients WHERE status='IN' AND location<>'KDP' AND sex='M'");
    const female = total - male;
    const vent = this.n("SELECT COUNT(*) FROM patients WHERE status='IN' AND vent='1'");
    const adm = this.n("SELECT COUNT(*) FROM events WHERE type='ADMIT' AND " + sinceSql);
    const trf = this.n("SELECT COUNT(*) FROM events WHERE type='TRANSFER' AND " + sinceSql);
    const dis = this.n("SELECT COUNT(*) FROM events WHERE type='DISCHARGE' AND " + sinceSql);
    const died = this.n("SELECT COUNT(*) FROM events WHERE type='DEATH' AND " + sinceSql);

    const hero = Ui.v(this);
    hero.setBackground(Glass.hero(this, Ui.HERO, 24));
    hero.setPadding(Ui.dp(this, 18), Ui.dp(this, 16), Ui.dp(this, 18), Ui.dp(this, 16));
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    top.addView(this.liveDot());
    const live = Ui.tv(this, "  LIVE", 12, Color.WHITE, true);
    live.setLetterSpacing(0.15);
    top.addView(live);
    const sp = new View(this);
    top.addView(sp, Ui.weight(1));
    const au = this.db.admittingUnits(Dates.dow(Dates.admitDay()));
    const today = Ui.tv(this, "Admitting today: " + (au.isEmpty() ? "-" : TextUtils.join(", ", au)), 12, Color.WHITE, true);
    today.setBackground(Ui.round(this, 0x33FFFFFF, 14));
    today.setPadding(Ui.dp(this, 10), Ui.dp(this, 3), Ui.dp(this, 10), Ui.dp(this, 3));
    top.addView(today);
    hero.addView(top);

    const big = Ui.h(this);
    big.setGravity(Gravity.BOTTOM);
    const tn = Ui.tv(this, String(total), 54, Color.WHITE, true);
    big.addView(tn);
    const tl = Ui.v(this);
    tl.setPadding(Ui.dp(this, 12), 0, 0, Ui.dp(this, 12));
    tl.addView(Ui.tv(this, "inpatients now", 15, Color.WHITE, true));
    tl.addView(Ui.tv(this, "at TVMCH, all medicine wards", 12, 0xCCFFFFFF, false));
    big.addView(tl, Ui.weight(1));
    const dt = this.track("total", total);
    if (dt !== 0) {
      big.addView(this.changeBadge(dt, true));
      LiveCensusActivity.pulse(tn);
    }
    hero.addView(big);
    hero.addView(this.sexBar(male, female, true));
    const mf = Ui.h(this);
    mf.addView(Ui.tv(this, "♂ Male " + male, 12, Color.WHITE, true), Ui.weight(1));
    const fv = Ui.tv(this, "Female " + female + " ♀", 12, Color.WHITE, true);
    fv.setGravity(Gravity.END);
    mf.addView(fv, Ui.weight(1));
    hero.addView(mf);

    // today's movement, on frosted chips
    const moves = Ui.h(this);
    moves.addView(this.heroStat("adm", adm, "Admitted"), Ui.weight(1));
    moves.addView(this.heroStat("trf", trf, "Moved"), Ui.weight(1));
    moves.addView(this.heroStat("dis", dis, "Discharged"), Ui.weight(1));
    moves.addView(this.heroStat("died", died, "Died"), Ui.weight(1));
    moves.addView(this.heroStat("vent", vent, "Ventilator"), Ui.weight(1));
    hero.addView(moves);
    Ui.margins(moves, 0, 12, 0, 0);
    hero.addView(Ui.tv(this, "Movement since 7:30 AM  ·  refreshes by itself every 15 seconds", 11, 0xB3FFFFFF, false));
    const hp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    hp.setMargins(Ui.dp(this, 12), Ui.dp(this, 6), Ui.dp(this, 12), Ui.dp(this, 4));
    page.addView(hero, hp);

    // ---- the census table: every ward, every number ----
    page.addView(Ui.heading(this, "Census table  ·  all wards now", LiveCensusActivity.COLOR));
    page.addView(this.table(sinceSql));

    // ---- where everyone is: one bar, a segment per ward ----
    page.addView(Ui.heading(this, "Where the patients are", LiveCensusActivity.COLOR));
    const sc = Ui.card(this);
    const wards = ArrayList(Db.CENSUS_WARDS);
    const counts = new Array(wards.size()).fill(0);
    const colors = new Array(wards.size()).fill(0);
    for (let i = 0; i < wards.size(); i++) {
      counts[i] = this.db.census(wards.get(i), null);
      colors[i] = Ui.unitColor(wards.get(i));
    }
    sc.addView(new LiveCensusActivity.ShareBar(this, counts, colors), Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, Ui.dp(this, 22)));
    const legend = new LiveCensusActivity.FlowRow(this);
    for (let i = 0; i < wards.size(); i++) {
      if (counts[i] === 0) continue;
      legend.addView(this.legendItem(Db.shortName(wards.get(i)) + " " + counts[i], colors[i]));
    }
    sc.addView(legend);
    Ui.margins(legend, 0, 8, 0, 0);
    page.addView(sc);

    // ---- the wards ----
    page.addView(Ui.heading(this, "Medical units  ·  " + this.sum(Db.WARD_UNITS) + " in their own wards", Ui.PRIMARY));
    page.addView(this.grid(Db.WARD_UNITS, sinceSql));
    const special = [];
    for (const w of Db.CENSUS_WARDS) if (!Db.isWardUnit(w)) special.add(w);
    const sp2 = special;
    page.addView(Ui.heading(this, "Special wards  ·  " + this.sum(sp2) + " inpatients", Ui.RED));
    page.addView(this.grid(sp2, sinceSql));

    // ---- each unit's responsibility, wherever its patients are ----
    page.addView(Ui.heading(this, "Each unit's patients, wherever they are", Ui.PURPLE));
    page.addView(this.unitTable());

    // ---- Kandiyaperi ----
    page.addView(Ui.heading(this, "Peripheral hospital", Ui.unitColor(Db.KDP)));
    page.addView(this.grid([Db.KDP], sinceSql));
    this.setPage(page);
  }

  /** One row per ward (units, special wards, Kandiyaperi) and a total row; today's columns count from 7:30 AM. */
  table(sinceSql) {
    const TABLE_HEAD = LiveCensusActivity.TABLE_HEAD;
    const card = Ui.card(this);
    card.setPadding(0, Ui.dp(this, 6), 0, Ui.dp(this, 6));
    const t = new TableLayout(this);
    t.addView(this.tableRow(TABLE_HEAD, LiveCensusActivity.COLOR, true, 0));
    const wards = ArrayList(Db.CENSUS_WARDS);
    wards.add(Db.KDP);
    const tot = new Array(TABLE_HEAD.length - 1).fill(0);
    let i = 0;
    for (const w of wards) {
      const unit = Db.isWardUnit(w);
      const v = [
          this.db.census(w, null), this.db.census(w, "M"), this.db.census(w, "F"),
          unit ? this.n("SELECT COUNT(*) FROM events WHERE type='ADMIT' AND from_loc=? AND " + sinceSql, w)
              : this.n("SELECT COUNT(*) FROM events WHERE type='ADMIT' AND to_loc=? AND " + sinceSql, w),
          this.n("SELECT COUNT(*) FROM events WHERE type='TRANSFER' AND to_loc=? AND " + sinceSql, w),
          this.n("SELECT COUNT(*) FROM events WHERE type='TRANSFER' AND from_loc=? AND " + sinceSql, w),
          this.n("SELECT COUNT(*) FROM events WHERE type='DISCHARGE' AND from_loc=? AND " + sinceSql, w),
          this.n("SELECT COUNT(*) FROM events WHERE type='DEATH' AND from_loc=? AND " + sinceSql, w),
          Db.CCB.equals(w) ? 12 : Db.IMCU.equals(w) ? Db.TOX_BEDS + Db.NONTOX_BEDS : this.db.capacity(w)];
      const cells = new Array(TABLE_HEAD.length).fill(null);
      cells[0] = unit ? w + " unit" : Db.shortName(w);
      for (let k = 0; k < v.length; k++) {
        cells[k + 1] = String(v[k]);
        if (!Db.KDP.equals(w)) tot[k] += v[k];
      }
      const row = this.tableRow(cells, Ui.unitColor(w), false, i++);
      row.setOnClickListener(Db.KDP.equals(w) ? this.opener(KdpActivity) : this.opener(UnitActivity, "code", w));
      t.addView(row);
    }
    // the department's admissions are each counted once, under the admitting unit
    tot[3] = this.n("SELECT COUNT(*) FROM events WHERE type='ADMIT' AND IFNULL(to_loc,'')<>'KDP' AND " + sinceSql);
    const cells = new Array(TABLE_HEAD.length).fill(null);
    cells[0] = "TVMCH total";
    for (let k = 0; k < tot.length; k++) cells[k + 1] = String(tot[k]);
    t.addView(this.tableRow(cells, Ui.PRIMARY, true, 0));
    card.addView(Ui.hscroll(this, t));
    card.addView(this.pad(Ui.muted(this, "Admitted: by the unit for M1 to M7, into the ward for special wards; the total counts each admission once. Moved in / out, discharged and died: since 7:30 AM. Tap a row to open the ward. Kandiyaperi is left out of the TVMCH total.")));
    return card;
  }

  pad(v) {
    v.setPadding(Ui.dp(this, 14), Ui.dp(this, 6), Ui.dp(this, 14), 0);
    return v;
  }

  tableRow(cells, color, head, index) {
    const row = new TableRow(this);
    row.setBackgroundColor(head ? Ui.mix(color, Color.WHITE, 0.88) : index % 2 === 1 ? 0xFFF8FAFC : Color.WHITE);
    for (let k = 0; k < cells.length; k++) {
      let c;
      if (k === 0 && !head) {
        c = Ui.tv(this, cells[k], 13, Color.WHITE, true);
        c.setBackground(Ui.round(this, color, 10));
        c.setPadding(Ui.dp(this, 8), Ui.dp(this, 3), Ui.dp(this, 8), Ui.dp(this, 3));
      } else {
        const zero = !head && "0".equals(cells[k]);
        const col = head ? Ui.mix(color, Color.BLACK, 0.35) : zero ? 0xFFCBD5E1
            : k === 1 ? Ui.TEXT : k === 4 || k === 5 ? Ui.ORANGE : k === 7 ? Ui.GREEN : k === 8 ? Ui.RED : Ui.SLATE;
        c = Ui.tv(this, cells[k], k === 1 && !head ? 15 : 13, col, head || k === 1);
        c.setGravity(k === 0 ? Gravity.START : Gravity.CENTER);
        c.setPadding(Ui.dp(this, 8), Ui.dp(this, 7), Ui.dp(this, 8), Ui.dp(this, 7));
      }
      const lp = new TableRow.LayoutParams(WRAP_CONTENT, WRAP_CONTENT);
      lp.gravity = Gravity.CENTER_VERTICAL;
      lp.setMargins(k === 0 ? Ui.dp(this, 10) : 0, Ui.dp(this, 2), 0, Ui.dp(this, 2));
      row.addView(c, lp);
    }
    return row;
  }

  sum(wards) {
    let s = 0;
    for (const w of wards) s += this.db.census(w, null);
    return s;
  }

  // ---------- pieces ----------

  liveDot() {
    const dot = new View(this);
    dot.setBackground(Ui.round(this, 0xFF4ADE80, 6));
    dot.setLayoutParams(Ui.lp(Ui.dp(this, 10), Ui.dp(this, 10)));
    const a = new AlphaAnimation(1, 0.25);
    a.setDuration(800);
    a.setRepeatMode(Animation.REVERSE);
    a.setRepeatCount(Animation.INFINITE);
    dot.startAnimation(a);
    return dot;
  }

  static pulse(v) {
    const s = new ScaleAnimation(1, 1.18, 1, 1.18, Animation.RELATIVE_TO_SELF, 0.5, Animation.RELATIVE_TO_SELF, 0.5);
    s.setDuration(450);
    s.setRepeatMode(Animation.REVERSE);
    s.setRepeatCount(3);
    v.startAnimation(s);
  }

  /** ▲2 / ▼1: how a number just changed. */
  changeBadge(d, onDark) {
    const t = Ui.tv(this, (d > 0 ? "▲" : "▼") + Math.abs(d), 12, onDark ? Ui.TEXT : Color.WHITE, true);
    t.setBackground(Ui.round(this, onDark ? Color.WHITE : (d > 0 ? Ui.ORANGE : Ui.GREEN), 10));
    t.setPadding(Ui.dp(this, 7), Ui.dp(this, 1), Ui.dp(this, 7), Ui.dp(this, 1));
    return t;
  }

  heroStat(key, value, label) {
    const l = Ui.v(this);
    l.setGravity(Gravity.CENTER_HORIZONTAL);
    l.setBackground(Glass.frost(this, 14));
    l.setPadding(Ui.dp(this, 2), Ui.dp(this, 6), Ui.dp(this, 2), Ui.dp(this, 6));
    const nv = Ui.tv(this, String(value), 20, Color.WHITE, true);
    nv.setGravity(Gravity.CENTER);
    l.addView(nv);
    const lv = Ui.tv(this, label, 10, 0xD9FFFFFF, false);
    lv.setGravity(Gravity.CENTER);
    lv.setSingleLine(true);
    l.addView(lv);
    if (this.track(key, value) !== 0) LiveCensusActivity.pulse(nv);
    const wrap = Ui.v(this);
    wrap.setPadding(Ui.dp(this, 3), 0, Ui.dp(this, 3), 0);
    wrap.addView(l);
    return wrap;
  }

  /** Blue / pink proportion bar of male and female patients. */
  sexBar(m, f, onDark) {
    const track = Ui.h(this);
    track.setBackground(Ui.round(this, onDark ? 0x33FFFFFF : Ui.LINE, 5));
    const all = m + f;
    const a = new View(this), b = new View(this);
    a.setBackground(Ui.round(this, 0xFF60A5FA, 5));
    b.setBackground(Ui.round(this, 0xFFF472B6, 5));
    if (all > 0) {
      track.addView(a, new LinearLayout.LayoutParams(0, Ui.dp(this, 8), m));
      track.addView(b, new LinearLayout.LayoutParams(0, Ui.dp(this, 8), f));
    } else {
      track.addView(new View(this), new LinearLayout.LayoutParams(0, Ui.dp(this, 8), 1));
    }
    const p = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, Ui.dp(this, 8));
    p.setMargins(0, Ui.dp(this, 6), 0, Ui.dp(this, 4));
    track.setLayoutParams(p);
    return track;
  }

  legendItem(s, color) {
    const l = Ui.h(this);
    l.setGravity(Gravity.CENTER_VERTICAL);
    const sw = new View(this);
    sw.setBackground(Ui.round(this, color, 3));
    l.addView(sw, Ui.lp(Ui.dp(this, 10), Ui.dp(this, 10)));
    const t = Ui.tv(this, " " + s, 12, Ui.TEXT, false);
    l.addView(t);
    l.setPadding(0, Ui.dp(this, 2), Ui.dp(this, 12), Ui.dp(this, 2));
    return l;
  }

  grid(wards, sinceSql) {
    const g = Ui.v(this);
    g.setPadding(Ui.dp(this, 7), 0, Ui.dp(this, 7), 0);
    let row = null;
    for (let i = 0; i < wards.length; i++) {
      if (i % 2 === 0) {
        row = Ui.h(this);
        row.setGravity(Gravity.TOP);
        g.addView(row);
      }
      const p = Ui.weight(1);
      p.setMargins(Ui.dp(this, 5), Ui.dp(this, 5), Ui.dp(this, 5), Ui.dp(this, 5));
      row.addView(this.wardCard(wards[i], sinceSql), p);
    }
    if (wards.length % 2 === 1) {
      const p = Ui.weight(1);
      p.setMargins(Ui.dp(this, 5), Ui.dp(this, 5), Ui.dp(this, 5), Ui.dp(this, 5));
      row.addView(new View(this), p);
    }
    return g;
  }

  /** Green under 85 % of the usual load, amber to 100 %, red above. */
  static loadColor(value, cap) {
    if (cap <= 0) return Ui.TEAL;
    const f = value / cap;
    return f < 0.85 ? Ui.GREEN : f <= 1 ? Ui.AMBER : Ui.RED;
  }

  wardCard(code, sinceSql) {
    const color = Ui.unitColor(code);
    const unit = Db.isWardUnit(code);
    const total = this.db.census(code, null), m = this.db.census(code, "M"), f = this.db.census(code, "F");
    const cap = Db.CCB.equals(code) ? 12 : Db.IMCU.equals(code) ? Db.TOX_BEDS + Db.NONTOX_BEDS : this.db.capacity(code);
    const inN = unit ? this.n("SELECT COUNT(*) FROM events WHERE type='ADMIT' AND from_loc=? AND " + sinceSql, code)
        : this.n("SELECT COUNT(*) FROM events WHERE type IN ('ADMIT','TRANSFER') AND to_loc=? AND " + sinceSql, code);
    const out = this.n("SELECT COUNT(*) FROM events WHERE type IN ('TRANSFER','DISCHARGE','DEATH') AND from_loc=? AND " + sinceSql, code);

    const card = Ui.v(this);
    card.setBackground(Ui.round(this, Color.WHITE, 20));
    card.setElevation(Ui.dp(this, 2));
    // coloured band with the ward's name
    const band = Ui.h(this);
    band.setGravity(Gravity.CENTER_VERTICAL);
    band.setBackground(Ui.gradient(this, Ui.shades(color), 20));
    band.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 10), Ui.dp(this, 8));
    const name = Ui.tv(this, unit ? code + " unit" : Db.shortName(code), 14, Color.WHITE, true);
    name.setSingleLine(true);
    band.addView(name, Ui.weight(1));
    const d = this.track("w:" + code, total);
    if (d !== 0) band.addView(this.changeBadge(d, true));
    card.addView(band);

    const body = Ui.v(this);
    body.setPadding(Ui.dp(this, 12), Ui.dp(this, 10), Ui.dp(this, 12), Ui.dp(this, 12));
    const r = Ui.h(this);
    r.setGravity(Gravity.CENTER_VERTICAL);
    const ring = new LiveCensusActivity.Ring(this, total, cap, LiveCensusActivity.loadColor(total, cap));
    r.addView(ring, Ui.lp(Ui.dp(this, 70), Ui.dp(this, 70)));
    if (d !== 0) LiveCensusActivity.pulse(ring);
    const side = Ui.v(this);
    side.setPadding(Ui.dp(this, 10), 0, 0, 0);
    side.addView(Ui.tv(this, "♂ " + m + "   ♀ " + f, 13, Ui.TEXT, true));
    side.addView(Ui.tv(this, cap > 0 ? (Db.CCB.equals(code) || Db.IMCU.equals(code) ? Math.max(0, cap - total) + " beds free" : "usual ~" + cap) : "", 11, Ui.MUTED, false));
    const io = Ui.h(this);
    io.addView(Ui.softPill(this, "+" + inN, Ui.ORANGE));
    const o = Ui.softPill(this, "−" + out, Ui.GREEN);
    io.addView(o);
    Ui.margins(o, 6, 0, 0, 0);
    side.addView(io);
    Ui.margins(io, 0, 4, 0, 0);
    r.addView(side, Ui.weight(1));
    body.addView(r);
    body.addView(this.sexBar(m, f, false));

    // the extra line each ward needs
    let extra;
    let ec = Ui.MUTED;
    if (unit) {
      const away = this.db.awayFrom(code);
      extra = away > 0 ? away + " more in special wards" : "Admits " + Dates.DAYS[Ui.toInt(this.db.unit(code).get("admit_day"), 0)];
      if (away > 0) ec = Ui.RED;
    } else if (Db.IMCU.equals(code)) {
      const v = this.n("SELECT COUNT(*) FROM patients WHERE status='IN' AND location='IMCU' AND vent='1'");
      extra = v + " on ventilator";
      if (v > 0) ec = Ui.RED;
    } else if (Db.FEVER.equals(code)) {
      const dg = this.n("SELECT COUNT(*) FROM patients WHERE status='IN' AND location='FEVER' AND dengue='1'");
      extra = dg + " dengue positive";
    } else if (Db.KDP.equals(code)) {
      extra = "Kandiyaperi OP & IP";
    } else {
      extra = "Under the admitting units";
    }
    const tasks = Tasks.inWard(this.db, code);
    if (tasks > 0) {
      extra += "  ·  ⏳ " + tasks;
    }
    body.addView(Ui.tv(this, extra, 11, ec, (ec | 0) !== (Ui.MUTED | 0)));
    card.addView(body);
    Ui.ripple(card, Ui.alpha(color, 0x22));
    card.setOnClickListener(Db.KDP.equals(code) ? this.opener(KdpActivity) : this.opener(UnitActivity, "code", code));
    return card;
  }

  /** M1..M7: own ward plus each special ward, as one stacked bar per unit. */
  unitTable() {
    const card = Ui.card(this);
    const locs = ArrayList(Db.CENSUS_WARDS);
    for (const u of Db.WARD_UNITS) {
      const cs = [];
      const cols = [];
      let all = 0;
      // own ward first, then the special wards holding its patients
      const own = this.n("SELECT COUNT(*) FROM patients WHERE status='IN' AND location=?", u);
      cs.add(own);
      cols.add(Ui.unitColor(u));
      all += own;
      for (const w of locs) {
        if (Db.isWardUnit(w)) continue;
        const c = this.db.awayFrom(u, w);
        if (c === 0) continue;
        cs.add(c);
        cols.add(Ui.unitColor(w));
        all += c;
      }
      const row = Ui.h(this);
      row.setGravity(Gravity.CENTER_VERTICAL);
      row.setPadding(0, Ui.dp(this, 5), 0, Ui.dp(this, 5));
      const name = Ui.pill(this, u, Ui.unitColor(u));
      row.addView(name, Ui.lp(Ui.dp(this, 46), LinearLayout.LayoutParams.WRAP_CONTENT));
      const a = new Array(cs.size()).fill(0), b = new Array(cols.size()).fill(0);
      for (let i = 0; i < a.length; i++) { a[i] = cs.get(i); b[i] = cols.get(i); }
      const bp = new LinearLayout.LayoutParams(0, Ui.dp(this, 16), 1);
      bp.setMargins(Ui.dp(this, 10), 0, Ui.dp(this, 10), 0);
      row.addView(new LiveCensusActivity.ShareBar(this, a, b), bp);
      const tv = Ui.tv(this, String(all), 16, Ui.TEXT, true);
      tv.setGravity(Gravity.END);
      row.addView(tv, Ui.lp(Ui.dp(this, 36), LinearLayout.LayoutParams.WRAP_CONTENT));
      if (this.track("u:" + u, all) !== 0) LiveCensusActivity.pulse(tv);
      row.setOnClickListener(this.opener(UnitActivity, "code", u));
      card.addView(row);
    }
    card.addView(Ui.muted(this, "Each bar: the unit's own ward first, then its patients in triage, step-down, IMCU, CCB, fever, ID and other wards (colours as above)."));
    return card;
  }
}

// ---------- drawn views ----------

/** Occupancy ring: the arc fills with the census against the usual load; the number sits in the middle. */
LiveCensusActivity.Ring = class extends View {
  constructor(c, value, cap, color) {
    super(c);
    this.val = value;
    this.capN = cap;
    this.col = color;
    this.paint = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.rect = new RectF();
  }

  onDraw(cv) {
    const p = this.paint, r = this.rect, value = this.val, cap = this.capN, color = this.col;
    const w = this.getWidth(), h = this.getHeight(), s = Math.min(w, h), stroke = s * 0.11;
    r.set((w - s) / 2 + stroke, (h - s) / 2 + stroke, (w + s) / 2 - stroke, (h + s) / 2 - stroke);
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeWidth(stroke);
    p.setStrokeCap(Paint.Cap.ROUND);
    p.setColor(Ui.mix(color, Color.WHITE, 0.82));
    cv.drawArc(r, 0, 360, false, p);
    const frac = cap > 0 ? Math.min(1, value / cap) : value > 0 ? 1 : 0;
    p.setColor(color);
    if (frac > 0) cv.drawArc(r, -90, Math.max(4, 360 * frac), false, p);
    p.setStyle(Paint.Style.FILL);
    p.setColor(Ui.TEXT);
    p.setTypeface(Typeface.DEFAULT_BOLD);
    p.setTextAlign(Paint.Align.CENTER);
    p.setTextSize(s * (value >= 100 ? 0.26 : 0.32));
    cv.drawText(String(value), w / 2, h / 2 + p.getTextSize() * 0.22, p);
    if (cap > 0) {
      p.setTypeface(Typeface.DEFAULT);
      p.setColor(Ui.MUTED);
      p.setTextSize(s * 0.13);
      cv.drawText(Math.round(100 * value / cap) + "%", w / 2, h / 2 + s * 0.24, p);
    }
  }
};

/** A rounded bar split into coloured segments in proportion to the counts. */
LiveCensusActivity.ShareBar = class extends View {
  constructor(c, counts, colors) {
    super(c);
    this.cnts = counts;
    this.cols = colors;
    this.paint = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.rect = new RectF();
  }

  onDraw(cv) {
    const p = this.paint, r = this.rect, counts = this.cnts, colors = this.cols;
    const w = this.getWidth(), h = this.getHeight(), rad = h / 2;
    let all = 0;
    for (const v of counts) all += v;
    p.setColor(Ui.LINE);
    r.set(0, 0, w, h);
    cv.drawRoundRect(r, rad, rad, p);
    if (all === 0) return;
    cv.save();
    const clip = new Path();
    clip.addRoundRect(r, rad, rad, Path.Direction.CW);
    cv.clipPath(clip);
    let x = 0;
    const gap = Math.max(1, h * 0.08);
    for (let i = 0; i < counts.length; i++) {
      if (counts[i] === 0) continue;
      const seg = w * counts[i] / all;
      p.setColor(colors[i]);
      cv.drawRect(x, 0, x + seg - (x + seg < w - 1 ? gap : 0), h, p);
      x += seg;
    }
    cv.restore();
  }
};

/** Lays its children left to right, wrapping to a new line when the row is full (for the legend). */
LiveCensusActivity.FlowRow = class extends FlowLayout {
  constructor(c) {
    super(c, 0, 0);
  }
};
