'use strict';
/** Live quiz: join a quiz with a PIN; faculty and PGs also see their quizzes, make new ones and host them live. */
class LiveQuizActivity extends Base {

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Live quiz");
    this.subtitle = "Play together in class, like Kahoot";
    this.headerColors = Quiz.GRADIENT;
    if (Quiz.canHost(this)) this.headerAction("+ New quiz", this.opener(QuizEditActivity));
  }

  render() {
    const page = Ui.v(this);
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Quiz.GRADIENT, 20));
    hero.addView(Ui.tv(this, "🎮  Join a live quiz", 20, Color.WHITE, true));
    const link = Quiz.joinLink(this.db);
    hero.addView(Ui.tv(this, "Enter the game PIN shown on the screen. Students without the app open "
        + (link.isEmpty() ? "the web app's quiz page" : link) + " in any phone browser.", 13, 0xE6FFFFFF, false));
    const join = Ui.button(this, "Enter PIN", Quiz.COLORS[3], this.opener(QuizPlayActivity));
    hero.addView(join);
    Ui.margins(join, 0, 12, 0, 0);
    page.addView(hero);

    if (!Quiz.canHost(this)) {
      if (!Cloud.active(this)) page.addView(this.emptyNote("Live quiz needs the shared database: sign in from Settings › Account."));
      this.setPage(page);
      return;
    }
    page.addView(Ui.heading(this, "Quizzes", Quiz.PURPLE));
    const sets = this.db.rows("SELECT * FROM quiz_sets ORDER BY time DESC, id DESC");
    if (sets.isEmpty()) page.addView(this.emptyNote("No quizzes yet. Tap + New quiz, type your questions or add them from the Daily MCQs, then Host live."));
    for (const s of sets) {
      const n = Quiz.questions(s).length();
      const card = this.entryCard(n + (n === 1 ? " question" : " questions"), Quiz.PURPLE, Ui.nz(s.get("title")),
          "By " + Ui.nz(s.get("by_name")), Dates.nice(Ui.nz(s.get("time")).length >= 10 ? s.get("time").substring(0, 10) : ""),
          this.opener(QuizEditActivity, "id", s.get("id")));
      if (n > 0) {
        const host = Ui.button(this, "▶  Host live", Quiz.PURPLE, this.opener(QuizHostActivity, "id", s.get("id")));
        card.addView(host);
        Ui.margins(host, 0, 10, 0, 0);
      }
      page.addView(card);
    }

    page.addView(Ui.heading(this, "Student link", Quiz.PURPLE));
    const lc = Ui.card(this);
    lc.addView(Ui.muted(this, link.isEmpty() ? "Add the web app's address (for example tvmchmed.netlify.app) so the big screen shows students where to join without the app."
        : "Shown on the big screen: " + link));
    const edit = Ui.outlineButton(this, link.isEmpty() ? "Add web app address" : "Change", Quiz.PURPLE, { onClick: (v) => { this.editLink(); } });
    lc.addView(edit);
    Ui.margins(edit, 0, 10, 0, 0);
    page.addView(lc);
    this.setPage(page);
  }

  editLink() {
    const f = new Form(this);
    f.text("url", "Web app address", this.db.setting("quiz_url", ""), Form.PLAIN);
    Ui.formDialog(this, "Student link", f, "Save", {
      run: () => {
        this.db.setSetting("quiz_url", f.get("url").trim());
        this.render();
        return true;
      }
    });
  }

  /** Saves a quiz (new when id < 0) and returns its id. */
  static save(db, c, id, title, qs) {
    const cv = new ContentValues();
    cv.put("title", title);
    cv.put("questions", qs.toString());
    cv.put("by_name", Approvals.me(c));
    cv.put("time", Dates.todayIso() + " " + Dates.now());
    if (id < 0) return db.insert("quiz_sets", cv);
    db.update("quiz_sets", cv, id);
    return id;
  }
}
