/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** The PG procedure logbook: what counts, and who signs. */
class Logbook {
  constructor() {}

  static COLOR = 0xFF4338CA;
  static PENDING = "Pending";
  static SIGNED = "Signed";
  static RETURNED = "Returned";
  static PROCEDURES = ["Central venous line", "Lumbar puncture", "Endotracheal intubation", "Pleural tap", "Intercostal drain",
      "Ascitic tap", "Bone marrow aspiration", "Arterial blood gas", "Arterial line", "Mechanical ventilation", "Non-invasive ventilation",
      "CPR / ACLS", "DC cardioversion / defibrillation", "Temporary pacemaker", "Pericardiocentesis", "Knee joint aspiration",
      "Liver biopsy", "Renal biopsy", "Haemodialysis catheter", "Plasmapheresis (PLEX)", "Ryle's tube", "Urinary catheter",
      "Upper GI endoscopy", "ECHO (bedside)", "USG-guided procedure", "Other"];
  static ROLES = ["Performed under supervision", "Performed independently", "Assisted", "Observed"];

  /** Faculty sign the logbook: the Assistant / Associate Professors, Professors, HOD, Medical Registrar and admin. */
  static canSign(c) {
    return SessionAttendance.canRun(c);
  }

  /** The PG's own staff entry when this phone belongs to a PG, else -1. */
  static myPg(c, db) {
    const id = Cloud.myStaff(c);
    if (id <= 0) return -1;
    const s = db.row("SELECT role FROM staff WHERE id=?", String(id));
    return s != null && ("Postgraduate".equals(s.get("role")) || "CRMI".equals(s.get("role"))) ? id : -1;
  }

  /** Entries waiting for this faculty member's signature: those naming them as supervisor, or any when no one is named. */
  static waitingToSign(c, db) {
    if (!Logbook.canSign(c)) return 0;
    const me = CallDutyActivity.myName(c);
    let n = 0;
    for (const r of db.rows("SELECT supervisor FROM logbook WHERE status=?", Logbook.PENDING)) {
      const sup = Ui.nz(r.get("supervisor"));
      if (sup.isEmpty() || me.isEmpty() || Chat.sameName(sup, me)) n++;
    }
    return n;
  }
}
;
/* ---- app/LogbookActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * PG logbook: PGs log the procedures they do (central line, LP, intubation, pleural tap…); faculty sign each entry
 * or return it with a remark. Each PG's logbook can be saved as a PDF.
 */
class LogbookActivity extends Base {
  constructor() { super(); this.toSign = false; this.pg = -1; }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("PG logbook");
    this.subtitle = "Procedures logged by PGs, signed by faculty";
    this.headerColor(Logbook.COLOR);
    this.pg = Logbook.myPg(this, this.db);
    this.toSign = this.pg <= 0 && Logbook.canSign(this) && Logbook.waitingToSign(this, this.db) > 0;
    if (b != null) {
      this.pg = b.getLong("pg", this.pg);
      this.toSign = b.getBoolean("toSign", this.toSign);
    }
    if (this.pg <= 0) {
      const first = this.db.row("SELECT id FROM staff WHERE role='Postgraduate' AND " + Approvals.APPROVED_SQL + " ORDER BY name LIMIT 1");
      if (first != null) this.pg = Long.parseLong(first.get("id"));
    }
    this.headerAction("+ Log", {
      onClick: (v) => { this.entryDialog(null); }
    });
  }

  onSaveInstanceState(out) {
    super.onSaveInstanceState(out);
    out.putLong("pg", this.pg);
    out.putBoolean("toSign", this.toSign);
  }

  render() {
    const page = Ui.v(this);
    if (Logbook.canSign(this)) {
      const tabs = Ui.h(this);
      tabs.setPadding(Ui.dp(this, 12), Ui.dp(this, 6), Ui.dp(this, 12), 0);
      const a = Ui.chip(this, "To sign · " + Logbook.waitingToSign(this, this.db), this.toSign, Ui.AMBER);
      a.setOnClickListener({
        onClick: (v) => { this.toSign = true; this.render(); }
      });
      const b = Ui.chip(this, "PG logbooks", !this.toSign, Logbook.COLOR);
      b.setOnClickListener({
        onClick: (v) => { this.toSign = false; this.render(); }
      });
      tabs.addView(a);
      tabs.addView(b);
      Ui.margins(b, 8, 0, 0, 0);
      page.addView(tabs);
    }
    if (this.toSign && Logbook.canSign(this)) this.renderToSign(page);
    else this.renderPg(page);
    this.setPage(page);
  }

  renderToSign(page) {
    const db = this.db;
    const me = CallDutyActivity.myName(this);
    let n = 0;
    page.addView(Ui.heading(this, "Waiting for your signature", Ui.AMBER));
    for (const r of db.rows("SELECT * FROM logbook WHERE status=? ORDER BY date, id", Logbook.PENDING)) {
      const sup = Ui.nz(r.get("supervisor"));
      if (!sup.isEmpty() && !me.isEmpty() && !Chat.sameName(sup, me)) continue;
      page.addView(this.entryRow(r, true));
      n++;
    }
    if (n == 0) page.addView(this.emptyNote("Nothing to sign."));
    const others = db.rows("SELECT * FROM logbook WHERE status=? AND supervisor<>'' ORDER BY date, id", Logbook.PENDING);
    let k = 0;
    for (const r of others) if (me.isEmpty() || !Chat.sameName(r.get("supervisor"), me)) k++;
    if (k > 0) page.addView(Ui.muted(this, "      " + k + " more " + (k == 1 ? "entry is" : "entries are") + " waiting for other faculty."));
  }

  renderPg(page) {
    const db = this.db;
    const pg = this.pg;
    const s = pg > 0 ? db.row("SELECT * FROM staff WHERE id=?", String(pg)) : null;
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(Logbook.COLOR), 20));
    hero.addView(Ui.tv(this, s == null ? "No PG chosen" : s.get("name"), 20, Color.WHITE, true));
    hero.addView(Ui.tv(this, s == null ? "Add PGs in Students" : Ui.nz(s.get("role")) + (Ui.nz(s.get("unit")).isEmpty() ? "" : " · " + s.get("unit"))
      + (Ui.nz(s.get("batch")).isEmpty() ? "" : " · " + s.get("batch")), 13, 0xD9FFFFFF, false));
    const total = pg > 0 ? db.num("SELECT COUNT(*) FROM logbook WHERE staff_id=?", String(pg)) : 0;
    const signed = pg > 0 ? db.num("SELECT COUNT(*) FROM logbook WHERE staff_id=? AND status=?", String(pg), Logbook.SIGNED) : 0;
    const stats = Ui.statRow(this, this.white(String(total), "Logged"), this.white(String(signed), "Signed"),
      this.white(String(pg > 0 ? db.num("SELECT COUNT(*) FROM logbook WHERE staff_id=? AND status=?", String(pg), Logbook.PENDING) : 0), "Waiting"));
    hero.addView(stats);
    Ui.margins(stats, 0, 8, 0, 0);
    const btns = Ui.h(this);
    const change = Ui.outlineButton(this, "Choose PG", Logbook.COLOR, {
      onClick: (v) => { this.choosePg(); }
    });
    btns.addView(change, Ui.weight(1));
    if (total > 0) {
      const pdf = Ui.outlineButton(this, "Save as PDF", Logbook.COLOR, {
        onClick: (v) => { this.pdf(); }
      });
      btns.addView(pdf, Ui.weight(1));
      Ui.margins(pdf, 8, 0, 0, 0);
    }
    hero.addView(btns);
    Ui.margins(btns, 0, 10, 0, 0);
    page.addView(hero);
    if (pg <= 0) return;

    // procedures done so far, signed count first
    const count = new JMap();
    for (const r of db.rows("SELECT procedure, status FROM logbook WHERE staff_id=? ORDER BY procedure", String(pg))) {
      let c = count.get(r.get("procedure"));
      if (c == null) { c = [0, 0]; count.put(r.get("procedure"), c); }
      c[0]++;
      if (Logbook.SIGNED.equals(r.get("status"))) c[1]++;
    }
    if (!count.isEmpty()) {
      page.addView(Ui.heading(this, "Procedures  ·  " + count.size() + " kinds", Logbook.COLOR));
      const card = Ui.card(this);
      for (const e of count.entrySet()) {
        const r = Ui.h(this);
        r.setGravity(Gravity.CENTER_VERTICAL);
        r.addView(Ui.tv(this, e.getKey(), 14, Ui.TEXT, false), Ui.weight(1));
        r.addView(Ui.tv(this, e.getValue()[0] + "  (" + e.getValue()[1] + " signed)", 13, e.getValue()[1] == e.getValue()[0] ? Ui.GREEN : Ui.AMBER, true));
        card.addView(r);
        Ui.margins(r, 0, 3, 0, 3);
      }
      page.addView(card);
    }
    const rows = db.rows("SELECT * FROM logbook WHERE staff_id=? ORDER BY date DESC, id DESC", String(pg));
    page.addView(Ui.heading(this, "Entries  ·  " + rows.size(), Logbook.COLOR));
    if (rows.isEmpty()) page.addView(this.emptyNote("No procedures logged yet. Tap + Log."));
    for (const r of rows) page.addView(this.entryRow(r, false));
  }

  white(v, l) {
    const s = Ui.v(this);
    s.setGravity(Gravity.CENTER);
    s.addView(Ui.tv(this, v, 20, Color.WHITE, true));
    s.addView(Ui.tv(this, l, 11, 0xD9FFFFFF, false));
    return s;
  }

  static statusColor(st) {
    return Logbook.SIGNED.equals(st) ? Ui.GREEN : Logbook.RETURNED.equals(st) ? Ui.RED : Ui.AMBER;
  }

  entryRow(r, showPg) {
    const sub = (showPg ? Ui.nz(r.get("pg")) + "  ·  " : "") + Dates.nice(r.get("date")) + "  ·  " + Ui.nz(r.get("role"))
      + (Ui.nz(r.get("patient")).isEmpty() ? "" : "\n" + r.get("patient") + (Ui.nz(r.get("ip_no")).isEmpty() ? "" : " · IP " + r.get("ip_no")))
      + (Ui.nz(r.get("ward")).isEmpty() ? "" : " · " + Db.shortName(r.get("ward")))
      + (Ui.nz(r.get("notes")).isEmpty() ? "" : "\n" + r.get("notes"))
      + (Logbook.SIGNED.equals(r.get("status")) ? "\n✓ Signed by " + r.get("signed_by") + " · " + Ui.nz(r.get("signed_time"))
        : Ui.nz(r.get("supervisor")).isEmpty() ? "" : "\nSupervisor: " + r.get("supervisor"))
      + (Ui.nz(r.get("remarks")).isEmpty() ? "" : "\nRemark: " + r.get("remarks"));
    return this.entryCard(r.get("status"), LogbookActivity.statusColor(r.get("status")), Ui.nz(r.get("procedure")), sub, null, {
      onClick: (v) => { this.tap(r); }
    });
  }

  tap(r) {
    const mine = Ui.toInt(r.get("staff_id"), -2) == Logbook.myPg(this, this.db);
    const sign = Logbook.canSign(this) && !Logbook.SIGNED.equals(r.get("status"));
    if (sign) this.signDialog(r);
    else if (mine && !Logbook.SIGNED.equals(r.get("status"))) this.entryDialog(r);
    else if (!Cloud.active(this)) this.entryDialog(r);
  }

  choosePg() {
    const pgs = this.db.rows("SELECT id, name, unit FROM staff WHERE role IN ('Postgraduate','CRMI') AND " + Approvals.APPROVED_SQL + " ORDER BY role DESC, name");
    if (pgs.isEmpty()) {
      Ui.toast(this, "Add PGs in Students first");
      return;
    }
    const names = new Array(pgs.size()).fill(null);
    for (let i = 0; i < names.length; i++) names[i] = pgs.get(i).get("name") + (Ui.nz(pgs.get(i).get("unit")).isEmpty() ? "" : "  (" + pgs.get(i).get("unit") + ")");
    new AlertDialog.Builder(this).setTitle("Whose logbook?").setItems(names, {
      onClick: (d, w) => {
        this.pg = Long.parseLong(pgs.get(w).get("id"));
        this.toSign = false;
        this.render();
      }
    }).show();
  }

  entryDialog(r) {
    const db = this.db;
    const mine = Logbook.myPg(this, db);
    const f = new Form(this);
    const pgs = db.rows("SELECT id, name FROM staff WHERE role IN ('Postgraduate','CRMI') AND " + Approvals.APPROVED_SQL + " ORDER BY name");
    if (mine <= 0 || (r != null && Ui.toInt(r.get("staff_id"), 0) != mine)) {
      if (pgs.isEmpty()) {
        Ui.toast(this, "Add PGs in Students first");
        return;
      }
      const l = new Array(pgs.size()).fill(null), v = new Array(pgs.size()).fill(null);
      for (let i = 0; i < l.length; i++) { l[i] = pgs.get(i).get("name"); v[i] = pgs.get(i).get("id"); }
      f.choice("pg", "PG", l, v, r != null ? r.get("staff_id") : this.pg > 0 ? String(this.pg) : v[0], null);
    }
    f.date("date", "Date", r == null ? Dates.todayIso() : r.get("date"));
    f.choice("procedure", "Procedure", Logbook.PROCEDURES, Logbook.PROCEDURES, r == null ? Logbook.PROCEDURES[0] : r.get("procedure"), null);
    f.text("other", "If other, which procedure", r == null || Logbook.PROCEDURES.contains(r.get("procedure")) ? "" : r.get("procedure"), Form.PLAIN);
    f.choice("role", "Your part", Logbook.ROLES, Logbook.ROLES, r == null ? Logbook.ROLES[0] : r.get("role"), null);
    const all = PatientPick.inpatients(db, null);
    f.suggest("patient", "Patient (name or IP number)", r == null ? "" : r.get("patient"), all.keySet());
    f.suggest("supervisor", "Supervising faculty (signs this entry)", r == null ? "" : r.get("supervisor"),
      db.staffNames("AND role IN ('Assistant Professor','Associate Professor','Professor')"));
    f.multi("notes", "Indication, findings, complications", r == null ? "" : r.get("notes"));
    Ui.formDialog(this, r == null ? "Log a procedure" : "Edit entry", f, "Save", {
      run: () => {
        const who = f.has("pg") ? Long.parseLong(f.get("pg")) : mine;
        const proc = f.get("procedure").equals("Other") && !f.get("other").trim().isEmpty() ? f.get("other").trim() : f.get("procedure");
        const cv = new ContentValues();
        cv.put("staff_id", who);
        const s = db.row("SELECT name FROM staff WHERE id=?", String(who));
        cv.put("pg", s == null ? "" : s.get("name"));
        cv.put("date", f.get("date"));
        cv.put("procedure", proc);
        cv.put("role", f.get("role"));
        const p = PatientPick.find(all, f.get("patient"));
        cv.put("patient", p == null ? f.get("patient").trim() : Ui.nz(p.get("name")));
        cv.put("ip_no", p == null ? (r == null ? "" : Ui.nz(r.get("ip_no"))) : Ui.nz(p.get("ip_no")));
        cv.put("ward", p == null ? (r == null ? "" : Ui.nz(r.get("ward"))) : Ui.nz(p.get("location")));
        cv.put("supervisor", f.get("supervisor").trim());
        cv.put("notes", f.get("notes").trim());
        cv.put("status", Logbook.PENDING);
        cv.put("remarks", "");
        cv.put("time", Dates.todayIso() + " " + Dates.now());
        if (r == null) db.insert("logbook", cv);
        else db.update("logbook", cv, Long.parseLong(r.get("id")));
        this.pg = who;
        this.toSign = false;
        this.render();
        return true;
      }
    });
  }

  signDialog(r) {
    const f = new Form(this);
    const dec = ["Sign", "Return to the PG"];
    f.segment("decision", "Decision", dec, dec[0], dec[0]);
    f.multi("remarks", "Remark (optional; say what to correct when returning)", Ui.nz(r.get("remarks")));
    Ui.formDialog(this, r.get("procedure") + " · " + r.get("pg"), f, "Save", {
      run: () => {
        const rem = f.get("remarks").trim();
        if (f.get("decision").equals(dec[0])) this.save(r, Logbook.SIGNED, rem);
        else this.save(r, Logbook.RETURNED, rem.isEmpty() ? "Please correct and resubmit" : rem);
        return true;
      }
    });
  }

  save(r, status, remarks) {
    const cv = new ContentValues();
    cv.put("status", status);
    cv.put("remarks", remarks);
    cv.put("signed_by", Logbook.SIGNED.equals(status) ? CallDutyActivity.myName(this) : "");
    cv.put("signed_time", Logbook.SIGNED.equals(status) ? Dates.todayIso() + " " + Dates.now() : "");
    this.db.update("logbook", cv, Long.parseLong(r.get("id")));
    this.render();
  }

  pdf() {
    const db = this.db;
    const s = db.row("SELECT * FROM staff WHERE id=?", String(this.pg));
    if (s == null) return;
    const f = new FormDoc();
    f.college = db.setting("college", "Tirunelveli Medical College Hospital");
    f.address = db.setting("address", "Tirunelveli – 627 011, Tamil Nadu");
    f.dept = db.setting("dept", "Department of General Medicine");
    f.title = "PG PROCEDURE LOGBOOK";
    f.footer = s.get("name") + "  •  " + f.dept + ", " + f.college;
    f.fileBase = "Logbook_" + s.get("name").replaceAllRx("[^A-Za-z0-9]+", "_");
    const h = f.block(null, 0, 0.5, 0.25, 0.25);
    h.row(16, new FormDoc.Cell("PG: " + s.get("name")).b(), new FormDoc.Cell("Unit: " + Ui.nz(s.get("unit"))).b(), new FormDoc.Cell("Batch: " + Ui.nz(s.get("batch"))).b());
    const t = f.block("PROCEDURES", FormDoc.NAVY, 0.05, 0.11, 0.2, 0.17, 0.2, 0.27);
    t.row(14, new FormDoc.Cell("No").b(), new FormDoc.Cell("Date").b(), new FormDoc.Cell("Procedure").b(), new FormDoc.Cell("Part").b(),
      new FormDoc.Cell("Patient / IP").b(), new FormDoc.Cell("Signed by").b());
    let i = 0;
    for (const r of db.rows("SELECT * FROM logbook WHERE staff_id=? ORDER BY date, id", String(this.pg))) {
      t.row(14, new FormDoc.Cell(String(++i)), new FormDoc.Cell(Dates.nice(r.get("date"))), new FormDoc.Cell(r.get("procedure")),
        new FormDoc.Cell(r.get("role")), new FormDoc.Cell(Ui.nz(r.get("patient")) + (Ui.nz(r.get("ip_no")).isEmpty() ? "" : " / " + r.get("ip_no"))),
        new FormDoc.Cell(Logbook.SIGNED.equals(r.get("status")) ? r.get("signed_by") + "\n" + Ui.nz(r.get("signed_time")) : r.get("status")));
    }
    try {
      const rel = f.pdf(this);
      Store.share(this, rel, "Logbook " + s.get("name"));
    } catch (e) {
      Ui.toast(this, "Could not make the PDF: " + e.getMessage());
    }
  }
}
;
