/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Daily MCQ: faculty post a case-based question each day; students (and anyone) answer once on their own phone.
 * Every answer is recorded, so the faculty see how many answered and how many were right, option by option.
 * The explanation opens after answering.
 */
class Mcq {
  constructor() {}

  static LETTERS = ["A", "B", "C", "D", "E"];
  static SUBJECTS = ["General medicine", "Cardiology", "Neurology", "Nephrology", "Pulmonology", "Gastroenterology & hepatology",
      "Endocrinology & metabolism", "Infectious diseases", "Haematology", "Rheumatology", "Toxicology", "Critical care", "ECG & imaging", "Pharmacology"];
  static LEVELS = ["All", "MBBS", "PG"];
  /** Card gradient: deep indigo to violet to pink. */
  static GRADIENT = [0xFF312E81, 0xFF6D28D9, 0xFFDB2777];

  /** Only faculty (and the admin, HOD) post questions; a phone without shared login belongs to its user. */
  static canPost(c) {
    return SessionAttendance.canRun(c);
  }

  static options(q) {
    const out = [];
    for (const l of Mcq.LETTERS) {
      const o = Ui.nz(q.get("opt_" + l.toLowerCase()));
      if (!o.isEmpty()) out.add(o);
    }
    return out;
  }

  // ---------- which question ----------

  /** Today's question for the home card: the first one not yet answered, else the latest of today, else the latest. */
  static featured(c, db) {
    const me = SessionAttendance.me(c, db);
    const t = Dates.todayIso();
    const today = db.rows("SELECT * FROM mcqs WHERE date=? ORDER BY id", t);
    for (const q of today) if (me == null || Mcq.mine(db, q.get("id"), me) == null) return q;
    if (!today.isEmpty()) return today.get(today.size() - 1);
    return db.row("SELECT * FROM mcqs WHERE date<=? ORDER BY date DESC, id DESC LIMIT 1", t);
  }

  // ---------- answers ----------

  static mine(db, mcqId, me) {
    if (me == null) return null;
    return db.row("SELECT * FROM mcq_answers WHERE mcq_id=? AND (staff_id=? OR name=?) ORDER BY time LIMIT 1", mcqId, me.get("id"), me.get("name"));
  }

  /** Records an answer (first answer counts). Returns whether it was right, or null if already answered. */
  static answer(db, c, q, me, letter) {
    if (Mcq.mine(db, q.get("id"), me) != null) return null;
    const right = letter.equals(q.get("answer"));
    const cv = new ContentValues();
    cv.put("mcq_id", q.get("id"));
    cv.put("staff_id", me.get("id"));
    cv.put("name", me.get("name"));
    cv.put("role", me.get("role"));
    cv.put("choice", letter);
    cv.put("correct", right ? "1" : "0");
    cv.put("time", LocalDateTime.now().withNano(0).toString());
    db.insert("mcq_answers", cv);
    return right;
  }

  static answered(db, mcqId) {
    return db.num("SELECT COUNT(*) FROM mcq_answers WHERE mcq_id=?", mcqId);
  }

  static correct(db, mcqId) {
    return db.num("SELECT COUNT(*) FROM mcq_answers WHERE mcq_id=? AND correct='1'", mcqId);
  }

  static picked(db, mcqId, letter) {
    return db.num("SELECT COUNT(*) FROM mcq_answers WHERE mcq_id=? AND choice=?", mcqId, letter);
  }

  static percent(part, whole) {
    return whole === 0 ? 0 : Math.round(part * 100 / whole);
  }

  /** Days in a row (ending today or yesterday) on which this person answered at least one MCQ. */
  static streak(db, me) {
    if (me == null) return 0;
    const days = db.rows("SELECT DISTINCT substr(time,1,10) AS d FROM mcq_answers WHERE staff_id=? OR name=? ORDER BY d DESC",
        me.get("id"), me.get("name"));
    let expect = Dates.today();
    let n = 0;
    for (let i = 0; i < days.size(); i++) {
      const d = Dates.parse(days.get(i).get("d"));
      if (d == null) continue;
      if (i === 0 && d.equals(expect.minusDays(1))) expect = d;
      if (!d.equals(expect)) break;
      n++;
      expect = expect.minusDays(1);
    }
    return n;
  }

  /** This month's top scorers: name, role, right, answered. */
  static leaders(db, month, limit) {
    const m0 = Dates.monthStart(month).toString(), m1 = Dates.monthStart(month).plusMonths(1).toString();
    return db.rows("SELECT name, role, SUM(correct='1') AS ok, COUNT(*) AS n FROM mcq_answers WHERE time>=? AND time<? "
        + "GROUP BY name ORDER BY ok DESC, n ASC, MIN(time) LIMIT " + limit, m0, m1);
  }

  // ---------- the home card ----------

  /** A modern glass card for the home page: today's case, streak, a ring of how many got it right, one tap to answer. */
  static homeCard(a, db) {
    const q = Mcq.featured(a, db);
    const poster = Mcq.canPost(a);
    if (q == null && !poster) return null;
    const me = SessionAttendance.me(a, db);
    const card = Ui.v(a);
    card.setBackground(Glass.hero(a, Mcq.GRADIENT, 24));
    card.setPadding(Ui.dp(a, 18), Ui.dp(a, 16), Ui.dp(a, 18), Ui.dp(a, 16));
    card.setElevation(Ui.dp(a, 6));
    Glass.softShadow(card, 0xFF6D28D9);
    const lp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(Ui.dp(a, 12), Ui.dp(a, 12), Ui.dp(a, 12), Ui.dp(a, 4));
    card.setLayoutParams(lp);

    const top = Ui.h(a);
    top.setGravity(Gravity.CENTER_VERTICAL);
    const tag = Ui.tv(a, "✦  DAILY MCQ", 11, Color.WHITE, true);
    tag.setLetterSpacing(0.12);
    tag.setBackground(Glass.frost(a, 14));
    tag.setPadding(Ui.dp(a, 10), Ui.dp(a, 4), Ui.dp(a, 10), Ui.dp(a, 4));
    top.addView(tag);
    const sp = new View(a);
    top.addView(sp, Ui.weight(1));
    const st = Mcq.streak(db, me);
    if (st > 0) {
      const s = Ui.tv(a, "🔥 " + st + "-day streak", 12, Color.WHITE, true);
      s.setBackground(Ui.round(a, 0x33000000, 14));
      s.setPadding(Ui.dp(a, 10), Ui.dp(a, 4), Ui.dp(a, 10), Ui.dp(a, 4));
      top.addView(s);
    }
    card.addView(top);

    if (q == null) {
      const t = Ui.tv(a, "Start the department's daily question", 19, Color.WHITE, true);
      card.addView(t);
      Ui.margins(t, 0, 12, 0, 0);
      card.addView(Ui.tv(a, "Post a case-based MCQ. Students answer on their phones and you see how many got it right.", 13, 0xD9FFFFFF, false));
      const go = Mcq.cta(a, "Post today's MCQ  →");
      go.setOnClickListener(a.opener(McqEditActivity));
      card.addView(go);
      Ui.margins(go, 0, 14, 0, 0);
      return card;
    }

    const isToday = Dates.todayIso().equals(q.get("date"));
    const sub = Ui.tv(a, Ui.nz(q.get("subject")) + "  ·  " + (isToday ? "Today" : Dates.nice(q.get("date")))
        + ("All".equals(Ui.nz(q.get("level"))) || Ui.nz(q.get("level")).isEmpty() ? "" : "  ·  " + q.get("level")), 12, 0xCCFFFFFF, true);
    card.addView(sub);
    Ui.margins(sub, 0, 12, 0, 0);
    const preview = Ui.nz(q.get("scenario")).isEmpty() ? q.get("question") : q.get("scenario");
    const body = Ui.tv(a, preview, 16, Color.WHITE, true);
    body.setMaxLines(3);
    body.setEllipsize(TextUtils.TruncateAt.END);
    body.setLineSpacing(0, 1.1);
    card.addView(body);
    Ui.margins(body, 0, 4, 0, 0);

    const n = Mcq.answered(db, q.get("id")), ok = Mcq.correct(db, q.get("id"));
    const bottom = Ui.h(a);
    bottom.setGravity(Gravity.CENTER_VERTICAL);
    const ring = new Mcq.Ring(a, Mcq.percent(ok, n), n > 0);
    bottom.addView(ring, Ui.lp(Ui.dp(a, 54), Ui.dp(a, 54)));
    const stats = Ui.v(a);
    stats.setPadding(Ui.dp(a, 12), 0, 0, 0);
    stats.addView(Ui.tv(a, n === 0 ? "Be the first to answer" : n + " answered", 14, Color.WHITE, true));
    stats.addView(Ui.tv(a, n === 0 ? "Answer to unlock the explanation" : Mcq.percent(ok, n) + "% got it right", 12, 0xCCFFFFFF, false));
    bottom.addView(stats, Ui.weight(1));
    const mine = Mcq.mine(db, q.get("id"), me);
    const go = Mcq.cta(a, mine == null ? "Answer  →" : "1".equals(mine.get("correct")) ? "✓ Correct" : "✗ Review");
    if (mine != null) go.setTextColor("1".equals(mine.get("correct")) ? Ui.GREEN : Ui.RED);
    bottom.addView(go);
    card.addView(bottom);
    Ui.margins(bottom, 0, 14, 0, 0);

    const open = a.opener(McqQuestionActivity, "id", q.get("id"));
    go.setOnClickListener(open);
    card.setOnClickListener(open);
    Ui.ripple(card, 0x33FFFFFF);
    return card;
  }

  static cta(c, s) {
    const t = Ui.tv(c, s, 14, 0xFF4C1D95, true);
    t.setBackground(Ui.round(c, Color.WHITE, 20));
    t.setPadding(Ui.dp(c, 16), Ui.dp(c, 9), Ui.dp(c, 16), Ui.dp(c, 9));
    t.setGravity(Gravity.CENTER);
    return t;
  }
}

/** A small progress ring with the percentage in the middle. */
Mcq.Ring = class extends View {
  constructor(c, pct, has) {
    super(c);
    this.p = new Paint(Paint.ANTI_ALIAS_FLAG);
    this.r = new RectF();
    this.pct = pct;
    this.has = has;
  }

  onDraw(cv) {
    const w = this.getWidth(), h = this.getHeight(), s = Math.min(w, h), stroke = s * 0.11;
    const p = this.p, r = this.r;
    r.set((w - s) / 2 + stroke, (h - s) / 2 + stroke, (w + s) / 2 - stroke, (h + s) / 2 - stroke);
    p.setStyle(Paint.Style.STROKE);
    p.setStrokeWidth(stroke);
    p.setStrokeCap(Paint.Cap.ROUND);
    p.setColor(0x40FFFFFF);
    cv.drawArc(r, 0, 360, false, p);
    if (this.has && this.pct > 0) {
      p.setColor(0xFF6EE7B7);
      cv.drawArc(r, -90, 360 * this.pct / 100, false, p);
    }
    p.setStyle(Paint.Style.FILL);
    p.setColor(Color.WHITE);
    p.setTextAlign(Paint.Align.CENTER);
    p.setFakeBoldText(true);
    p.setTextSize(s * 0.26);
    cv.drawText(this.has ? this.pct + "%" : "–", w / 2, h / 2 - (p.descent() + p.ascent()) / 2, p);
  }
};
;
