/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Daily MCQ, Daily ECG and Daily Image: today's questions, every earlier question with results, and this month's top scorers;
 * and the ECGs and images that faculty and students post for discussion.
 */
class McqActivity extends Base {
  constructor() {
    super();
    this.tab = "today";
    this.section = McqActivity.MCQ;
  }

  static MCQ = "MCQ";

  onCreate(b) {
    super.onCreate(b);
    if (this.getIntent().getStringExtra("section") != null) this.section = this.getIntent().getStringExtra("section");
    this.setTitle("Daily MCQ, ECG & Image");
    this.subtitle = "Learn something new every day";
    this.headerAction("+ Post", {
      onClick: (v) => {
        if (!this.section.equals(McqActivity.MCQ)) this.open(SpotEditActivity, "kind", this.section);
        else if (Mcq.canPost(this)) this.open(McqEditActivity);
        else Ui.toast(this, "Only faculty post MCQs. Anyone can post an ECG or an image.");
      }
    });
  }

  /** MCQ / ECG / Image switch at the top of the screen. */
  sections() {
    const keys = [McqActivity.MCQ, Spots.ECG, Spots.IMAGE];
    const labels = ["✦  MCQ", "♥  ECG", "◉  Image"];
    const cols = [0xFF6D28D9, Spots.ECG_COLOR, Spots.IMAGE_COLOR];
    const bar = Ui.h(this);
    bar.setBackground(Ui.round(this, 0x14000000, 22));
    bar.setPadding(Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4), Ui.dp(this, 4));
    const lp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 2));
    bar.setLayoutParams(lp);
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i];
      const on = k.equals(this.section);
      const t = Ui.tv(this, labels[i], 14, on ? Color.WHITE : cols[i], true);
      t.setGravity(Gravity.CENTER);
      t.setPadding(0, Ui.dp(this, 9), 0, Ui.dp(this, 9));
      if (on) t.setBackground(Ui.round(this, cols[i], 18));
      t.setOnClickListener({ onClick: (v) => { this.section = k; this.tab = "today"; this.render(); } });
      bar.addView(t, Ui.weight(1));
    }
    return bar;
  }

  render() {
    this.headerColors = this.section.equals(McqActivity.MCQ) ? Mcq.GRADIENT : Spots.gradient(this.section);
    if (!this.section.equals(McqActivity.MCQ)) {
      this.spots();
      return;
    }
    const page = Ui.v(this);
    page.addView(this.sections());
    const home = Mcq.homeCard(this, this.db);
    if (home != null) page.addView(home);
    page.addView(this.myStats());

    const keys = ["today", "all", "top"];
    const labels = ["Today", "All questions", "Top scorers"];
    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 2));
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i];
      const c = Ui.chip(this, labels[i], k.equals(this.tab), 0xFF6D28D9);
      c.setOnClickListener({ onClick: (v) => { this.tab = k; this.render(); } });
      chips.addView(c);
    }
    page.addView(Ui.hscroll(this, chips));

    if (this.tab.equals("top")) this.top(page);
    else {
      const qs = this.tab.equals("today")
          ? this.db.rows("SELECT * FROM mcqs WHERE date=? ORDER BY id", Dates.todayIso())
          : this.db.rows("SELECT * FROM mcqs WHERE date<=? ORDER BY date DESC, id DESC LIMIT 200", Dates.todayIso());
      if (qs.isEmpty()) page.addView(this.emptyNote(this.tab.equals("today")
          ? (Mcq.canPost(this) ? "No MCQ for today yet. Tap + Post to add one." : "Today's MCQ has not been posted yet.")
          : "No MCQs yet."));
      const me = SessionAttendance.me(this, this.db);
      for (const q of qs) page.addView(this.row(q, me));
      if (Mcq.canPost(this)) {
        const later = this.db.rows("SELECT * FROM mcqs WHERE date>? ORDER BY date, id", Dates.todayIso());
        if (!later.isEmpty()) {
          page.addView(Ui.heading(this, "Scheduled (" + later.size() + ")", Ui.SLATE));
          for (const q of later) page.addView(this.row(q, me));
        }
      }
    }
    this.setPage(page);
  }

  /** Daily ECG or Daily Image: a hero with the upload button, then today's or every post with its discussion count. */
  spots() {
    const kind = this.section;
    const col = Spots.color(kind);
    const page = Ui.v(this);
    page.addView(this.sections());
    const hero = Ui.v(this);
    hero.setBackground(Glass.hero(this, Spots.gradient(kind), 22));
    hero.setPadding(Ui.dp(this, 18), Ui.dp(this, 16), Ui.dp(this, 18), Ui.dp(this, 16));
    const lp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 4));
    hero.setLayoutParams(lp);
    hero.addView(Ui.tv(this, Spots.name(kind), 20, Color.WHITE, true));
    hero.addView(Ui.tv(this, Spots.ECG.equals(kind)
        ? "Faculty and students upload an interesting ECG with a short history. Everyone writes their reading; the answer opens when you tap Show."
        : "Upload an X-ray, CT, MRI, USG, fundus, smear or clinical photo with a short history. Everyone discusses it; the answer opens when you tap Show.",
        13, 0xE6FFFFFF, false));
    const up = Mcq.cta(this, Spots.ECG.equals(kind) ? "+  Upload an ECG" : "+  Upload an image");
    up.setTextColor(col);
    up.setOnClickListener(this.opener(SpotEditActivity, "kind", kind));
    hero.addView(up);
    Ui.margins(up, 0, 14, 0, 0);
    page.addView(hero);

    const keys = ["today", "all"];
    const labels = ["Today", Spots.ECG.equals(kind) ? "All ECGs" : "All images"];
    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 2));
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i];
      const c = Ui.chip(this, labels[i], k.equals(this.tab) || (i === 0 && !this.tab.equals("all")), col);
      c.setOnClickListener({ onClick: (v) => { this.tab = k; this.render(); } });
      chips.addView(c);
    }
    page.addView(Ui.hscroll(this, chips));
    const l = this.tab.equals("all") ? Spots.all(this.db, kind) : Spots.today(this.db, kind);
    if (l.isEmpty()) page.addView(this.emptyNote(this.tab.equals("all") ? "Nothing posted yet." : "Nothing posted today yet. Tap Upload to share one."));
    for (const s of l) {
      const n = Spots.count(this.db, s.get("id"));
      let sub = Ui.nz(s.get("question"));
      if (sub.length > 120) sub = sub.substring(0, 120) + "…";
      sub += (sub.isEmpty() ? "" : "\n") + "By " + Ui.nz(s.get("name")) + "  ·  " + (n === 0 ? "No comments yet" : n + (n === 1 ? " comment" : " comments"))
          + (Ui.nz(s.get("answer")).isEmpty() ? "" : "  ·  answer inside");
      page.addView(this.entryCard(Ui.nz(s.get("type")), col, Spots.label(s), sub, Dates.nice(s.get("date")),
          this.opener(SpotActivity, "id", s.get("id"))));
    }
    this.setPage(page);
  }

  /** The person's own record: answered, accuracy, streak. */
  myStats() {
    const me = SessionAttendance.me(this, this.db);
    const c = Ui.card(this);
    if (me == null) {
      c.addView(Ui.muted(this, "Answer a question to start your score and streak."));
      return c;
    }
    const n = this.db.num("SELECT COUNT(*) FROM mcq_answers WHERE staff_id=? OR name=?", me.get("id"), me.get("name"));
    const ok = this.db.num("SELECT COUNT(*) FROM mcq_answers WHERE (staff_id=? OR name=?) AND correct='1'", me.get("id"), me.get("name"));
    c.addView(Ui.statRow(this, Ui.stat(this, String(n), "Answered", Ui.PRIMARY),
        Ui.stat(this, Mcq.percent(ok, n) + "%", "Accuracy", Ui.GREEN),
        Ui.stat(this, "🔥 " + Mcq.streak(this.db, me), "Day streak", Ui.ORANGE)));
    return c;
  }

  row(q, me) {
    const n = Mcq.answered(this.db, q.get("id")), ok = Mcq.correct(this.db, q.get("id"));
    const mine = Mcq.mine(this.db, q.get("id"), me);
    const status = mine == null ? "Not answered" : "1".equals(mine.get("correct")) ? "✓ You got it right" : "✗ You answered " + mine.get("choice");
    const sub = n + " answered" + (n > 0 ? " · " + Mcq.percent(ok, n) + "% right" : "") + "  ·  " + status;
    const future = q.get("date").compareTo(Dates.todayIso()) > 0;
    const body = Ui.nz(q.get("question"));
    return this.entryCard(Ui.nz(q.get("subject")), mine == null ? 0xFF6D28D9 : "1".equals(mine.get("correct")) ? Ui.GREEN : Ui.RED,
        body.length > 140 ? body.substring(0, 140) + "…" : body, sub, (future ? "Shows " : "") + Dates.nice(q.get("date")),
        this.opener(McqQuestionActivity, "id", q.get("id")));
  }

  top(page) {
    const l = Mcq.leaders(this.db, Dates.today(), 20);
    page.addView(Ui.heading(this, "Top scorers · " + Dates.month(Dates.today()), 0xFF6D28D9));
    if (l.isEmpty()) {
      page.addView(this.emptyNote("No answers this month yet."));
      return;
    }
    const c = Ui.card(this);
    const medals = ["🥇", "🥈", "🥉"];
    for (let i = 0; i < l.size(); i++) {
      const r = l.get(i);
      const row = Ui.h(this);
      row.setGravity(Gravity.CENTER_VERTICAL);
      row.setPadding(0, Ui.dp(this, 7), 0, Ui.dp(this, 7));
      const rank = Ui.tv(this, i < 3 ? medals[i] : String(i + 1), i < 3 ? 20 : 14, Ui.MUTED, true);
      rank.setGravity(Gravity.CENTER);
      row.addView(rank, Ui.lp(Ui.dp(this, 36), LinearLayout.LayoutParams.WRAP_CONTENT));
      const who = Ui.v(this);
      who.addView(Ui.tv(this, r.get("name"), 15, Ui.TEXT, true));
      who.addView(Ui.muted(this, "Postgraduate".equals(r.get("role")) ? "PG" : Ui.nz(r.get("role"))));
      row.addView(who, Ui.weight(1));
      const ok = Ui.toInt(r.get("ok"), 0), n = Ui.toInt(r.get("n"), 0);
      const sc = Ui.tv(this, ok + " / " + n, 15, i === 0 ? Color.WHITE : 0xFF6D28D9, true);
      sc.setBackground(i === 0 ? Ui.round(this, 0xFF6D28D9, 14) : Ui.round(this, Ui.alpha(0xFF6D28D9, 0x1A), 14));
      sc.setPadding(Ui.dp(this, 12), Ui.dp(this, 4), Ui.dp(this, 12), Ui.dp(this, 4));
      row.addView(sc);
      c.addView(row);
    }
    page.addView(c);
  }
}
;
