/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Faculty: post a daily MCQ (case scenario, question, up to five options, the answer, explanation), or edit one. */
class McqEditActivity extends Base {
  constructor() {
    super();
    this.form = null;
    this.id = -1;
  }

  onCreate(b) {
    super.onCreate(b);
    const s = this.getIntent().getStringExtra("id");
    if (s != null) this.id = Long.parseLong(s);
    this.setTitle(this.id >= 0 ? "Edit MCQ" : "Post a daily MCQ");
    this.headerColor(0xFF6D28D9);
    this.headerAction("Save", { onClick: (v) => { this.save(); } });
  }

  liveRefresh() {
    return false;
  }

  render() {
    if (this.form != null) return;
    if (!Mcq.canPost(this)) {
      const page = Ui.v(this);
      page.addView(this.emptyNote("Only faculty can post MCQs."));
      this.setPage(page);
      return;
    }
    const v = McqEditActivity.v;
    const q = this.id >= 0 ? this.db.row("SELECT * FROM mcqs WHERE id=?", String(this.id)) : null;
    const form = this.form = new Form(this);
    form.heading("Question");
    form.date("date", "Show on (date)", v(q, "date", Dates.todayIso()));
    form.choice("subject", "Subject", Mcq.SUBJECTS, Mcq.SUBJECTS, v(q, "subject", Mcq.SUBJECTS[0]), null);
    form.choice("level", "For", ["Everyone", "MBBS students", "PGs"], Mcq.LEVELS, v(q, "level", "All"), null);
    form.multi("scenario", "Case scenario", v(q, "scenario", ""));
    form.multi("question", "Question *", v(q, "question", ""));
    form.heading("Options");
    for (const l of Mcq.LETTERS) form.text("opt_" + l.toLowerCase(), l + (l.compareTo("C") < 0 ? " *" : " (optional)"),
        v(q, "opt_" + l.toLowerCase(), ""), Form.PLAIN);
    form.choice("answer", "Correct answer", Mcq.LETTERS, Mcq.LETTERS, v(q, "answer", "A"), null);
    form.heading("Explanation (shown after answering)");
    form.multi("explanation", "Explanation / teaching points", v(q, "explanation", ""));
    form.text("refs", "Reference (book, guideline, page)", v(q, "refs", ""), Form.PLAIN);

    const page = Ui.v(this);
    const card = Ui.card(this);
    card.addView(form.view);
    page.addView(card);
    const btns = Ui.v(this);
    btns.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), 0);
    btns.addView(Ui.button(this, this.id >= 0 ? "Save changes" : "Post MCQ", 0xFF6D28D9, { onClick: (v2) => { this.save(); } }));
    if (this.id >= 0) {
      const del = Ui.outlineButton(this, "Delete MCQ", Ui.RED, {
        onClick: (v2) => {
          Ui.confirm(this, "Delete this MCQ?", "The question and everyone's answers will be removed.", "Delete", {
            run: () => {
              for (const r of this.db.rows("SELECT id FROM mcq_answers WHERE mcq_id=?", String(this.id)))
                this.db.delete("mcq_answers", Long.parseLong(r.get("id")));
              this.db.delete("mcqs", this.id);
              this.finish();
            }
          });
        }
      });
      btns.addView(del);
      Ui.margins(del, 0, 10, 0, 0);
    }
    page.addView(btns);
    this.setPage(page);
  }

  static v(r, k, def) {
    return r == null || Ui.nz(r.get(k)).isEmpty() ? def : r.get(k);
  }

  save() {
    const form = this.form;
    if (form == null) return;
    if (!form.require("question", "Enter the question")) return;
    if (!form.require("opt_a", "Enter option A") || !form.require("opt_b", "Enter option B")) return;
    const ans = form.get("answer");
    if (form.get("opt_" + ans.toLowerCase()).isEmpty()) {
      Ui.toast(this, "The correct answer (" + ans + ") has no option text");
      return;
    }
    const cv = new ContentValues();
    for (const k of ["date", "subject", "level", "scenario", "question", "opt_a", "opt_b", "opt_c", "opt_d", "opt_e", "answer", "explanation", "refs"])
      cv.put(k, form.get(k));
    if (this.id < 0) {
      cv.put("posted_by", Approvals.me(this).isEmpty() ? Reminders.myName(this, this.db) : Approvals.me(this));
      cv.put("posted_on", Dates.todayIso() + " " + Dates.now());
      this.id = this.db.insert("mcqs", cv);
      Ui.toast(this, "MCQ posted");
      this.finish();
      this.open(McqQuestionActivity, "id", String(this.id));
      return;
    }
    this.db.update("mcqs", cv, this.id);
    Ui.toast(this, "Saved");
    this.finish();
  }
}
;
