/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** The monthly department report for the HOD: admissions, deaths, CMCHIS claims and academics in one PDF or Word file. */
class MonthlyReport {
  static c(t) {
    return new FormDoc.Cell(t);
  }

  static h(t) {
    return new FormDoc.Cell(t).b().fill(0xFFE3F2FD);
  }

  static pct(deaths, out) {
    return out === 0 ? '-' : jfmt('%.1f%%', deaths * 100.0 / out);
  }

  static money(v) {
    // String.format(Locale.ENGLISH, "%,.0f", v): western digit grouping
    return v === 0 ? '-' : '₹' + Math.round(Number(v)).toLocaleString('en-US');
  }

  /** Asks which month, makes the PDF or Word file and offers to share or open it. */
  static choose(a, pdf) {
    const now = YearMonth.from(Dates.today());
    const ms = [now, now.minusMonths(1), now.minusMonths(2), now.minusMonths(3)];
    const names = new Array(ms.length).fill(null);
    for (let i = 0; i < ms.length; i++) names[i] = Dates.month(ms[i].atDay(1)) + (i === 0 ? ' (so far)' : '');
    new AlertDialog.Builder(a).setTitle('Monthly report for')
        .setItems(names, {
          onClick: (d, w) => { MonthlyReport.make(a, ms[w], pdf); }
        }).show();
  }

  static make(a, m, pdf) {
    let rel;
    try {
      const f = MonthlyReport.build(a.db, m);
      rel = pdf ? f.pdf(a) : f.docx(a);
    } catch (e) {
      Ui.toast(a, 'Could not make the report: ' + e.getMessage());
      return;
    }
    const subject = 'Monthly report ' + Dates.month(m.atDay(1));
    new AlertDialog.Builder(a).setTitle((pdf ? 'PDF' : 'Word') + ' report ready')
        .setItems(['Share (WhatsApp, email…)', 'Open'], {
          onClick: (d, w) => {
            if (w === 0) Store.share(a, rel, subject);
            else Store.openWith(a, rel);
          }
        }).setNegativeButton('Close', null).show();
  }

  static build(db, m) {
    const c = MonthlyReport.c, h = MonthlyReport.h, pct = MonthlyReport.pct, money = MonthlyReport.money;
    const a = m.atDay(1).toString(), b = m.atEndOfMonth().toString();
    const f = new FormDoc();
    f.college = db.setting('college', 'Tirunelveli Medical College Hospital');
    f.address = db.setting('address', 'Tirunelveli – 627 011, Tamil Nadu');
    f.dept = db.setting('dept', 'Department of General Medicine');
    f.title = 'MONTHLY DEPARTMENT REPORT · ' + Dates.month(m.atDay(1)).toUpperCase();
    f.footer = Dates.month(m.atDay(1)) + '  •  ' + f.dept + ', ' + f.college;
    f.fileBase = 'Monthly_report_' + m;

    const adm = db.events(Db.ADMIT, a, b, null, null), dis = db.events(Db.DISCHARGE, a, b, null, null), died = db.events(Db.DEATH, a, b, null, null);
    const s = f.block('SUMMARY', FormDoc.NAVY, 0.25, 0.25, 0.25, 0.25);
    s.row(16, h('Admissions'), h('Discharges'), h('Deaths'), h('Mortality'));
    s.row(16, c(String(adm)).b().center(), c(String(dis)).b().center(), c(String(died)).b().center(), c(pct(died, died + dis)).b().center());
    s.row(16, h('Transfers to IMCU'), h('Transfers to CCB'), h('Inpatients now'), h('Head of Department'));
    s.row(16, c(String(db.transfers(a, b, null, Db.IMCU))).center(), c(String(db.transfers(a, b, null, Db.CCB))).center(),
        c(String(db.totalInpatients())).center(), c(db.setting('hod', '')).center());

    const u = f.block('UNIT AND WARD MOVEMENT', 0xFF0F766E, 0.22, 0.13, 0.13, 0.13, 0.13, 0.13, 0.13);
    u.row(14, h('Ward'), h('Admitted'), h('In'), h('Out'), h('Discharged'), h('Deaths'), h('Mortality'));
    const wards = Array.from(Db.WARD_UNITS).concat(Array.from(Db.SPECIAL));
    for (const w of wards) {
      const ad = db.events(Db.ADMIT, a, b, Db.isWardUnit(w) ? 'from_loc' : 'to_loc', w), inn = db.transfers(a, b, null, w), out = db.transfers(a, b, w, null);
      const ds = db.events(Db.DISCHARGE, a, b, 'from_loc', w), dd = db.events(Db.DEATH, a, b, 'from_loc', w);
      if (ad + inn + out + ds + dd === 0) continue;
      u.row(14, c(Db.unitName(w)).b(), c(String(ad)).center(), c(String(inn)).center(), c(String(out)).center(),
          c(String(ds)).center(), c(String(dd)).center(), c(pct(dd, dd + ds)).center());
    }

    const deaths = db.rows('SELECT e.date, e.from_loc, p.name, p.age, p.sex, p.ip_no, p.home_unit, p.outcome_note, p.diagnosis FROM events e '
        + 'JOIN patients p ON p.id = e.patient_id WHERE e.type=? AND e.date BETWEEN ? AND ? ORDER BY e.date', Db.DEATH, a, b);
    const d = f.block('DEATHS  ·  ' + deaths.size(), 0xFF475569, 0.05, 0.12, 0.25, 0.12, 0.46);
    d.row(14, h('No'), h('Date'), h('Name, age, IP'), h('Unit / place'), h('Cause of death'));
    if (deaths.isEmpty()) d.row(14, c('Nil').span(5));
    let i = 0;
    for (const r of deaths) {
      const cause = Ui.nz(r.get('outcome_note')).isEmpty() ? Ui.nz(r.get('diagnosis')) : r.get('outcome_note');
      d.row(14, c(String(++i)), c(Dates.nice(r.get('date'))), c(Ui.nz(r.get('name')) + ', ' + Ui.nz(r.get('age')) + ' ' + Ui.nz(r.get('sex'))
          + (Ui.nz(r.get('ip_no')).isEmpty() ? '' : '\nIP ' + r.get('ip_no'))), c(Ui.nz(r.get('home_unit')) + ' / ' + Db.shortName(r.get('from_loc'))), c(cause.split('\n').join(' ')));
    }

    const cm = f.block('CMCHIS CLAIMS', 0xFFBE185D, 0.2, 0.12, 0.12, 0.12, 0.12, 0.16, 0.16);
    cm.row(14, h('Unit'), h('Cases'), h('Approved'), h('Awaiting'), h('Rejected'), h('Approved amount'), h('Credited'));
    let ct = 0, ca = 0, cw = 0, cr = 0;
    let am = 0, cred = 0;
    const cu = Array.from(Db.WARD_UNITS).concat([Db.IMCU]);
    for (const w of cu) {
      const n = db.num('SELECT COUNT(*) FROM cmchis_cases WHERE unit=? AND date BETWEEN ? AND ?', w, a, b);
      if (n === 0) continue;
      const ap = db.num('SELECT COUNT(*) FROM cmchis_cases WHERE unit=? AND date BETWEEN ? AND ? AND ' + CmchisStages.APPROVED_SQL, w, a, b);
      const aw = db.num('SELECT COUNT(*) FROM cmchis_cases WHERE unit=? AND date BETWEEN ? AND ? AND ' + CmchisStages.AWAITING_SQL, w, a, b);
      const rj = db.num('SELECT COUNT(*) FROM cmchis_cases WHERE unit=? AND date BETWEEN ? AND ? AND status=?', w, a, b, CmchisStages.REJECTED);
      const amt = db.dbl('SELECT COALESCE(SUM(amount),0) FROM cmchis_cases WHERE unit=? AND date BETWEEN ? AND ? AND ' + CmchisStages.APPROVED_SQL, w, a, b);
      const cr1 = db.dbl('SELECT COALESCE(SUM(credited),0) FROM cmchis_cases WHERE unit=? AND date BETWEEN ? AND ?', w, a, b);
      cm.row(14, c(Db.unitName(w)).b(), c(String(n)).center(), c(String(ap)).center(), c(String(aw)).center(), c(String(rj)).center(),
          c(money(amt)).center(), c(money(cr1)).center());
      ct += n; ca += ap; cw += aw; cr += rj; am += amt; cred += cr1;
    }
    if (ct === 0) cm.row(14, c('No CMCHIS cases this month').span(7));
    else cm.row(14, c('Total').b(), c(String(ct)).b().center(), c(String(ca)).b().center(), c(String(cw)).b().center(),
        c(String(cr)).b().center(), c(money(am)).b().center(), c(money(cred)).b().center());

    const ac = f.block('ACADEMICS', 0xFF7C3AED, 0.28, 0.12, 0.6);
    ac.row(14, h('Activity'), h('Number'), h('Topics'));
    for (const k of db.rows("SELECT kind, COUNT(*) AS n, GROUP_CONCAT(topic, '; ') AS topics FROM academics WHERE date BETWEEN ? AND ? GROUP BY kind ORDER BY kind", a, b))
      ac.row(14, c(Ui.nz(k.get('kind'))).b(), c(k.get('n')).center(), c(Ui.nz(k.get('topics'))));
    for (const k of db.rows("SELECT kind, COUNT(*) AS n, GROUP_CONCAT(topic, '; ') AS topics FROM classes WHERE date BETWEEN ? AND ? GROUP BY kind ORDER BY kind", a, b))
      ac.row(14, c(('PG'.equals(k.get('kind')) ? 'PG' : 'MBBS') + ' classes').b(), c(k.get('n')).center(), c(Ui.nz(k.get('topics'))));
    ac.row(14, c('Daily MCQs posted').b(), c(String(db.num('SELECT COUNT(*) FROM mcqs WHERE date BETWEEN ? AND ?', a, b))).center(),
        c(db.num('SELECT COUNT(*) FROM mcq_answers a JOIN mcqs q ON q.id = a.mcq_id WHERE q.date BETWEEN ? AND ?', a, b) + ' answers'));
    ac.row(14, c('Session check-ins').b(), c(String(db.num('SELECT COUNT(*) FROM acad_attendance t JOIN academics s ON s.id = t.academic_id WHERE s.date BETWEEN ? AND ?', a, b))).center(),
        c('Physicon / journal club attendance taken in the app'));
    ac.row(14, c('PG logbook procedures signed').b(), c(String(db.num('SELECT COUNT(*) FROM logbook WHERE status=? AND date BETWEEN ? AND ?', Logbook.SIGNED, a, b))).center(),
        c(db.num('SELECT COUNT(DISTINCT staff_id) FROM logbook WHERE date BETWEEN ? AND ?', a, b) + ' PGs logged procedures'));

    const o = f.block('OTHER SERVICES', 0xFF0369A1, 0.5, 0.5);
    o.row(14, c('Call overs answered for other departments').b(), c(String(db.num('SELECT COUNT(*) FROM callover WHERE date BETWEEN ? AND ?', a, b))));
    o.row(14, c('OG block cases seen (obstetric physician)').b(), c(String(db.num('SELECT COUNT(*) FROM og_cases WHERE date BETWEEN ? AND ?', a, b))));
    o.row(14, c('Kandiyaperi OP / IP').b(), c(db.num('SELECT COALESCE(SUM(COALESCE(new_m,0)+COALESCE(new_f,0)+COALESCE(review,0)),0) FROM kdp_op WHERE date BETWEEN ? AND ?', a, b) + ' OP  ·  ' + db.events(Db.ADMIT, a, b, 'to_loc', Db.KDP) + ' IP'));
    o.row(14, c('Achievements recorded').b(), c(String(db.num('SELECT COUNT(*) FROM achievements WHERE date BETWEEN ? AND ?', a, b))));
    return f;
  }
}
;
/* ---- app/NightlyBackup.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * A copy of all the records every night (the admin's phone, taken by the background job after 2 AM): kept on the phone (last 7)
 * and uploaded to the server's private "backups/" folder (last 14), readable only by the admin, HOD and registrar.
 * Web: maybeRun() does nothing (there is no background job in a browser). run() is async (returns a Promise of the file name):
 * Backup.write and the upload are asynchronous here.
 */
class NightlyBackup {
  static prefs(c) {
    return c.getApplicationContext().getSharedPreferences("backup", Context.MODE_PRIVATE);
  }

  static dir(c) {
    const base = c.getExternalFilesDir(null);
    const d = new File(base == null ? c.getFilesDir() : base, "backups");
    d.mkdirs();
    return d;
  }

  static last(c) {
    return NightlyBackup.prefs(c).getString("last", "");
  }

  /** Runs from the background job: once a day, after 2 AM, on the admin's phone only. Web: no background job, so nothing to do. */
  static maybeRun(c) {
  }

  /** Makes the copy now. Resolves to the file name. */
  static async run(c) {
    const db = Db.get(c);
    const day = LocalDate.now().toString();
    const bo = new ByteArrayOutputStream();
    await Backup.write(db, bo);
    const zip = bo.toByteArray();
    const f = new File(NightlyBackup.dir(c), "TVMCHMED-" + day + ".zip");
    const fo = new FileOutputStream(f);
    fo.write(zip);
    fo.close();
    const old = NightlyBackup.dir(c).list();
    if (old != null) {
      old.sort();
      for (let i = 0; i < old.length - 7; i++) new File(NightlyBackup.dir(c), old[i]).delete();
    }
    let note = "Saved on this phone";
    try {
      await Cloud.httpA(c, "POST", "/storage/v1/object/files/backups/" + day + ".zip", zip, "application/zip", await Cloud.tokenA(c), "x-upsert", "true");
      note = "Saved on this phone and on the server";
      try {
        await Cloud.httpA(c, "DELETE", "/storage/v1/object/files/" + Uri.encode("backups/" + LocalDate.now().minusDays(14) + ".zip", "/"), null, null, await Cloud.tokenA(c));
      } catch (ignored) {
      }
    } catch (e) {
      note = "Saved on this phone; the server copy failed (" + e.getMessage() + ")";
    }
    NightlyBackup.prefs(c).edit().putString("day", day).putString("last", LocalDateTime.now().toString().substring(0, 16).split("T").join(" ") + " \u00B7 " + idiv(zip.length, 1024) + " KB \u00B7 " + note).remove("error").apply();
    return f.getName();
  }
}
;
/* ---- app/ObstetricActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Obstetric physician: each month one Assistant Professor is the obstetric physician, with a senior PG of that
 * Assistant Professor's unit. They see the critical cases in the OG block, 9 AM to 2 PM daily.
 */
class ObstetricActivity extends Base {
  constructor() { super(); this.month = null; }

  static COLOR = 0xFFBE185D;
  static STATUS = ["Seen", "Follow-up", "Shifted to medicine / IMCU", "Settled"];

  onCreate(b) {
    super.onCreate(b);
    this.month = YearMonth.from(Dates.today());
    this.setTitle("Obstetric physician");
    this.subtitle = "Critical cases in the OG block · 9 AM to 2 PM daily";
    this.headerColor(ObstetricActivity.COLOR);
    this.headerAction("+ Case", {
      onClick: (v) => { this.caseDialog(null); }
    });
  }

  static onNow() {
    const t = Dates.time();
    return !t.isBefore(LocalTime.of(9, 0)) && t.isBefore(LocalTime.of(14, 0));
  }

  static duty(db, m) {
    return db.row("SELECT * FROM ob_duty WHERE month=? ORDER BY id DESC LIMIT 1", m.toString());
  }

  render() {
    const COLOR = ObstetricActivity.COLOR;
    const page = Ui.v(this);
    const d = ObstetricActivity.duty(this.db, this.month);

    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(COLOR), 20));
    const nav = Ui.h(this);
    nav.setGravity(Gravity.CENTER_VERTICAL);
    const prev = Ui.tv(this, "‹", 24, Color.WHITE, true);
    prev.setPadding(Ui.dp(this, 6), 0, Ui.dp(this, 14), 0);
    prev.setOnClickListener({
      onClick: (v) => { this.month = this.month.minusMonths(1); this.render(); }
    });
    nav.addView(prev);
    nav.addView(Ui.tv(this, Dates.month(this.month.atDay(1)), 15, 0xD9FFFFFF, true), Ui.weight(1));
    const nxt = Ui.tv(this, "›", 24, Color.WHITE, true);
    nxt.setPadding(Ui.dp(this, 14), 0, Ui.dp(this, 6), 0);
    nxt.setOnClickListener({
      onClick: (v) => { this.month = this.month.plusMonths(1); this.render(); }
    });
    nav.addView(nxt);
    hero.addView(nav);
    const ap = d == null ? "" : Ui.nz(d.get("ap")), pg = d == null ? "" : Ui.nz(d.get("pg")), unit = d == null ? "" : Ui.nz(d.get("unit"));
    hero.addView(Ui.tv(this, ap.isEmpty() ? "Not set yet" : ap, 20, Color.WHITE, true));
    hero.addView(Ui.tv(this, "Assistant Professor, obstetric physician" + (unit.isEmpty() ? "" : " · " + unit + " unit"), 12, 0xD9FFFFFF, false));
    hero.addView(Ui.tv(this, "Senior PG: " + (pg.isEmpty() ? "not set" : pg), 14, Color.WHITE, true));
    const thisMonth = this.month.equals(YearMonth.from(Dates.today()));
    hero.addView(Ui.tv(this, thisMonth && ObstetricActivity.onNow() ? "● On duty now (9 AM to 2 PM)" : "Duty 9 AM to 2 PM daily", 12, Color.WHITE, false));
    if (SessionAttendance.canRun(this)) {
      const set = Ui.outlineButton(this, d == null ? "+ Set this month's obstetric physician" : "Change", COLOR, {
        onClick: (v) => { this.dutyDialog(); }
      });
      hero.addView(set);
      Ui.margins(set, 0, 10, 0, 0);
    }
    page.addView(hero);

    const m0 = this.month.atDay(1).toString(), m1 = this.month.atEndOfMonth().toString();
    const open = this.db.rows("SELECT * FROM og_cases WHERE status IN ('Seen','Follow-up') AND date BETWEEN ? AND ? ORDER BY date DESC, time DESC", m0, m1);
    page.addView(Ui.heading(this, "Being followed  ·  " + open.size(), COLOR));
    if (open.isEmpty()) page.addView(this.emptyNote("No OG block cases on follow-up"));
    for (const r of open) page.addView(this.caseRow(r));
    const all = this.db.rows("SELECT * FROM og_cases WHERE status NOT IN ('Seen','Follow-up') AND date BETWEEN ? AND ? ORDER BY date DESC, time DESC", m0, m1);
    page.addView(Ui.heading(this, "Done this month  ·  " + all.size(), Ui.SLATE));
    for (const r of all) page.addView(this.caseRow(r));
    this.setPage(page);
  }

  caseRow(r) {
    const COLOR = ObstetricActivity.COLOR;
    const card = Ui.card(this);
    card.addView(Ui.tv(this, Ui.nz(r.get("patient")) + (Ui.nz(r.get("age_sex")).isEmpty() ? "" : "  ·  " + r.get("age_sex")), 15, Ui.TEXT, true));
    card.addView(Ui.muted(this, Dates.nice(r.get("date")) + " " + Ui.nz(r.get("time")) + (Ui.nz(r.get("ward")).isEmpty() ? "" : "  ·  " + r.get("ward"))
        + (Ui.nz(r.get("ip_no")).isEmpty() ? "" : "  ·  IP " + r.get("ip_no"))));
    if (!Ui.nz(r.get("problem")).isEmpty()) card.addView(Ui.body(this, r.get("problem")));
    if (!Ui.nz(r.get("advice")).isEmpty()) card.addView(Ui.tv(this, "Advice: " + r.get("advice"), 13, Ui.TEXT, false));
    card.addView(Ui.tv(this, Ui.nz(r.get("status")) + (Ui.nz(r.get("seen_by")).isEmpty() ? "" : "  ·  seen by " + r.get("seen_by")), 12, COLOR, true));
    Ui.ripple(card, Ui.alpha(COLOR, 0x22));
    card.setOnClickListener({
      onClick: (v) => { this.caseDialog(r); }
    });
    return card;
  }

  caseDialog(r) {
    const f = new Form(this);
    const d = ObstetricActivity.duty(this.db, YearMonth.from(Dates.today()));
    f.date("date", "Date", r == null ? Dates.todayIso() : r.get("date"));
    f.time("time", "Time", r == null ? Dates.now() : r.get("time"));
    f.text("patient", "Patient name *", r == null ? "" : r.get("patient"), Form.TEXT);
    f.text("age_sex", "Age / G P L (e.g. 24 F, G2P1L1, 34 weeks)", r == null ? "" : r.get("age_sex"), Form.TEXT);
    f.text("ip_no", "IP number", r == null ? "" : r.get("ip_no"), Form.TEXT);
    f.text("ward", "OG ward / bed", r == null ? "" : r.get("ward"), Form.TEXT);
    f.multi("problem", "Medical problem (e.g. eclampsia, PPH with shock, heart disease, sepsis)", r == null ? "" : r.get("problem"));
    f.multi("advice", "Opinion / advice", r == null ? "" : r.get("advice"));
    const by = d == null ? "" : Ui.nz(d.get("ap"));
    f.suggest("seen_by", "Seen by", r == null ? by : r.get("seen_by"), this.db.staffNames("AND role IN ('Assistant Professor','Associate Professor','Professor','Postgraduate')"));
    f.choice("status", "Status", ObstetricActivity.STATUS, ObstetricActivity.STATUS, r == null ? ObstetricActivity.STATUS[0] : r.get("status"), null);
    Ui.formDialog(this, r == null ? "OG block case" : "Edit OG block case", f, "Save", {
      run: () => {
        if (!f.require("patient", "Enter the patient's name")) return false;
        const cv = new ContentValues();
        for (const k of ["date", "time", "patient", "age_sex", "ip_no", "ward", "problem", "advice", "seen_by", "status"]) cv.put(k, f.get(k));
        cv.put("by_name", CallDutyActivity.myName(this));
        if (r == null) this.db.insert("og_cases", cv);
        else this.db.update("og_cases", cv, Long.parseLong(r.get("id")));
        this.render();
        return true;
      }
    });
  }

  dutyDialog() {
    const d = ObstetricActivity.duty(this.db, this.month);
    const f = new Form(this);
    f.suggest("ap", "Assistant Professor (obstetric physician)", d == null ? "" : d.get("ap"), this.db.staffNames("AND role IN ('Assistant Professor','Associate Professor')"));
    f.suggest("pg", "Senior PG (from the same unit)", d == null ? "" : d.get("pg"), this.db.staffNames("AND role='Postgraduate'"));
    Ui.formDialog(this, "Obstetric physician, " + Dates.month(this.month.atDay(1)), f, "Save", {
      run: () => {
        const cv = new ContentValues();
        cv.put("month", this.month.toString());
        cv.put("ap", f.get("ap").trim());
        cv.put("pg", f.get("pg").trim());
        const s = this.db.row("SELECT unit FROM staff WHERE name=? LIMIT 1", f.get("ap").trim());
        cv.put("unit", s == null ? "" : Ui.nz(s.get("unit")));
        cv.put("by_name", CallDutyActivity.myName(this));
        if (d == null) this.db.insert("ob_duty", cv);
        else this.db.update("ob_duty", cv, Long.parseLong(d.get("id")));
        this.render();
        return true;
      }
    });
  }
}
;
