'use strict';
/**
 * Presentations (PPT / PDF) for the physician conference (Physicon) and journal club. Files are shared through the
 * department's storage; other phones download one only when it is opened, to save mobile data.
 */
class PresentationsActivity extends Base {
  constructor() {
    super();
    this.kind = null;
  }

  static REQ_FILE = 41;
  static MAX_BYTES = 45 * 1024 * 1024;   // the free storage plan takes files up to 50 MB
  static MIMES = ["application/pdf", "application/vnd.ms-powerpoint",
      "application/vnd.openxmlformats-officedocument.presentationml.presentation"];

  onCreate(b) {
    super.onCreate(b);
    this.kind = this.getIntent().getStringExtra("kind");
    if (!"JC".equals(this.kind)) this.kind = "CONF";
    this.setTitle(PresentationsActivity.label(this.kind));
    this.subtitle = "Presentations (PPT / PDF)";
    this.headerColor(Ui.PURPLE);
    this.headerAction("+ Upload", { onClick: (v) => { this.upload(); } });
  }

  static label(kind) {
    return "JC".equals(kind) ? "Journal club" : "Physicon";
  }

  static count(db, kind) {
    return db.num("SELECT COUNT(*) FROM acad_files WHERE kind=?", kind);
  }

  static countFor(db, academicId) {
    return db.num("SELECT COUNT(*) FROM acad_files WHERE academic_id=?", academicId);
  }

  render() {
    const page = Ui.v(this);
    const hero = Ui.card(this);
    hero.setBackground(Glass.hero(this, Ui.shades(Ui.PURPLE), 20));
    const files = this.db.rows("SELECT * FROM acad_files WHERE kind=? ORDER BY date DESC, id DESC", this.kind);
    hero.addView(Ui.tv(this, files.size() + " " + (files.size() === 1 ? "presentation" : "presentations"), 18, 0xFFFFFFFF, true));
    hero.addView(Ui.tv(this, "Upload the PPT or PDF used at the " + ("JC".equals(this.kind) ? "journal club" : "physician conference")
        + " so everyone in the department can open it later. Files up to 45 MB.", 13, 0xE6FFFFFF, false));
    const up = Ui.button(this, "Upload PPT / PDF", Ui.PURPLE, { onClick: (v) => { this.upload(); } });
    hero.addView(up);
    Ui.margins(up, 0, 12, 0, 0);
    page.addView(hero);

    if (files.isEmpty()) page.addView(this.emptyNote("No presentations uploaded yet."));
    let month = null;
    for (const f of files) {
      const m = Dates.parse(f.get("date")) != null ? Dates.month(Dates.parse(f.get("date"))) : "";
      if (!m.equals(month)) {
        page.addView(Ui.heading(this, m.isEmpty() ? "Undated" : m, Ui.PURPLE));
        month = m;
      }
      page.addView(this.fileCard(f));
    }
    this.setPage(page);
  }

  fileCard(f) {
    const db = this.db;
    const rel = f.get("file");
    const here = db.file(rel).exists();
    const bits = [];
    if (!Ui.nz(f.get("presenter")).isEmpty()) bits.add(f.get("presenter"));
    bits.add(Store.kindLabel(rel) + (Ui.toInt(f.get("size"), 0) > 0 ? " · " + Store.sizeLabel(Ui.toInt(f.get("size"), 0)) : ""));
    if (!here) bits.add("tap to download");
    let session = "";
    if (!Ui.nz(f.get("academic_id")).isEmpty()) {
      const a = db.row("SELECT topic FROM academics WHERE id=?", f.get("academic_id"));
      if (a != null && !Ui.nz(a.get("topic")).isEmpty() && !a.get("topic").equals(f.get("title"))) session = "Session: " + a.get("topic");
    }
    const card = this.entryCard(Store.kindLabel(rel), Store.kindLabel(rel).equals("PDF") ? Ui.RED : Ui.ORANGE, f.get("title"),
        TextUtils.join("  ·  ", bits) + (session.isEmpty() ? "" : "\n" + session),
        Dates.nice(f.get("date")), { onClick: (v) => { this.openFile(rel, false); } });
    const row = Ui.h(this);
    row.setGravity(Gravity.END);
    const share = Ui.outlineButton(this, "Share", Ui.PURPLE, { onClick: (v) => { this.openFile(rel, true); } });
    row.addView(share);
    if (this.canDelete(f)) {
      const del = Ui.outlineButton(this, "Delete", Ui.RED, {
        onClick: (v) => {
          Ui.confirm(this, "Delete presentation?", f.get("title") + " will be removed for everyone.", "Delete", {
            run: () => {
              this.db.forgetFile(rel);
              this.db.delete("acad_files", Long.parseLong(f.get("id")));
              this.render();
            }
          });
        }
      });
      row.addView(del);
      Ui.margins(del, 8, 0, 0, 0);
    }
    card.addView(row);
    Ui.margins(row, 0, 8, 0, 0);
    return card;
  }

  canDelete(f) {
    if (!Cloud.active(this) || Cloud.isAdmin(this)) return true;
    const me = Approvals.me(this);
    return !me.isEmpty() && me.equals(f.get("added_by"));
  }

  /** Opens (or shares) a presentation, downloading it first if it was uploaded from another phone. */
  openFile(rel, share) {
    if (this.db.file(rel).exists()) {
      if (share) Store.share(this, rel, "Presentation");
      else Store.openWith(this, rel);
      return;
    }
    if (!Cloud.active(this)) {
      Ui.toast(this, "This file is not on this phone");
      return;
    }
    Ui.toast(this, "Downloading…");
    const main = new Handler(Looper.getMainLooper());
    // Sync.fetchFile is a Promise on the web (a blocking call in a Thread on the phone)
    const done = (err) => {
      const e2 = err;
      main.post({
        run: () => {
          if (this.isFinishing()) return;
          if (e2 != null) {
            Ui.toast(this, "Could not download: " + e2);
            return;
          }
          this.render();
          if (share) Store.share(this, rel, "Presentation");
          else Store.openWith(this, rel);
        }
      });
    };
    let p;
    try {
      p = Promise.resolve(Sync.fetchFile(this, this.db, rel));
    } catch (e) {
      p = Promise.reject(e);
    }
    p.then(() => done(null), (e) => done(e == null ? "error" : (e.message ? e.message : String(e))));
  }

  upload() {
    Store.pick(this, PresentationsActivity.MIMES, PresentationsActivity.REQ_FILE);
  }

  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    if (req !== PresentationsActivity.REQ_FILE || res !== RESULT_OK || data == null || data.getData() == null) return;
    const uri = data.getData();
    const name = Store.displayName(this, uri);
    let ext = Store.extOf(name);
    const mime = Ui.nz(this.getContentResolver().getType(uri));
    if (!ext.equals("pdf") && !ext.equals("ppt") && !ext.equals("pptx")) {
      if (mime.equals("application/pdf")) ext = "pdf";
      else if (mime.contains("presentationml")) ext = "pptx";
      else if (mime.contains("powerpoint")) ext = "ppt";
      else {
        Ui.toast(this, "Choose a PPT, PPTX or PDF file");
        return;
      }
    }
    const title = name.contains(".") ? name.substring(0, name.lastIndexOf('.')) : name;
    try {
      const rel = this.save(uri, ext);
      this.details(rel, title.split('_').join(' ').trim());
    } catch (e) {
      Ui.toast(this, e.getMessage());
    }
  }

  /** Copies the picked file to academics/ and returns its path; refuses files over the size limit. */
  save(uri, ext) {
    const rel = "academics/" + this.kind.toLowerCase() + "_" + System.currentTimeMillis() + "." + ext;
    const out = this.db.file(rel);
    out.getParentFile().mkdirs();
    const inp = this.getContentResolver().openInputStream(uri);
    if (inp == null) throw new Error("Could not read the file");
    try {
      Store.copy(inp, new FileOutputStream(out));
    } finally {
      inp.close();
    }
    if (out.length() > PresentationsActivity.MAX_BYTES) {
      out.delete();
      throw new Error("The file is larger than 45 MB. Save it as PDF or compress the pictures, then try again.");
    }
    return rel;
  }

  /** Asks for the title, date, presenter and session, then adds the presentation. */
  details(rel, title) {
    const db = this.db;
    const sessions = db.rows("SELECT id, date, topic FROM academics WHERE kind=? ORDER BY date DESC, id DESC LIMIT 20", this.kind);
    const labels = new Array(sessions.size() + 1).fill(null);
    const values = new Array(sessions.size() + 1).fill(null);
    labels[0] = "Not linked";
    values[0] = "";
    for (let i = 0; i < sessions.size(); i++) {
      const s = sessions.get(i);
      labels[i + 1] = Dates.nice(s.get("date")) + "  " + s.get("topic");
      values[i + 1] = s.get("id");
    }
    const f = new Form(this);
    f.text("title", "Title *", title, Form.PLAIN);
    f.suggest("presenter", "Presented by", Reminders.myName(this, db), db.staffNames(""));
    f.date("date", "Date presented", sessions.isEmpty() ? Dates.todayIso() : sessions.get(0).get("date"));
    f.choice("academic_id", "Session", labels, values, sessions.isEmpty() ? "" : values[1], null);
    Ui.formDialog(this, "Add presentation", f, "Upload", {
      run: () => {
        if (!f.require("title", "Enter a title")) return false;
        const cv = new ContentValues();
        cv.put("kind", this.kind);
        cv.put("title", f.get("title"));
        cv.put("presenter", f.get("presenter"));
        cv.put("date", f.get("date"));
        cv.put("academic_id", f.get("academic_id"));
        cv.put("file", rel);
        cv.put("size", db.file(rel).length());
        cv.put("added_by", Approvals.me(this));
        cv.put("added_on", Dates.todayIso() + " " + Dates.now());
        db.insert("acad_files", cv);
        Ui.toast(this, Cloud.active(this) ? "Added. It is shared with the department in the background." : "Added");
        this.render();
        return true;
      }
    });
  }
}
