'use strict';
/**
 * Live quiz, played together in class like Kahoot. Faculty and PGs make quizzes (kept in the shared table quiz_sets)
 * and host them from the app on the projector; students join with a 6-digit PIN, from the app or from any phone
 * browser (quiz.html on the web app), with only a name. The server (quiz_* functions in supabase-setup.sql) keeps the
 * game, times each question and scores the answers: a right answer earns 500 to 1000 points, more for a fast one.
 */
class Quiz {
  constructor() {}

  /** Answer colours and shapes, as on the projector and on the students' phones. */
  static COLORS = [0xFFE21B3C, 0xFF1368CE, 0xFFD89E00, 0xFF26890C];
  static SHAPES = ["▲", "◆", "●", "■"];
  static PURPLE = 0xFF46178F;
  static GRADIENT = [0xFF2E0F63, 0xFF46178F, 0xFF864CBF];
  static SECS = ["10", "20", "30", "60", "90"];

  /** Faculty (and the HOD, Medical Registrar, admin) and PGs host quizzes. */
  static canHost(c) {
    if (!Cloud.active(c)) return false;
    return SessionAttendance.canRun(c) || "pg".equals(Cloud.role(c));
  }

  /** Calls a quiz function on the server. Errors carry the server's message ("No live quiz with this PIN"). */
  static rpc(c, fn, args) {
    return new JSONObject(Cloud.json(c, "POST", "/rest/v1/rpc/" + fn, args).text());
  }

  static questions(set) {
    try {
      return new JSONArray(Ui.nz(set.get("questions")).isEmpty() ? "[]" : set.get("questions"));
    } catch (e) {
      return new JSONArray();
    }
  }

  /** Where students join from a browser: the web app's address (Settings, or Live quiz › Student link) + quiz.html. */
  static joinLink(db) {
    let u = db.setting("quiz_url", "").trim();
    if (u.isEmpty()) return "";
    u = u.replaceFirstRx("^https?://", "");
    if (u.endsWith("/")) u = u.substring(0, u.length - 1);
    return u.endsWith(".html") ? u : u + "/quiz.html";
  }

  static ordinal(n) {
    const m = n % 100;
    const s = m >= 11 && m <= 13 ? "th" : n % 10 === 1 ? "st" : n % 10 === 2 ? "nd" : n % 10 === 3 ? "rd" : "th";
    return n + s;
  }

  // ---------- shared pieces of the host and player screens ----------

  /** A big coloured answer tile: its shape, and the option's text. */
  static tile(c, i, text, textSp, dim) {
    const t = Ui.h(c);
    t.setGravity(Gravity.CENTER_VERTICAL);
    const col = dim ? Ui.mix(Quiz.COLORS[i], Color.WHITE, 0.6) : Quiz.COLORS[i];
    t.setBackground(Ui.round(c, col, 12));
    t.setPadding(Ui.dp(c, 12), Ui.dp(c, 14), Ui.dp(c, 12), Ui.dp(c, 14));
    t.setMinimumHeight(Ui.dp(c, 64));
    const s = Ui.tv(c, Quiz.SHAPES[i], textSp + 6, Color.WHITE, true);
    t.addView(s);
    const o = Ui.tv(c, text, textSp, Color.WHITE, true);
    o.setPadding(Ui.dp(c, 10), 0, 0, 0);
    t.addView(o, Ui.weight(1));
    return t;
  }

  /** Two answer tiles to a row. */
  static grid(c, ...tiles) {
    if (tiles.length === 1 && Array.isArray(tiles[0])) tiles = tiles[0];
    const g = Ui.v(c);
    let row = null;
    for (let i = 0; i < tiles.length; i++) {
      if (i % 2 === 0) {
        row = Ui.h(c);
        g.addView(row);
      }
      const lp = Ui.weight(1);
      lp.setMargins(Ui.dp(c, 4), Ui.dp(c, 4), Ui.dp(c, 4), Ui.dp(c, 4));
      row.addView(tiles[i], lp);
    }
    if (tiles.length % 2 === 1) row.addView(new View(c), Ui.weight(1));
    return g;
  }

  /** The round countdown: seconds left in a purple circle. */
  static timer(c, left) {
    const t = Ui.tv(c, String(toInt(Math.ceil(left))), 26, Color.WHITE, true);
    t.setGravity(Gravity.CENTER);
    t.setBackground(Ui.round(c, left <= 5 ? 0xFFE21B3C : Quiz.PURPLE, 32));
    return t;
  }

  /** A white rounded card for the question text. */
  static questionCard(c, q, sp) {
    const t = Ui.tv(c, q, sp, Ui.TEXT, true);
    t.setGravity(Gravity.CENTER);
    t.setBackground(Ui.round(c, Color.WHITE, 14));
    t.setPadding(Ui.dp(c, 16), Ui.dp(c, 18), Ui.dp(c, 16), Ui.dp(c, 18));
    return t;
  }
}
;
