/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * A student's phone in a live quiz: enter the PIN and a name, then tap the colour of the answer for each question.
 * Shows right or wrong, the points and the place after each question, and the final place at the end.
 */
class QuizPlayActivity extends Base {
  constructor() {
    super();
    this.pin = "";
    this.token = "";
    this.st = null;
    this.error = null;
    this.busy = false;
    /** The answer tapped for the current question, until the server confirms it. */
    this.sentQ = -1;
    this.sentChoice = -1;
    this.body = null;
    this.pinEdit = null;
    this.nameEdit = null;
    this.typedPin = null;
    this.typedName = null;
    this.h = new Handler(Looper.getMainLooper());
    this.poll = {
      run: () => {
        if (!this.token.isEmpty()) this.refresh();
        this.h.postDelayed(this.poll, 1000);
      }
    };
  }

  prefs() {
    return this.getSharedPreferences("quiz", Context.MODE_PRIVATE);
  }

  onCreate(b) {
    super.onCreate(b);
    this.pin = this.prefs().getString("pin", "");
    this.token = this.prefs().getString("token", "");
    this.setTitle("Live quiz");
    this.subtitle = "Tap the colour of your answer";
    this.headerColors = Quiz.GRADIENT;
    this.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
  }

  liveRefresh() {
    return false;
  }

  onResume() {
    super.onResume();
    this.h.removeCallbacks(this.poll);
    this.h.post(this.poll);
  }

  onPause() {
    super.onPause();
    this.h.removeCallbacks(this.poll);
  }

  render() {
    if (this.body == null) {
      this.body = Ui.v(this);
      this.setPage(this.body);
    }
    this.draw();
  }

  leave() {
    this.prefs().edit().remove("token").apply();
    this.token = "";
    this.st = null;
    this.error = null;
    this.draw();
  }

  join() {
    const p = this.pinEdit.getText().toString().replaceAllRx("\\D", "");
    const n = this.nameEdit.getText().toString().trim();
    if (p.length !== 6) {
      this.pinEdit.setError("6 digits");
      return;
    }
    if (n.isEmpty()) {
      this.nameEdit.setError("Your name");
      return;
    }
    this.prefs().edit().putString("name", n).apply();
    this.busy = true;
    new Thread({
      run: () => {
        let err = null;
        try {
          const j = Quiz.rpc(this, "quiz_join", new JSONObject().put("p_pin", p).put("p_name", n));
          this.pin = p;
          this.token = j.getString("token");
          this.prefs().edit().putString("pin", this.pin).putString("token", this.token).apply();
        } catch (e) {
          err = e.getMessage();
        }
        const fe = err;
        this.runOnUiThread({
          run: () => {
            this.busy = false;
            this.error = fe;
            if (fe == null) this.refresh();
            this.draw();
          }
        });
      }
    }).start();
  }

  refresh() {
    if (this.busy) return;
    this.busy = true;
    new Thread({
      run: () => {
        let s = null;
        let err = null;
        try {
          s = Quiz.rpc(this, "quiz_state", new JSONObject().put("p_pin", this.pin).put("p_token", this.token));
        } catch (e) {
          err = e.getMessage();
        }
        const fs = s;
        const fe = err;
        this.runOnUiThread({
          run: () => {
            this.busy = false;
            if (this.isFinishing()) return;
            if (fs != null) {
              this.st = fs;
              this.error = null;
            } else if (fe != null && fe.contains("Join the quiz again")) {
              this.leave();
              this.error = "That quiz has closed. Enter a new PIN.";
            } else this.error = fe;
            this.draw();
          }
        });
      }
    }).start();
  }

  answer(q, choice) {
    this.sentQ = q;
    this.sentChoice = choice;
    this.draw();
    new Thread({
      run: () => {
        let err = null;
        try {
          Quiz.rpc(this, "quiz_answer", new JSONObject().put("p_pin", this.pin).put("p_token", this.token).put("p_q", q).put("p_choice", choice));
        } catch (e) {
          err = e.getMessage();
        }
        const fe = err;
        this.runOnUiThread({
          run: () => {
            if (fe != null) {
              this.sentQ = -1;
              this.error = fe;
            }
            this.draw();
          }
        });
      }
    }).start();
  }

  big(s, sp, color) {
    const t = Ui.tv(this, s, sp, color, true);
    t.setGravity(Gravity.CENTER);
    return t;
  }

  draw() {
    if (this.body == null) return;
    if (this.pinEdit != null && this.pinEdit.isAttachedToWindow()) {
      this.typedPin = this.pinEdit.getText().toString();
      this.typedName = this.nameEdit.getText().toString();
    }
    this.body.removeAllViews();
    this.drawState();
    if (!this.token.isEmpty() && this.st != null && !"ended".equals(this.st.optString("state"))) {
      const out = Ui.outlineButton(this, "Leave quiz", Ui.MUTED, {
        onClick: (v) => {
          Ui.confirm(this, "Leave the quiz?", "Your score stays on the leaderboard.", "Leave", { run: () => { this.leave(); } });
        }
      });
      this.body.addView(out);
      Ui.margins(out, 0, 24, 0, 0);
    }
  }

  drawState() {
    const body = this.body;
    body.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), Ui.dp(this, 28));
    if (this.error != null) {
      const e = this.big(this.error, 14, Ui.RED);
      e.setPadding(0, Ui.dp(this, 6), 0, Ui.dp(this, 6));
      body.addView(e);
    }
    if (this.token.isEmpty()) {
      this.joinForm();
      return;
    }
    const st = this.st;
    if (st == null) {
      body.addView(this.emptyNote("Connecting…"));
      return;
    }
    const state = st.optString("state");
    const q = st.optInt("q_index"), total = st.optInt("total");
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    top.addView(Ui.softPill(this, st.optString("name"), Quiz.PURPLE));
    top.addView(new View(this), Ui.weight(1));
    top.addView(Ui.tv(this, st.optInt("score") + " pts", 16, Ui.TEXT, true));
    body.addView(top);

    if (state.equals("lobby")) {
      body.addView(this.big("You're in! 🎉", 28, Quiz.PURPLE));
      body.addView(this.big("See your name on the screen.\nWaiting for the host to start…", 16, Ui.MUTED));
      body.addView(this.big(st.optInt("players") + " players", 14, Ui.MUTED));
      return;
    }
    const qo = st.optJSONObject("question");
    if (state.equals("question") && qo != null) {
      const mine = !st.isNull("choice") || this.sentQ === q;
      const chosen = !st.isNull("choice") ? st.optInt("choice") : this.sentChoice;
      const qt = Ui.h(this);
      qt.setGravity(Gravity.CENTER_VERTICAL);
      qt.addView(Ui.softPill(this, "Question " + (q + 1) + " of " + total, Quiz.PURPLE));
      qt.addView(new View(this), Ui.weight(1));
      qt.addView(Quiz.timer(this, st.optDouble("left")), Ui.lp(Ui.dp(this, 52), Ui.dp(this, 52)));
      body.addView(qt);
      Ui.margins(qt, 0, 8, 0, 8);
      body.addView(Quiz.questionCard(this, qo.optString("q"), 17));
      if (mine) {
        const w = this.big(Quiz.SHAPES[Math.max(0, chosen)] + "\nAnswer sent\nWaiting for the others…", 20, Color.WHITE);
        w.setBackground(Ui.round(this, Quiz.COLORS[Math.max(0, Math.min(3, chosen))], 16));
        w.setPadding(0, Ui.dp(this, 24), 0, Ui.dp(this, 24));
        body.addView(w);
        Ui.margins(w, 0, 12, 0, 0);
        return;
      }
      if (st.optDouble("left") <= 0) {
        body.addView(this.big("⏰ Time's up", 22, Quiz.COLORS[0]));
        return;
      }
      const o = qo.optJSONArray("options");
      const tiles = new Array(o == null ? 0 : o.length()).fill(null);
      for (let k = 0; k < tiles.length; k++) {
        const kk = k;
        const qq = q;
        const t = Quiz.tile(this, k, o.optString(k), 16, false);
        t.setMinimumHeight(Ui.dp(this, 96));
        Ui.ripple(t, 0x55FFFFFF);
        t.setOnClickListener({ onClick: (v) => { this.answer(qq, kk); } });
        tiles[k] = t;
      }
      const g = Quiz.grid(this, tiles);
      body.addView(g);
      Ui.margins(g, 0, 10, 0, 0);
      return;
    }
    if (state.equals("reveal") || state.equals("board") || (state.equals("question") && qo == null)) {
      const answered = !st.isNull("choice");
      const ans = st.isNull("answer") ? -1 : st.optInt("answer");
      const right = answered && st.optInt("choice") === ans;
      const r = this.big(right ? "✓  Correct\n+" + st.optInt("points") + " points" : answered ? "✗  Incorrect" : "⏰  No answer", 26, Color.WHITE);
      r.setBackground(Ui.round(this, right ? Quiz.COLORS[3] : Quiz.COLORS[0], 16));
      r.setPadding(0, Ui.dp(this, 26), 0, Ui.dp(this, 26));
      body.addView(r);
      Ui.margins(r, 0, 14, 0, 10);
      if (!right && qo != null && ans >= 0) {
        const o = qo.optJSONArray("options");
        if (o != null && ans < o.length()) body.addView(Quiz.tile(this, ans, "Right answer: " + o.optString(ans), 15, false));
      }
      body.addView(this.big("You are " + Quiz.ordinal(st.optInt("rank")) + " of " + st.optInt("players"), 20, Quiz.PURPLE));
      return;
    }
    // ended
    this.h.removeCallbacks(this.poll);
    body.addView(this.big("🏁", 48, Quiz.PURPLE));
    body.addView(this.big("Final: " + Quiz.ordinal(st.optInt("rank")) + " of " + st.optInt("players"), 26, Quiz.PURPLE));
    body.addView(this.big(st.optInt("score") + " points", 20, Ui.TEXT));
    if (st.optInt("rank") <= 3) body.addView(this.big(["🥇", "🥈", "🥉"][st.optInt("rank") - 1] + "  Well done!", 22, Ui.TEXT));
    const again = Ui.button(this, "Join another quiz", Quiz.PURPLE, { onClick: (v) => { this.leave(); } });
    body.addView(again);
    Ui.margins(again, 0, 16, 0, 0);
  }

  joinForm() {
    const card = Ui.card(this);
    card.setBackground(Glass.hero(this, Quiz.GRADIENT, 20));
    card.addView(this.big("🎮  Live quiz", 24, Color.WHITE));
    card.addView(this.big("Enter the game PIN on the screen", 14, 0xE6FFFFFF));
    const pinEdit = this.pinEdit = new EditText(this);
    pinEdit.setHint("Game PIN");
    pinEdit.setInputType(InputType.TYPE_CLASS_NUMBER);
    pinEdit.setTextSize(28);
    pinEdit.setGravity(Gravity.CENTER);
    pinEdit.setBackground(Ui.round(this, Color.WHITE, 12));
    pinEdit.setText(this.typedPin != null ? this.typedPin : this.pin);
    card.addView(pinEdit);
    Ui.margins(pinEdit, 0, 14, 0, 0);
    const nameEdit = this.nameEdit = new EditText(this);
    nameEdit.setHint("Your name");
    nameEdit.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_CAP_WORDS);
    nameEdit.setTextSize(20);
    nameEdit.setGravity(Gravity.CENTER);
    nameEdit.setBackground(Ui.round(this, Color.WHITE, 12));
    let n = this.prefs().getString("name", "");
    if (n.isEmpty() && Cloud.active(this)) n = Cloud.prefs(this).getString("name", "");
    nameEdit.setText(this.typedName != null ? this.typedName : n);
    card.addView(nameEdit);
    Ui.margins(nameEdit, 0, 10, 0, 0);
    const go = Ui.button(this, "Join  ▶", Quiz.COLORS[3], { onClick: (v) => { if (!this.busy) this.join(); } });
    card.addView(go);
    Ui.margins(go, 0, 14, 0, 0);
    this.body.addView(card);
  }
}
;
