'use strict';
/**
 * Browser stub of the Supabase Realtime client the intercom uses (Phoenix channels over a WebSocket). The intercom works
 * only in the Android app, so nothing connects here; every method keeps its name and does nothing.
 * Interface Realtime.Handler { onBroadcast(channel, event, payload); onPresence(channel); onStatus(connected); onJoinFailed(channel, why); }
 * Interface Realtime.Tokens { token(); }
 */
class Realtime {
  constructor(wsUrl, tokens, handler) {
    this.wsUrl = wsUrl;
    this.tokens = tokens;
    this.handler = handler;
    this.restUrl = "";
    this.apiKey = "";
  }

  /** The WebSocket address of a project. */
  static urlFor(projectUrl, apiKey) {
    const u = projectUrl.endsWith("/") ? projectUrl.substring(0, projectUrl.length - 1) : projectUrl;
    return u.replaceFirstRx("^http", "ws") + "/realtime/v1/websocket?apikey=" + apiKey + "&vsn=1.0.0";
  }

  setRest(projectUrl, key) {
    this.restUrl = projectUrl;
    this.apiKey = key;
  }

  post(topic, event, payload) {
  }

  isConnected() { return false; }

  start() {
  }

  stop() {
  }

  join(name, presenceKey) {
  }

  leave(name) {
  }

  joined(name) { return false; }

  broadcast(channel, event, payload) { return false; }

  track(channel, meta) {
  }

  /** Who is online on a channel: presence key to meta (none in the browser). */
  online(channel) { return new JMap(); }

  refreshToken() {
  }

  // Ws.Listener
  onOpen() {
  }

  onClose(why) {
  }

  onText(text) {
  }
}
