/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Department statistics for a date range, with text sharing and CSV export. */
class ReportActivity extends Base {
  constructor() { super(); this.from = null; this.to = null; }

  static REQ_CSV = 21;
  static COLS = ["Ward", "Adm", "In", "Out", "Disch", "Death", "Now"];

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Reports & statistics");
    this.headerColor(Ui.SKY);
    this.to = Dates.today();
    this.from = Dates.monthStart(this.to);
  }

  /** One row per ward: admissions, transfers in, transfers out, discharges, deaths, current census. */
  unitRow(u) {
    const db = this.db;
    const a = this.from.toString(), b = this.to.toString();
    return [
      db.events(Db.ADMIT, a, b, Db.isWardUnit(u) ? "from_loc" : "to_loc", u),
      db.transfers(a, b, null, u),
      db.transfers(a, b, u, null),
      db.events(Db.DISCHARGE, a, b, "from_loc", u),
      db.events(Db.DEATH, a, b, "from_loc", u),
      db.census(u, null)];
  }

  static pct(deaths, discharges) {
    const out = deaths + discharges;
    return out === 0 ? "-" : jfmt("%.1f%%", deaths * 100.0 / out);
  }

  render() {
    const db = this.db;
    const pct = ReportActivity.pct;
    const page = Ui.v(this);
    const range = Ui.card(this);
    range.addView(Ui.muted(this, "Period"));
    const pick = Ui.h(this);
    pick.addView(this.dateButton(true), Ui.weight(1));
    const dash = Ui.tv(this, "  to  ", 14, Ui.MUTED, false);
    pick.addView(dash);
    pick.addView(this.dateButton(false), Ui.weight(1));
    range.addView(pick);
    const t = Dates.today();
    const quick = Ui.h(this);
    quick.setPadding(0, Ui.dp(this, 10), 0, 0);
    this.quickChip(quick, "Today", t, t);
    this.quickChip(quick, "This week", Dates.weekStart(t), t);
    this.quickChip(quick, "This month", Dates.monthStart(t), t);
    this.quickChip(quick, "Last month", Dates.monthStart(t).minusMonths(1), Dates.monthStart(t).minusDays(1));
    this.quickChip(quick, "This year", t.withDayOfYear(1), t);
    range.addView(Ui.hscroll(this, quick));
    page.addView(range);

    // Ward movement table
    page.addView(Ui.section(this, "Ward movement"));
    const tbl = Ui.card(this);
    tbl.setPadding(Ui.dp(this, 10), Ui.dp(this, 12), Ui.dp(this, 10), Ui.dp(this, 12));
    tbl.addView(this.tableRow(ReportActivity.COLS, true, 0));
    const tot = new Array(6).fill(0);
    for (const u of Db.ALL_LOCS) {
      const r = this.unitRow(u);
      const cells = new Array(7).fill(null);
      cells[0] = Db.shortName(u);
      for (let i = 0; i < 6; i++) {
        cells[i + 1] = String(r[i]);
        if (Db.KDP !== u) tot[i] += r[i];
      }
      tbl.addView(this.tableRow(cells, false, Ui.unitColor(u)));
    }
    const total = ["TVMCH", String(tot[0]), "", "", String(tot[3]), String(tot[4]), String(db.totalInpatients())];
    tbl.addView(Ui.divider(this));
    tbl.addView(this.tableRow(total, true, 0));
    tbl.addView(Ui.space(this, 6));
    tbl.addView(Ui.muted(this, "Adm = new admissions · In / Out = transfers between wards · Now = current census. TVMCH totals exclude Kandiyaperi."));
    page.addView(tbl);

    const mort = Ui.card(this);
    mort.addView(Ui.kv(this, "TVMCH mortality", pct(tot[4], tot[3]) + "  (deaths / all outcomes)"));
    for (const sw of Db.SPECIAL) {
      const r = this.unitRow(sw);
      mort.addView(Ui.kv(this, Db.unitName(sw) + " mortality", pct(r[4], r[3] + r[2])));
    }
    const k = this.unitRow(Db.KDP);
    mort.addView(Ui.kv(this, "Kandiyaperi mortality", pct(k[4], k[3] + k[2])));
    page.addView(mort);

    const a0 = this.from.toString(), b0 = this.to.toString();
    page.addView(Ui.section(this, "DAP duty register"));
    const dap = Ui.card(this);
    dap.addView(Ui.kv(this, "Duty days logged", String(db.num("SELECT COUNT(*) FROM dap WHERE date BETWEEN ? AND ?", a0, b0))));
    dap.addView(Ui.kv(this, "Admissions (DAP)", String(db.num("SELECT SUM(admissions) FROM dap WHERE date BETWEEN ? AND ?", a0, b0))));
    dap.addView(Ui.kv(this, "Absconded", String(db.num("SELECT SUM(abscond) FROM dap WHERE date BETWEEN ? AND ?", a0, b0))));
    dap.addView(Ui.kv(this, "AMA / LAMA", String(db.num("SELECT SUM(ama) FROM dap WHERE date BETWEEN ? AND ?", a0, b0))));
    dap.addView(Ui.kv(this, "Deaths (DAP)", String(db.num("SELECT SUM(deaths) FROM dap WHERE date BETWEEN ? AND ?", a0, b0))));
    page.addView(dap);

    page.addView(Ui.section(this, "Call over by unit"));
    const co = Ui.card(this);
    for (const u of Db.WARD_UNITS)
      co.addView(Ui.kv(this, u, db.num("SELECT COUNT(*) FROM callover WHERE unit=? AND date BETWEEN ? AND ?", u, a0, b0) + " calls  ·  "
        + db.num("SELECT COUNT(*) FROM callover WHERE unit=? AND date BETWEEN ? AND ? AND status IN ('Pending','Follow-up')", u, a0, b0) + " open"));
    page.addView(co);

    page.addView(Ui.section(this, "Kandiyaperi outpatients"));
    const op = Ui.card(this);
    op.addView(Ui.kv(this, "New male", String(db.num("SELECT SUM(new_m) FROM kdp_op WHERE date BETWEEN ? AND ?", a0, b0))));
    op.addView(Ui.kv(this, "New female", String(db.num("SELECT SUM(new_f) FROM kdp_op WHERE date BETWEEN ? AND ?", a0, b0))));
    op.addView(Ui.kv(this, "Review", String(db.num("SELECT SUM(review) FROM kdp_op WHERE date BETWEEN ? AND ?", a0, b0))));
    op.addView(Ui.kv(this, "OP days entered", String(db.num("SELECT COUNT(*) FROM kdp_op WHERE date BETWEEN ? AND ?", a0, b0))));
    page.addView(op);

    // Academics
    const a = this.from.toString(), b = this.to.toString();
    page.addView(Ui.section(this, "Teaching & academics"));
    const ac = Ui.card(this);
    for (let i = 0; i < Db.CLASS_KINDS.length; i++)
      ac.addView(Ui.kv(this, Db.CLASS_LABELS[i], String(db.num("SELECT COUNT(*) FROM classes WHERE kind=? AND date BETWEEN ? AND ?", Db.CLASS_KINDS[i], a, b))));
    for (let i = 0; i < Db.ACAD_KINDS.length; i++)
      ac.addView(Ui.kv(this, Db.ACAD_LABELS[i], String(db.num("SELECT COUNT(*) FROM academics WHERE kind=? AND date BETWEEN ? AND ?", Db.ACAD_KINDS[i], a, b))));
    page.addView(ac);

    page.addView(Ui.section(this, "Classes taken, by teacher"));
    const byT = Ui.card(this);
    const teachers = db.rows("SELECT taken_by, SUM(kind='MBBS') AS mbbs, SUM(kind='PG') AS pg FROM classes WHERE date BETWEEN ? AND ? AND taken_by<>'' GROUP BY taken_by ORDER BY COUNT(*) DESC", a, b);
    if (teachers.isEmpty()) byT.addView(Ui.muted(this, "No classes logged in this period"));
    for (const r of teachers)
      byT.addView(Ui.kv(this, r.get("taken_by"), "MBBS " + r.get("mbbs") + "  ·  PG " + r.get("pg")));
    page.addView(byT);

    page.addView(Ui.section(this, "CMCHIS (weeks starting in period)"));
    const cm = Ui.card(this);
    let cmTotal = 0;
    for (const u of Db.UNITS) {
      const n = db.num("SELECT SUM(cases) FROM cmchis WHERE unit=? AND week_start BETWEEN ? AND ?", u, a, b);
      cmTotal += n;
      cm.addView(Ui.kv(this, Db.unitName(u), String(n)));
    }
    cm.addView(Ui.divider(this));
    cm.addView(Ui.kv(this, "Total cases", String(cmTotal)));
    const amt = db.dbl("SELECT SUM(amount) FROM cmchis WHERE week_start BETWEEN ? AND ?", a, b);
    if (amt > 0) cm.addView(Ui.kv(this, "Total amount", "₹ " + Math.round(amt).toLocaleString('en-US')));
    page.addView(cm);

    const btns = Ui.card(this);
    btns.addView(Ui.buttonRow(this,
      Ui.button(this, "Share summary", Ui.GREEN, { onClick: (v) => { ReportActivity.shareText(this, this.summaryText()); } }),
      Ui.button(this, "Export CSV", Ui.PRIMARY, {
        onClick: (v) => {
          const i = new Intent(Intent.ACTION_CREATE_DOCUMENT);
          i.addCategory(Intent.CATEGORY_OPENABLE);
          i.setType("text/csv");
          i.putExtra(Intent.EXTRA_TITLE, "TVMCHMED-patients-" + this.from + "-to-" + this.to + ".csv");
          this.startActivityForResult(i, ReportActivity.REQ_CSV);
        }
      })));
    btns.addView(Ui.muted(this, "CSV lists every patient admitted in the period with outcome, for Excel."));
    const mr = Ui.button(this, "Monthly report for the HOD (PDF)", Ui.PRIMARY_DARK, { onClick: (v) => { MonthlyReport.choose(this, true); } });
    const mw = Ui.outlineButton(this, "Monthly report as Word", Ui.PRIMARY_DARK, { onClick: (v) => { MonthlyReport.choose(this, false); } });
    btns.addView(mr);
    Ui.margins(mr, 0, 10, 0, 0);
    btns.addView(mw);
    Ui.margins(mw, 0, 6, 0, 0);
    btns.addView(Ui.muted(this, "Admissions, deaths, CMCHIS claims and academics of one month in one file."));
    page.addView(btns);
    this.setPage(page);
  }

  tableRow(cells, bold, unitColor) {
    const row = Ui.h(this);
    row.setPadding(0, Ui.dp(this, 5), 0, Ui.dp(this, 5));
    for (let i = 0; i < cells.length; i++) {
      let t;
      if (i === 0 && unitColor !== 0) {
        t = Ui.pill(this, cells[i], unitColor);
        t.setTextSize(11);
        t.setGravity(Gravity.CENTER);
        const wrap = Ui.h(this);
        wrap.addView(t);
        row.addView(wrap, Ui.weight(1.3));
        continue;
      }
      t = Ui.tv(this, cells[i], 13, bold ? Ui.TEXT : Ui.TEXT, bold);
      if (bold) t.setTypeface(Typeface.DEFAULT_BOLD);
      t.setGravity(i === 0 ? Gravity.START : Gravity.CENTER);
      row.addView(t, Ui.weight(i === 0 ? 1.3 : 1));
    }
    return row;
  }

  dateButton(isFrom) {
    const t = Ui.outlineButton(this, Dates.nice(isFrom ? this.from : this.to), Ui.PRIMARY, {
      onClick: (v) => {
        const d = isFrom ? this.from : this.to;
        new DatePickerDialog(this, {
          onDateSet: (p, y, m, day) => {
            const n = LocalDate.of(y, m + 1, day);
            if (isFrom) this.from = n; else this.to = n;
            if (this.from.isAfter(this.to)) { const x = this.from; this.from = this.to; this.to = x; }
            this.render();
          }
        }, d.getYear(), d.getMonthValue() - 1, d.getDayOfMonth()).show();
      }
    });
    return t;
  }

  quickChip(row, label, a, b) {
    const c = Ui.chip(this, label, a.equals(this.from) && b.equals(this.to), Ui.PRIMARY);
    c.setOnClickListener({ onClick: (v) => { this.from = a; this.to = b; this.render(); } });
    row.addView(c);
  }

  summaryText() {
    const db = this.db;
    const s = new StringBuilder();
    s.append("TVMCHMED – ").append(db.setting("dept", "")).append(", ").append(db.setting("college", "")).append('\n');
    s.append("Report ").append(Dates.nice(this.from)).append(" to ").append(Dates.nice(this.to)).append("\n\n");
    s.append("Ward: Adm / In / Out / Disch / Death / Now\n");
    for (const u of Db.ALL_LOCS) {
      const r = this.unitRow(u);
      s.append(Db.shortName(u)).append(": ").append(r[0]).append(" / ").append(r[1]).append(" / ").append(r[2])
        .append(" / ").append(r[3]).append(" / ").append(r[4]).append(" / ").append(r[5]).append('\n');
    }
    const a = this.from.toString(), b = this.to.toString();
    s.append("\nAcademics\n");
    for (let i = 0; i < Db.CLASS_KINDS.length; i++)
      s.append(Db.CLASS_LABELS[i]).append(": ").append(db.num("SELECT COUNT(*) FROM classes WHERE kind=? AND date BETWEEN ? AND ?", Db.CLASS_KINDS[i], a, b)).append('\n');
    for (let i = 0; i < Db.ACAD_KINDS.length; i++)
      s.append(Db.ACAD_LABELS[i]).append(": ").append(db.num("SELECT COUNT(*) FROM academics WHERE kind=? AND date BETWEEN ? AND ?", Db.ACAD_KINDS[i], a, b)).append('\n');
    s.append("CMCHIS cases: ").append(db.num("SELECT SUM(cases) FROM cmchis WHERE week_start BETWEEN ? AND ?", a, b)).append('\n');
    return s.toString();
  }

  /** Today's census as a short message for WhatsApp / SMS. */
  static censusText(db) {
    const t = Dates.today();
    const iso = t.toString();
    const s = new StringBuilder();
    s.append("TVMCHMED – Medicine census\n").append(Dates.longFmt(t)).append(", ").append(Dates.now()).append('\n');
    const adm = db.admittingUnits(Dates.dow(t));
    s.append("Admitting today: ").append(adm.isEmpty() ? "-" : TextUtils.join(", ", adm)).append(" + IMCU\n\n");
    for (const u of Db.WARD_UNITS) {
      const m = db.census(u, "M"), f = db.census(u, "F"), ic = db.awayFrom(u);
      s.append(u).append(": Male ").append(m).append(", Female ").append(f).append(" = ").append(m + f);
      if (ic > 0) s.append(" (+").append(ic).append(" in special wards)");
      s.append('\n');
    }
    for (const w of Db.SPECIAL)
      s.append(Db.unitName(w)).append(": ").append(db.census(w, null)).append(" (M ").append(db.census(w, "M")).append(", F ").append(db.census(w, "F")).append(")\n");
    s.append("Total TVMCH inpatients: ").append(db.totalInpatients()).append('\n');
    s.append("Kandiyaperi: ").append(db.census(Db.KDP, null)).append(" inpatients\n\n");
    s.append("Today – Admissions ").append(db.events(Db.ADMIT, iso, iso, null, null))
      .append(", Discharges ").append(db.events(Db.DISCHARGE, iso, iso, null, null))
      .append(", To IMCU ").append(db.transfers(iso, iso, null, Db.IMCU))
      .append(", Deaths ").append(db.events(Db.DEATH, iso, iso, null, null)).append('\n');
    return s.toString();
  }

  static shareText(a, text) {
    const i = new Intent(Intent.ACTION_SEND);
    i.setType("text/plain");
    i.putExtra(Intent.EXTRA_TEXT, text);
    a.startActivity(Intent.createChooser(i, "Share via"));
  }

  static csv(s) {
    const v = s == null ? "" : s.split("\"").join("\"\"");
    return "\"" + v + "\"";
  }

  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    if (req !== ReportActivity.REQ_CSV || res !== RESULT_OK || data == null || data.getData() == null) return;
    const uri = data.getData();
    try {
      const s = new StringBuilder("IP No,Name,Age,Sex,Phone,Diagnosis,Admitted to,Parent unit,Admit date,Status,Current location,Outcome date,Outcome notes,CMCHIS,CMCHIS ID\n");
      for (const p of this.db.rows(
        "SELECT p.*, e.to_loc AS admitted_to FROM patients p JOIN events e ON e.patient_id=p.id AND e.type='ADMIT' WHERE e.date BETWEEN ? AND ? ORDER BY e.date, p.id",
        this.from.toString(), this.to.toString())) {
        const f = [p.get("ip_no"), p.get("name"), p.get("age"), p.get("sex"), p.get("phone"), p.get("diagnosis"),
          p.get("admitted_to"), p.get("home_unit"), p.get("admit_date"), p.get("status"), p.get("location"),
          p.get("outcome_date"), p.get("outcome_note"), "1" === p.get("cmchis") ? "Yes" : "No", p.get("cmchis_no")];
        for (let i = 0; i < f.length; i++) {
          if (i > 0) s.append(',');
          s.append(ReportActivity.csv(f[i]));
        }
        s.append('\n');
      }
      const os = this.getContentResolver().openOutputStream(uri, "wt");
      os.write(jbytes(s.toString()));
      os.close();
      Ui.toast(this, "CSV saved");
    } catch (e) {
      Ui.toast(this, "Export failed: " + e.getMessage());
    }
  }
}
;
