/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** The daily duty roster: who is on duty where, in the same layout as the department's morning WhatsApp message. */
class Roster {
  /** Groups of {key, label}; each field holds one person per line ("Dr. Name 98765 43210"). */
  static GROUPS = ["Unit faculty", "OP", "Triage PGs", "CRRI", "IMCU PGs", "Critical Care Block", "Fever ward"];
  static FIELDS = [
    [["chief", "Chief"], ["aps", "Assistant Professors"], ["dap", "DAP"]],
    [["male_op", "Male OP PG"], ["female_op", "Female OP PG"], ["fever_op", "Fever OP"]],
    [["triage_pg_day", "7.30 AM to 12 PM"], ["triage_pg_night", "12 PM to 7.30 AM"]],
    [["op_crri", "OP duty CRRI"], ["triage_crri", "Triage CRRI (7.30 AM to 7.30 AM)"], ["stepdown_crri", "CRRI step down"],
      ["crri_triage_day", "CRRI triage 7.30 AM to 7.30 PM"], ["crri_triage_night", "CRRI triage 7.30 PM to 7.30 AM"]],
    [["imcu_day", "Day IMCU"], ["imcu_night", "Night IMCU"]],
    [["ccb_day_pg", "7.30 AM to 7.30 PM · PG"], ["ccb_day_crri", "7.30 AM to 7.30 PM · CRRI"],
      ["ccb_night_pg", "7.30 PM to 7.30 AM · PG"], ["ccb_night_crri", "7.30 PM to 7.30 AM · CRRI"]],
    [["fever_day_pg", "8 AM to 8 PM · PG"], ["fever_day_crmi", "8 AM to 8 PM · CRMI"], ["fever_night", "8 PM to 8 AM"]],
  ];

  static keys() {
    const k = [];
    for (const g of Roster.FIELDS) for (const f of g) k.add(f[0]);
    return k;
  }

  static ORDINALS = ["first", "second", "third", "fourth", "fifth", "sixth", "seventh"];

  static PHONE = Pattern.compile("(\\+?\\d[\\d ]{8,13}\\d)\\s*$");
  static TIME_RANGE = Pattern.compile("^\\(?\\s*(\\d{1,2}([.:]\\d{2})?\\s*(am|pm))\\s*to\\s*\\d{1,2}([.:]\\d{2})?\\s*(am|pm)\\s*\\)?\\s*:?\\s*(.*)$", Pattern.CASE_INSENSITIVE);
  static DATE = Pattern.compile("(\\d{1,2})[/.-](\\d{1,2})[/.-](\\d{2,4})");

  /** The phone number at the end of a line, digits only, or "". */
  static phone(line) {
    const m = Roster.PHONE.matcher(line.trim());
    return m.find() ? m.group(1).replaceAllRx("[^+\\d]", "") : "";
  }

  /** The name part of a line, without the phone number or a "PG :" label. */
  static name(line) {
    let s = line.trim().replaceFirstRx("^(PG|CRRI|CRMI)\\s*:\\s*", "");
    const m = Roster.PHONE.matcher(s);
    if (m.find()) s = s.substring(0, m.start());
    return s.trim();
  }

  /**
   * Reads the morning roster message as the department posts it on WhatsApp, e.g.
   * "*IMCU PGS*: / *Day IMCU* / Dr Starrose 84381 91047". Headings decide the field; time lines
   * ("7.30 PM to 7.30 AM") switch a section between its day and night fields; "PG :" / "CRRI :" pick the role.
   */
  static parse(text) {
    const p = new Roster.Parsed();
    let section = null, key = null;
    let night = false;
    for (const raw of text.jsplit("\\r?\\n")) {
      const line = raw.split("*").join("").split("‎").join("").trim();
      if (line.isEmpty() || line.matches("[-—–_=\\s]+")) continue;
      const low = line.toLowerCase();
      if (p.date == null) {
        const d = Roster.DATE.matcher(line);
        if (d.find()) {
          try {
            const y = Integer.parseInt(d.group(3));
            p.date = LocalDate.of(y < 100 ? 2000 + y : y, Integer.parseInt(d.group(2)), Integer.parseInt(d.group(1))).toString();
            continue;
          } catch (e) {}
        }
      }
      if (p.unit == null && low.contains("medical unit")) {
        for (let i = 0; i < Roster.ORDINALS.length; i++) if (low.startsWith(Roster.ORDINALS[i])) p.unit = Db.WARD_UNITS[i];
        if (p.unit == null) {
          const m = Pattern.compile("(\\d)").matcher(low);
          if (m.find()) p.unit = "M" + m.group(1);
        }
        continue;
      }
      if (low.startsWith("good morning") || low.startsWith("thank") || low.startsWith("department of")) continue;

      // inline "Heading: Dr Name 99999" lines
      let rest = "";
      const colon = line.indexOf(':');
      let head = low;
      if (colon > 0 && !low.startsWith("pg") && !low.startsWith("crri") && !low.startsWith("crmi") && !Roster.TIME_RANGE.matcher(line).find()) {
        head = low.substring(0, colon).trim();
        rest = line.substring(colon + 1).trim();
      }
      const newSection = Roster.sectionOf(head);
      if (newSection != null) {
        section = newSection;
        night = head.contains("night") || head.contains("7.30 pm to") || head.contains("7.30pm to");
        key = Roster.keyFor(section, night, "");
        if (!rest.isEmpty()) Roster.add(p, key, rest);
        continue;
      }
      const t = Roster.TIME_RANGE.matcher(line);
      if (t.find()) {
        night = t.group(3).equalsIgnoreCase("pm");
        // "12 pm to 7.30 am" on its own, before any section, belongs to the triage PGs
        if (section == null) section = "triage_pg";
        key = Roster.keyFor(section, night, "");
        const after = t.group(6).trim();
        if (!after.isEmpty()) {
          key = Roster.keyFor(section, night, Roster.roleOf(after));
          Roster.add(p, key, after);
        }
        continue;
      }
      if (section == null) continue;
      const role = Roster.roleOf(line);
      if (!role.isEmpty()) key = Roster.keyFor(section, night, role);
      if (key != null) Roster.add(p, key, line.replaceFirstRx("(?i)^(PG|CRRI|CRMI)\\s*:\\s*", ""));
    }
    return p;
  }

  static roleOf(line) {
    const l = line.toLowerCase();
    if (l.matches("^pg\\s*:.*")) return "pg";
    if (l.matches("^crri\\s*:.*")) return "crri";
    if (l.matches("^crmi\\s*:.*")) return "crmi";
    return "";
  }

  /** Which section a heading starts, or null when the line is not a heading. */
  static sectionOf(h) {
    h = h.replaceAllRx("\\s+", " ");
    if (h.equals("chief") || h.startsWith("chief ") || h.startsWith("unit chief")) return "chief";
    if (h.startsWith("assistant professor") || h.startsWith("asst prof") || h.startsWith("asst. prof")) return "aps";
    if (h.equals("dap") || h.startsWith("dap ")) return "dap";
    if (h.startsWith("male op")) return "male_op";
    if (h.startsWith("female op")) return "female_op";
    if (h.startsWith("fever op")) return "fever_op";
    if (h.startsWith("triage pg")) return "triage_pg";
    if (h.startsWith("op duty crri") || h.startsWith("op crri")) return "op_crri";
    if (h.startsWith("triage crri")) return "triage_crri";
    if (h.contains("step down") || h.contains("stepdown")) return "stepdown_crri";
    if (h.startsWith("crri triage")) return "crri_triage";
    if (h.startsWith("imcu pg")) return "imcu";
    if (h.startsWith("day imcu")) return "imcu";
    if (h.startsWith("night imcu")) return "imcu";
    if (h.contains("critical care")) return "ccb";
    if (h.startsWith("fever ward")) return "fever";
    return null;
  }

  static keyFor(section, night, role) {
    switch (section) {
      case "triage_pg": return night ? "triage_pg_night" : "triage_pg_day";
      case "crri_triage": return night ? "crri_triage_night" : "crri_triage_day";
      case "imcu": return night ? "imcu_night" : "imcu_day";
      case "ccb": return (night ? "ccb_night_" : "ccb_day_") + (role.equals("crri") ? "crri" : "pg");
      case "fever":
        if (night) return "fever_night";
        return role.equals("crmi") || role.equals("crri") ? "fever_day_crmi" : "fever_day_pg";
      default: return section;
    }
  }

  static add(p, key, line) {
    if (key == null) return;
    line = line.trim();
    if (line.isEmpty()) return;
    const old = p.fields.containsKey(key) ? p.fields.get(key) : "";
    p.fields.put(key, old.isEmpty() ? line : old + "\n" + line);
    p.count++;
  }

  /** The roster as a WhatsApp message in the department's usual layout. */
  static shareText(db, r) {
    const s = new StringBuilder();
    const d = Dates.parse(r.get("date"));
    const unit = Ui.nz(r.get("unit"));
    s.append("*").append(db.setting("dept", "Department of General Medicine")).append("*\n\n");
    s.append("Good morning sir/madam\n\n");
    if (d != null) s.append(Dates.nice(r.get("date"))).append(" ").append(d.getDayOfWeek().getDisplayName(TextStyle.FULL, Locale.ENGLISH));
    s.append(" Admission day\n\n");
    const ui = Db.isWardUnit(unit) ? Integer.parseInt(unit.substring(1)) - 1 : -1;
    if (ui >= 0) s.append("*").append(Character.toUpperCase(Roster.ORDINALS[ui].charAt(0))).append(Roster.ORDINALS[ui].substring(1)).append(" Medical Unit*\n\n");
    else if (!unit.isEmpty()) s.append("*").append(Db.unitName(unit)).append("*\n\n");
    for (let g = 0; g < Roster.FIELDS.length; g++) {
      let any = false;
      for (const f of Roster.FIELDS[g]) if (!Ui.nz(r.get(f[0])).trim().isEmpty()) any = true;
      if (!any) continue;
      if (g >= 2) s.append("*").append(Roster.GROUPS[g]).append("*\n");
      for (const f of Roster.FIELDS[g]) {
        const v = Ui.nz(r.get(f[0])).trim();
        if (v.isEmpty()) continue;
        s.append("*").append(f[1]).append("*\n").append(v).append("\n");
      }
      s.append("\n");
    }
    if (!Ui.nz(r.get("notes")).trim().isEmpty()) s.append(r.get("notes").trim()).append("\n\n");
    s.append("Thank You sir/madam.");
    return s.toString();
  }
}

/** Result of reading a pasted roster message: the fields plus the date and unit when the message names them. */
Roster.Parsed = class {
  constructor() { this.fields = new JMap(); this.date = null; this.unit = null; this.count = 0; }
};
