/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** One box to find a patient (name, IP number, phone, bed, diagnosis), a staff member, a phone-book number or a pending task. */
class SearchActivity extends Base {
  static COLOR = 0xFF4F46E5;

  constructor() { super(); this.q = ""; this.results = null; this.box = null; }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Search");
    this.subtitle = "Patients, staff, phone book and tasks";
    this.headerColor(SearchActivity.COLOR);
  }

  liveRefresh() {
    return false;
  }

  render() {
    const page = Ui.v(this);
    this.box = new EditText(this);
    this.box.setHint("Name, IP no, phone, bed or diagnosis");
    this.box.setSingleLine(true);
    this.box.setText(this.q);
    this.box.setBackground(Ui.outline(this, Ui.CARD, Ui.LINE, 14));
    this.box.setPadding(Ui.dp(this, 16), Ui.dp(this, 12), Ui.dp(this, 16), Ui.dp(this, 12));
    const p = new LinearLayout.LayoutParams(-1, -2);
    p.setMargins(Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 12), Ui.dp(this, 4));
    page.addView(this.box, p);
    this.results = Ui.v(this);
    page.addView(this.results);
    this.box.addTextChangedListener({
      beforeTextChanged: (s, a, b, c) => { },
      onTextChanged: (s, a, b, c) => { },
      afterTextChanged: (e) => {
        this.q = e.toString().trim();
        this.fill();
      }
    });
    this.setPage(page);
    this.fill();
    if (this.q.isEmpty()) this.box.requestFocus();
  }

  fill() {
    const results = this.results;
    results.removeAllViews();
    if (this.q.length < 2) {
      results.addView(this.emptyNote("Type at least two letters or digits."));
      return;
    }
    const like = "%" + this.q.split("%").join("").split("_").join("") + "%";
    const pts = this.db.rows("SELECT * FROM patients WHERE name LIKE ? OR ip_no LIKE ? OR phone LIKE ? OR bed LIKE ? OR diagnosis LIKE ? "
      + "ORDER BY CASE status WHEN 'Admitted' THEN 0 ELSE 1 END, admit_date DESC LIMIT 30", like, like, like, like, like);
    let shown = 0;
    if (!pts.isEmpty()) {
      results.addView(Ui.heading(this, "Patients \u00B7 " + pts.length, Ui.PRIMARY));
      for (const pt of pts) {
        results.addView(this.patientRow(pt));
        shown++;
      }
    }
    const staff = this.db.rows("SELECT * FROM staff WHERE (name LIKE ? OR phone LIKE ?) AND " + Approvals.APPROVED_SQL + " ORDER BY name LIMIT 20", like, like);
    if (!staff.isEmpty()) {
      results.addView(Ui.heading(this, "Staff and students \u00B7 " + staff.length, Ui.PURPLE));
      for (const s of staff) {
        const card = Ui.card(this);
        card.addView(Ui.tv(this, s.get("name"), 15, Ui.TEXT, true));
        card.addView(Ui.muted(this, Ui.nz(s.get("role")) + (Ui.nz(s.get("unit")).isEmpty() ? "" : " \u00B7 " + s.get("unit")) + (Ui.nz(s.get("phone")).isEmpty() ? "" : " \u00B7 " + s.get("phone"))));
        results.addView(card);
        shown++;
      }
    }
    const con = this.db.rows("SELECT * FROM contacts WHERE name LIKE ? OR phone LIKE ? OR designation LIKE ? OR place LIKE ? ORDER BY name LIMIT 15", like, like, like, like);
    if (!con.isEmpty()) {
      results.addView(Ui.heading(this, "Phone book \u00B7 " + con.length, Ui.TEAL));
      for (const s of con) {
        const card = Ui.card(this);
        card.addView(Ui.tv(this, s.get("name"), 15, Ui.TEXT, true));
        card.addView(Ui.muted(this, (Ui.nz(s.get("designation")) + " " + Ui.nz(s.get("place")) + " " + Ui.nz(s.get("phone"))).trim()));
        results.addView(card);
        shown++;
      }
    }
    const tasks = this.db.rows("SELECT t.*, p.name AS pname FROM tasks t LEFT JOIN patients p ON p.id=t.patient_id WHERE t.text LIKE ? ORDER BY t.id DESC LIMIT 15", like);
    if (!tasks.isEmpty()) {
      results.addView(Ui.heading(this, "Tasks \u00B7 " + tasks.length, Ui.AMBER));
      for (const t of tasks) {
        const card = Ui.card(this);
        card.addView(Ui.tv(this, Ui.nz(t.get("text")), 15, Ui.TEXT, true));
        card.addView(Ui.muted(this, Ui.nz(t.get("pname"))));
        if (!Ui.nz(t.get("patient_id")).isEmpty()) card.setOnClickListener(this.opener(PatientActivity, "id", t.get("patient_id")));
        results.addView(card);
        shown++;
      }
    }
    if (shown == 0) results.addView(this.emptyNote("Nothing found for \"" + this.q + "\"."));
  }
}
;
/* ---- app/SessionAttendance.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Attendance at the physician conference (Physicon) and journal club. The organiser starts attendance for a session;
 * their phone then shows a 4-digit code that changes every 30 seconds. Each person in the hall enters the code in
 * the app on their own phone and is marked present with the time. The code is worked out from a secret kept with
 * the session, so any phone can check it without the internet; it cannot usefully be forwarded because it changes.
 */
class SessionAttendance {
  constructor() {}

  static WINDOW_MS = 30000;
  static HOURS_OPEN = 3;
  static KINDS = ["CONF", "JC"];

  static forKind(kind) {
    return "CONF" === kind || "JC" === kind;
  }

  // ---------- the changing code ----------

  static code(secret, sessionId, window) {
    try {
      const mac = Mac.getInstance("HmacSHA256");
      mac.init(new SecretKeySpec(jbytes(secret), "HmacSHA256"));
      const h = mac.doFinal(jbytes(sessionId + ":" + window));
      const v = ((h[0] & 0x7f) << 24) | ((h[1] & 0xff) << 16) | ((h[2] & 0xff) << 8) | (h[3] & 0xff);
      return jfmt("%04d", v % 10000);
    } catch (e) {
      throw new IllegalStateException(e);
    }
  }

  static window(millis) {
    return Math.floor(millis / SessionAttendance.WINDOW_MS);
  }

  static codeNow(s, millis) {
    return SessionAttendance.code(s.get("att_secret"), s.get("id"), SessionAttendance.window(millis));
  }

  /** Seconds until the code changes. */
  static secondsLeft(millis) {
    return toInt(Math.floor((SessionAttendance.WINDOW_MS - millis % SessionAttendance.WINDOW_MS + 999) / 1000));
  }

  /** Accepts the current code and the ones just before and after (phones' clocks differ a little). */
  static check(s, typed, millis) {
    const t = Ui.nz(typed).replaceAllRx("\\D", "");
    if (t.length !== 4 || Ui.nz(s.get("att_secret")).isEmpty()) return false;
    const w = SessionAttendance.window(millis);
    for (let x = w - 2; x <= w + 1; x++) if (SessionAttendance.code(s.get("att_secret"), s.get("id"), x).equals(t)) return true;
    return false;
  }

  // ---------- opening and closing ----------

  static isOpen(s) {
    if (s == null || !("1" === s.get("att_open"))) return false;
    const until = Ui.nz(s.get("att_until"));
    return until.isEmpty() || LocalDateTime.now().toString().compareTo(until) < 0;
  }

  /** Sessions with attendance open right now. */
  static open(db) {
    const out = [];
    for (const s of db.rows("SELECT * FROM academics WHERE att_open='1' ORDER BY date DESC, id DESC")) if (SessionAttendance.isOpen(s)) out.add(s);
    return out;
  }

  /** The admin, the HOD, the Medical Registrar and faculty start attendance; on a phone without shared login, its user can. */
  static canRun(c) {
    if (!Cloud.active(c)) return true;
    const r = Cloud.role(c);
    return Cloud.isManager(r) || r.equals("professor") || r.equals("faculty");
  }

  static start(db, c, id) {
    const b = new Uint8Array(16);
    new SecureRandom().nextBytes(b);
    const sb = new StringBuilder();
    for (const x of b) sb.append(jfmt("%02x", x));
    const now = LocalDateTime.now().withNano(0);
    const cv = new ContentValues();
    cv.put("att_secret", sb.toString());
    cv.put("att_open", "1");
    cv.put("att_start", now.toString());
    cv.put("att_until", now.plusHours(SessionAttendance.HOURS_OPEN).toString());
    cv.put("att_by", Approvals.me(c));
    db.update("academics", cv, id);
  }

  static stop(db, id) {
    const cv = new ContentValues();
    cv.put("att_open", "0");
    db.update("academics", cv, id);
  }

  // ---------- who is present ----------

  /** The staff row of the person using this phone, or null when it is not known. */
  static me(c, db) {
    const sid = Cloud.myStaff(c);
    if (sid > 0) {
      const s = db.row("SELECT * FROM staff WHERE id=?", String(sid));
      if (s != null) return s;
    }
    let name = Reminders.prefs(c).getString("name", "");
    if (name.isEmpty()) name = Reminders.myName(c, db);
    return name.isEmpty() ? null : db.row("SELECT * FROM staff WHERE name=? AND " + Approvals.APPROVED_SQL + " ORDER BY id LIMIT 1", name);
  }

  static present(db, sessionId) {
    return db.rows("SELECT * FROM acad_attendance WHERE academic_id=? ORDER BY time, name", sessionId);
  }

  static count(db, sessionId) {
    return db.num("SELECT COUNT(*) FROM acad_attendance WHERE academic_id=?", sessionId);
  }

  static isPresent(db, sessionId, person) {
    return db.num("SELECT COUNT(*) FROM acad_attendance WHERE academic_id=? AND (staff_id=? OR name=?)",
      sessionId, person.get("id"), person.get("name")) > 0;
  }

  /** Marks a person present (once per session). Returns false if already marked. */
  static mark(db, c, sessionId, person, method) {
    if (SessionAttendance.isPresent(db, sessionId, person)) return false;
    const cv = new ContentValues();
    cv.put("academic_id", sessionId);
    cv.put("staff_id", person.get("id"));
    cv.put("name", person.get("name"));
    cv.put("role", person.get("role"));
    cv.put("time", LocalDateTime.now().withNano(0).toString());
    cv.put("method", method);
    cv.put("by_name", Approvals.me(c));
    db.insert("acad_attendance", cv);
    return true;
  }

  /** Faculty, PGs and CRMIs expected at the session who have not checked in. */
  static absent(db, sessionId) {
    return db.rows("SELECT * FROM staff WHERE role IN ('Professor','Associate Professor','Assistant Professor','Postgraduate','CRMI') AND "
      + Approvals.APPROVED_SQL + " AND id NOT IN (SELECT staff_id FROM acad_attendance WHERE academic_id=? AND staff_id IS NOT NULL) "
      + "AND name NOT IN (SELECT name FROM acad_attendance WHERE academic_id=?) "
      + "ORDER BY CASE role WHEN 'Professor' THEN 0 WHEN 'Associate Professor' THEN 1 WHEN 'Assistant Professor' THEN 2 WHEN 'Postgraduate' THEN 3 ELSE 4 END, name",
      sessionId, sessionId);
  }
}
;
/* ---- app/SettingsActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Department details, unit admission days, unit chiefs and typical ward load. */
class SettingsActivity extends Base {
  static DAY_VALUES = ["1", "2", "3", "4", "5", "6", "7"];
  static DAY_LABELS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
  static REQ_APK = 41;

  constructor() {
    super();
    this.form = null;
    this.adminBox = null;
    this.lockBox = null;
    this.reminders = null;
    this.aiBox = null;
    this.updates = null;
  }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Settings");
    this.headerColor(Ui.SLATE);
    this.headerAction("Save", { onClick: (v) => { this.save(); } });
    // from the "update is ready" notification or the home page: install straight away (already downloaded in the background)
    if ("1".equals(this.getIntent().getStringExtra(Updates.INSTALL))) {
      const o = Updates.available(this, this.db);
      if (o != null) this.downloadAndInstall(o);
    }
  }

  liveRefresh() {
    return false;
  }

  render() {
    if (this.form != null) return;
    this.form = new Form(this);
    const form = this.form;
    form.heading("Department");
    form.text("dept", "Department", this.db.setting("dept", ""), Form.TEXT);
    form.text("college", "Institution", this.db.setting("college", ""), Form.TEXT);
    form.text("hod", "Head of Department", this.db.setting("hod", ""), Form.TEXT);
    form.date("jc_anchor", "A journal club Saturday (later ones repeat every 2 weeks)", this.db.setting("jc_anchor", ""));

    for (const u of Db.ALL_LOCS) {
      const r = this.db.unit(u);
      form.heading(Db.unitName(u));
      const ward = Db.isWardUnit(u);
      if (ward) {
        const day = Ui.tv(this, "Admission day: " + SettingsActivity.DAY_LABELS[Db.fixedAdmitDay(u) - 1] + " 7:30 AM to 7:30 AM next day  ·  fixed", 14, Ui.PRIMARY, true);
        day.setPadding(0, Ui.dp(this, 4), 0, Ui.dp(this, 4));
        form.view.addView(day);
      }
      form.text(u + "_head", ward ? "Unit chief (Professor)" : "Professor in-charge", r.get("head"), Form.TEXT);
      form.text(u + "_m", ward ? "Typical male ward census" : "Typical male patients / beds", r.get("male_cap"), Form.NUMBER);
      form.text(u + "_f", ward ? "Typical female ward census" : "Typical female patients / beds", r.get("female_cap"), Form.NUMBER);
    }

    const page = Ui.v(this);
    if (Cloud.isOwner(this)) {
      this.adminBox = Ui.v(this);
      page.addView(this.adminBox);
      this.fillAdmin();
    }
    if (Lock.applies(this)) {
      this.lockBox = Ui.v(this);
      page.addView(this.lockBox);
      this.fillLock();
    }
    this.updates = Ui.v(this);
    page.addView(this.updates);
    this.fillUpdates();
    page.addView(Copyright.footer(this, Ui.MUTED));
    this.reminders = Ui.v(this);
    page.addView(this.reminders);
    this.fillReminders();
    this.aiBox = Ui.v(this);
    page.addView(this.aiBox);
    this.fillAi();
    page.addView(Ui.heading(this, "Department and units", Ui.SLATE));
    const card = Ui.card(this);
    card.addView(form.view);
    page.addView(card);
    const btn = Ui.v(this);
    btn.setPadding(Ui.dp(this, 12), Ui.dp(this, 8), Ui.dp(this, 12), 0);
    btn.addView(Ui.button(this, "Save settings", Ui.PRIMARY, { onClick: (v) => { this.save(); } }));
    page.addView(btn);
    this.setPage(page);
  }

  // ---------- admin control (the admin only) ----------

  /** Switches for the whole department that only the admin sees and changes. */
  fillAdmin() {
    this.adminBox.removeAllViews();
    this.adminBox.addView(Ui.heading(this, "Admin control", 0xFFB91C1C));
    const c = Ui.card(this);
    c.addView(Ui.muted(this, "Only you (the admin) see this section. These switches apply to every phone in the department; no one else can change them."));
    const on = AdminControl.aiCheckOn(this.db);
    const row = Ui.h(this);
    row.setGravity(Gravity.CENTER_VERTICAL);
    const l = Ui.v(this);
    l.addView(Ui.tv(this, "AI check in the case sheet", 15, Ui.TEXT, true));
    l.addView(Ui.tv(this, on ? "Shown: differential diagnosis and treatment check by AI" : "Hidden on every phone", 13, on ? Ui.GREEN : Ui.RED, true));
    row.addView(l, Ui.weight(1));
    const sw = new Switch(this);
    sw.setChecked(on);
    sw.setOnCheckedChangeListener({
      onCheckedChanged: (b, v) => {
        AdminControl.setAiCheck(this.db, v);
        Ui.toast(this, v ? "AI check is now shown on every phone" : "AI check is now hidden on every phone");
        this.fillAdmin();
      }
    });
    row.addView(sw);
    c.addView(row);
    Ui.margins(row, 0, 10, 0, 0);
    const icOn = AdminControl.intercomOn(this.db);
    const row2 = Ui.h(this);
    row2.setGravity(Gravity.CENTER_VERTICAL);
    const l2 = Ui.v(this);
    l2.addView(Ui.tv(this, "Intercom (calls and pages)", 15, Ui.TEXT, true));
    l2.addView(Ui.tv(this, icOn ? "On: members can call each other" : "Off on every phone: the icon is hidden and calls stop", 13, icOn ? Ui.GREEN : Ui.RED, true));
    row2.addView(l2, Ui.weight(1));
    const sw2 = new Switch(this);
    sw2.setChecked(icOn);
    sw2.setOnCheckedChangeListener({
      onCheckedChanged: (b, v) => {
        AdminControl.setIntercom(this.db, v);
        Ui.toast(this, v ? "Intercom is now on for everyone" : "Intercom is now off for everyone");
        // Web: no standby listener or background service on this device, so stopping and re-syncing them is a no-op.
        try { if (!v && typeof Intercom !== 'undefined' && Intercom.current && Intercom.current() != null) Intercom.current().stop(); } catch (e) { }
        try { if (typeof IntercomService !== 'undefined' && IntercomService.sync) IntercomService.sync(this); } catch (e) { }
        this.fillAdmin();
      }
    });
    row2.addView(sw2);
    c.addView(row2);
    Ui.margins(row2, 0, 14, 0, 0);
    this.adminBox.addView(c);
    const bk = Ui.card(this);
    bk.addView(Ui.tv(this, "Nightly backup", 15, Ui.TEXT, true));
    // Web: the nightly backup runs from the Android app (a scheduled job on the phone); a browser cannot run it.
    bk.addView(Ui.muted(this, "Every night after 2 AM, while the Android app has internet, a copy of all records is saved on the phone (last 7) and on the server (last 14, admin only). "
      + "This is not available in the browser: use the Android app."));
    bk.addView(Ui.tv(this, "Not available in the browser", 13, Ui.MUTED, true));
    const now = Ui.outlineButton(this, "Back up now", Ui.PRIMARY, {
      onClick: (v) => {
        Ui.toast(this, "Backups are not available in the browser. Use the Android app.");
      }
    });
    bk.addView(now);
    Ui.margins(now, 0, 8, 0, 0);
    this.adminBox.addView(bk);
  }

  // ---------- app lock ----------

  /** This phone's app PIN, fingerprint and how soon it locks. */
  fillLock() {
    this.lockBox.removeAllViews();
    this.lockBox.addView(Ui.heading(this, "App lock", Ui.PRIMARY));
    const c = Ui.card(this);
    c.addView(Ui.muted(this, "The app asks for this phone's PIN when it opens and after it has been away for a while, so a lost phone does not show patient records. "
      + "Five wrong PINs sign the phone out."));
    c.addView(Ui.button(this, "Change PIN", Ui.PRIMARY, {
      onClick: (v) => {
        this.startActivity(new Intent(this, LockActivity).putExtra("change", true));
      }
    }));
    if (Lock.bioAvailable(this)) {
      const row = Ui.h(this);
      row.setGravity(Gravity.CENTER_VERTICAL);
      row.addView(Ui.tv(this, "Unlock with fingerprint", 15, Ui.TEXT, true), Ui.weight(1));
      const sw = new Switch(this);
      sw.setChecked(Lock.bio(this));
      sw.setOnCheckedChangeListener({
        onCheckedChanged: (b, v) => { Lock.setBio(this, v); }
      });
      row.addView(sw);
      c.addView(row);
      Ui.margins(row, 0, 10, 0, 0);
    } else {
      c.addView(Ui.muted(this, "Fingerprint: not set up on this phone (add one in the phone's own settings to use it here)."));
    }
    const t = Ui.tv(this, "Lock after the app is away for", 14, Ui.TEXT, true);
    t.setPadding(0, Ui.dp(this, 12), 0, Ui.dp(this, 4));
    c.addView(t);
    const opts = Ui.h(this);
    const now = Lock.afterMinutes(this);
    for (const m of Lock.AFTER_MINUTES) {
      const on = m == now;
      const o = Ui.tv(this, m + " min", 14, on ? Color.WHITE : Ui.PRIMARY, true);
      o.setGravity(Gravity.CENTER);
      o.setPadding(0, Ui.dp(this, 8), 0, Ui.dp(this, 8));
      o.setBackground(Ui.round(this, on ? Ui.PRIMARY : 0x141D4E89, 14));
      o.setOnClickListener({
        onClick: (v) => { Lock.setAfterMinutes(this, m); this.fillLock(); }
      });
      const lp = new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1);
      lp.setMargins(Ui.dp(this, 3), 0, Ui.dp(this, 3), 0);
      opts.addView(o, lp);
    }
    c.addView(opts);
    this.lockBox.addView(c);
  }

  // ---------- reminders ----------

  /** Reminders before this person's classes and duties: on/off, whose, how early, the next one. */
  fillReminders() {
    this.reminders.removeAllViews();
    this.reminders.addView(Ui.heading(this, "Class and duty reminders", Ui.PURPLE));
    const c = Ui.card(this);
    const next = Reminders.next(this, this.db);
    const name = Reminders.myName(this, this.db);
    let state;
    if (!Reminders.on(this)) state = "Reminders are off on this phone.";
    else if (name.isEmpty()) state = "Choose your name below to get reminders.";
    else if (next == null) state = "Nothing coming up for " + name + " in the next 3 days.";
    else state = "Next: " + next.title + ", " + (next.start.toLocalDate().equals(Dates.today()) ? "today" : Dates.shortFmt(next.start.toLocalDate()))
      + " at " + next.start.toLocalTime();
    c.addView(Ui.tv(this, state, 14, Ui.TEXT, true));
    c.addView(Ui.muted(this, "The phone reminds you shortly before the classes you take, the conferences and journal clubs you present or moderate, "
      + "your DAP duty and your duties in the daily duty roster and ward duty list."));
    if (Reminders.on(this) && !Reminders.allowed(this)) {
      const allow = Ui.button(this, "Allow notifications", Ui.AMBER, {
        onClick: (v) => { Reminders.askPermission(this, true); }
      });
      c.addView(allow);
      Ui.margins(allow, 0, 10, 0, 0);
    }
    const rf = new Form(this);
    rf.check("on", "Remind me on this phone", Reminders.on(this));
    rf.check("ble", "Mark my Physicon / journal club attendance by Bluetooth", Reminders.prefs(this).getBoolean("ble", true));
    rf.suggest("name", "Remind me as (your name as written in rosters)", name, this.db.staffNames(""));
    const vals = new Array(Reminders.LEADS.length).fill(null);
    for (let i = 0; i < vals.length; i++) vals[i] = String(Reminders.LEADS[i]);
    rf.choice("lead", "When", Reminders.LEAD_LABELS, vals, String(Reminders.lead(this)), null);
    c.addView(rf.view);
    const row = Ui.buttonRow(this,
      Ui.button(this, "Save reminders", Ui.PURPLE, {
        onClick: (v) => {
          Reminders.prefs(this).edit().putBoolean("on", "1".equals(rf.get("on"))).putBoolean("ble", "1".equals(rf.get("ble")))
            .putString("name", rf.get("name")).putInt("lead", Ui.toInt(rf.get("lead"), 30)).apply();
          Reminders.schedule(this);
          Reminders.askPermission(this, true);
          if ("1".equals(rf.get("ble"))) Beacon.ask(this);
          Ui.toast(this, "Reminders saved");
          this.fillReminders();
        }
      }),
      Ui.outlineButton(this, "Test", Ui.PURPLE, {
        onClick: (v) => {
          Reminders.show(this, new Reminders.Item("test", "Test reminder",
            "Reminders work on this phone", LocalDateTime.now().withSecond(0).withNano(0), "SettingsActivity"));
        }
      }));
    c.addView(row);
    Ui.margins(row, 0, 12, 0, 0);
    this.reminders.addView(c);
  }

  // ---------- AI summaries ----------

  /** The Anthropic API key for "Write with AI" on case and discharge summaries; kept on this phone only. */
  fillAi() {
    this.aiBox.removeAllViews();
    this.aiBox.addView(Ui.heading(this, "AI summaries", Ui.PURPLE));
    const c = Ui.card(this);
    const k = Ai.key(this);
    c.addView(Ui.tv(this, k.isEmpty() ? "Claude: no API key on this phone." : Ai.ready(this) ? "Claude: on. Key " + Ai.masked(k) : "Switched off. Key " + Ai.masked(k),
      14, k.isEmpty() ? Ui.TEXT : Ai.ready(this) ? Ui.GREEN : Ui.ORANGE, true));
    c.addView(Ui.muted(this, "\"Write with AI\" on the case summary and discharge summary sends the summary text to Claude AI (Anthropic) "
      + "with the patient's name, IP number, phone, address and CMCHIS number taken out. Get a key at console.anthropic.com "
      + "(API keys); usage is billed to that account. The key is kept on this phone only: it is not synced, backed up or shared."));
    const af = new Form(this);
    af.text("key", k.isEmpty() ? "Anthropic API key" : "New API key (leave empty to keep the current one)", "",
      InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD);
    af.check("on", "Use AI summaries on this phone", Ai.prefs(this).getBoolean("on", true));
    c.addView(af.view);
    const save = Ui.button(this, "Save", Ui.PURPLE, {
      onClick: (v) => {
        const nk = af.get("key").trim();
        if (!nk.isEmpty() && !nk.startsWith("sk-ant-")) {
          Ui.toast(this, "That doesn't look like an Anthropic key (it starts with sk-ant-)");
          return;
        }
        Ai.setKey(this, nk.isEmpty() ? Ai.key(this) : nk, "1".equals(af.get("on")));
        Ui.toast(this, "AI summaries saved");
        this.fillAi();
      }
    });
    const row = Ai.key(this).isEmpty() ? save : Ui.buttonRow(this, save,
      Ui.outlineButton(this, "Remove key", Ui.RED, {
        onClick: (v) => {
          Ai.setKey(this, "", true);
          Ui.toast(this, "Key removed");
          this.fillAi();
        }
      }));
    c.addView(row);
    Ui.margins(row, 0, 12, 0, 0);
    this.aiBox.addView(c);
    this.aiBox.addView(this.geminiCard());
  }

  /** Google Gemini with a free key: AI writes inside the app without paying. */
  geminiCard() {
    const c = Ui.card(this);
    const g = Ai.geminiKey(this);
    c.addView(Ui.tv(this, g.isEmpty() ? "Gemini (free): no key on this phone." : "Gemini (free): on. Key " + Ai.masked(g),
      14, g.isEmpty() ? Ui.TEXT : Ui.GREEN, true));
    c.addView(Ui.muted(this, "Free way to write inside the app. Open aistudio.google.com on the phone, sign in with a Google account, "
      + "tap Get API key, then Create API key, copy it and paste it here. There is a daily limit. On the free plan Google may use what is sent "
      + "to improve its products; the patient's name, IP number, phone, address and CMCHIS number are always taken out first. "
      + "The key is kept on this phone only."));
    const gf = new Form(this);
    gf.text("gkey", g.isEmpty() ? "Gemini API key (starts with AIza or AQ.)" : "New Gemini key (leave empty to keep the current one)", "",
      InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD);
    c.addView(gf.view);
    const save = Ui.button(this, "Save Gemini key", Ui.TEAL, {
      onClick: (v) => {
        const nk = gf.get("gkey").trim();
        if (nk.isEmpty()) return;
        if (!nk.startsWith("AIza") && !nk.startsWith("AQ.") || nk.length < 30 || nk.contains(" ")) {
          Ui.toast(this, "That doesn't look like a Gemini key (it starts with AIza or AQ.)");
          return;
        }
        Ai.setGeminiKey(this, nk);
        Ui.toast(this, "Gemini key saved");
        this.fillAi();
      }
    });
    const row = g.isEmpty() ? save : Ui.buttonRow(this, save,
      Ui.outlineButton(this, "Remove Gemini key", Ui.RED, {
        onClick: (v) => {
          Ai.setGeminiKey(this, "");
          Ui.toast(this, "Gemini key removed");
          this.fillAi();
        }
      }));
    c.addView(row);
    Ui.margins(row, 0, 12, 0, 0);
    return c;
  }

  // ---------- app update ----------

  onResume() {
    super.onResume();
    if (this.updates != null) this.fillUpdates();
    if (this.lockBox != null) this.fillLock();
  }

  /** The App update section: this version, a newer published one, install from a file, publish (admin only), what's new.
   *  Web: the website updates itself; installing and publishing the Android app are not available (Updates says so politely). */
  fillUpdates() {
    this.updates.removeAllViews();
    Updates.cleanup(this);
    this.updates.addView(Ui.heading(this, "App update", Ui.PRIMARY));
    const c = Ui.card(this);
    c.setBackground(Glass.hero(this, Ui.HERO, 20));
    const avail = Updates.available(this, this.db);
    c.addView(Ui.tv(this, "Version " + Updates.myName(this) + (avail == null ? "" : "  →  " + avail.optString("name") + " available"), 18, Color.WHITE, true));
    let sub;
    if (avail != null) {
      sub = "Published " + Dates.nice(avail.optString("date")) + (avail.optString("by").isEmpty() ? "" : " by " + avail.optString("by"))
        + (avail.optString("notes").isEmpty() ? "" : "\n" + avail.optString("notes"));
    } else if (Cloud.active(this)) {
      sub = "You have the latest version the admin has published. Records stay on the phone when the app is updated.";
    } else {
      sub = "Install a newer version from an APK file (from WhatsApp, Drive or Downloads). Records stay on the phone when the app is updated.";
    }
    c.addView(Ui.tv(this, sub, 13, 0xD9FFFFFF, false));
    if (avail != null) {
      const up = Ui.button(this, "Download and install " + avail.optString("name"), Ui.GREEN, {
        onClick: (v) => { this.downloadAndInstall(avail); }
      });
      c.addView(up);
      Ui.margins(up, 0, 12, 0, 0);
    }
    const file = Ui.button(this, "Install from an APK file", Ui.SKY, {
      onClick: (v) => { Store.pick(this, [Updates.APK_MIME, "application/octet-stream"], SettingsActivity.REQ_APK); }
    });
    file.setBackground(Glass.frost(this, 14));
    c.addView(file);
    Ui.margins(file, 0, avail == null ? 12 : 8, 0, 0);
    this.updates.addView(c);

    if (Cloud.active(this) && Cloud.isOwner(this)) {
      const p = Ui.card(this);
      const last = Updates.latest(this.db);
      const newer = last == null || Updates.myCode(this) > last.optInt("code");
      p.addView(Ui.tv(this, "Send this version to every phone", 15, Ui.TEXT, true));
      p.addView(Ui.muted(this, (last == null ? "No version published yet. " : "Last published: " + last.optString("name") + " on " + Dates.nice(last.optString("date")) + ". ")
        + (newer ? "Publishing uploads the app installed on this phone (version " + Updates.myName(this) + ") to the shared database, and every phone shows an update button."
          : "This phone has the published version. Install a newer one first, then publish it.")));
      if (newer) {
        const pub = Ui.button(this, "Publish version " + Updates.myName(this), Ui.PRIMARY, {
          onClick: (v) => { this.publish(); }
        });
        p.addView(pub);
        Ui.margins(pub, 0, 10, 0, 0);
      }
      this.updates.addView(p);
    }

    const w = Ui.card(this);
    w.addView(Ui.tv(this, "What's new", 15, Ui.TEXT, true));
    for (const ch of Updates.CHANGES) {
      const t = Ui.tv(this, ch[0] + (ch[0].equals(Updates.myName(this)) ? "  (this phone)" : ""), 13, Ui.PRIMARY, true);
      w.addView(t);
      Ui.margins(t, 0, 8, 0, 0);
      w.addView(Ui.muted(this, ch[1]));
    }
    this.updates.addView(w);
  }

  downloadAndInstall(o) {
    const d = new AlertDialog.Builder(this).setTitle("Downloading " + o.optString("name"))
      .setMessage("Getting the update from the shared database…").setCancelable(false).show();
    new Thread({
      run: () => {
        let rel = null, err = null;
        try {
          rel = Updates.download(this, o);
        } catch (e) {
          err = e.getMessage();
        }
        const r = rel, er = err;
        this.runOnUiThread({
          run: () => {
            d.dismiss();
            if (r != null) Updates.install(this, r);
            else Ui.toast(this, "Download failed: " + er + ". Check the internet and try again.");
          }
        });
      }
    }).start();
  }

  publish() {
    const f = new Form(this);
    f.multi("notes", "What changed (shown to everyone)", "");
    Ui.formDialog(this, "Publish version " + Updates.myName(this) + "?", f, "Publish", {
      run: () => {
        const notes = f.get("notes");
        const d = new AlertDialog.Builder(this).setTitle("Publishing")
          .setMessage("Uploading the app to the shared database…").setCancelable(false).show();
        new Thread({
          run: () => {
            let err = null;
            try {
              Updates.publish(this, this.db, notes);
            } catch (e) {
              err = e.getMessage();
            }
            const er = err;
            this.runOnUiThread({
              run: () => {
                d.dismiss();
                Ui.toast(this, er == null ? "Published. Other phones will see the update after they sync." : "Could not publish: " + er);
                this.fillUpdates();
              }
            });
          }
        }).start();
        return true;
      }
    });
  }

  onActivityResult(req, res, data) {
    super.onActivityResult(req, res, data);
    if (req != SettingsActivity.REQ_APK || res != RESULT_OK || data == null || data.getData() == null) return;
    try {
      const rel = Updates.importApk(this, data.getData());
      const pi = Updates.inspect(this, this.db.file(rel));
      const r = rel;
      if (pi != null && pi.versionCode <= Updates.myCode(this)) {
        Ui.confirm(this, "Not a newer version", "This file is version " + pi.versionName + "; the phone has " + Updates.myName(this)
          + ". Installing an older version can fail. Install anyway?", "Install", {
          run: () => { Updates.install(this, r); }
        });
      } else {
        Updates.install(this, rel);
      }
    } catch (e) {
      Ui.toast(this, e.getMessage());
    }
  }

  save() {
    for (const k of ["dept", "college", "hod", "jc_anchor"]) this.db.setSetting(k, this.form.get(k));
    for (const u of Db.ALL_LOCS) {
      const day = Db.fixedAdmitDay(u);
      this.db.saveUnit(u, day, this.form.get(u + "_head"), this.form.getInt(u + "_m", 0), this.form.getInt(u + "_f", 0));
    }
    Ui.toast(this, "Settings saved");
    this.finish();
  }
}
;
