/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** One Daily ECG or Daily Image: the picture (tap to zoom), history, question, hidden interpretation, and the discussion. */
class SpotActivity extends Base {
  constructor() { super(); this.id = 0; this.reveal = false; this.input = null; }

  onCreate(b) {
    super.onCreate(b);
    this.id = Long.parseLong(this.getIntent().getStringExtra("id"));
    const s = this.db.row("SELECT * FROM spots WHERE id=?", String(this.id));
    const kind = s == null ? Spots.ECG : s.get("kind");
    this.setTitle(Spots.name(kind));
    this.subtitle = "Discussion for faculty and students";
    this.headerColors = Spots.gradient(kind);
    if (s != null && Spots.canEdit(this, s)) this.headerAction("Edit", this.opener(SpotEditActivity, "id", String(this.id)));
  }

  liveRefresh() {
    return this.input == null || this.input.getText().toString().trim().isEmpty();
  }

  render() {
    const page = Ui.v(this);
    const s = this.db.row("SELECT * FROM spots WHERE id=?", String(this.id));
    if (s == null) {
      page.addView(this.emptyNote("This post was removed."));
      this.setPage(page);
      return;
    }
    const col = Spots.color(s.get("kind"));

    const card = Ui.card(this);
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    top.addView(Ui.softPill(this, Ui.nz(s.get("type")).isEmpty() ? Spots.name(s.get("kind")) : s.get("type"), col));
    const sp = new View(this);
    top.addView(sp, Ui.weight(1));
    top.addView(Ui.muted(this, Dates.nice(s.get("date"))));
    card.addView(top);
    if (!Ui.nz(s.get("title")).isEmpty()) {
      const t = Ui.title(this, s.get("title"));
      card.addView(t);
      Ui.margins(t, 0, 8, 0, 0);
    }
    const f = this.db.file(Ui.nz(s.get("image")));
    if (!Ui.nz(s.get("image")).isEmpty() && f.exists()) {
      const iv = new ImageView(this);
      iv.setImageBitmap(Ui.loadScaled(f, 1600));
      iv.setAdjustViewBounds(true);
      iv.setBackground(Ui.round(this, 0xFF0F172A, 12));
      iv.setOnClickListener({ onClick: (v) => { Store.openWith(this, s.get("image")); } });
      card.addView(iv);
      Ui.margins(iv, 0, 10, 0, 4);
      const hint = Ui.tv(this, "Tap the picture to zoom", 11, Ui.MUTED, false);
      hint.setGravity(Gravity.CENTER);
      card.addView(hint);
    } else {
      const wait = Ui.tv(this, "The picture is downloading. It appears after the next sync.", 13, Ui.MUTED, false);
      wait.setGravity(Gravity.CENTER);
      wait.setBackground(Ui.round(this, Ui.alpha(col, 0x14), 12));
      wait.setPadding(Ui.dp(this, 12), Ui.dp(this, 28), Ui.dp(this, 12), Ui.dp(this, 28));
      card.addView(wait);
      Ui.margins(wait, 0, 10, 0, 4);
    }
    if (!Ui.nz(s.get("history")).isEmpty()) {
      card.addView(this.label("Clinical history", col));
      card.addView(Ui.body(this, s.get("history")));
    }
    if (!Ui.nz(s.get("question")).isEmpty()) {
      card.addView(this.label("Question", col));
      card.addView(Ui.tv(this, s.get("question"), 15, Ui.TEXT, true));
    }
    const by = Ui.muted(this, "Posted by " + Ui.nz(s.get("name")) + (Ui.nz(s.get("role")).isEmpty() ? "" : " (" + s.get("role") + ")"));
    card.addView(by);
    Ui.margins(by, 0, 10, 0, 0);
    page.addView(card);

    // the poster's interpretation, hidden until asked for
    const ans = Ui.card(this);
    if (Ui.nz(s.get("answer")).isEmpty()) {
      ans.addView(Ui.muted(this, "The interpretation has not been added yet. Discuss below; the poster or a faculty member can add it with Edit."));
    } else if (!this.reveal) {
      ans.addView(Ui.muted(this, "Write your own reading in the discussion first, then check the answer."));
      const show = Ui.button(this, "Show interpretation", col, { onClick: (v) => { this.reveal = true; this.render(); } });
      ans.addView(show);
      Ui.margins(show, 0, 8, 0, 0);
    } else {
      ans.addView(this.label("Interpretation", Ui.GREEN));
      ans.addView(Ui.body(this, s.get("answer")));
    }
    page.addView(ans);

    // discussion
    const cs = Spots.comments(this.db, String(this.id));
    page.addView(Ui.heading(this, "Discussion  ·  " + cs.size(), col));
    if (cs.isEmpty()) page.addView(this.emptyNote("No comments yet. Share your reading of the " + (Spots.ECG === s.get("kind") ? "ECG" : "image") + "."));
    for (const c of cs) page.addView(this.bubble(c, col));

    const box = Ui.card(this);
    box.addView(Ui.tv(this, "Add to the discussion", 14, Ui.TEXT, true));
    this.input = new EditText(this);
    this.input.setHint("Your interpretation, a question or a teaching point");
    this.input.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_MULTI_LINE | InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);
    this.input.setMinLines(2);
    box.addView(this.input);
    box.addView(Ui.button(this, "Post comment", col, { onClick: (v) => { this.send(); } }));
    page.addView(box);
    this.setPage(page);
  }

  label(s, col) {
    const t = Ui.tv(this, s.toUpperCase(), 11, col, true);
    t.setLetterSpacing(0.08);
    Ui.margins(t, 0, 12, 0, 2);
    return t;
  }

  bubble(c, col) {
    const fac = Spots.isFaculty(c.get("role"));
    const me = Spots.mine(this, c.get("name"));
    const b = Ui.v(this);
    b.setBackground(Ui.round(this, fac ? Ui.alpha(Ui.GREEN, 0x14) : me ? Ui.alpha(col, 0x12) : Color.WHITE, 16));
    b.setPadding(Ui.dp(this, 14), Ui.dp(this, 10), Ui.dp(this, 14), Ui.dp(this, 10));
    const lp = Ui.lp(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
    lp.setMargins(Ui.dp(this, me ? 40 : 12), Ui.dp(this, 4), Ui.dp(this, me ? 12 : 40), Ui.dp(this, 4));
    b.setLayoutParams(lp);
    b.setElevation(Ui.dp(this, 1));
    const top = Ui.h(this);
    top.setGravity(Gravity.CENTER_VERTICAL);
    top.addView(Ui.tv(this, Ui.nz(c.get("name")), 13, fac ? Ui.GREEN : Ui.TEXT, true));
    if (!Ui.nz(c.get("role")).isEmpty()) {
      const r = Ui.tv(this, (fac ? "★ " : "") + c.get("role"), 11, fac ? Ui.GREEN : Ui.MUTED, false);
      r.setPadding(Ui.dp(this, 6), 0, 0, 0);
      top.addView(r);
    }
    const sp = new View(this);
    top.addView(sp, Ui.weight(1));
    const t = Ui.nz(c.get("time"));
    top.addView(Ui.tv(this, t.length >= 16 ? (t.substring(0, 10) === Dates.todayIso() ? "" : Dates.nice(t.substring(0, 10)) + " ") + t.substring(11, 16) : t, 11, Ui.MUTED, false));
    b.addView(top);
    const body = Ui.body(this, Ui.nz(c.get("text")));
    b.addView(body);
    Ui.margins(body, 0, 4, 0, 0);
    if (me || SessionAttendance.canRun(this)) {
      b.setOnLongClickListener({
        onLongClick: (v) => {
          Ui.confirm(this, "Delete comment?", "This comment will be removed for everyone.", "Delete", {
            run: () => {
              this.db.delete("spot_comments", Long.parseLong(c.get("id")));
              this.render();
            }
          });
          return true;
        }
      });
    }
    return b;
  }

  send() {
    const t = this.input == null ? "" : this.input.getText().toString().trim();
    if (t.isEmpty()) {
      Ui.toast(this, "Write a comment first");
      return;
    }
    Spots.comment(this, this.db, String(this.id), t);
    this.input.setText("");
    this.render();
  }
}
;
