/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Pending tasks per patient ("CT brain booked", "nephro opinion awaited"), ticked off when done and counted on the ward census. */
class Tasks {
  constructor() {}

  static COLOR = 0xFFEA580C;
  static KINDS = ["Investigation", "Opinion", "Procedure", "Report", "Other"];
  static SUGGEST = ["CT brain booked", "MRI brain booked", "USG abdomen booked", "ECHO booked", "Chest X-ray", "Endoscopy booked",
    "Nephro opinion awaited", "Cardio opinion awaited", "Neuro opinion awaited", "Surgery opinion awaited", "Gastro opinion awaited", "OG opinion awaited",
    "Blood culture report awaited", "Biopsy report awaited", "Serology report awaited", "CBNAAT report awaited",
    "Blood transfusion", "Dialysis", "Pleural tap", "Ascitic tap", "Lumbar puncture", "CMCHIS pre-auth", "Discharge summary"];

  static PENDING_SQL = "SELECT COUNT(*) FROM tasks t JOIN patients p ON p.id = t.patient_id WHERE t.done='' AND p.status='IN'";

  static pending(db, pid) {
    return db.num("SELECT COUNT(*) FROM tasks WHERE patient_id=? AND done=''", String(pid));
  }

  /** Pending tasks of inpatients now in this ward (or every ward when null). */
  static inWard(db, loc) {
    return loc == null ? db.num(Tasks.PENDING_SQL) : db.num(Tasks.PENDING_SQL + " AND p.location=?", loc);
  }

  static overdue(db) {
    return db.num(Tasks.PENDING_SQL + " AND t.due<>'' AND t.due<?", Dates.todayIso());
  }

  static markDone(a, db, t, done) {
    const cv = new ContentValues();
    cv.put("done", done ? "1" : "");
    cv.put("done_by", done ? CallDutyActivity.myName(a) : "");
    cv.put("done_time", done ? Dates.todayIso() + " " + Dates.now() : "");
    db.update("tasks", cv, Long.parseLong(t.get("id")));
  }

  /** One task with a tick box; ticking it marks it done for every phone. */
  static row(a, db, t, prefix) {
    const r = Ui.v(a);
    r.setPadding(0, Ui.dp(a, 4), 0, Ui.dp(a, 4));
    const done = "1" === t.get("done");
    const cb = new CheckBox(a);
    cb.setText((prefix == null ? "" : prefix) + Ui.nz(t.get("text")));
    cb.setTextSize(15);
    cb.setTextColor(done ? Ui.MUTED : Ui.TEXT);
    cb.setChecked(done);
    if (done) cb.setPaintFlags(cb.getPaintFlags() | Paint.STRIKE_THRU_TEXT_FLAG);
    cb.setOnCheckedChangeListener({
      onCheckedChanged: (b, on) => {
        Tasks.markDone(a, db, t, on);
        a.render();
      }
    });
    r.addView(cb);
    const due = Ui.nz(t.get("due"));
    const late = !done && !due.isEmpty() && due.compareTo(Dates.todayIso()) < 0;
    const sub = Ui.nz(t.get("kind")) + (due.isEmpty() ? "" : "  ·  by " + Dates.nice(due) + (late ? " (overdue)" : ""))
      + (done ? "  ·  done by " + Ui.nz(t.get("done_by")) + " " + Ui.nz(t.get("done_time")) : "  ·  added by " + Ui.nz(t.get("by_name")));
    const s = Ui.tv(a, sub, 12, late ? Ui.RED : Ui.MUTED, false);
    s.setPadding(Ui.dp(a, 32), 0, 0, 0);
    r.addView(s);
    r.setOnLongClickListener({
      onLongClick: (v) => { Tasks.addDialog(a, db, Long.parseLong(t.get("patient_id")), t); return true; }
    });
    return r;
  }

  /** The patient page's "Pending tasks" section. */
  static section(a, db, pid) {
    const box = Ui.v(a);
    const open = db.rows("SELECT * FROM tasks WHERE patient_id=? AND done='' ORDER BY CASE WHEN due='' THEN 1 ELSE 0 END, due, id", String(pid));
    const done = db.rows("SELECT * FROM tasks WHERE patient_id=? AND done<>'' ORDER BY done_time DESC LIMIT 5", String(pid));
    box.addView(Ui.heading(a, "Pending tasks  ·  " + open.size(), Tasks.COLOR));
    const card = Ui.card(a);
    if (open.isEmpty()) card.addView(Ui.muted(a, "Nothing pending. Add tests booked, opinions awaited or procedures planned."));
    for (const t of open) card.addView(Tasks.row(a, db, t, null));
    for (const t of done) card.addView(Tasks.row(a, db, t, null));
    const add = Ui.outlineButton(a, "+ Add task", Tasks.COLOR, { onClick: (v) => { Tasks.addDialog(a, db, pid, null); } });
    card.addView(add);
    Ui.margins(add, 0, 8, 0, 0);
    box.addView(card);
    return box;
  }

  static addDialog(a, db, pid, t) {
    const f = new Form(a);
    f.suggest("text", "Task (e.g. CT brain booked, nephro opinion awaited)", t == null ? "" : t.get("text"), Tasks.SUGGEST);
    f.choice("kind", "Type", Tasks.KINDS, Tasks.KINDS, t == null ? Tasks.KINDS[0] : t.get("kind"), null);
    f.optionalDate("due", "Expected by (optional)", t == null ? "" : t.get("due"));
    Ui.formDialog(a, t == null ? "Add a pending task" : "Edit task", f, "Save", {
      run: () => {
        if (!f.require("text", "Write the task")) return false;
        const cv = new ContentValues();
        cv.put("text", f.get("text").trim());
        cv.put("kind", f.get("kind"));
        cv.put("due", f.get("due"));
        if (t == null) {
          cv.put("patient_id", pid);
          cv.put("by_name", CallDutyActivity.myName(a));
          cv.put("time", Dates.todayIso() + " " + Dates.now());
          db.insert("tasks", cv);
        } else db.update("tasks", cv, Long.parseLong(t.get("id")));
        a.render();
        return true;
      }
    });
  }
}
;
/* ---- app/TasksActivity.js ---- */
/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/** Every pending task of the inpatients, ward by ward; tick to mark done, tap the patient to open them. */
class TasksActivity extends Base {
  constructor() { super(); this.overdueOnly = false; }

  onCreate(b) {
    super.onCreate(b);
    this.setTitle("Pending tasks");
    this.subtitle = "Tests booked, opinions awaited, procedures planned";
    this.headerColor(Tasks.COLOR);
  }

  render() {
    const db = this.db;
    const page = Ui.v(this);
    const chips = Ui.h(this);
    chips.setPadding(Ui.dp(this, 12), Ui.dp(this, 6), Ui.dp(this, 12), 0);
    const all = Ui.chip(this, "All · " + Tasks.inWard(db, null), !this.overdueOnly, Tasks.COLOR);
    all.setOnClickListener({ onClick: (v) => { this.overdueOnly = false; this.render(); } });
    const late = Ui.chip(this, "Overdue · " + Tasks.overdue(db), this.overdueOnly, Ui.RED);
    late.setOnClickListener({ onClick: (v) => { this.overdueOnly = true; this.render(); } });
    chips.addView(all);
    chips.addView(late);
    Ui.margins(late, 8, 0, 0, 0);
    page.addView(chips);
    const where = "t.done='' AND p.status='IN'" + (this.overdueOnly ? " AND t.due<>'' AND t.due<'" + Dates.todayIso() + "'" : "");
    let last = null, lastPatient = null;
    let card = null;
    const rows = db.rows("SELECT t.*, p.name AS pname, p.location AS loc, p.bed AS pbed FROM tasks t JOIN patients p ON p.id = t.patient_id WHERE "
      + where + " ORDER BY p.location, p.bed, p.name, t.due, t.id");
    if (rows.isEmpty()) page.addView(this.emptyNote(this.overdueOnly ? "Nothing overdue." : "No pending tasks. Add them from a patient's page."));
    for (const t of rows) {
      if (!t.get("loc").equals(last)) {
        last = t.get("loc");
        lastPatient = null;
        page.addView(Ui.heading(this, Db.unitName(last) + "  ·  " + Tasks.inWard(db, last), Ui.unitColor(last)));
      }
      if (!t.get("patient_id").equals(lastPatient)) {
        lastPatient = t.get("patient_id");
        card = Ui.card(this);
        const name = Ui.tv(this, t.get("pname") + (Ui.nz(t.get("pbed")).isEmpty() ? "" : "  ·  bed " + t.get("pbed")), 15, Ui.TEXT, true);
        name.setOnClickListener(this.opener(PatientActivity, "id", t.get("patient_id")));
        card.addView(name);
        page.addView(card);
      }
      card.addView(Tasks.row(this, db, t, null));
    }
    this.setPage(page);
  }
}
;
