/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * The daily "Ward duty PGs & CRRIs list" WhatsApp message: for each unit M1-M7, the PG and CRRI on duty with their
 * phone numbers, or a note such as "Admission day". Saved one row per unit per day in ward_duty.
 */
class WardDuty {
  static $clinit() {
    WardDuty.UNITS = ["M1", "M2", "M3", "M4", "M5", "M6", "M7", Db.IMCU, Db.FEVER, Db.CCB, Db.GERI, Db.RHEUM];
  }

  static UNIT = Pattern.compile("^\\W*(M\\s?[1-7]|IMCU|ICU|FEVER(?:\\s*WARD)?|CCB|CRITICAL CARE(?:\\s*BLOCK)?|GERIATRICS?(?:\\s*WARD)?|RHEUMATOLOGY(?:\\s*WARD)?|RHEUM)\\b\\s*[:\\-–]?\\s*(.*)$", Pattern.CASE_INSENSITIVE);
  static ROLE = Pattern.compile("^\\W*(PG|P\\.G\\.?|CRRI|CRMI|HS|INTERN)\\b\\s*[:\\-–.]?\\s*(.*)$", Pattern.CASE_INSENSITIVE);
  static ONLY_PHONE = Pattern.compile("^\\+?[\\d ]{10,16}$");
  static DATE = Pattern.compile("\\b(\\d{1,2})[/.-](\\d{1,2})[/.-](\\d{2,4})\\b");

  static parse(text) {
    const p = new WardDuty.Parsed();
    let cur = null;
    let last = null;           // "pg" or "crri": where a phone on its own line belongs
    for (const raw of text.split(' ').join(' ').jsplit("\\r?\\n")) {
      let line = raw.split("*").join("").split("_").join(" ").trim();
      if (line.isEmpty()) continue;
      if (p.date == null) {
        const d = WardDuty.DATE.matcher(line);
        if (d.find()) {
          let y = Integer.parseInt(d.group(3));
          if (y < 100) y += 2000;
          try {
            p.date = LocalDate.of(y, Integer.parseInt(d.group(2)), Integer.parseInt(d.group(1))).toString();
            continue;
          } catch (e) {
          }
        }
      }
      const u = WardDuty.UNIT.matcher(line);
      if (u.find()) {
        const code = WardDuty.unitCode(u.group(1));
        cur = p.units.containsKey(code) ? p.units.get(code) : new WardDuty.Entry();
        p.units.put(code, cur);
        last = null;
        const rest = u.group(2).trim();
        if (rest.isEmpty()) continue;
        line = rest;                                 // "M1 PG: Dr X 98..." on one line
        if (!WardDuty.ROLE.matcher(line).find()) {
          cur.note = WardDuty.join(cur.note, line);         // "Admission day", "Holiday", ...
          continue;
        }
      }
      if (cur == null) continue;                       // greeting, title before the first unit
      const r = WardDuty.ROLE.matcher(line);
      if (r.find()) {
        const role = r.group(1).toUpperCase().split(".").join("");
        const who = r.group(2).trim();
        if (role.equals("PG") || role.equals("P G")) {
          cur.pg = WardDuty.join(cur.pg, who);
          last = "pg";
        } else {
          cur.crri = WardDuty.join(cur.crri, who);
          last = "crri";
        }
        continue;
      }
      if (WardDuty.ONLY_PHONE.matcher(line).matches() && last != null) {     // phone on the next line
        if (last.equals("pg")) cur.pg = (cur.pg + " " + line).trim();
        else cur.crri = (cur.crri + " " + line).trim();
        continue;
      }
      const low = line.toLowerCase();
      if (low.startsWith("thank") || low.startsWith("regards")) {
        cur = null;
        continue;
      }
      if (last == null) cur.note = WardDuty.join(cur.note, line);
      else if (last.equals("pg")) cur.pg = WardDuty.join(cur.pg, line);      // a second PG on its own line
      else cur.crri = WardDuty.join(cur.crri, line);
    }
    return p;
  }

  static join(a, b) {
    b = b.trim();
    if (b.isEmpty()) return a;
    return a.isEmpty() ? b : a + "\n" + b;
  }

  static unitCode(s) {
    const u = s.toUpperCase().split(" ").join("");
    if (u.startsWith("M") && u.length === 2) return u;
    if (u.contains("FEVER")) return Db.FEVER;
    if (u.contains("CCB") || u.contains("CRITICAL")) return Db.CCB;
    if (u.contains("GERI")) return Db.GERI;
    if (u.contains("RHEUM")) return Db.RHEUM;
    return Db.IMCU;
  }

  /** Replaces the day's ward duty list with the parsed one. */
  static save(db, date, p) {
    const old = db.rows("SELECT id FROM ward_duty WHERE date=?", date);
    for (const r of old) db.delete("ward_duty", Long.parseLong(r.get("id")));
    let n = 0;
    for (const e of p.units.entrySet()) {
      const cv = new ContentValues();
      cv.put("date", date);
      cv.put("unit", e.getKey());
      cv.put("pg", e.getValue().pg);
      cv.put("crri", e.getValue().crri);
      cv.put("note", e.getValue().note);
      db.insert("ward_duty", cv);
      n++;
    }
    return n;
  }

  /** Name and number from a line like "Dr Karthick 75981 02340" or "Dr. Nandini p +919489215036". */
  static person(line) {
    const l = line.trim();
    const phone = Roster.phone(l);
    const name = Roster.name(l);
    return [name, phone];
  }

  /** The day's list as text, to share back on WhatsApp. */
  static shareText(db, date) {
    const b = new StringBuilder("Ward duty PGs & CRRIs list\n" + Dates.nice(LocalDate.parse(date)).split('-').join('/') + "\n");
    for (const r of db.rows("SELECT * FROM ward_duty WHERE date=? ORDER BY CASE unit WHEN 'M1' THEN 1 WHEN 'M2' THEN 2 WHEN 'M3' THEN 3 WHEN 'M4' THEN 4 "
        + "WHEN 'M5' THEN 5 WHEN 'M6' THEN 6 WHEN 'M7' THEN 7 ELSE 8 END", date)) {
      b.append("\n").append(Db.shortName(r.get("unit")));
      if (!Ui.nz(r.get("note")).isEmpty()) b.append(" : ").append(r.get("note").split("\n").join(", "));
      b.append("\n");
      for (const l of Ui.nz(r.get("pg")).jsplit("\n")) if (!l.trim().isEmpty()) b.append("PG: ").append(l.trim()).append("\n");
      for (const l of Ui.nz(r.get("crri")).jsplit("\n")) if (!l.trim().isEmpty()) b.append("CRRI: ").append(l.trim()).append("\n");
    }
    return b.toString().trim();
  }
}

/** One unit's entry: lines are "name phone", as in the message. */
WardDuty.Entry = class {
  constructor() { this.pg = ""; this.crri = ""; this.note = ""; }
};

WardDuty.Parsed = class {
  constructor() { this.date = null; this.units = new JMap(); }
};
;
