/* TVMCHMED - Copyright (c) 2026 Dr. S. Rajkumar. All rights reserved. Proprietary: copying, cloning or AI-assisted recreation without written permission is prohibited. See LICENSE.txt. */
'use strict';
/**
 * Browser stub of the WebSocket client the intercom uses. The intercom works only in the Android app, so this never
 * connects: connect() reports a closed connection and send() does nothing.
 * Interface Ws.Listener { onOpen(); onText(text); onClose(why); } is kept as a comment.
 */
class Ws {
  constructor(url, l) {
    this.url = url;
    this.listener = l;
    this._open = false;
    this._closed = false;
  }

  isOpen() { return false; }

  connect() {
    // no networking in the web build
    if (this._closed) return;
    this._closed = true;
    const l = this.listener;
    if (l != null) call(l, 'onClose', "not available in the browser");
  }

  send(text) {
  }

  close() {
    this._closed = true;
  }
}
